const ROLE_PRIORITY = ['owner', 'admin', 'board_member', 'staff', 'foster', 'volunteer', 'adopter'];
function getDefaultRole(roles: string[]): string {
  for (const r of ROLE_PRIORITY) {
    if (roles.includes(r)) return r;
  }
  return roles[0];
}

