  /**
   * POST /api/forgot-password
   * Request password reset token
   */
  app.post('/api/forgot-password', passwordResetLimiter, requireTenant, async (req, res, next) => {
    try {
      const { passwordResetTokens, users } = await import('@shared/schema');
      const crypto = await import('crypto');
      
      const requestSchema = z.object({
        email: z.string().email(),
      });

      const { email } = requestSchema.parse(req.body);
      
      // Find user by email and tenant
      const [user] = await db
        .select({
          id: users.id,
          email: users.email,
          fullName: users.fullName,
          tenantId: users.tenantId,
        })
        .from(users)
        .where(and(
          eq(users.email, email),
          eq(users.tenantId, req.tenant!.id)
        ))
        .limit(1);

      // Always return success to prevent email enumeration
      if (!user) {
        return res.json({ success: true, message: 'If an account exists with that email, a password reset link has been sent.' });
      }

      // Generate secure random token
      const token = crypto.randomBytes(32).toString('hex');
      const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour from now

      // Delete any existing tokens for this user
      await db
        .delete(passwordResetTokens)
        .where(eq(passwordResetTokens.userId, user.id));

      // Create new reset token
      await db.insert(passwordResetTokens).values({
        userId: user.id,
        tenantId: req.tenant!.id,
        token,
        expiresAt,
      });

      // Send reset email using EmailService (Gmail priority, platform Resend fallback)
      try {
        const { EmailService } = await import('./lib/email-service');
        // Construct reset URL with proper domain and path-based routing
        let resetUrl: string;
        if (req.tenant!.customDomain) {
          resetUrl = `https://${req.tenant!.customDomain}/reset-password?token=${token}`;
        } else {
          // Use path-based routing: {baseUrl}/{subdomain}/reset-password
          const isProduction = process.env.REPLIT_DEPLOYMENT === '1';
          const baseUrl = isProduction 
            ? 'https://irescue.life'
            : process.env.REPLIT_DEV_DOMAIN 
              ? `https://${process.env.REPLIT_DEV_DOMAIN}`
              : 'http://localhost:5000';
          resetUrl = `${baseUrl}/${req.tenant!.subdomain}/reset-password?token=${token}`;
        }
        // Use EmailService.forTenant which prioritizes Gmail, then falls back to platform Resend
        const emailService = await EmailService.forTenant(req.tenant!.id);
        if (emailService) {
          await emailService.send({
            to: user.email,
            subject: 'Password Reset Request',
            html: `
              <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                <h2>Password Reset Request</h2>
                <p>Hi ${user.fullName},</p>
                <p>You requested to reset your password. Click the button below to create a new password:</p>
                <p style="text-align: center; margin: 30px 0;">
                  <a href="${resetUrl}" style="display: inline-block; background-color: #2563eb; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold;">Reset Password</a>
                </p>
                <p style="color: #6b7280; font-size: 14px;">Or copy and paste this link into your browser:</p>
                <p style="font-size: 14px; word-break: break-all;"><a href="${resetUrl}" style="color: #2563eb;">${resetUrl}</a></p>
                <p style="color: #6b7280; font-size: 14px;">This link will expire in 1 hour.</p>
                <p style="color: #6b7280; font-size: 14px;">If you didn't request this, you can safely ignore this email.</p>
                <p>Best regards,<br/>${req.tenant!.name}</p>
              </div>
            `,
          });
          console.log(`[FORGOT PASSWORD] Password reset email sent to ${user.email} for tenant ${req.tenant!.subdomain}`);
        } else {
          console.warn(`[FORGOT PASSWORD] No email service available for tenant ${req.tenant!.subdomain} - password reset email not sent`);
        }
      } catch (emailError) {
        console.error('Failed to send password reset email:', emailError);
        // Don't fail the request if email fails - user can still use the token
      }

      res.json({ success: true, message: 'If an account exists with that email, a password reset link has been sent.' });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/reset-password
   * Reset password using token
   */
  app.post('/api/reset-password', passwordResetLimiter, requireTenant, async (req, res, next) => {
    try {
      const { passwordResetTokens, users } = await import('@shared/schema');
      const bcrypt = await import('bcrypt');
      
      const resetSchema = z.object({
        token: z.string(),
        newPassword: z.string().min(8, 'Password must be at least 8 characters'),
      });

      const { token, newPassword } = resetSchema.parse(req.body);
      
      // Find and validate token
      const [resetToken] = await db
        .select({
          id: passwordResetTokens.id,
          userId: passwordResetTokens.userId,
          tenantId: passwordResetTokens.tenantId,
          token: passwordResetTokens.token,
          expiresAt: passwordResetTokens.expiresAt,
        })
        .from(passwordResetTokens)
        .where(and(
          eq(passwordResetTokens.token, token),
          eq(passwordResetTokens.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!resetToken) {
        return res.status(400).json({ error: 'Invalid or expired reset token' });
      }

      // Check if token is expired
      if (new Date() > resetToken.expiresAt) {
        // Delete expired token
        await db.delete(passwordResetTokens).where(eq(passwordResetTokens.id, resetToken.id));
        return res.status(400).json({ error: 'Reset token has expired. Please request a new one.' });
      }

      // Hash new password
      const passwordHash = await bcrypt.hash(newPassword, 10);

      // Update user's password
      await db
        .update(users)
        .set({ passwordHash })
        .where(eq(users.id, resetToken.userId));

      // Delete used token
      await db.delete(passwordResetTokens).where(eq(passwordResetTokens.id, resetToken.id));

      res.json({ success: true, message: 'Password has been reset successfully. You can now log in with your new password.' });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/switch-role
   * Switch the user's active role
   * Admins and owners can preview any role, others can only switch to their own roles
   */
  app.post('/api/switch-role', requireAuth, (req, res) => {
    const { role } = req.body;
    
    if (!role) {
      return res.status(400).json({ error: 'Role is required' });
    }
    
    // Valid roles that can be previewed
    const validRoles = ['owner', 'admin', 'board_member', 'staff', 'foster', 'volunteer'];
    
    // Check if user is admin or owner (can preview any role)
    const isAdminOrOwner = req.user!.roles.includes('admin') || req.user!.roles.includes('owner');
    
    if (isAdminOrOwner) {
      // Admins/owners can switch to any valid role for preview
      if (!validRoles.includes(role)) {
        return res.status(403).json({ 
          error: 'Invalid role',
          message: `"${role}" is not a valid role. Valid roles are: ${validRoles.join(', ')}`
        });
      }
    } else {
      // Non-admins can only switch to roles they actually have
      if (!req.user!.roles.includes(role)) {
        return res.status(403).json({ 
          error: 'Invalid role',
          message: `You don't have the ${role} role. Your available roles are: ${req.user!.roles.join(', ')}`
        });
      }
    }
    
    // Update session with new active role
    req.session.activeRole = role;
    
    res.json({
      success: true,
      user: {
        id: req.user!.id,
        email: req.user!.email,
        fullName: req.user!.fullName,
        roles: req.user!.roles,
        activeRole: role,
      },
    });
  });

