  /**
   * PATCH /api/me/profile
   * Update current user's profile (phone, email, password) - available to all roles
   */
  app.patch('/api/me/profile', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const bcrypt = await import('bcrypt');
      const updateSchema = z.object({
        phone: z.string().max(20).optional().nullable(),
        email: z.string().email().optional(),
        currentPassword: z.string().optional(),
        newPassword: z.string().min(8).optional(),
        dailySmsOptIn: z.boolean().optional(),
        smsOptIn: z.boolean().optional(),
      }).refine(data => {
        if (data.newPassword && !data.currentPassword) {
          return false;
        }
        return true;
      }, { message: 'Current password is required to set a new password', path: ['currentPassword'] });

      const data = updateSchema.parse(req.body);
      const userId = req.user!.id;

      if (data.newPassword && data.currentPassword) {
        const [currentUser] = await db.select({ passwordHash: users.passwordHash })
          .from(users)
          .where(eq(users.id, userId));

        if (!currentUser) {
          return res.status(404).json({ error: 'User not found' });
        }

        const validPassword = await bcrypt.compare(data.currentPassword, currentUser.passwordHash);
        if (!validPassword) {
          return res.status(400).json({ error: 'Current password is incorrect' });
        }
      }

      if (data.email && data.email !== req.user!.email) {
        const [existing] = await db.select({ id: users.id })
          .from(users)
          .where(and(
            eq(users.tenantId, req.tenant!.id),
            sql`LOWER(${users.email}) = LOWER(${data.email})`,
            sql`${users.id} != ${userId}`
          ))
          .limit(1);

        if (existing) {
          return res.status(400).json({ error: 'That email address is already in use by another account' });
        }
      }

      const updateFields: Record<string, any> = {};
      if (data.phone !== undefined) updateFields.phone = data.phone ? data.phone.trim() : data.phone;
      if (data.email) updateFields.email = data.email.trim().toLowerCase();
      if (data.newPassword) {
        updateFields.passwordHash = await bcrypt.hash(data.newPassword, 10);
      }
      if (data.dailySmsOptIn !== undefined) updateFields.dailySmsOptIn = data.dailySmsOptIn;
      if (data.smsOptIn !== undefined) updateFields.smsOptIn = data.smsOptIn;

      if (Object.keys(updateFields).length === 0) {
        return res.status(400).json({ error: 'No fields to update' });
      }

      const [updated] = await db.update(users)
        .set(updateFields)
        .where(eq(users.id, userId))
        .returning({
          id: users.id,
          email: users.email,
          phone: users.phone,
          fullName: users.fullName,
          dailySmsOptIn: users.dailySmsOptIn,
          smsOptIn: users.smsOptIn,
        });

      res.json({ user: updated, message: 'Profile updated successfully' });
    } catch (error: any) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: 'Validation error', details: error.errors });
      }
      next(error);
    }
  });

