  /**
   * GET /api/stats
   * Get dashboard statistics with trend indicators (authenticated users only)
   */
  app.get('/api/stats', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { getAnimalsByTenant } = await import('./services/animals');
      const { getApplicationsByTenant } = await import('./services/applications');
      const { db } = await import('./db');
      const { users, donations, animals: animalsTable, applications: applicationsTable, kennelRows, volunteerApplications, fosterApplications } = await import('@shared/schema');
      const { eq, and, or, sql, gte, lte } = await import('drizzle-orm');

      // Calculate date ranges for current and previous periods
      const now = new Date();
      const currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
      const previousMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      const previousMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999);

      // Fetch all data in parallel
      const [
        animals,
        applications,
        currentMonthDonations,
        previousMonthDonations,
        volunteers,
        previousMonthAnimals,
        previousMonthApplications,
        kennelCapacityResult,
        pendingVolunteerApps,
        pendingFosterApps,
      ] = await Promise.all([
        getAnimalsByTenant(req.tenant!.id),
        getApplicationsByTenant(req.tenant!.id),
        // Current month cash donations (excludes in-kind, treats NULL as cash for backward compatibility)
        db.select({ total: sql<number>`COALESCE(SUM(CAST(${donations.amount} AS NUMERIC)), 0)` })
          .from(donations)
          .where(
            and(
              eq(donations.tenantId, req.tenant!.id),
              gte(donations.date, currentMonthStart),
              sql`COALESCE(${donations.donationType}, 'cash') NOT IN ('in_kind', 'in_kind_goods', 'in_kind_services')`
            )
          ),
        // Previous month cash donations (excludes in-kind, treats NULL as cash for backward compatibility)
        db.select({ total: sql<number>`COALESCE(SUM(CAST(${donations.amount} AS NUMERIC)), 0)` })
          .from(donations)
          .where(
            and(
              eq(donations.tenantId, req.tenant!.id),
              gte(donations.date, previousMonthStart),
              lte(donations.date, previousMonthEnd),
              sql`COALESCE(${donations.donationType}, 'cash') NOT IN ('in_kind', 'in_kind_goods', 'in_kind_services')`
            )
          ),
        // Volunteers - explicit field selection for dynamic import
        db.select({
          id: users.id,
        }).from(users).where(
          and(
            eq(users.tenantId, req.tenant!.id),
            sql`(${users.roles} && ARRAY['volunteer', 'admin', 'owner', 'staff']::text[])`
          )
        ),
        // Previous month animals in care (those that existed and were in care)
        db.select({ count: sql<number>`count(*)::int` })
          .from(animalsTable)
          .where(
            and(
              eq(animalsTable.tenantId, req.tenant!.id),
              sql`${animalsTable.createdAt} <= ${previousMonthEnd}`,
              or(
                sql`${animalsTable.status} NOT IN ('adopted', 'transported', 'deceased')`,
                and(
                  eq(animalsTable.status, 'adopted'),
                  sql`${animalsTable.adoptionDate} > ${previousMonthEnd}`
                )
              )
            )
          ),
        // Previous month pending applications
        db.select({ count: sql<number>`count(*)::int` })
          .from(applicationsTable)
          .where(
            and(
              eq(applicationsTable.tenantId, req.tenant!.id),
              sql`${applicationsTable.createdAt} <= ${previousMonthEnd}`,
              sql`${applicationsTable.stage} IN ('new', 'screening')`
            )
          ),
        // Kennel capacity (total units from all rows)
        db.select({ totalCapacity: sql<number>`COALESCE(SUM(${kennelRows.capacity}), 0)::int` })
          .from(kennelRows)
          .where(eq(kennelRows.tenantId, req.tenant!.id)),
        // Pending volunteer applications
        db.select({ count: sql<number>`count(*)::int` })
          .from(volunteerApplications)
          .where(
            and(
              eq(volunteerApplications.tenantId, req.tenant!.id),
              eq(volunteerApplications.status, 'pending')
            )
          ),
        // Pending foster applications
        db.select({ count: sql<number>`count(*)::int` })
          .from(fosterApplications)
          .where(
            and(
              eq(fosterApplications.tenantId, req.tenant!.id),
              eq(fosterApplications.status, 'pending')
            )
          ),
      ]);

      // Calculate current stats
      const currentAnimalsInCare = animals.filter(a => a.status === 'available' || a.locationType === 'foster').length;
      const currentPendingApplications = applications.filter(a => a.stage === 'new' || a.stage === 'screening').length;
      const currentActiveVolunteers = volunteers.length;
      const currentDonationsThisMonth = Number(currentMonthDonations[0]?.total || 0);

      // Calculate kennel occupancy (total units from kennel_rows capacity)
      const totalKennels = kennelCapacityResult[0]?.totalCapacity || 0;
      
      // Get active animals (not adopted or deceased, and not in foster)
      const activeAnimals = animals.filter(
        a => a.status === 'available' || a.status === 'pending' || a.status === 'medical_hold'
      );
      
      // Count animals with kennel assignments using structured fields
      const occupiedKennels = activeAnimals.filter(animal => 
        animal.kennelBuildingId && animal.kennelRowId && animal.kennelPosition !== null
      ).length;
      const vacantKennels = totalKennels - occupiedKennels;

      // Previous period stats
      const previousAnimalsInCare = previousMonthAnimals[0]?.count || 0;
      const previousPendingApplications = previousMonthApplications[0]?.count || 0;
      const previousDonationsLastMonth = Number(previousMonthDonations[0]?.total || 0);

      // Calculate percentage changes
      const calculateTrend = (current: number, previous: number) => {
        if (previous === 0) {
          return current > 0 ? { change: 100, isPositive: true } : { change: 0, isPositive: true };
        }
        const percentChange = ((current - previous) / previous) * 100;
        return {
          change: Math.round(Math.abs(percentChange)),
          isPositive: percentChange >= 0,
        };
      };

      const stats = {
        totalAnimals: animals.length,
        animalsInCare: currentAnimalsInCare,
        animalsInCareTrend: calculateTrend(currentAnimalsInCare, previousAnimalsInCare),
        pendingApplications: currentPendingApplications,
        pendingApplicationsTrend: calculateTrend(currentPendingApplications, previousPendingApplications),
        activeVolunteers: currentActiveVolunteers,
        donationsThisMonth: currentDonationsThisMonth,
        donationsThisMonthTrend: calculateTrend(currentDonationsThisMonth, previousDonationsLastMonth),
        totalKennels,
        occupiedKennels,
        vacantKennels,
        pendingVolunteerApplications: pendingVolunteerApps[0]?.count || 0,
        pendingFosterApplications: pendingFosterApps[0]?.count || 0,
      };

      res.json({ stats });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/activity
   * Get recent activity feed for dashboard (last 10 activities)
   * Tracks: application status changes, new applications, volunteer/foster apps, events, donations, animal updates, happy tails
   */
  app.get('/api/dashboard/activity', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { 
        applications, 
        donations, 
        animals, 
        volunteerApplications, 
        fosterApplications,
        calendarEvents,
        happyTails 
      } = await import('@shared/schema');
      const { desc } = await import('drizzle-orm');

      // Fetch recent data from all sources
      const [
        recentApplications,
        recentDonations, 
        recentAnimalUpdates,
        recentVolunteerApps,
        recentFosterApps,
        recentEvents,
        recentHappyTails,
        recentNewAnimals
      ] = await Promise.all([
        // New adoption applications
        db.select({
          id: applications.id,
          createdAt: applications.createdAt,
          applicantName: applications.applicantName,
          animalId: applications.animalId,
        })
          .from(applications)
          .where(eq(applications.tenantId, req.tenant!.id))
          .orderBy(desc(applications.createdAt))
          .limit(10),
        // Donations
        db.select({
          id: donations.id,
          createdAt: donations.createdAt,
          donorName: donations.donorName,
          amount: donations.amount,
        })
          .from(donations)
          .where(eq(donations.tenantId, req.tenant!.id))
          .orderBy(desc(donations.createdAt))
          .limit(10),
        // Animal status updates
        db.select({
          id: animals.id,
          updatedAt: animals.updatedAt,
          name: animals.name,
          status: animals.status,
        })
          .from(animals)
          .where(
            and(
              eq(animals.tenantId, req.tenant!.id),
              sql`${animals.updatedAt} > ${animals.createdAt}`
            )
          )
          .orderBy(desc(animals.updatedAt))
          .limit(10),
        // Volunteer applications
        db.select({
          id: volunteerApplications.id,
          createdAt: volunteerApplications.createdAt,
          applicantName: volunteerApplications.applicantName,
        })
          .from(volunteerApplications)
          .where(eq(volunteerApplications.tenantId, req.tenant!.id))
          .orderBy(desc(volunteerApplications.createdAt))
          .limit(10),
        // Foster applications
        db.select({
          id: fosterApplications.id,
          createdAt: fosterApplications.createdAt,
          applicantName: fosterApplications.applicantName,
        })
          .from(fosterApplications)
          .where(eq(fosterApplications.tenantId, req.tenant!.id))
          .orderBy(desc(fosterApplications.createdAt))
          .limit(10),
        // New events
        db.select({
          id: calendarEvents.id,
          createdAt: calendarEvents.createdAt,
          title: calendarEvents.title,
          startTime: calendarEvents.startTime,
        })
          .from(calendarEvents)
          .where(eq(calendarEvents.tenantId, req.tenant!.id))
          .orderBy(desc(calendarEvents.createdAt))
          .limit(10),
        // New happy tails
        db.select({
          id: happyTails.id,
          createdAt: happyTails.createdAt,
          animalName: happyTails.animalName,
        })
          .from(happyTails)
          .where(eq(happyTails.tenantId, req.tenant!.id))
          .orderBy(desc(happyTails.createdAt))
          .limit(10),
        // New animals added
        db.select({
          id: animals.id,
          createdAt: animals.createdAt,
          name: animals.name,
          species: animals.species,
        })
          .from(animals)
          .where(eq(animals.tenantId, req.tenant!.id))
          .orderBy(desc(animals.createdAt))
          .limit(10),
      ]);

      // Get animal names for applications
      const allAnimalIds = recentApplications
        .map(a => a.animalId)
        .filter(Boolean) as string[];
      
      const animalsMap = new Map();
      if (allAnimalIds.length > 0) {
        const animalsForApps = await db.select({ id: animals.id, name: animals.name })
          .from(animals)
          .where(inArray(animals.id, allAnimalIds));
        animalsForApps.forEach(a => animalsMap.set(a.id, a.name));
      }

      // Transform into unified activity format
      const activities = [
        // New adoption applications
        ...recentApplications.map(app => ({
          type: 'application' as const,
          title: 'New adoption application',
          description: `${app.applicantName} applied to adopt ${animalsMap.get(app.animalId) || 'an animal'}`,
          timestamp: app.createdAt,
        })),
        // Donations
        ...recentDonations.map(don => ({
          type: 'donation' as const,
          title: 'Donation received',
          description: `$${Number(don.amount).toFixed(2)} from ${don.donorName}`,
          timestamp: don.createdAt,
        })),
        // Animal status updates
        ...recentAnimalUpdates.map(animal => ({
          type: 'status_change' as const,
          title: 'Animal status updated',
          description: `${animal.name} ${animal.status === 'adopted' ? 'was adopted' : `moved to ${animal.status}`}`,
          timestamp: animal.updatedAt,
        })),
        // Volunteer applications
        ...recentVolunteerApps.map(app => ({
          type: 'volunteer_app' as const,
          title: 'New volunteer application',
          description: `${app.applicantName} applied to volunteer`,
          timestamp: app.createdAt,
        })),
        // Foster applications
        ...recentFosterApps.map(app => ({
          type: 'foster_app' as const,
          title: 'New foster application',
          description: `${app.applicantName} applied to foster`,
          timestamp: app.createdAt,
        })),
        // New events
        ...recentEvents.map(event => ({
          type: 'event' as const,
          title: 'New event created',
          description: `${event.title}`,
          timestamp: event.createdAt,
        })),
        // New happy tails
        ...recentHappyTails.map(tale => ({
          type: 'happy_tail' as const,
          title: 'New success story',
          description: `Happy tail posted for ${tale.animalName}`,
          timestamp: tale.createdAt,
        })),
        // New animals
        ...recentNewAnimals.map(animal => ({
          type: 'animal_new' as const,
          title: 'New animal added',
          description: `${animal.name} (${animal.species}) joined our rescue`,
          timestamp: animal.createdAt,
        })),
      ];

      // Sort by timestamp and take the 10 most recent
      activities.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
      const recentActivities = activities.slice(0, 10);

      res.json({ activities: recentActivities });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/urgent-items
   * Get urgent items requiring attention (overdue medical doses, old pending applications, animals needing adoption)
   */
  app.get('/api/dashboard/urgent-items', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalDoses, applications, animals, medicalPrescriptions } = await import('@shared/schema');
      const { lt, or } = await import('drizzle-orm');

      const now = new Date();
      const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);

      // Fetch urgent items in parallel
      const [overdueDoses, oldApplications, longTermAnimals] = await Promise.all([
        // Overdue medical doses (due date in the past and status is 'due')
        db.select({
          id: medicalDoses.id,
          prescriptionId: medicalDoses.prescriptionId,
          dueDate: medicalDoses.dueDate,
        })
          .from(medicalDoses)
          .where(
            and(
              eq(medicalDoses.tenantId, req.tenant!.id),
              eq(medicalDoses.status, 'due'),
              lt(medicalDoses.dueDate, now)
            )
          ),
        // Applications pending for more than 7 days
        db.select({
          id: applications.id,
          applicantName: applications.applicantName,
          createdAt: applications.createdAt,
        })
          .from(applications)
          .where(
            and(
              eq(applications.tenantId, req.tenant!.id),
              or(
                eq(applications.stage, 'new'),
                eq(applications.stage, 'screening')
              ),
              lt(applications.createdAt, sevenDaysAgo)
            )
          )
          .limit(10),
        // Animals available for adoption for more than 90 days
        db.select({
          id: animals.id,
          name: animals.name,
          intakeDate: animals.intakeDate,
        })
          .from(animals)
          .where(
            and(
              eq(animals.tenantId, req.tenant!.id),
              eq(animals.status, 'available'),
              lt(animals.intakeDate, ninetyDaysAgo)
            )
          )
          .limit(10),
      ]);

      // Get prescription details for overdue doses
      const prescriptionIds = overdueDoses.map(d => d.prescriptionId);
      let dosesWithMedication = [];
      if (prescriptionIds.length > 0) {
        const prescriptions = await db.select({
          id: medicalPrescriptions.id,
          medicationName: medicalPrescriptions.medicationName,
          animalId: medicalPrescriptions.animalId,
        })
          .from(medicalPrescriptions)
          .where(inArray(medicalPrescriptions.id, prescriptionIds));
        const prescriptionsMap = new Map(prescriptions.map(p => [p.id, p]));
        const animalIdsForDoses = prescriptions.map(p => p.animalId).filter(Boolean);
        const animalsForDoses = await db.select({
          id: animals.id,
          name: animals.name,
        })
          .from(animals)
          .where(inArray(animals.id, animalIdsForDoses));
        const animalsMap = new Map(animalsForDoses.map(a => [a.id, a.name]));
        dosesWithMedication = overdueDoses.map(dose => {
          const prescription = prescriptionsMap.get(dose.prescriptionId);
          return {
            id: dose.id,
            medication: prescription?.medicationName || 'Unknown',
            animalName: prescription?.animalId ? animalsMap.get(prescription.animalId) || 'Unknown' : 'Unknown',
            dueDate: dose.dueDate,
          };
        });
      }

      const urgentItems = {
        overdueMedicalDoses: dosesWithMedication.length,
        overdueMedicalDosesDetails: dosesWithMedication,
        oldPendingApplications: oldApplications.length,
        oldPendingApplicationsDetails: oldApplications,
        longTermAvailableAnimals: longTermAnimals.length,
        longTermAvailableAnimalsDetails: longTermAnimals,
      };

      res.json({ urgentItems });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/compliance
   * Get compliance/at-risk items:
   * - Animals with no medical exam in >30 days
   * - Active fosters with no updates in >14 days
   * - Overdue medications
   */
  app.get('/api/dashboard/compliance', requireTenant, requireAuth, requireRole('admin', 'staff', 'owner'), async (req, res, next) => {
    try {
      const { 
        animals, 
        medicalExams, 
        fosterAnimals, 
        fosterUpdates, 
        medicalDoses, 
        medicalPrescriptions,
        users 
      } = await import('@shared/schema');
      const { lt, max, sql, isNotNull } = await import('drizzle-orm');

      const now = new Date();
      const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      const fourteenDaysAgo = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000);

      // Get all active animals with their most recent medical exam
      const animalsWithLastExam = await db.select({
        id: animals.id,
        name: animals.name,
        species: animals.species,
        status: animals.status,
        intakeDate: animals.intakeDate,
        lastExamDate: max(medicalExams.examDate),
      })
        .from(animals)
        .leftJoin(medicalExams, and(
          eq(medicalExams.animalId, animals.id),
          eq(medicalExams.tenantId, req.tenant!.id)
        ))
        .where(
          and(
            eq(animals.tenantId, req.tenant!.id),
            inArray(animals.status, ['Shelter', 'Boarding', 'Foster'])
          )
        )
        .groupBy(animals.id);

      // Filter animals with no exam or exam older than 30 days
      const animalsNeedingMedical = animalsWithLastExam.filter(a => {
        if (!a.lastExamDate) {
          // No exam ever - only flag if intake was more than 30 days ago
          if (!a.intakeDate) return true;
          return new Date(a.intakeDate) < thirtyDaysAgo;
        }
        return new Date(a.lastExamDate) < thirtyDaysAgo;
      }).map(a => ({
        id: a.id,
        name: a.name,
        species: a.species,
        status: a.status,
        daysSinceLastExam: a.lastExamDate 
          ? Math.floor((now.getTime() - new Date(a.lastExamDate).getTime()) / (24 * 60 * 60 * 1000))
          : null,
        lastExamDate: a.lastExamDate,
      }));

      // Get active fosters with their most recent update
      const activeFostersWithUpdates = await db.select({
        fosterAnimalId: fosterAnimals.id,
        animalId: fosterAnimals.animalId,
        fosterId: fosterAnimals.fosterId,
        fosterName: users.fullName,
        fosterEmail: users.email,
        startDate: fosterAnimals.startDate,
        lastUpdateDate: max(fosterUpdates.createdAt),
      })
        .from(fosterAnimals)
        .leftJoin(users, eq(users.id, fosterAnimals.fosterId))
        .leftJoin(fosterUpdates, and(
          eq(fosterUpdates.animalId, fosterAnimals.animalId),
          eq(fosterUpdates.fosterId, fosterAnimals.fosterId),
          eq(fosterUpdates.tenantId, req.tenant!.id)
        ))
        .where(
          and(
            eq(fosterAnimals.tenantId, req.tenant!.id),
            eq(fosterAnimals.status, 'active')
          )
        )
        .groupBy(fosterAnimals.id, users.fullName, users.email);

      // Get animal names for silent fosters
      const fosterAnimalIds = activeFostersWithUpdates.map(f => f.animalId);
      let fosterAnimalNames: Record<string, string> = {};
      if (fosterAnimalIds.length > 0) {
        const fosterAnimalsList = await db.select({ id: animals.id, name: animals.name })
          .from(animals)
          .where(inArray(animals.id, fosterAnimalIds));
        fosterAnimalNames = Object.fromEntries(fosterAnimalsList.map(a => [a.id, a.name]));
      }

      // Filter fosters with no update or update older than 14 days
      const silentFosters = activeFostersWithUpdates.filter(f => {
        if (!f.lastUpdateDate) {
          // No updates ever - flag if fostering for more than 14 days
          return new Date(f.startDate) < fourteenDaysAgo;
        }
        return new Date(f.lastUpdateDate) < fourteenDaysAgo;
      }).map(f => ({
        fosterAnimalId: f.fosterAnimalId,
        animalId: f.animalId,
        animalName: fosterAnimalNames[f.animalId] || 'Unknown',
        fosterName: f.fosterName,
        fosterEmail: f.fosterEmail,
        daysSinceLastUpdate: f.lastUpdateDate 
          ? Math.floor((now.getTime() - new Date(f.lastUpdateDate).getTime()) / (24 * 60 * 60 * 1000))
          : Math.floor((now.getTime() - new Date(f.startDate).getTime()) / (24 * 60 * 60 * 1000)),
        lastUpdateDate: f.lastUpdateDate,
      }));

      // Get overdue medication doses
      const overdueDoses = await db.select({
        id: medicalDoses.id,
        prescriptionId: medicalDoses.prescriptionId,
        dueDate: medicalDoses.dueDate,
      })
        .from(medicalDoses)
        .where(
          and(
            eq(medicalDoses.tenantId, req.tenant!.id),
            eq(medicalDoses.status, 'due'),
            lt(medicalDoses.dueDate, now)
          )
        )
        .limit(50);

      // Get prescription and animal details for overdue doses
      let overdueMedications: Array<{
        doseId: string;
        medicationName: string;
        animalId: string;
        animalName: string;
        dueDate: Date;
        daysOverdue: number;
      }> = [];

      if (overdueDoses.length > 0) {
        const prescriptionIds = [...new Set(overdueDoses.map(d => d.prescriptionId))];
        const prescriptions = await db.select({
          id: medicalPrescriptions.id,
          medicationName: medicalPrescriptions.medicationName,
          animalId: medicalPrescriptions.animalId,
        })
          .from(medicalPrescriptions)
          .where(inArray(medicalPrescriptions.id, prescriptionIds));

        const prescriptionsMap = new Map(prescriptions.map(p => [p.id, p]));
        const animalIdsForDoses = [...new Set(prescriptions.map(p => p.animalId))];

        const animalsForDoses = await db.select({ id: animals.id, name: animals.name })
          .from(animals)
          .where(inArray(animals.id, animalIdsForDoses));
        const animalsMap = new Map(animalsForDoses.map(a => [a.id, a.name]));

        overdueMedications = overdueDoses.map(dose => {
          const prescription = prescriptionsMap.get(dose.prescriptionId);
          return {
            doseId: dose.id,
            medicationName: prescription?.medicationName || 'Unknown',
            animalId: prescription?.animalId || '',
            animalName: prescription?.animalId ? (animalsMap.get(prescription.animalId) || 'Unknown') : 'Unknown',
            dueDate: dose.dueDate,
            daysOverdue: Math.floor((now.getTime() - new Date(dose.dueDate).getTime()) / (24 * 60 * 60 * 1000)),
          };
        });
      }

      // Calculate compliance rate (animals with recent medical attention / total animals)
      const totalActiveAnimals = animalsWithLastExam.length;
      const compliantAnimals = totalActiveAnimals - animalsNeedingMedical.length;
      const complianceRate = totalActiveAnimals > 0 
        ? Math.round((compliantAnimals / totalActiveAnimals) * 100) 
        : 100;

      res.json({
        compliance: {
          animalsNeedingMedical: {
            count: animalsNeedingMedical.length,
            items: animalsNeedingMedical.slice(0, 10),
          },
          silentFosters: {
            count: silentFosters.length,
            items: silentFosters.slice(0, 10),
          },
          overdueMedications: {
            count: overdueMedications.length,
            items: overdueMedications.slice(0, 10),
          },
          complianceRate,
          totalActiveAnimals,
        },
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/notifications/counts
   * Returns counts of actionable items for the notification bell:
   * - Pending vet visits needing medical review
   * - Pending adopter compliance confirmations needing staff approval
   */
  app.get('/api/notifications/counts', requireTenant, requireAuth, requireRole('admin', 'staff', 'owner', 'manager', 'medical'), async (req, res, next) => {
    try {
      const { vetVisits, adopterComplianceConfirmations, medicalImportItems } = await import('@shared/schema');

      const [vetResult] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(vetVisits)
        .where(and(
          eq(vetVisits.tenantId, req.tenant!.id),
          eq(vetVisits.status, 'pending')
        ));

      const [complianceResult] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(adopterComplianceConfirmations)
        .where(and(
          eq(adopterComplianceConfirmations.tenantId, req.tenant!.id),
          eq(adopterComplianceConfirmations.status, 'pending_review')
        ));

      const [medicalImportResult] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(medicalImportItems)
        .where(and(
          eq(medicalImportItems.tenantId, req.tenant!.id),
          eq(medicalImportItems.status, 'pending')
        ));

      const vetCount = vetResult?.count || 0;
      const complianceCount = complianceResult?.count || 0;
      const medicalImportCount = medicalImportResult?.count || 0;

      res.json({
        pendingVetVisits: vetCount,
        pendingComplianceReviews: complianceCount,
        pendingMedicalImports: medicalImportCount,
        total: vetCount + complianceCount + medicalImportCount,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/medical-snapshot
   * Returns all medical KPI counts split by shelter vs foster location
   * for the Command Center medical snapshot widget
   */
  app.get('/api/dashboard/medical-snapshot', requireTenant, requireAuth, requireRole('admin', 'staff', 'owner', 'manager'), async (req, res, next) => {
    try {
      const { medicalDoses, medicalPrescriptions, vetVisits, medicalExams, vaccineRecords, preventativeCareRecords, TERMINAL_STATUSES } = await import('@shared/schema');

      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);

      const isFoster = eq(animals.locationType, 'foster');
      const isShelter = or(ne(animals.locationType, 'foster'), isNull(animals.locationType));

      const [medsDueShelter] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .innerJoin(animals, eq(medicalPrescriptions.animalId, animals.id))
        .where(and(
          eq(medicalDoses.tenantId, req.tenant!.id),
          eq(medicalDoses.status, 'due'),
          sql`${medicalDoses.dueDate} >= ${today}`,
          sql`${medicalDoses.dueDate} < ${tomorrow}`,
          isShelter
        ));

      const [medsDueFoster] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .innerJoin(animals, eq(medicalPrescriptions.animalId, animals.id))
        .where(and(
          eq(medicalDoses.tenantId, req.tenant!.id),
          eq(medicalDoses.status, 'due'),
          sql`${medicalDoses.dueDate} >= ${today}`,
          sql`${medicalDoses.dueDate} < ${tomorrow}`,
          isFoster
        ));

      const [surgShelter] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          eq(animals.medicalStatus, 'surgery_pending'),
          notInArray(animals.status, TERMINAL_STATUSES),
          isShelter
        ));

      const [surgFoster] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          eq(animals.medicalStatus, 'surgery_pending'),
          notInArray(animals.status, TERMINAL_STATUSES),
          isFoster
        ));

      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const intakeAnimalsAll = await db
        .select({
          id: animals.id,
          locationType: animals.locationType,
        })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          or(
            eq(animals.medicalStatus, 'needs_vetting'),
            and(
              gte(animals.intakeDate, thirtyDaysAgo),
              notInArray(animals.status, TERMINAL_STATUSES)
            )
          )
        ));

      const animalIds = intakeAnimalsAll.map(a => a.id);
      let examSet = new Set<string>();
      let vaccineSet = new Set<string>();
      if (animalIds.length > 0) {
        const examRows = await db
          .select({ animalId: medicalExams.animalId })
          .from(medicalExams)
          .where(and(eq(medicalExams.tenantId, req.tenant!.id), inArray(medicalExams.animalId, animalIds)))
          .groupBy(medicalExams.animalId);
        examSet = new Set(examRows.map(e => e.animalId));

        const vaccineRows = await db
          .select({ animalId: vaccineRecords.animalId })
          .from(vaccineRecords)
          .where(and(eq(vaccineRecords.tenantId, req.tenant!.id), inArray(vaccineRecords.animalId, animalIds)))
          .groupBy(vaccineRecords.animalId);
        vaccineSet = new Set(vaccineRows.map(v => v.animalId));
      }

      let needsVettingShelter = 0;
      let needsVettingFoster = 0;
      for (const a of intakeAnimalsAll) {
        const hasExam = examSet.has(a.id);
        const hasVaccines = vaccineSet.has(a.id);
        if (!hasExam || !hasVaccines) {
          if (a.locationType === 'foster') {
            needsVettingFoster++;
          } else {
            needsVettingShelter++;
          }
        }
      }

      const [vetShelter] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(vetVisits)
        .innerJoin(animals, eq(vetVisits.animalId, animals.id))
        .where(and(
          eq(vetVisits.tenantId, req.tenant!.id),
          eq(vetVisits.status, 'pending'),
          isShelter
        ));

      const [vetFoster] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(vetVisits)
        .innerJoin(animals, eq(vetVisits.animalId, animals.id))
        .where(and(
          eq(vetVisits.tenantId, req.tenant!.id),
          eq(vetVisits.status, 'pending'),
          isFoster
        ));

      const [prevCareFoster] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(preventativeCareRecords)
        .innerJoin(animals, eq(preventativeCareRecords.animalId, animals.id))
        .where(and(
          eq(preventativeCareRecords.tenantId, req.tenant!.id),
          isNotNull(preventativeCareRecords.nextDueDate),
          sql`${preventativeCareRecords.nextDueDate} >= ${today}`,
          sql`${preventativeCareRecords.nextDueDate} < ${tomorrow}`,
          notInArray(animals.status, TERMINAL_STATUSES),
          isFoster
        ));

      const [examsFoster] = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(medicalExams)
        .innerJoin(animals, eq(medicalExams.animalId, animals.id))
        .where(and(
          eq(medicalExams.tenantId, req.tenant!.id),
          eq(medicalExams.status, 'pending'),
          sql`${medicalExams.examDate} >= ${today}`,
          sql`${medicalExams.examDate} < ${tomorrow}`,
          notInArray(animals.status, TERMINAL_STATUSES),
          isFoster
        ));

      const fosterActionsToday =
        (medsDueFoster?.count || 0) +
        (prevCareFoster?.count || 0) +
        (examsFoster?.count || 0);

      res.json({
        medsDueToday: {
          shelter: medsDueShelter?.count || 0,
          foster: medsDueFoster?.count || 0,
          total: (medsDueShelter?.count || 0) + (medsDueFoster?.count || 0),
        },
        needsVetting: {
          shelter: needsVettingShelter,
          foster: needsVettingFoster,
          total: needsVettingShelter + needsVettingFoster,
        },
        surgeryPending: {
          shelter: surgShelter?.count || 0,
          foster: surgFoster?.count || 0,
          total: (surgShelter?.count || 0) + (surgFoster?.count || 0),
        },
        vetVisitsToReview: {
          shelter: vetShelter?.count || 0,
          foster: vetFoster?.count || 0,
          total: (vetShelter?.count || 0) + (vetFoster?.count || 0),
        },
        fosterActionsToday,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/action-items-count/:role?
   * Returns the count of ALL active workload items for the Command Center:
   * - Surrender requests: all active statuses (new, review, spacecheck, waitlist, scheduled) - excludes only 'intaken'
   * - Adoption applications: all active stages (new, screening, vet_check, home_visit, approved, trial) - excludes 'adopted', 'denied', 'trial_failed'
   * - Foster applications with status 'pending'
   * - Volunteer applications with status 'pending'
   * Note: The :role param is optional and used only for cache busting on the frontend
   */
  app.get('/api/dashboard/action-items-count/:role?', requireTenant, requireAuth, requireRole('admin', 'staff', 'owner', 'board_member', 'intake_coordinator'), async (req, res, next) => {
    try {
      const { 
        applications, 
        volunteerApplications, 
        fosterApplications, 
      } = await import('@shared/schema');
      const { or, count, ne, notInArray } = await import('drizzle-orm');
      const surrenderRequestsTable = surrenderRequests;

      // Get counts from all sources in parallel
      const [
        surrenderCount,
        adoptionCount,
        fosterCount,
        volunteerCount,
      ] = await Promise.all([
        // Surrender requests - only active pipeline statuses (exclude 'intaken' and 'declined')
        db.select({ count: count() })
          .from(surrenderRequestsTable)
          .where(
            and(
              eq(surrenderRequestsTable.tenantId, req.tenant!.id),
              notInArray(surrenderRequestsTable.status, ['intaken', 'declined'])
            )
          ),
        // Adoption applications - all active stages (exclude only final stages)
        db.select({ count: count() })
          .from(applications)
          .where(
            and(
              eq(applications.tenantId, req.tenant!.id),
              notInArray(applications.stage, ['adopted', 'denied', 'trial_failed'])
            )
          ),
        // Foster applications - pending status
        db.select({ count: count() })
          .from(fosterApplications)
          .where(
            and(
              eq(fosterApplications.tenantId, req.tenant!.id),
              eq(fosterApplications.status, 'pending')
            )
          ),
        // Volunteer applications - pending status
        db.select({ count: count() })
          .from(volunteerApplications)
          .where(
            and(
              eq(volunteerApplications.tenantId, req.tenant!.id),
              eq(volunteerApplications.status, 'pending')
            )
          ),
      ]);

      const totalCount = 
        Number(surrenderCount[0]?.count || 0) + 
        Number(adoptionCount[0]?.count || 0) + 
        Number(fosterCount[0]?.count || 0) + 
        Number(volunteerCount[0]?.count || 0);

      res.json({
        total: totalCount,
        breakdown: {
          surrenders: Number(surrenderCount[0]?.count || 0),
          adoptions: Number(adoptionCount[0]?.count || 0),
          fosters: Number(fosterCount[0]?.count || 0),
          volunteers: Number(volunteerCount[0]?.count || 0),
        },
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/animal-counts/:role?
   * Get counts of animals by location (in shelter vs in foster)
   * Note: The :role param is optional and used only for cache busting on the frontend
   */
  app.get('/api/dashboard/animal-counts/:role?', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { animals } = await import('@shared/schema');
      const { or, count } = await import('drizzle-orm');

      const allAnimals = await db.select({
        id: animals.id,
        status: animals.status,
        locationType: animals.locationType,
      })
        .from(animals)
        .where(
          and(
            eq(animals.tenantId, req.tenant!.id),
            or(
              eq(animals.status, 'available'),
              eq(animals.status, 'adoption_pending'),
              eq(animals.status, 'transfer_pending'),
              eq(animals.status, 'medical_hold'),
              eq(animals.status, 'stray_hold')
            )
          )
        );

      const inFoster = allAnimals.filter(a => a.locationType === 'foster').length;
      const inShelter = allAnimals.length - inFoster;

      res.json({
        inShelter,
        inFoster,
        total: inShelter + inFoster,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/daily-briefing
   * Aggregate today's and tomorrow's events for the Daily Briefing component
   * Returns: surgeries, transports, medical tasks, calendar events grouped by urgency
   */
  app.get('/api/dashboard/daily-briefing', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { 
        animals, 
        transportEvents, 
        calendarEvents,
        calendars,
        preventativeCareRecords,
        procedureLogs,
        vaccineRecords,
        medicalExams,
        medicalDoses,
        medicalPrescriptions,
        medicationTasks,
        medicationPlans,
        fosterAnimals,
        users,
        complianceReminders,
        TERMINAL_STATUSES
      } = await import('@shared/schema');
      const { gte, lte } = await import('drizzle-orm');
      
      // Calculate date ranges
      // Note: Server runs in UTC, but dates are displayed in user's local time.
      // To account for timezone offset (US timezones are up to 8 hours behind UTC),
      // we extend the query range by 1 extra day. A surgery stored as "Feb 6 00:00 UTC"
      // would appear as "Feb 5 6PM" in CST. The frontend uses local time for display.
      const now = new Date();
      const todayStart = new Date(now);
      todayStart.setHours(0, 0, 0, 0);
      const todayEnd = new Date(now);
      todayEnd.setHours(23, 59, 59, 999);
      const tomorrowStart = new Date(todayStart);
      tomorrowStart.setDate(tomorrowStart.getDate() + 1);
      const tomorrowEnd = new Date(todayEnd);
      tomorrowEnd.setDate(tomorrowEnd.getDate() + 1);
      
      // Extended end date to account for timezone offset (up to +1 day for US timezones)
      const extendedEnd = new Date(tomorrowEnd);
      extendedEnd.setDate(extendedEnd.getDate() + 1);

      // 1. Get surgeries scheduled for today through day-after-tomorrow (timezone buffer)
      const surgeriesData = await db
        .select({
          id: animals.id,
          name: animals.name,
          species: animals.species,
          photoUrls: animals.photoUrls,
          scheduledSurgeryDate: animals.scheduledSurgeryDate,
          medicalStatus: animals.medicalStatus,
          neuterStatus: animals.neuterStatus,
        })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          isNotNull(animals.scheduledSurgeryDate),
          gte(animals.scheduledSurgeryDate, todayStart),
          lte(animals.scheduledSurgeryDate, extendedEnd)
        ));

      // Filter surgeries - use extended range for "tomorrow" to account for timezone offset
      const surgeriesToday = surgeriesData.filter(s => 
        s.scheduledSurgeryDate && new Date(s.scheduledSurgeryDate) <= todayEnd
      );
      const surgeriesTomorrow = surgeriesData.filter(s => 
        s.scheduledSurgeryDate && new Date(s.scheduledSurgeryDate) > todayEnd && new Date(s.scheduledSurgeryDate) <= extendedEnd
      );

      // 2. Get transports for today through day-after-tomorrow (timezone buffer)
      const transportsData = await db
        .select({
          id: transportEvents.id,
          name: transportEvents.name,
          transportType: transportEvents.transportType,
          status: transportEvents.status,
          departureDate: transportEvents.departureDate,
          originLocation: transportEvents.originLocation,
          destinationLocation: transportEvents.destinationLocation,
          animalCount: transportEvents.animalCount,
        })
        .from(transportEvents)
        .where(and(
          eq(transportEvents.tenantId, req.tenant!.id),
          not(eq(transportEvents.status, 'completed')),
          not(eq(transportEvents.status, 'cancelled')),
          isNotNull(transportEvents.departureDate),
          gte(transportEvents.departureDate, todayStart),
          lte(transportEvents.departureDate, extendedEnd)
        ));

      // Filter transports - use extended range for "tomorrow" to account for timezone offset
      const transportsToday = transportsData.filter(t => 
        t.departureDate && new Date(t.departureDate) <= todayEnd
      );
      const transportsTomorrow = transportsData.filter(t => 
        t.departureDate && new Date(t.departureDate) > todayEnd && new Date(t.departureDate) <= extendedEnd
      );

      // 3. Get preventative care items due today through day-after-tomorrow (timezone buffer)
      const medicalTasksData = await db
        .select({
          id: preventativeCareRecords.id,
          animalId: preventativeCareRecords.animalId,
          careName: preventativeCareRecords.careName,
          careCategory: preventativeCareRecords.careCategory,
          nextDueDate: preventativeCareRecords.nextDueDate,
          animalName: animals.name,
          animalSpecies: animals.species,
        })
        .from(preventativeCareRecords)
        .innerJoin(animals, eq(preventativeCareRecords.animalId, animals.id))
        .where(and(
          eq(preventativeCareRecords.tenantId, req.tenant!.id),
          isNotNull(preventativeCareRecords.nextDueDate),
          gte(preventativeCareRecords.nextDueDate, todayStart),
          lte(preventativeCareRecords.nextDueDate, extendedEnd),
          notInArray(animals.status, TERMINAL_STATUSES)
        ));

      // Filter medical tasks - use extended range for "tomorrow" to account for timezone offset
      const medicalToday = medicalTasksData.filter(m => 
        m.nextDueDate && new Date(m.nextDueDate) <= todayEnd
      );
      const medicalTomorrow = medicalTasksData.filter(m => 
        m.nextDueDate && new Date(m.nextDueDate) > todayEnd && new Date(m.nextDueDate) <= extendedEnd
      );

      // Also get overdue items (due before today's start, not including midnight today)
      const { lt } = await import('drizzle-orm');
      const overdueData = await db
        .select({
          id: preventativeCareRecords.id,
          animalId: preventativeCareRecords.animalId,
          careName: preventativeCareRecords.careName,
          careCategory: preventativeCareRecords.careCategory,
          nextDueDate: preventativeCareRecords.nextDueDate,
          animalName: animals.name,
          animalSpecies: animals.species,
        })
        .from(preventativeCareRecords)
        .innerJoin(animals, eq(preventativeCareRecords.animalId, animals.id))
        .where(and(
          eq(preventativeCareRecords.tenantId, req.tenant!.id),
          isNotNull(preventativeCareRecords.nextDueDate),
          lt(preventativeCareRecords.nextDueDate, todayStart),
          notInArray(animals.status, TERMINAL_STATUSES)
        ));

      // 4. Get calendar events for today through day-after-tomorrow (timezone buffer)
      // Exclude volunteer-type calendars and calendars with simplifiedVolunteerMode enabled
      const { sql: sqlOp, ne: neOp } = await import('drizzle-orm');
      const calendarData = await db
        .select({
          id: calendarEvents.id,
          title: calendarEvents.title,
          description: calendarEvents.description,
          startTime: calendarEvents.startTime,
          endTime: calendarEvents.endTime,
          location: calendarEvents.location,
        })
        .from(calendarEvents)
        .innerJoin(calendars, eq(calendarEvents.calendarId, calendars.id))
        .where(and(
          eq(calendarEvents.tenantId, req.tenant!.id),
          gte(calendarEvents.startTime, todayStart),
          lte(calendarEvents.startTime, extendedEnd),
          // Exclude volunteer-type calendars entirely
          neOp(calendars.type, 'volunteer'),
          // Also exclude any non-volunteer calendar with simplifiedVolunteerMode enabled
          sqlOp`(${calendars.eventFormSettings}->>'simplifiedVolunteerMode')::boolean IS NOT TRUE`
        ));

      // 4b. Fetch events from Google Calendar for calendars with google_calendar_id
      const googleLinkedCalendars = await db
        .select({
          id: calendars.id,
          name: calendars.name,
          googleCalendarId: calendars.googleCalendarId,
          type: calendars.type,
          eventFormSettings: calendars.eventFormSettings,
        })
        .from(calendars)
        .where(and(
          eq(calendars.tenantId, req.tenant!.id),
          isNotNull(calendars.googleCalendarId),
          neOp(calendars.type, 'volunteer'),
          sqlOp`(${calendars.eventFormSettings}->>'simplifiedVolunteerMode')::boolean IS NOT TRUE`
        ));

      let googleCalendarEvents: typeof calendarData = [];
      console.log(`[Daily Briefing] Found ${googleLinkedCalendars.length} Google-linked calendars for tenant ${req.tenant!.id}`);
      if (googleLinkedCalendars.length > 0) {
        try {
          const { CalendarService } = await import('./lib/googleWorkspace');
          const calService = await CalendarService.forTenant(req.tenant!.id);
          console.log(`[Daily Briefing] CalendarService.forTenant result: ${calService ? "initialized" : "null"}`);
          if (calService) {
            const googleResults = await Promise.all(
              googleLinkedCalendars.map(async (cal) => {
                console.log(`[Daily Briefing] Fetching events for calendar "${cal.name}" (gcalId: ${cal.googleCalendarId}), timeMin: ${todayStart.toISOString()}, timeMax: ${extendedEnd.toISOString()}`);
                const result = await calService.listEvents(cal.googleCalendarId!, todayStart, extendedEnd);
                console.log(`[Daily Briefing] Calendar "${cal.name}" result: success=${result.success}, events=${result.events?.length || 0}, error=${result.error || "none"}`);
                if (result.success && result.events) {
                  return result.events.map(ev => ({
                    id: `gcal-${cal.id}-${ev.id}`,
                    title: ev.summary,
                    description: ev.description || null,
                    startTime: new Date(ev.start),
                    endTime: ev.end ? new Date(ev.end) : null,
                    location: ev.location || null,
                  }));
                }
                return [];
              })
            );
            googleCalendarEvents = googleResults.flat();
          }
        } catch (gcalError: any) {
          console.error("[Daily Briefing] Error fetching Google Calendar events:", gcalError?.message || gcalError);
        }
      }

      // Merge local + Google Calendar events, deduplicating by title+startTime
      const localEventKeys = new Set(
        calendarData.map(c => `${c.title}|${c.startTime ? new Date(c.startTime).toISOString() : ''}`)
      );
      const uniqueGoogleEvents = googleCalendarEvents.filter(g => {
        const key = `${g.title}|${g.startTime ? new Date(g.startTime).toISOString() : ''}`;
        return !localEventKeys.has(key);
      });
      const mergedCalendarData = [...calendarData, ...uniqueGoogleEvents];
      console.log(`[Daily Briefing] Merged calendar: ${calendarData.length} local + ${uniqueGoogleEvents.length} unique Google = ${mergedCalendarData.length} total`);

      // Filter calendar events - use extended range for "tomorrow" to account for timezone offset
      const calendarToday = mergedCalendarData.filter(c => 
        c.startTime && new Date(c.startTime) <= todayEnd
      );
      const calendarTomorrow = mergedCalendarData.filter(c => 
        c.startTime && new Date(c.startTime) > todayEnd && new Date(c.startTime) <= extendedEnd
      );

      // 5. Get vet calendar events: procedures, vaccines, exams scheduled for today/tomorrow
      const animalMap = new Map<string, string>();
      const activeAnimals = await db
        .select({ id: animals.id, name: animals.name })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          notInArray(animals.status, TERMINAL_STATUSES)
        ));
      activeAnimals.forEach(a => animalMap.set(a.id, a.name));

      const [futureProcedures, futureVaccines, futureExams] = await Promise.all([
        db.select({
          id: procedureLogs.id,
          animalId: procedureLogs.animalId,
          procedureName: procedureLogs.procedureName,
          procedureDate: procedureLogs.procedureDate,
          veterinarian: procedureLogs.veterinarian,
        })
          .from(procedureLogs)
          .where(and(
            eq(procedureLogs.tenantId, req.tenant!.id),
            gte(procedureLogs.procedureDate, todayStart),
            lte(procedureLogs.procedureDate, extendedEnd)
          )),
        db.select({
          id: vaccineRecords.id,
          animalId: vaccineRecords.animalId,
          itemName: vaccineRecords.itemName,
          dateDue: vaccineRecords.dateDue,
          administeredBy: vaccineRecords.administeredBy,
        })
          .from(vaccineRecords)
          .where(and(
            eq(vaccineRecords.tenantId, req.tenant!.id),
            isNotNull(vaccineRecords.dateDue),
            gte(vaccineRecords.dateDue, todayStart),
            lte(vaccineRecords.dateDue, extendedEnd)
          )),
        db.select({
          id: medicalExams.id,
          animalId: medicalExams.animalId,
          examType: medicalExams.examType,
          examDate: medicalExams.examDate,
          performedBy: medicalExams.performedBy,
        })
          .from(medicalExams)
          .where(and(
            eq(medicalExams.tenantId, req.tenant!.id),
            gte(medicalExams.examDate, todayStart),
            lte(medicalExams.examDate, extendedEnd)
          )),
      ]);

      const vetEvents = [
        ...futureProcedures.map(p => ({
          id: `procedure-${p.id}`,
          title: `${p.procedureName} - ${animalMap.get(p.animalId) || 'Unknown'}`,
          startTime: p.procedureDate?.toISOString() || '',
          location: p.veterinarian ? `Vet: ${p.veterinarian}` : '',
          type: 'procedure' as const,
          animalId: p.animalId,
        })),
        ...futureVaccines.map(v => ({
          id: `vaccine-${v.id}`,
          title: `${v.itemName} - ${animalMap.get(v.animalId) || 'Unknown'}`,
          startTime: v.dateDue?.toISOString() || '',
          location: v.administeredBy ? `By: ${v.administeredBy}` : '',
          type: 'vaccine' as const,
          animalId: v.animalId,
        })),
        ...futureExams.map(e => ({
          id: `exam-${e.id}`,
          title: `${e.examType || 'Exam'} - ${animalMap.get(e.animalId) || 'Unknown'}`,
          startTime: e.examDate?.toISOString() || '',
          location: e.performedBy ? `By: ${e.performedBy}` : '',
          type: 'exam' as const,
          animalId: e.animalId,
        })),
      ];

      const vetEventsToday = vetEvents.filter(v =>
        v.startTime && new Date(v.startTime) <= todayEnd
      );
      const vetEventsTomorrow = vetEvents.filter(v =>
        v.startTime && new Date(v.startTime) > todayEnd && new Date(v.startTime) <= extendedEnd
      );

      // 6. Foster non-compliance: foster animals with overdue preventative care
      const fosterNonCompliancePrevCare = await db
        .select({
          animalId: animals.id,
          animalName: animals.name,
          itemName: preventativeCareRecords.careName,
          fosterName: users.fullName,
          dueDate: preventativeCareRecords.nextDueDate,
        })
        .from(preventativeCareRecords)
        .innerJoin(animals, eq(preventativeCareRecords.animalId, animals.id))
        .innerJoin(fosterAnimals, and(
          eq(fosterAnimals.animalId, animals.id),
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.status, 'active')
        ))
        .innerJoin(users, eq(users.id, fosterAnimals.fosterId))
        .where(and(
          eq(preventativeCareRecords.tenantId, req.tenant!.id),
          isNotNull(preventativeCareRecords.nextDueDate),
          lt(preventativeCareRecords.nextDueDate, todayStart),
          notInArray(animals.status, TERMINAL_STATUSES),
          eq(animals.locationType, 'foster')
        ));

      // Foster non-compliance: foster animals with overdue medication doses
      const fosterNonComplianceDoses = await db
        .select({
          animalId: animals.id,
          animalName: animals.name,
          itemName: medicalPrescriptions.medicationName,
          fosterName: users.fullName,
          dueDate: medicalDoses.dueDate,
        })
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .innerJoin(animals, eq(medicalPrescriptions.animalId, animals.id))
        .innerJoin(fosterAnimals, and(
          eq(fosterAnimals.animalId, animals.id),
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.status, 'active')
        ))
        .innerJoin(users, eq(users.id, fosterAnimals.fosterId))
        .where(and(
          eq(medicalDoses.tenantId, req.tenant!.id),
          eq(medicalDoses.status, 'due'),
          lt(medicalDoses.dueDate, todayStart),
          notInArray(animals.status, TERMINAL_STATUSES),
          eq(animals.locationType, 'foster')
        ));

      // Merge and deduplicate foster non-compliance items
      const seenFosterAlerts = new Set<string>();
      const fosterNonCompliance: Array<{ animalId: string; animalName: string; itemName: string; fosterName: string; dueDate: Date | string | null }> = [];
      for (const item of [...fosterNonCompliancePrevCare, ...fosterNonComplianceDoses]) {
        const key = `${item.animalId}|${item.itemName}`;
        if (!seenFosterAlerts.has(key)) {
          seenFosterAlerts.add(key);
          fosterNonCompliance.push(item);
        }
      }

      // 6b. Missed foster medication tasks from yesterday
      const yesterdayStart = new Date(todayStart);
      yesterdayStart.setDate(yesterdayStart.getDate() - 1);
      const yesterdayEnd = new Date(todayStart);
      yesterdayEnd.setMilliseconds(-1);
      const yesterdayStr = yesterdayStart.toISOString().split('T')[0];

      const missedMedTasks = await db
        .select({
          animalId: medicationTasks.animalId,
          animalName: animals.name,
          drugName: medicationPlans.drugName,
          fosterName: users.fullName,
          scheduledTime: medicationTasks.scheduledTime,
        })
        .from(medicationTasks)
        .innerJoin(medicationPlans, eq(medicationTasks.planId, medicationPlans.id))
        .innerJoin(animals, eq(medicationTasks.animalId, animals.id))
        .innerJoin(fosterAnimals, and(
          eq(fosterAnimals.animalId, animals.id),
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.status, 'active')
        ))
        .innerJoin(users, eq(users.id, fosterAnimals.fosterId))
        .where(and(
          eq(medicationTasks.tenantId, req.tenant!.id),
          eq(medicationTasks.status, 'pending'),
          eq(medicationTasks.scheduledDate, yesterdayStr)
        ));

      const missedMedDoses = await db
        .select({
          animalId: animals.id,
          animalName: animals.name,
          drugName: medicalPrescriptions.medicationName,
          fosterName: users.fullName,
        })
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .innerJoin(animals, eq(medicalPrescriptions.animalId, animals.id))
        .innerJoin(fosterAnimals, and(
          eq(fosterAnimals.animalId, animals.id),
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.status, 'active')
        ))
        .innerJoin(users, eq(users.id, fosterAnimals.fosterId))
        .where(and(
          eq(medicalDoses.tenantId, req.tenant!.id),
          eq(medicalDoses.status, 'due'),
          gte(medicalDoses.dueDate, yesterdayStart),
          lte(medicalDoses.dueDate, yesterdayEnd)
        ));

      const seenMissedMeds = new Set<string>();
      const missedFosterMeds: Array<{ animalId: string; animalName: string; drugName: string; fosterName: string; scheduledTime?: string }> = [];
      for (const item of [...missedMedTasks, ...missedMedDoses]) {
        const key = `${item.animalId}|${item.drugName}`;
        if (!seenMissedMeds.has(key)) {
          seenMissedMeds.add(key);
          missedFosterMeds.push({
            animalId: item.animalId,
            animalName: item.animalName,
            drugName: item.drugName,
            fosterName: item.fosterName || 'Unknown',
            scheduledTime: 'scheduledTime' in item ? item.scheduledTime : undefined,
          });
        }
      }

      // 7. Bio/photo follow-ups: pending bio_photo compliance reminders
      const bioPhotoReminders = await db
        .select({
          reminderId: complianceReminders.id,
          animalId: complianceReminders.animalId,
          animalName: animals.name,
          fosterName: users.fullName,
          startDate: fosterAnimals.startDate,
        })
        .from(complianceReminders)
        .innerJoin(animals, eq(animals.id, complianceReminders.animalId))
        .innerJoin(fosterAnimals, and(
          eq(fosterAnimals.id, complianceReminders.fosterAnimalId!),
        ))
        .innerJoin(users, eq(users.id, fosterAnimals.fosterId))
        .where(and(
          eq(complianceReminders.tenantId, req.tenant!.id),
          eq(complianceReminders.reminderType, 'bio_photo'),
          eq(complianceReminders.state, 'pending')
        ));

      const nowMs = Date.now();
      const fosterBioPhotoFollowUps = bioPhotoReminders.map(r => ({
        reminderId: r.reminderId,
        animalId: r.animalId,
        animalName: r.animalName,
        fosterName: r.fosterName || 'Unknown',
        daysInFoster: r.startDate
          ? Math.floor((nowMs - new Date(r.startDate).getTime()) / 86400000)
          : 0,
      }));

      const { adopterComplianceConfirmations: accTable, complianceObligations: coTable } = await import('@shared/schema');
      const { lt: ltOp } = await import('drizzle-orm');

      const [pendingConfirmationsRaw, pendingObligationsRaw, spayNeuterOverdueRaw] = await Promise.all([
        db.select({
          confirmationId: accTable.id,
          animalId: accTable.animalId,
          animalName: animals.name,
          careName: accTable.careName,
        })
          .from(accTable)
          .innerJoin(animals, eq(animals.id, accTable.animalId))
          .where(and(
            eq(accTable.tenantId, req.tenant!.id),
            eq(accTable.status, 'pending_review'),
          ))
          .limit(10),

        db.select({
          obligationId: coTable.id,
          animalId: coTable.animalId,
          animalName: animals.name,
          obligationType: coTable.obligationType,
          proofDocumentUrl: coTable.proofDocumentUrl,
        })
          .from(coTable)
          .innerJoin(animals, eq(animals.id, coTable.animalId))
          .where(and(
            eq(coTable.tenantId, req.tenant!.id),
            eq(coTable.status, 'pending_review'),
          ))
          .limit(10),

        // Overdue spay/neuter obligations — no proof uploaded, past contractual due date (pending or escalated to overdue)
        db.select({
          obligationId: coTable.id,
          animalId: coTable.animalId,
          animalName: animals.name,
          adopterName: coTable.adopterName,
          adopterPhone: coTable.adopterPhone,
          adopterEmail: coTable.adopterEmail,
          contractualDueDate: coTable.contractualDueDate,
        })
          .from(coTable)
          .innerJoin(animals, eq(animals.id, coTable.animalId))
          .where(and(
            eq(coTable.tenantId, req.tenant!.id),
            eq(coTable.obligationType, 'spay_neuter'),
            or(eq(coTable.status, 'pending'), eq(coTable.status, 'overdue')),
            isNull(coTable.proofDocumentUrl),
            ltOp(coTable.contractualDueDate, new Date().toISOString().split('T')[0]),
          ))
          .limit(10),
      ]);

      const spayNeuterOverdue = spayNeuterOverdueRaw.map(o => ({
        ...o,
        daysOverdue: Math.floor((Date.now() - new Date(o.contractualDueDate).getTime()) / 86400000),
      }));

      const { medicalImportBatches: mibTable2 } = await import('@shared/schema');
      const pendingImportBatches = await db
        .select({
          batchId: mibTable2.id,
          fileName: mibTable2.originalFileName,
          animalId: mibTable2.animalId,
          itemCount: sql<number>`(SELECT count(*)::int FROM medical_import_items WHERE batch_id = ${mibTable2.id} AND status = 'pending')`,
        })
        .from(mibTable2)
        .where(and(
          eq(mibTable2.tenantId, req.tenant!.id),
          sql`EXISTS (SELECT 1 FROM medical_import_items WHERE batch_id = ${mibTable2.id} AND status = 'pending')`
        ))
        .limit(10);

      const pendingImportAnimalIds = pendingImportBatches.map(b => b.animalId).filter((id): id is string => !!id);
      let pendingImportAnimalMap = new Map<string, string>();
      if (pendingImportAnimalIds.length > 0) {
        const pAnimals = await db.select({ id: animals.id, name: animals.name }).from(animals).where(inArray(animals.id, pendingImportAnimalIds));
        pendingImportAnimalMap = new Map(pAnimals.map(a => [a.id, a.name]));
      }

      const pendingMedicalImports = pendingImportBatches
        .filter(b => b.itemCount > 0)
        .map(b => ({
          batchId: b.batchId,
          fileName: b.fileName,
          itemCount: b.itemCount,
          animalName: b.animalId ? (pendingImportAnimalMap.get(b.animalId) || null) : null,
        }));

      res.json({
        today: {
          surgeries: surgeriesToday,
          transports: transportsToday,
          medical: medicalToday,
          calendar: calendarToday,
          vetEvents: vetEventsToday,
          overdue: overdueData,
          fosterNonCompliance,
          missedFosterMeds,
          fosterBioPhotoFollowUps,
          adopterConfirmationsPendingReview: pendingConfirmationsRaw,
          adopterObligationsPendingReview: pendingObligationsRaw,
          spayNeuterOverdue,
          pendingMedicalImports,
        },
        tomorrow: {
          surgeries: surgeriesTomorrow,
          transports: transportsTomorrow,
          medical: medicalTomorrow,
          calendar: calendarTomorrow,
          vetEvents: vetEventsTomorrow,
        },
        summary: {
          urgentCount: surgeriesToday.length + transportsToday.length + overdueData.length + fosterNonCompliance.length + missedFosterMeds.length + pendingObligationsRaw.length,
          medicalTodayCount: medicalToday.length,
          medicalTomorrowCount: medicalTomorrow.length,
          calendarTodayCount: calendarToday.length,
          calendarTomorrowCount: calendarTomorrow.length,
          vetEventsTodayCount: vetEventsToday.length,
          vetEventsTomorrowCount: vetEventsTomorrow.length,
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/dashboard/pending-applications
   * Get all pending applications from all sources (adoption, foster, volunteer, surrender, custom forms)
   * Consolidated view for the dashboard
   */
  app.get('/api/dashboard/pending-applications', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { 
        applications, 
        volunteerApplications, 
        fosterApplications, 
        customFormSubmissions,
        customForms,
        animals 
      } = await import('@shared/schema');
      const { or, desc } = await import('drizzle-orm');

      const surrenderRequestsTable = surrenderRequests;
      // Fetch all pending applications from different sources in parallel
      const [
        adoptionApps,
        volunteerApps,
        fosterApps,
        phase1SurrenderRequests,
        formSubmissions
      ] = await Promise.all([
        // Adoption applications - pending stages (new, screening, vet_check, home_visit)
        // Note: Adoption applications store most form data in customResponses JSON field
        db.select({
          id: applications.id,
          applicantName: applications.applicantName,
          applicantEmail: applications.applicantEmail,
          applicantPhone: applications.applicantPhone,
          status: applications.stage,
          createdAt: applications.createdAt,
          animalId: applications.animalId,
          customResponses: applications.customResponses,
          notes: applications.notes,
        })
          .from(applications)
          .where(
            and(
              eq(applications.tenantId, req.tenant!.id),
              or(
                eq(applications.stage, 'new'),
                eq(applications.stage, 'screening'),
                eq(applications.stage, 'vet_check'),
                eq(applications.stage, 'home_visit')
              )
            )
          )
          .orderBy(desc(applications.createdAt))
          .limit(50),
        // Volunteer applications - pending status
        db.select({
          id: volunteerApplications.id,
          applicantName: volunteerApplications.applicantName,
          applicantEmail: volunteerApplications.applicantEmail,
          applicantPhone: volunteerApplications.applicantPhone,
          status: volunteerApplications.status,
          createdAt: volunteerApplications.createdAt,
          customResponses: volunteerApplications.customResponses,
          address: volunteerApplications.address,
          experience: volunteerApplications.experience,
          availability: volunteerApplications.availability,
          interests: volunteerApplications.interests,
          skills: volunteerApplications.skills,
          emergencyContactName: volunteerApplications.emergencyContactName,
          emergencyContactPhone: volunteerApplications.emergencyContactPhone,
          notes: volunteerApplications.notes,
        })
          .from(volunteerApplications)
          .where(
            and(
              eq(volunteerApplications.tenantId, req.tenant!.id),
              eq(volunteerApplications.status, 'pending')
            )
          )
          .orderBy(desc(volunteerApplications.createdAt))
          .limit(50),
        // Foster applications - pending status
        db.select({
          id: fosterApplications.id,
          applicantName: fosterApplications.applicantName,
          applicantEmail: fosterApplications.applicantEmail,
          applicantPhone: fosterApplications.applicantPhone,
          status: fosterApplications.status,
          createdAt: fosterApplications.createdAt,
          customResponses: fosterApplications.customResponses,
          address: fosterApplications.address,
          experience: fosterApplications.experience,
          availability: fosterApplications.availability,
          housingType: fosterApplications.housingType,
          hasYard: fosterApplications.hasYard,
          hasOtherPets: fosterApplications.hasOtherPets,
          otherPetsDetails: fosterApplications.otherPetsDetails,
          preferences: fosterApplications.preferences,
          vetReference: fosterApplications.vetReference,
          personalReference: fosterApplications.personalReference,
          notes: fosterApplications.notes,
        })
          .from(fosterApplications)
          .where(
            and(
              eq(fosterApplications.tenantId, req.tenant!.id),
              eq(fosterApplications.status, 'pending')
            )
          )
          .orderBy(desc(fosterApplications.createdAt))
          .limit(50),
        // Surrender requests - new surrenderRequests table (statuses: new, review, spacecheck, waitlist, scheduled)
        db.select({
          id: surrenderRequestsTable.id,
          applicantName: surrenderRequestsTable.ownerName,
          applicantEmail: surrenderRequestsTable.ownerEmail,
          applicantPhone: surrenderRequestsTable.ownerPhone,
          status: surrenderRequestsTable.status,
          createdAt: surrenderRequestsTable.createdAt,
          dogName: surrenderRequestsTable.dogName,
          dogBreed: surrenderRequestsTable.dogBreed,
          dogAge: surrenderRequestsTable.dogAge,
          dogGender: surrenderRequestsTable.dogGender,
          reasonForSurrender: surrenderRequestsTable.reasonForSurrender,
          medicalIssues: surrenderRequestsTable.medicalIssues,
          behavioralIssues: surrenderRequestsTable.behavioralIssues,
          photoUrl: surrenderRequestsTable.photoUrl,
        })
          .from(surrenderRequestsTable)
          .where(
            and(
              eq(surrenderRequestsTable.tenantId, req.tenant!.id),
              or(
                eq(surrenderRequestsTable.status, 'new'),
                eq(surrenderRequestsTable.status, 'review'),
                eq(surrenderRequestsTable.status, 'spacecheck'),
                eq(surrenderRequestsTable.status, 'waitlist'),
                eq(surrenderRequestsTable.status, 'scheduled')
              )
            )
          )
          .orderBy(desc(surrenderRequestsTable.createdAt))
          .limit(50),
        // Custom form submissions - pending status
        db.select({
          id: customFormSubmissions.id,
          applicantName: customFormSubmissions.signerName,
          applicantEmail: customFormSubmissions.signerEmail,
          applicantPhone: customFormSubmissions.signerPhone,
          status: customFormSubmissions.status,
          createdAt: customFormSubmissions.createdAt,
          formId: customFormSubmissions.formId,
          animalId: customFormSubmissions.animalId,
          formData: customFormSubmissions.formData,
        })
          .from(customFormSubmissions)
          .where(
            and(
              eq(customFormSubmissions.tenantId, req.tenant!.id),
              eq(customFormSubmissions.status, 'pending')
            )
          )
          .orderBy(desc(customFormSubmissions.createdAt))
          .limit(50),
      ]);

      // Get animal names for adoption applications and custom form submissions
      const adoptionAnimalIds = adoptionApps.map(a => a.animalId).filter(Boolean);
      const customFormAnimalIds = formSubmissions.map(s => s.animalId).filter((id): id is string => id !== null);
      const allAnimalIds = [...new Set([...adoptionAnimalIds, ...customFormAnimalIds])];
      
      let animalsMap = new Map<string, string>();
      if (allAnimalIds.length > 0) {
        const animalRecords = await db.select({
          id: animals.id,
          name: animals.name,
        })
          .from(animals)
          .where(inArray(animals.id, allAnimalIds));
        animalsMap = new Map(animalRecords.map(a => [a.id, a.name]));
      }

      // Get form names for custom form submissions
      const formIds = formSubmissions.map(s => s.formId).filter(Boolean);
      let formsMap = new Map<string, string>();
      if (formIds.length > 0) {
        const formRecords = await db.select({
          id: customForms.id,
          name: customForms.name,
        })
          .from(customForms)
          .where(inArray(customForms.id, formIds));
        formsMap = new Map(formRecords.map(f => [f.id, f.name]));
      }

      // Transform and combine all applications - merge all fields into formData
      const allApplications = [
        ...adoptionApps.map(app => ({
          id: app.id,
          type: 'adoption' as const,
          applicantName: app.applicantName,
          applicantEmail: app.applicantEmail,
          applicantPhone: app.applicantPhone,
          status: app.status,
          createdAt: app.createdAt?.toISOString() || new Date().toISOString(),
          animalName: app.animalId ? animalsMap.get(app.animalId) : undefined,
          animalId: app.animalId,
          formData: {
            notes: app.notes,
            ...(app.customResponses || {}),
          },
          formName: undefined,
        })),
        ...volunteerApps.map(app => ({
          id: app.id,
          type: 'volunteer' as const,
          applicantName: app.applicantName,
          applicantEmail: app.applicantEmail,
          applicantPhone: app.applicantPhone,
          status: app.status,
          createdAt: app.createdAt?.toISOString() || new Date().toISOString(),
          animalName: undefined,
          animalId: undefined,
          formData: {
            address: app.address,
            experience: app.experience,
            availability: app.availability,
            interests: app.interests,
            skills: app.skills,
            emergencyContactName: app.emergencyContactName,
            emergencyContactPhone: app.emergencyContactPhone,
            notes: app.notes,
            ...(app.customResponses || {}),
          },
          formName: undefined,
        })),
        ...fosterApps.map(app => ({
          id: app.id,
          type: 'foster' as const,
          applicantName: app.applicantName,
          applicantEmail: app.applicantEmail,
          applicantPhone: app.applicantPhone,
          status: app.status,
          createdAt: app.createdAt?.toISOString() || new Date().toISOString(),
          animalName: undefined,
          animalId: undefined,
          formData: {
            address: app.address,
            experience: app.experience,
            availability: app.availability,
            housingType: app.housingType,
            hasYard: app.hasYard,
            hasOtherPets: app.hasOtherPets,
            otherPetsDetails: app.otherPetsDetails,
            preferences: app.preferences,
            vetReference: app.vetReference,
            personalReference: app.personalReference,
            notes: app.notes,
            ...(app.customResponses || {}),
          },
          formName: undefined,
        })),
        ...phase1SurrenderRequests.map(app => ({
          id: app.id,
          type: 'surrender' as const,
          applicantName: app.applicantName,
          applicantEmail: app.applicantEmail,
          applicantPhone: app.applicantPhone,
          status: app.status,
          createdAt: app.createdAt?.toISOString() || new Date().toISOString(),
          animalName: app.dogName,
          animalId: undefined,
          formData: {
            dogName: app.dogName,
            dogBreed: app.dogBreed,
            dogAge: app.dogAge,
            dogGender: app.dogGender,
            reasonForSurrender: app.reasonForSurrender,
            medicalIssues: app.medicalIssues,
            behavioralIssues: app.behavioralIssues,
            photoUrl: app.photoUrl,
          },
          formName: undefined,
        })),
        ...formSubmissions.map(app => ({
          id: app.id,
          type: 'custom' as const,
          applicantName: app.applicantName,
          applicantEmail: app.applicantEmail,
          applicantPhone: app.applicantPhone || '',
          status: app.status,
          createdAt: app.createdAt?.toISOString() || new Date().toISOString(),
          animalName: app.animalId ? animalsMap.get(app.animalId) : undefined,
          animalId: app.animalId || undefined,
          formData: app.formData,
          formName: app.formId ? formsMap.get(app.formId) : undefined,
        })),
      ];

      // Sort all applications by date, newest first
      allApplications.sort((a, b) => 
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      );

      const counts = {
        adoption: adoptionApps.length,
        foster: fosterApps.length,
        volunteer: volunteerApps.length,
        surrender: legacySurrenderRequests.length + phase1SurrenderRequests.length,
        custom: formSubmissions.length,
        total: allApplications.length,
      };

      // Get dismissed items for this tenant
      const { dismissedWidgetItems } = await import('@shared/schema');
      const dismissedItems = await db.select({
        applicationType: dismissedWidgetItems.applicationType,
        applicationId: dismissedWidgetItems.applicationId,
      })
        .from(dismissedWidgetItems)
        .where(eq(dismissedWidgetItems.tenantId, req.tenant!.id));
      
      // Create a set for fast lookup
      const dismissedSet = new Set(
        dismissedItems.map(d => `${d.applicationType}-${d.applicationId}`)
      );
      
      // Filter out dismissed applications
      const filteredApplications = allApplications.filter(
        app => !dismissedSet.has(`${app.type}-${app.id}`)
      );
      
      // Recalculate counts after filtering
      const filteredCounts = {
        adoption: filteredApplications.filter(a => a.type === 'adoption').length,
        foster: filteredApplications.filter(a => a.type === 'foster').length,
        volunteer: filteredApplications.filter(a => a.type === 'volunteer').length,
        surrender: filteredApplications.filter(a => a.type === 'surrender').length,
        custom: filteredApplications.filter(a => a.type === 'custom').length,
        total: filteredApplications.length,
      };

      res.json({
        applications: filteredApplications.slice(0, 100), // Limit to 100 total
        counts: filteredCounts,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/dashboard/pending-applications/dismiss
   * Dismiss an application from the pending applications widget
   * This doesn't change the application status - just hides it from the widget view
   */
  app.post('/api/dashboard/pending-applications/dismiss', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { dismissedWidgetItems } = await import('@shared/schema');
      const { logActivity } = await import('./lib/activity-logger');
      const { createAuditLog } = await import('./audit');
      
      const { applicationType, applicationId, applicantName } = req.body;
      
      if (!applicationType || !applicationId) {
        return res.status(400).json({ error: 'applicationType and applicationId are required' });
      }
      
      // Validate applicationType
      const validTypes = ['adoption', 'foster', 'volunteer', 'surrender', 'custom'];
      if (!validTypes.includes(applicationType)) {
        return res.status(400).json({ error: 'Invalid applicationType' });
      }
      
      // Check if already dismissed
      const existing = await db.select({
        id: dismissedWidgetItems.id,
      })
        .from(dismissedWidgetItems)
        .where(
          and(
            eq(dismissedWidgetItems.tenantId, req.tenant!.id),
            eq(dismissedWidgetItems.applicationType, applicationType),
            eq(dismissedWidgetItems.applicationId, applicationId)
          )
        )
        .limit(1);
      
      if (existing.length > 0) {
        return res.status(200).json({ message: 'Already dismissed', alreadyDismissed: true });
      }
      
      // Insert the dismissal record
      await db.insert(dismissedWidgetItems).values({
        tenantId: req.tenant!.id,
        applicationType,
        applicationId,
        dismissedBy: req.user!.id,
      });
      
      // Log to activity feed
      await logActivity({
        tenantId: req.tenant!.id,
        userId: req.user!.id,
        entityType: 'Application',
        entityId: applicationId,
        action: 'dismissed_from_widget',
        description: `Dismissed ${applicationType} application${applicantName ? ` from ${applicantName}` : ''} from pending widget`,
        category: 'adoption',
        metadata: { applicationType, applicationId, applicantName },
      });
      
      // Log to audit log
      await createAuditLog({
        userId: req.user!.id,
        tenantId: req.tenant!.id,
        action: 'dismiss_widget_item',
        entityType: 'Application',
        entityId: applicationId,
        metadata: { applicationType, applicationId, applicantName },
        req,
      });
      
      res.json({ success: true, message: 'Application dismissed from widget' });
    } catch (error) {
      next(error);
    }
  });

  /**
   * DELETE /api/dashboard/pending-applications/dismiss/:type/:id
   * Restore a dismissed application to the pending applications widget
   */
  app.delete('/api/dashboard/pending-applications/dismiss/:type/:id', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { dismissedWidgetItems } = await import('@shared/schema');
      const { logActivity } = await import('./lib/activity-logger');
      const { createAuditLog } = await import('./audit');
      
      const { type, id } = req.params;
      
      // Validate type parameter
      const validTypes = ['adoption', 'foster', 'volunteer', 'surrender', 'custom'];
      if (!validTypes.includes(type)) {
        return res.status(400).json({ error: 'Invalid application type' });
      }
      
      // Delete the dismissal record
      const result = await db.delete(dismissedWidgetItems)
        .where(
          and(
            eq(dismissedWidgetItems.tenantId, req.tenant!.id),
            eq(dismissedWidgetItems.applicationType, type as any),
            eq(dismissedWidgetItems.applicationId, id)
          )
        )
        .returning();
      
      if (result.length === 0) {
        return res.status(404).json({ error: 'Dismissal record not found' });
      }
      
      // Log to activity feed
      await logActivity({
        tenantId: req.tenant!.id,
        userId: req.user!.id,
        entityType: 'Application',
        entityId: id,
        action: 'restored_to_widget',
        description: `Restored ${type} application to pending widget`,
        category: 'adoption',
        metadata: { applicationType: type, applicationId: id },
      });
      
      // Log to audit log
      await createAuditLog({
        userId: req.user!.id,
        tenantId: req.tenant!.id,
        action: 'restore_widget_item',
        entityType: 'Application',
        entityId: id,
        metadata: { applicationType: type, applicationId: id },
        req,
      });
      
      res.json({ success: true, message: 'Application restored to widget' });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/activity-logs
   * Get recent activity timeline for tenant admin dashboard
   * Returns logged activities with user info, color-coded by category
   */
  app.get('/api/activity-logs', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { getRecentActivity } = await import('./lib/activity-logger');
      const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);
      
      const activities = await getRecentActivity(req.tenant!.id, limit);
      res.json({ activities });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/notifications/counts
   * Get notification counts for sidebar badges (authenticated users only)
   */
  app.get('/api/notifications/counts', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { applications, supplyRequests, fosterUpdates, userInvitations, medicalDoses } = await import('@shared/schema');
      const { eq, and, or, lte, isNull } = await import('drizzle-orm');

      const today = new Date();
      today.setHours(23, 59, 59, 999);

      const { tenantTransfers } = await import('@shared/schema');

      const [
        pendingApplications,
        overdueDoses,
        pendingSupplyRequests,
        pendingFosterUpdates,
        pendingInvitations,
        pendingTransfers,
      ] = await Promise.all([
        // Count pending applications (new or screening stage)
        db.select({ count: sql<number>`count(*)::int` })
          .from(applications)
          .where(
            and(
              eq(applications.tenantId, req.tenant!.id),
              or(
                eq(applications.stage, 'new'),
                eq(applications.stage, 'screening')
              )
            )
          ),

        // Count pending/overdue medical doses (medication tasks)
        db.select({ count: sql<number>`count(*)::int` })
          .from(medicalDoses)
          .where(
            and(
              eq(medicalDoses.tenantId, req.tenant!.id),
              or(
                eq(medicalDoses.status, 'pending'),
                eq(medicalDoses.status, 'overdue')
              ),
              lte(medicalDoses.dueDate, today)
            )
          ),

        // Count pending supply requests
        db.select({ count: sql<number>`count(*)::int` })
          .from(supplyRequests)
          .where(
            and(
              eq(supplyRequests.tenantId, req.tenant!.id),
              eq(supplyRequests.status, 'pending')
            )
          ),

        // Count pending foster updates
        db.select({ count: sql<number>`count(*)::int` })
          .from(fosterUpdates)
          .where(
            and(
              eq(fosterUpdates.tenantId, req.tenant!.id),
              eq(fosterUpdates.status, 'pending')
            )
          ),

        // Count pending team invitations
        db.select({ count: sql<number>`count(*)::int` })
          .from(userInvitations)
          .where(
            and(
              eq(userInvitations.tenantId, req.tenant!.id),
              isNull(userInvitations.acceptedAt)
            )
          ),

        // Count pending transfers (incoming or outgoing)
        db.select({ count: sql<number>`count(*)::int` })
          .from(tenantTransfers)
          .where(
            and(
              eq(tenantTransfers.status, 'pending'),
              or(
                eq(tenantTransfers.sendingTenantId, req.tenant!.id),
                eq(tenantTransfers.receivingTenantId, req.tenant!.id)
              )
            )
          ),
      ]);

      const counts = {
        applications: pendingApplications[0]?.count || 0,
        medicalTasks: overdueDoses[0]?.count || 0,
        supplyRequests: pendingSupplyRequests[0]?.count || 0,
        fosterUpdates: pendingFosterUpdates[0]?.count || 0,
        teamInvitations: pendingInvitations[0]?.count || 0,
        pendingTransfers: pendingTransfers[0]?.count || 0,
      };

      res.json({ counts });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/reports
   * Get comprehensive analytics and metrics for reports page
   */
  app.get('/api/reports', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { animals, adoptions, donations, expenditures, users } = await import('@shared/schema');
      const { eq, and, sql, gte, lte } = await import('drizzle-orm');
      
      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
      const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
      const startOfYear = new Date(now.getFullYear(), 0, 1);
      const endOfYear = new Date(now.getFullYear(), 11, 31, 23, 59, 59);
      
      // Run all database queries in parallel for better performance
      const [
        allAnimals,
        allAdoptions,
        donationsThisMonth,
        donationsYTD,
        expendituresThisMonth,
        expendituresYTD,
        fosters
      ] = await Promise.all([
        // Get all animals for intake calculations - explicit field selection for dynamic import
        db.select({
          id: animals.id,
          intakeDate: animals.intakeDate,
        }).from(animals).where(eq(animals.tenantId, req.tenant!.id)),
        // Get all adoptions for adoption calculations - explicit field selection
        db.select({
          id: adoptions.id,
          animalId: adoptions.animalId,
          adoptionDate: adoptions.adoptionDate,
        }).from(adoptions).where(eq(adoptions.tenantId, req.tenant!.id)),
        // Get donations this month (with upper bound to exclude future dates)
        db.select({
          id: donations.id,
          amount: donations.amount,
          donationType: donations.donationType,
          estimatedValue: donations.estimatedValue,
        }).from(donations).where(
          and(
            eq(donations.tenantId, req.tenant!.id),
            gte(donations.date, startOfMonth),
            lte(donations.date, endOfMonth)
          )
        ),
        // Get donations YTD (with upper bound to exclude future dates)
        db.select({
          id: donations.id,
          amount: donations.amount,
          donationType: donations.donationType,
          estimatedValue: donations.estimatedValue,
        }).from(donations).where(
          and(
            eq(donations.tenantId, req.tenant!.id),
            gte(donations.date, startOfYear),
            lte(donations.date, endOfYear)
          )
        ),
        // Get expenditures this month (with upper bound to exclude future dates)
        db.select({
          id: expenditures.id,
          amount: expenditures.amount,
        }).from(expenditures).where(
          and(
            eq(expenditures.tenantId, req.tenant!.id),
            gte(expenditures.date, startOfMonth),
            lte(expenditures.date, endOfMonth)
          )
        ),
        // Get expenditures YTD (with upper bound to exclude future dates)
        db.select({
          id: expenditures.id,
          amount: expenditures.amount,
        }).from(expenditures).where(
          and(
            eq(expenditures.tenantId, req.tenant!.id),
            gte(expenditures.date, startOfYear),
            lte(expenditures.date, endOfYear)
          )
        ),
        // Get active fosters (users with foster role)
        db.select({
          id: users.id,
        }).from(users).where(
          and(
            eq(users.tenantId, req.tenant!.id),
            sql`'foster' = ANY(${users.roles})`
          )
        )
      ]);
      
      // Calculate metrics
      const intakesThisMonth = allAnimals.filter(a => {
        if (!a.intakeDate) return false;
        const intakeDate = new Date(a.intakeDate);
        return intakeDate >= startOfMonth;
      }).length;
      
      const intakesYTD = allAnimals.filter(a => {
        if (!a.intakeDate) return false;
        const intakeDate = new Date(a.intakeDate);
        return intakeDate >= startOfYear;
      }).length;
      
      const adoptionsThisMonth = allAdoptions.filter(a => {
        const adoptionDate = new Date(a.adoptionDate);
        return adoptionDate >= startOfMonth;
      }).length;
      
      const adoptionsYTD = allAdoptions.filter(a => {
        const adoptionDate = new Date(a.adoptionDate);
        return adoptionDate >= startOfYear;
      }).length;
      
      // Calculate average length of stay for adopted animals
      const adoptedAnimals = allAdoptions
        .map(adoption => {
          const animal = allAnimals.find(a => a.id === adoption.animalId);
          if (!animal || !animal.intakeDate) return null;
          
          const intakeDate = new Date(animal.intakeDate);
          const adoptionDate = new Date(adoption.adoptionDate);
          const daysInCare = Math.floor((adoptionDate.getTime() - intakeDate.getTime()) / (1000 * 60 * 60 * 24));
          
          return daysInCare;
        })
        .filter((days): days is number => days !== null && days >= 0);
      
      const avgLengthOfStay = adoptedAnimals.length > 0
        ? Math.round(adoptedAnimals.reduce((sum, days) => sum + days, 0) / adoptedAnimals.length)
        : 0;
      
      // Separate cash/check/online donations from in-kind (treat NULL as cash for backward compatibility)
      const inKindTypes = ['in_kind', 'in_kind_goods', 'in_kind_services'];
      const cashDonationsThisMonth = donationsThisMonth.filter(d => !inKindTypes.includes(d.donationType || 'cash'));
      const cashDonationsYTD = donationsYTD.filter(d => !inKindTypes.includes(d.donationType || 'cash'));
      const inKindDonationsThisMonth = donationsThisMonth.filter(d => inKindTypes.includes(d.donationType || ''));
      const inKindDonationsYTD = donationsYTD.filter(d => inKindTypes.includes(d.donationType || ''));
      
      const totalDonationsThisMonth = cashDonationsThisMonth.reduce((sum, d) => sum + Number(d.amount || 0), 0);
      const totalDonationsYTD = cashDonationsYTD.reduce((sum, d) => sum + Number(d.amount || 0), 0);
      const totalInKindValueThisMonth = inKindDonationsThisMonth.reduce((sum, d) => sum + Number(d.estimatedValue || 0), 0);
      const totalInKindValueYTD = inKindDonationsYTD.reduce((sum, d) => sum + Number(d.estimatedValue || 0), 0);
      const totalExpendituresThisMonth = expendituresThisMonth.reduce((sum, e) => sum + Number(e.amount), 0);
      const totalExpendituresYTD = expendituresYTD.reduce((sum, e) => sum + Number(e.amount), 0);
      
      const metrics = {
        intakesThisMonth,
        intakesYTD,
        adoptionsThisMonth,
        adoptionsYTD,
        avgLengthOfStay,
        totalDonationsThisMonth,
        totalDonationsYTD,
        totalInKindValueThisMonth,
        totalInKindValueYTD,
        inKindCountThisMonth: inKindDonationsThisMonth.length,
        inKindCountYTD: inKindDonationsYTD.length,
        totalExpendituresThisMonth,
        totalExpendituresYTD,
        activeFosters: fosters.length,
      };
      
      res.json({ metrics });
    } catch (error) {
      next(error);
    }
  });

