  /**
   * GET /api/users
   * List all users in tenant (admin/staff only)
   */
  app.get('/api/users', requireTenant, requireAuth, requireRole('owner', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { users, contacts } = await import('@shared/schema');
      
      const userList = await db
        .select({
          id: users.id,
          email: users.email,
          fullName: users.fullName,
          roles: users.roles,
          tags: users.tags,
          phone: sql<string | null>`COALESCE(${users.phone}, ${contacts.phone})`,
          createdAt: users.createdAt,
          smsOptIn: users.smsOptIn,
          dailySmsOptIn: users.dailySmsOptIn,
          hasPushSubscription: sql<boolean>`EXISTS (
            SELECT 1 FROM push_subscriptions ps 
            WHERE ps.user_id = ${users.id} 
            AND ps.tenant_id = ${req.tenant!.id}
            AND ps.is_enabled = true
          )`,
        })
        .from(users)
        .leftJoin(contacts, eq(users.id, contacts.userId))
        .where(eq(users.tenantId, req.tenant!.id))
        .orderBy(desc(users.createdAt));
      
      res.json({ users: userList });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/audit-logs
   * Get tenant-scoped audit logs (admin/owner only)
   */
