  /**
   * PATCH /api/users/:id
   * Update user role (admin only)
   */
  app.patch('/api/users/:id', requireTenant, requireAuth, requireRole('owner', 'admin'), async (req, res, next) => {
    try {
      const { users } = await import('@shared/schema');
      
      const updateSchema = z.object({
        roles: z.array(z.enum(['admin', 'board_member', 'staff', 'foster', 'volunteer'])).min(1).optional(),
        fullName: z.string().min(1).optional(),
        tags: z.array(z.string().max(50)).max(20).optional(),
      });

      const data = updateSchema.parse(req.body);

      const [updatedUser] = await db
        .update(users)
        .set(data)
        .where(
          and(
            eq(users.id, req.params.id),
            eq(users.tenantId, req.tenant!.id)
          )
        )
        .returning({
          id: users.id,
          email: users.email,
          fullName: users.fullName,
          roles: users.roles,
          tags: users.tags,
          phone: users.phone,
          createdAt: users.createdAt,
        });

      if (!updatedUser) {
        return res.status(404).json({ error: 'User not found' });
      }

      // Sync the updated user information to contacts
      try {
        const { syncContactFromUser } = await import('./services/contacts');
        await syncContactFromUser(
          updatedUser.id,
          req.tenant!.id,
          updatedUser.email,
          updatedUser.fullName,
          updatedUser.roles.filter(r => r !== 'platform_admin') as any[]
        );
      } catch (error) {
        console.error('Failed to sync updated user to contacts:', error);
        // Don't fail the user update if contact sync fails
      }

      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'user.role_update',
          entityType: 'user',
          entityId: req.params.id,
          changes: { after: { roles: data.roles, fullName: data.fullName } },
          metadata: { targetUserEmail: updatedUser.email, targetUserName: updatedUser.fullName },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      res.json({ success: true, user: updatedUser });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/users/:id/sms-prefs
   * Update a user's SMS notification preferences (admin/owner only)
   * Used by Team Management to toggle dailySmsOptIn for foster users
   */
  app.patch('/api/users/:id/sms-prefs', requireTenant, requireAuth, requireRole('owner', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { users } = await import('@shared/schema');
      const updateSchema = z.object({
        dailySmsOptIn: z.boolean().optional(),
        smsRecruitmentOptIn: z.boolean().optional(),
      }).refine(d => d.dailySmsOptIn !== undefined || d.smsRecruitmentOptIn !== undefined, {
        message: 'At least one field must be provided',
      });
      const data = updateSchema.parse(req.body);

      const setFields: Record<string, unknown> = {};
      if (data.dailySmsOptIn !== undefined) setFields.dailySmsOptIn = data.dailySmsOptIn;
      if (data.smsRecruitmentOptIn !== undefined) setFields.smsRecruitmentOptIn = data.smsRecruitmentOptIn;

      const [updatedUser] = await db
        .update(users)
        .set(setFields as any)
        .where(
          and(
            eq(users.id, req.params.id),
            eq(users.tenantId, req.tenant!.id)
          )
        )
        .returning({
          id: users.id,
          email: users.email,
          fullName: users.fullName,
          roles: users.roles,
          dailySmsOptIn: users.dailySmsOptIn,
          smsRecruitmentOptIn: users.smsRecruitmentOptIn,
        });

      if (!updatedUser) {
        return res.status(404).json({ error: 'User not found' });
      }

      res.json({ success: true, user: updatedUser });
    } catch (error) {
      next(error);
    }
  });

