  /**
   * GET /api/animals/duplicates
   * Find potential duplicate animal profiles based on name similarity, breed, and intake date
   * NOTE: This route MUST be defined before /api/animals/:id to prevent "duplicates" from being matched as an animal ID
   */
  app.get('/api/animals/duplicates', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const tenantId = req.tenant!.id;
      
      // Levenshtein distance algorithm for fuzzy string matching
      function levenshteinDistance(str1: string, str2: string): number {
        const m = str1.length;
        const n = str2.length;
        // Create a matrix of distances
        const dp: number[][] = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));
        // Initialize first row and column
        for (let i = 0; i <= m; i++) dp[i][0] = i;
        for (let j = 0; j <= n; j++) dp[0][j] = j;
        // Fill in the rest of the matrix
        for (let i = 1; i <= m; i++) {
          for (let j = 1; j <= n; j++) {
            if (str1[i - 1] === str2[j - 1]) {
              dp[i][j] = dp[i - 1][j - 1];
            } else {
              dp[i][j] = 1 + Math.min(
                dp[i - 1][j],     // deletion
                dp[i][j - 1],     // insertion
                dp[i - 1][j - 1]  // substitution
              );
            }
          }
        }
        return dp[m][n];
      }
      
      // Calculate name similarity score (0-1, higher is more similar)
      function nameSimilarityScore(name1: string, name2: string): number {
        const s1 = name1.toLowerCase().trim();
        const s2 = name2.toLowerCase().trim();
        // Exact match
        if (s1 === s2) return 1.0;
        // One contains the other (e.g., "Max" vs "Maxy")
        if (s1.includes(s2) || s2.includes(s1)) {
          return 0.9;
        }
        // Levenshtein-based similarity
        const distance = levenshteinDistance(s1, s2);
        const maxLen = Math.max(s1.length, s2.length);
        if (maxLen === 0) return 1.0;
        const similarity = 1 - (distance / maxLen);
        return similarity;
      }
      
      // Get all active animals (not merged, not deceased)
      // Using explicit field selection for dynamic import compatibility
      const allAnimals = await db.select({
        id: animals.id,
        name: animals.name,
        species: animals.species,
        breed: animals.breed,
        status: animals.status,
        intakeDate: animals.intakeDate,
        photoUrls: animals.photoUrls,
      }).from(animals)
        .where(and(
          eq(animals.tenantId, tenantId),
          not(eq(animals.status, 'deceased'))
        ))
        .orderBy(animals.name);
      
      // Find potential duplicates based on name similarity + breed + intake date proximity
      const duplicateGroups: Array<{
        animals: typeof allAnimals;
        matchReason: string;
        confidence: 'high' | 'medium' | 'low';
        nameSimilarity: number;
      }> = [];
      
      const usedIds = new Set<string>();
      
      // Threshold for name similarity (0.7 = 70% similar)
      const NAME_SIMILARITY_THRESHOLD = 0.65;
      
      for (let i = 0; i < allAnimals.length; i++) {
        if (usedIds.has(allAnimals[i].id)) continue;
        const matches: typeof allAnimals = [];
        const allReasons = new Set<string>();
        let highestNameSimilarity = 0;
        let hasAnyBreedMatch = false;
        let hasAnyDateMatch = false;
        for (let j = i + 1; j < allAnimals.length; j++) {
          if (usedIds.has(allAnimals[j].id)) continue;
          
          const a = allAnimals[i];
          const b = allAnimals[j];
          
          // Skip very short names (3 chars or less) to avoid false positives
          if (a.name.length <= 3 || b.name.length <= 3) {
            // For short names, require exact match or one being a substring
            const nameA = a.name.toLowerCase().trim();
            const nameB = b.name.toLowerCase().trim();
            if (nameA !== nameB && !nameA.includes(nameB) && !nameB.includes(nameA)) {
              continue;
            }
          }
          
          // Calculate name similarity using Levenshtein distance
          const similarity = nameSimilarityScore(a.name, b.name);
          const nameSimilar = similarity >= NAME_SIMILARITY_THRESHOLD;
          
          // Check breed match
          const breedMatch = a.breed && b.breed && 
            a.breed.toLowerCase() === b.breed.toLowerCase();
          
          // Check species match
          const speciesMatch = a.species.toLowerCase() === b.species.toLowerCase();
          
          // Check intake date proximity (within 7 days)
          const intakeDateProximity = a.intakeDate && b.intakeDate &&
            Math.abs(new Date(a.intakeDate).getTime() - new Date(b.intakeDate).getTime()) < 7 * 24 * 60 * 60 * 1000;
          
          // Determine if this is a potential duplicate
          // Name similarity is now the PRIMARY factor
          if (nameSimilar && speciesMatch) {
            // Track the best name match quality across all pairs
            if (similarity >= 0.95) {
              allReasons.add('Nearly identical names');
            } else if (similarity >= 0.85) {
              allReasons.add('Very similar names');
            } else {
              allReasons.add('Similar names');
            }
            
            allReasons.add('Same species');
            if (breedMatch) {
              allReasons.add('Same breed');
              hasAnyBreedMatch = true;
            }
            if (intakeDateProximity) {
              allReasons.add('Similar intake dates');
              hasAnyDateMatch = true;
            }
            
            matches.push(b);
            highestNameSimilarity = Math.max(highestNameSimilarity, similarity);
            usedIds.add(b.id);
          }
        }
        if (matches.length > 0) {
          usedIds.add(allAnimals[i].id);
          const allMatches = [allAnimals[i], ...matches];
          
          // Convert reasons set to array and determine confidence
          const matchReasons = Array.from(allReasons);
          const hasNearlyIdenticalNames = allReasons.has('Nearly identical names');
          const hasVerySimilarNames = allReasons.has('Very similar names');
          
          let confidence: 'high' | 'medium' | 'low' = 'low';
          
          // High confidence: Nearly identical names, or very similar + breed/date match
          if (hasNearlyIdenticalNames) {
            confidence = 'high';
          } else if (hasVerySimilarNames && (hasAnyBreedMatch || hasAnyDateMatch)) {
            confidence = 'high';
          } else if (hasVerySimilarNames || (hasAnyBreedMatch && hasAnyDateMatch)) {
            confidence = 'medium';
          }
          
          duplicateGroups.push({
            animals: allMatches,
            matchReason: matchReasons.join(', '),
            confidence,
            nameSimilarity: Math.round(highestNameSimilarity * 100),
          });
        }
      }
      
      // Sort by confidence (high first), then by name similarity
      duplicateGroups.sort((a, b) => {
        const order = { high: 0, medium: 1, low: 2 };
        if (order[a.confidence] !== order[b.confidence]) {
          return order[a.confidence] - order[b.confidence];
        }
        return b.nameSimilarity - a.nameSimilarity;
      });
      
      res.json({ duplicateGroups });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/animals/lookup
   * Search animals by name, microchip number, or animalId
   * Returns all animals regardless of status with basic info and counts
   */
  app.get('/api/animals/lookup', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { animals, fosterAnimals, adoptions } = await import('@shared/schema');
      const { ilike } = await import('drizzle-orm');
      const tenantId = req.tenant!.id;
      const q = req.query.q as string;

      if (!q || q.trim().length < 2) {
        return res.status(400).json({ error: 'Search query must be at least 2 characters' });
      }

      const searchTerm = `%${q.trim()}%`;

      const animalResults = await db
        .select({
          id: animals.id,
          animalId: animals.animalId,
          name: animals.name,
          species: animals.species,
          breed: animals.breed,
          age: animals.age,
          status: animals.status,
          photoUrls: animals.photoUrls,
          intakeDate: animals.intakeDate,
          sex: animals.sex,
          petfinderBreed: animals.petfinderBreed,
          petfinderType: animals.petfinderType,
          fosterCount: sql<number>`(SELECT COUNT(*) FROM foster_animals WHERE foster_animals.animal_id = ${animals.id})::int`,
        })
        .from(animals)
        .where(
          and(
            eq(animals.tenantId, tenantId),
            or(
              ilike(animals.name, searchTerm),
              ilike(animals.microchipNumber, searchTerm),
              ilike(animals.animalId, searchTerm)
            )
          )
        )
        .orderBy(asc(animals.name))
        .limit(50);

      const animalIds = animalResults.map(a => a.id);
      let adoptionMap: Record<string, { adopterName: string | null; adoptionDate: Date | null }> = {};
      if (animalIds.length > 0) {
        const adoptionResults = await db
          .select({
            animalId: adoptions.animalId,
            adopterName: adoptions.adopterName,
            adoptionDate: adoptions.adoptionDate,
          })
          .from(adoptions)
          .where(
            and(
              eq(adoptions.tenantId, tenantId),
              inArray(adoptions.animalId, animalIds)
            )
          );
        for (const a of adoptionResults) {
          adoptionMap[a.animalId] = { adopterName: a.adopterName, adoptionDate: a.adoptionDate };
        }
      }

      const results = animalResults.map(a => ({
        ...a,
        photoUrls: a.photoUrls && a.photoUrls.length > 0 ? [a.photoUrls[0]] : [],
        adoptionInfo: adoptionMap[a.id] || null,
      }));

      res.json({ animals: results });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/animals/:id/full-profile
   * Returns comprehensive data for a single animal including foster history,
   * adoption info, medical summary, placement agreements, and applications
   */
  app.get('/api/animals/:id/full-profile', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { fosterAnimals, adoptions, users, medicalExams, applications, placementAgreementSessions, adoptionCheckoutSessions, adoptionContracts } = await import('@shared/schema');
      const { getAnimalById } = await import('./services/animals');
      const tenantId = req.tenant!.id;
      const animalId = req.params.id;

      const animal = await getAnimalById(tenantId, animalId);
      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      const fosterHistory = await db
        .select({
          id: fosterAnimals.id,
          fosterId: fosterAnimals.fosterId,
          fosterName: users.fullName,
          fosterEmail: users.email,
          startDate: fosterAnimals.startDate,
          expectedReturnDate: fosterAnimals.expectedReturnDate,
          actualReturnDate: fosterAnimals.actualReturnDate,
          status: fosterAnimals.status,
          notes: fosterAnimals.notes,
        })
        .from(fosterAnimals)
        .leftJoin(users, eq(fosterAnimals.fosterId, users.id))
        .where(
          and(
            eq(fosterAnimals.animalId, animalId),
            eq(fosterAnimals.tenantId, tenantId)
          )
        )
        .orderBy(desc(fosterAnimals.startDate));

      const adoptionRecords = await db
        .select({
          id: adoptions.id,
          applicationId: adoptions.applicationId,
          adopterName: adoptions.adopterName,
          adopterEmail: adoptions.adopterEmail,
          adopterPhone: adoptions.adopterPhone,
          adoptionDate: adoptions.adoptionDate,
          adoptionFee: adoptions.adoptionFee,
          notes: adoptions.notes,
        })
        .from(adoptions)
        .where(
          and(
            eq(adoptions.animalId, animalId),
            eq(adoptions.tenantId, tenantId)
          )
        )
        .orderBy(desc(adoptions.adoptionDate));

      const adoptionContractRecords = await db
        .select({
          sessionId: adoptionCheckoutSessions.id,
          contractId: adoptionContracts.id,
          applicationId: adoptionCheckoutSessions.applicationId,
          sessionStatus: adoptionCheckoutSessions.status,
          baseFee: adoptionCheckoutSessions.baseFee,
          signedAt: adoptionCheckoutSessions.signedAt,
          paidAt: adoptionCheckoutSessions.paidAt,
          contractPdfUrl: adoptionContracts.contractPdfUrl,
          signerName: adoptionContracts.signerName,
          signerEmail: adoptionContracts.signerEmail,
          contractSignedAt: adoptionContracts.signedAt,
        })
        .from(adoptionCheckoutSessions)
        .leftJoin(adoptionContracts, eq(adoptionContracts.sessionId, adoptionCheckoutSessions.id))
        .where(
          and(
            eq(adoptionCheckoutSessions.animalId, animalId),
            eq(adoptionCheckoutSessions.tenantId, tenantId),
            eq(adoptionCheckoutSessions.status, 'completed')
          )
        )
        .orderBy(desc(adoptionCheckoutSessions.signedAt));

      const adoptionInfo = adoptionRecords.length > 0 ? adoptionRecords[0] : null;

      const examCountResult = await db
        .select({ count: sql<number>`COUNT(*)::int` })
        .from(medicalExams)
        .where(
          and(
            eq(medicalExams.animalId, animalId),
            eq(medicalExams.tenantId, tenantId)
          )
        );

      const latestAgreement = await db
        .select({
          status: placementAgreementSessions.status,
          contractPdfUrl: placementAgreementSessions.contractPdfUrl,
          signedAt: placementAgreementSessions.signedAt,
          fosterName: placementAgreementSessions.fosterName,
        })
        .from(placementAgreementSessions)
        .where(
          and(
            eq(placementAgreementSessions.animalId, animalId),
            eq(placementAgreementSessions.tenantId, tenantId),
            eq(placementAgreementSessions.status, 'signed')
          )
        )
        .orderBy(desc(placementAgreementSessions.signedAt))
        .limit(1);

      const applicationHistory = await db
        .select({
          id: applications.id,
          applicantName: applications.applicantName,
          applicantEmail: applications.applicantEmail,
          stage: applications.stage,
          createdAt: applications.createdAt,
        })
        .from(applications)
        .where(
          and(
            eq(applications.animalId, animalId),
            eq(applications.tenantId, tenantId)
          )
        )
        .orderBy(desc(applications.createdAt));

      res.json({
        animal,
        fosterHistory,
        adoptionInfo,
        adoptionRecords,
        adoptionContractRecords,
        medicalSummary: {
          examCount: examCountResult[0]?.count || 0,
        },
        placementAgreement: latestAgreement.length > 0 ? latestAgreement[0] : null,
        applicationHistory,
      });
    } catch (error) {
      next(error);
    }
  });

