  app.post('/api/adoption-contracts/:contractId/regenerate-pdf', requireTenant, requireAuth, requireRole('admin', 'owner', 'manager'), async (req, res, next) => {
    try {
      const tenantId = req.tenant!.id;
      const contractId = parseInt(req.params.contractId);

      const [contract] = await db
        .select()
        .from(adoptionContracts)
        .where(eq(adoptionContracts.id, contractId))
        .limit(1);

      if (!contract) {
        return res.status(404).json({ error: 'Contract not found' });
      }

      const [session] = await db
        .select()
        .from(adoptionCheckoutSessions)
        .where(
          and(
            eq(adoptionCheckoutSessions.id, contract.sessionId),
            eq(adoptionCheckoutSessions.tenantId, tenantId)
          )
        )
        .limit(1);

      if (!session) {
        return res.status(404).json({ error: 'Adoption session not found for this tenant' });
      }

      const { generateAdoptionContractPDF } = await import('./services/contract-pdf');
      const newPdfUrl = await generateAdoptionContractPDF(session, contract.signatureImageUrl || undefined, {
        ipAddress: contract.signedIp || undefined,
        signedAt: contract.signedAt,
        driversLicenseNumber: (contract as any).driversLicenseNumber || undefined,
      });

      await db
        .update(adoptionContracts)
        .set({ contractPdfUrl: newPdfUrl })
        .where(eq(adoptionContracts.id, contractId));

      res.json({ contractPdfUrl: newPdfUrl });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/animals/search-duplicates
   * Search for potential duplicate animals by microchip number and/or name
   * Used during intake to prevent creating duplicate records
   * Searches across ALL statuses including archived animals
   * NOTE: This route MUST be defined before /api/animals/:id
   */
  app.get('/api/animals/search-duplicates', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const tenantId = req.tenant!.id;
      const { microchip, name } = req.query;
      
      if (!microchip && !name) {
        return res.status(400).json({ error: 'At least one search parameter (microchip or name) is required' });
      }

      const results: {
        microchipMatches: any[];
        nameMatches: any[];
      } = {
        microchipMatches: [],
        nameMatches: []
      };

      // Microchip exact match search (strict - returns exact match only)
      if (microchip && typeof microchip === 'string' && microchip.trim()) {
        const microchipValue = microchip.trim();
        const microchipResults = await db.select({
          id: animals.id,
          name: animals.name,
          status: animals.status,
          species: animals.species,
          breed: animals.breed,
          photoUrls: animals.photoUrls,
          microchipNumber: animals.microchipNumber,
          intakeDate: animals.intakeDate,
        }).from(animals)
          .where(and(
            eq(animals.tenantId, tenantId),
            eq(animals.microchipNumber, microchipValue)
          ));
        results.microchipMatches = microchipResults.map(a => ({
          ...a,
          matchType: 'microchip_exact' as const
        }));
      }

      // Name fuzzy search (case-insensitive prefix/contains)
      if (name && typeof name === 'string' && name.trim().length >= 2) {
        const nameValue = name.trim().toLowerCase();
        // Get all animals for fuzzy matching
        const allAnimals = await db.select({
          id: animals.id,
          name: animals.name,
          status: animals.status,
          species: animals.species,
          breed: animals.breed,
          photoUrls: animals.photoUrls,
          microchipNumber: animals.microchipNumber,
          intakeDate: animals.intakeDate,
        }).from(animals)
          .where(eq(animals.tenantId, tenantId));

        // Simple Levenshtein distance for fuzzy matching
        function levenshteinDistance(str1: string, str2: string): number {
          const m = str1.length;
          const n = str2.length;
          const dp: number[][] = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));
          for (let i = 0; i <= m; i++) dp[i][0] = i;
          for (let j = 0; j <= n; j++) dp[0][j] = j;
          for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= n; j++) {
              if (str1[i - 1] === str2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
              } else {
                dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
              }
            }
          }
          return dp[m][n];
        }

        // Find matches
        const nameMatches = allAnimals
          .map(animal => {
            const animalName = (animal.name || '').toLowerCase();
            
            // Exact match
            if (animalName === nameValue) {
              return { ...animal, matchType: 'name_exact' as const, similarity: 1.0 };
            }
            
            // Prefix match (e.g., "Max" matches "Maxy")
            if (animalName.startsWith(nameValue) || nameValue.startsWith(animalName)) {
              return { ...animal, matchType: 'name_prefix' as const, similarity: 0.9 };
            }
            
            // Contains match
            if (animalName.includes(nameValue) || nameValue.includes(animalName)) {
              return { ...animal, matchType: 'name_contains' as const, similarity: 0.85 };
            }
            
            // Levenshtein similarity (for typos)
            const distance = levenshteinDistance(animalName, nameValue);
            const maxLen = Math.max(animalName.length, nameValue.length);
            const similarity = maxLen > 0 ? 1 - (distance / maxLen) : 0;
            
            if (similarity >= 0.7) {
              return { ...animal, matchType: 'name_similar' as const, similarity };
            }
            
            return null;
          })
          .filter((m): m is NonNullable<typeof m> => m !== null)
          .sort((a, b) => b.similarity - a.similarity)
          .slice(0, 10); // Limit to top 10 matches

        // Exclude animals already in microchip matches
        const microchipIds = new Set(results.microchipMatches.map(m => m.id));
        results.nameMatches = nameMatches.filter(m => !microchipIds.has(m.id));
      }

      res.json(results);
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/merge
   * Merge two animal profiles - keeps primary, archives secondary, reassigns related records
   * Uses a database transaction to ensure atomicity
   * NOTE: This route MUST be defined before /api/animals/:id
   */
  app.post('/api/animals/merge', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      // PRE-WARM: Wake up Neon connection before doing any work
      // This absorbs cold-start latency before the timeout-sensitive operations
      await db.execute(sql`SELECT 1`);
      
      const tenantId = req.tenant!.id;
      const userId = req.user!.id;
      const { primaryAnimalId, secondaryAnimalId, fieldChoices, notes } = req.body;
      
      if (!primaryAnimalId || !secondaryAnimalId) {
        return res.status(400).json({ error: 'Both primaryAnimalId and secondaryAnimalId are required' });
      }
      
      if (primaryAnimalId === secondaryAnimalId) {
        return res.status(400).json({ error: 'Cannot merge an animal with itself' });
      }
      
      // Whitelist of allowed fields that can be merged
      const allowedMergeFields = new Set([
        'name', 'species', 'breed', 'age', 'sex',
        'weight', 'bio', 'medicalAlertMemo',
        'microchipNumber', 'intakeDate', 'intakeSource',
        'dogFriendly', 'catFriendly', 'childFriendly',
        'houseTrained', 'neuterStatus', 'specialNeeds',
        'shotsCurrent', 'heartwormPositive',
        'behaviorColor', 'behaviorRestrictionReason',
        'activityLevel', 'dietaryRestrictions', 'needsFence',
        'kennelLocation', 'kennelBuildingId', 'kennelRowId', 'kennelPosition',
        'petfinderType', 'petfinderBreed', 'petfinderBreedSecondary',
        'petfinderAge', 'petfinderSize', 'petfinderGender'
      ]);
      
      // Validate fieldChoices if provided
      if (fieldChoices && typeof fieldChoices === 'object') {
        for (const [field, choice] of Object.entries(fieldChoices)) {
          if (!allowedMergeFields.has(field)) {
            return res.status(400).json({ error: `Field '${field}' is not allowed to be merged` });
          }
          if (choice !== 'primary' && choice !== 'secondary') {
            return res.status(400).json({ error: `Invalid choice '${choice}' for field '${field}'. Must be 'primary' or 'secondary'` });
          }
        }
      }
      
      // Fetch both animals before transaction with error handling
      // Using explicit field selection for dynamic import compatibility
      const mergeSelectFields = {
          id: animals.id,
          name: animals.name,
          species: animals.species,
          breed: animals.breed,
          age: animals.age,
          sex: animals.sex,
          weight: animals.weight,
          bio: animals.bio,
          medicalAlertMemo: animals.medicalAlertMemo,
          microchipNumber: animals.microchipNumber,
          status: animals.status,
          intakeDate: animals.intakeDate,
          intakeSource: animals.intakeSource,
          photoUrls: animals.photoUrls,
          neuterStatus: animals.neuterStatus,
          specialNeeds: animals.specialNeeds,
          shotsCurrent: animals.shotsCurrent,
          heartwormPositive: animals.heartwormPositive,
          houseTrained: animals.houseTrained,
          dogFriendly: animals.dogFriendly,
          catFriendly: animals.catFriendly,
          childFriendly: animals.childFriendly,
          needsFence: animals.needsFence,
          behaviorColor: animals.behaviorColor,
          behaviorRestrictionReason: animals.behaviorRestrictionReason,
          activityLevel: animals.activityLevel,
          dietaryRestrictions: animals.dietaryRestrictions,
          kennelLocation: animals.kennelLocation,
          kennelBuildingId: animals.kennelBuildingId,
          kennelRowId: animals.kennelRowId,
          kennelPosition: animals.kennelPosition,
          petfinderType: animals.petfinderType,
          petfinderBreed: animals.petfinderBreed,
          petfinderBreedSecondary: animals.petfinderBreedSecondary,
          petfinderAge: animals.petfinderAge,
          petfinderSize: animals.petfinderSize,
          petfinderGender: animals.petfinderGender,
          tenantId: animals.tenantId,
        };
      let primaryAnimal, secondaryAnimal;
      try {
        const [primary] = await db.select(mergeSelectFields).from(animals)
          .where(and(eq(animals.id, primaryAnimalId), eq(animals.tenantId, tenantId)));
        const [secondary] = await db.select(mergeSelectFields).from(animals)
          .where(and(eq(animals.id, secondaryAnimalId), eq(animals.tenantId, tenantId)));
        primaryAnimal = primary;
        secondaryAnimal = secondary;
      } catch (fetchError: any) {
        console.error('Error fetching animals for merge:', fetchError?.message || fetchError);
        return res.status(503).json({ 
          error: 'Merge failed: ' + (fetchError?.message || 'Database temporarily unavailable'),
          details: fetchError?.message || 'Failed to fetch animal records'
        });
      }
      
      if (!primaryAnimal || !secondaryAnimal) {
        return res.status(404).json({ error: 'One or both animals not found' });
      }
      
      if (secondaryAnimal.status === 'adopted' || secondaryAnimal.status === 'transported' || secondaryAnimal.status === 'deceased') {
        return res.status(400).json({ error: 'Cannot merge a terminal-status animal' });
      }
      
      // Create snapshot of secondary animal before merge
      const secondaryAnimalSnapshot = { ...secondaryAnimal };
      
      // Track reassignment counts
      let reassignedMedicalRecords = 0;
      let reassignedPhotos = 0;
      let reassignedApplications = 0;
      let reassignedNotes = 0;
      let updatedPrimary: typeof primaryAnimal | undefined;
      
      console.log(`[MERGE] Starting merge: ${secondaryAnimal.name} -> ${primaryAnimal.name}`);
      const mergeStartTime = Date.now();
      
      // Prepare field updates outside transaction
      const updateData: Record<string, any> = {};
      if (fieldChoices && typeof fieldChoices === 'object') {
        for (const [field, choice] of Object.entries(fieldChoices)) {
          if (choice === 'secondary' && allowedMergeFields.has(field)) {
            const secondaryValue = (secondaryAnimal as any)[field];
            if (secondaryValue !== null && secondaryValue !== undefined && secondaryValue !== '') {
              updateData[field] = secondaryValue;
            }
          }
        }
      }
      
      // Note: Secondary animal photos are NOT merged - only primary photos are kept
      // This simplifies the merge and reduces timeout risk
      
      // MINIMAL TRANSACTION: Only the critical animal status changes
      // This reduces transaction duration and lock time significantly
      await db.transaction(async (tx) => {
        // Update primary animal fields (if any)
        if (Object.keys(updateData).length > 0) {
          await tx.update(animals).set(updateData).where(eq(animals.id, primaryAnimalId));
        }
        // Delete the secondary animal record - CRITICAL: must be atomic with primary update
        await tx.delete(animals)
          .where(eq(animals.id, secondaryAnimalId));
      });
      
      console.log(`[MERGE] Core transaction completed in ${Date.now() - mergeStartTime}ms`);
      
      // STEP 2: Reassign related records with compensating rollback on failure
      // Run all reassignments in PARALLEL to reduce total time
      try {
        const results = await Promise.all([
          db.update(medicalExams)
            .set({ animalId: primaryAnimalId })
            .where(eq(medicalExams.animalId, secondaryAnimalId)),
          db.update(medicalPrescriptions)
            .set({ animalId: primaryAnimalId })
            .where(eq(medicalPrescriptions.animalId, secondaryAnimalId)),
          db.update(medicalBills)
            .set({ animalId: primaryAnimalId })
            .where(eq(medicalBills.animalId, secondaryAnimalId)),
          db.update(medicalFiles)
            .set({ animalId: primaryAnimalId })
            .where(eq(medicalFiles.animalId, secondaryAnimalId)),
          db.update(animalNotes)
            .set({ animalId: primaryAnimalId })
            .where(eq(animalNotes.animalId, secondaryAnimalId)),
          db.update(applications)
            .set({ animalId: primaryAnimalId })
            .where(eq(applications.animalId, secondaryAnimalId)),
          // Non-critical: adoption records reassignment (no row count needed)
          db.update(adoptionCheckoutSessions)
            .set({ animalId: primaryAnimalId })
            .where(eq(adoptionCheckoutSessions.animalId, secondaryAnimalId)),
          db.update(adoptions)
            .set({ animalId: primaryAnimalId })
            .where(eq(adoptions.animalId, secondaryAnimalId)),
        ]);
        // Extract results by index (0-5 have row counts we care about)
        const [examResult, prescriptionResult, billsResult, filesResult, notesResult, appsResult] = results;
        reassignedMedicalRecords = (Number(examResult.rowCount) || 0) + 
          (Number(prescriptionResult.rowCount) || 0) + 
          (Number(billsResult.rowCount) || 0) + 
          (Number(filesResult.rowCount) || 0);
        reassignedNotes = Number(notesResult.rowCount) || 0;
        reassignedApplications = Number(appsResult.rowCount) || 0;
          
        console.log(`[MERGE] Related records reassigned in ${Date.now() - mergeStartTime}ms`);
        // Fetch updated primary animal BEFORE audit trail (critical for response)
        // Using explicit field selection for dynamic import compatibility
        const [result] = await db.select(mergeSelectFields).from(animals).where(eq(animals.id, primaryAnimalId));
        updatedPrimary = result;
        console.log(`[MERGE] Complete in ${Date.now() - mergeStartTime}ms`);
        // STEP 3: Create audit trail - FIRE AND FORGET (non-blocking)
        // These are important but not critical for the merge operation
        Promise.all([
          db.insert(animalMergeHistory).values({
            tenantId,
            primaryAnimalId,
            secondaryAnimalId,
            mergedBy: userId,
            fieldChoices: fieldChoices || {},
            reassignedMedicalRecords,
            reassignedPhotos,
            reassignedApplications,
            reassignedNotes,
            secondaryAnimalSnapshot,
            notes: notes || null,
          }),
          db.insert(activityLogs).values({
            tenantId,
            userId,
            entityType: 'Animal',
            entityId: primaryAnimalId,
            action: 'merged',
            description: `Merged animal profile "${secondaryAnimal.name}" into "${primaryAnimal.name}"`,
            category: 'system',
            metadata: {
              primaryAnimalId,
              secondaryAnimalId,
              primaryAnimalName: primaryAnimal.name,
              secondaryAnimalName: secondaryAnimal.name,
            },
          })
        ]).catch(auditError => {
          console.error('[MERGE] Audit trail creation failed (non-critical):', auditError);
        });
      } catch (postMergeError) {
        // NOTE: Secondary animal was deleted in transaction - rollback is not possible
        // The merge transaction itself succeeded, only post-merge steps (reassignment/audit) failed
        console.error('[MERGE] Post-merge steps failed:', postMergeError);
        throw postMergeError;
      }
      
      res.json({
        success: true,
        message: `Successfully merged "${secondaryAnimal.name}" into "${primaryAnimal.name}"`,
        primaryAnimal: updatedPrimary,
        stats: {
          reassignedMedicalRecords,
          reassignedPhotos,
          reassignedApplications,
          reassignedNotes,
        },
      });
    } catch (error: any) {
      console.error('Merge failed:', error);
      
      // Handle specific database errors
      if (error.code === 'ECONNRESET' || error.code === 'ETIMEDOUT' || 
          error.message?.includes('timeout') || error.message?.includes('connection')) {
        return res.status(503).json({ 
          error: 'Database temporarily unavailable. Please try again in a moment.',
          details: 'The merge operation timed out. This can happen with large records.'
        });
      }
      
      if (error.code === '23505') { // Unique constraint violation
        return res.status(409).json({ 
          error: 'Merge conflict detected. Some records may have already been modified.',
          details: error.detail || error.message
        });
      }
      
      next(error);
    }
  });

  /**
   * GET /api/animals/merge-history
   * Get merge history for this tenant
   * NOTE: This route MUST be defined before /api/animals/:id
   */
  app.get('/api/animals/merge-history', requireTenant, requireAuth, requireRole('admin', 'owner'), async (req, res, next) => {
    try {
      const tenantId = req.tenant!.id;
      
      const history = await db.select({
        id: animalMergeHistory.id,
        primaryAnimalId: animalMergeHistory.primaryAnimalId,
        secondaryAnimalId: animalMergeHistory.secondaryAnimalId,
        mergedBy: animalMergeHistory.mergedBy,
        mergedAt: animalMergeHistory.mergedAt,
        reassignedMedicalRecords: animalMergeHistory.reassignedMedicalRecords,
        reassignedApplications: animalMergeHistory.reassignedApplications,
        reassignedNotes: animalMergeHistory.reassignedNotes,
        notes: animalMergeHistory.notes,
      })
        .from(animalMergeHistory)
        .where(eq(animalMergeHistory.tenantId, tenantId))
        .orderBy(desc(animalMergeHistory.mergedAt));
      
      res.json({ history });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/animals/:id
   * Get specific animal
   */
  app.get('/api/animals/:id', requireTenant, async (req, res, next) => {
    try {
      const { getAnimalById } = await import('./services/animals');
      const animal = await getAnimalById(req.tenant!.id, req.params.id);
      
      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }
      
      const { fosterAnimals, users, kennelBuildings } = await import('@shared/schema');
      
      let activeFosterName: string | null = null;
      let activeFosterStartDate: string | null = null;
      let activeFosterId: string | null = null;
      const [activeFoster] = await db
        .select({
          fosterName: users.fullName,
          fosterId: fosterAnimals.fosterId,
          startDate: fosterAnimals.startDate,
        })
        .from(fosterAnimals)
        .innerJoin(users, eq(fosterAnimals.fosterId, users.id))
        .where(and(
          eq(fosterAnimals.animalId, req.params.id),
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.status, 'active')
        ))
        .orderBy(desc(fosterAnimals.startDate))
        .limit(1);
      
      if (activeFoster) {
        activeFosterName = activeFoster.fosterName;
        activeFosterStartDate = activeFoster.startDate?.toISOString() || null;
        activeFosterId = activeFoster.fosterId;
      }

      let kennelBuildingName: string | null = null;
      if (animal.kennelBuildingId) {
        const [building] = await db
          .select({ name: kennelBuildings.name })
          .from(kennelBuildings)
          .where(eq(kennelBuildings.id, animal.kennelBuildingId))
          .limit(1);
        if (building) {
          kennelBuildingName = building.name;
        }
      }
      
      res.json({ 
        animal: {
          ...animal,
          activeFosterName,
          activeFosterStartDate,
          activeFosterId,
          kennelBuildingName,
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:id/generate-ad-copy
   * Generate Google Ads Grant compliant ad copy for an animal using AI
   */
  app.post('/api/animals/:id/generate-ad-copy', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { getAnimalById } = await import('./services/animals');
      const { generateAdCopy } = await import('./geminiAdCopy');
      
      const animal = await getAnimalById(req.tenant!.id, req.params.id);
      
      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }
      
      const adCopy = await generateAdCopy(
        animal.name,
        animal.bio || animal.description || `${animal.name} is a ${animal.species} looking for a forever home.`,
        animal.species
      );
      
      if (!adCopy) {
        return res.status(500).json({ error: 'Failed to generate ad copy' });
      }
      
      res.json({ 
        success: true, 
        adCopy,
        animal: {
          id: animal.id,
          name: animal.name,
          species: animal.species,
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/generate-bio
   * Generate a Petfinder-ready bio for an animal using AI based on personality tags
   * This endpoint works without requiring an existing animal ID (for new animal forms)
   */
  app.post('/api/generate-bio', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { generateAnimalBio } = await import('./services/aiAnimalBio');
      
      // Validate request body with zod
      const generateBioSchema = z.object({
        name: z.string().min(1, 'Animal name is required'),
        species: z.string().min(1, 'Species is required'),
        breed: z.string().optional(),
        age: z.string().optional(),
        sex: z.string().optional(),
        childFriendly: z.boolean().nullable().optional(),
        dogFriendly: z.boolean().nullable().optional(),
        catFriendly: z.boolean().nullable().optional(),
        specialNeeds: z.boolean().nullable().optional(),
        tags: z.array(z.string().min(1)).min(1, 'At least one personality tag is required'),
      });
      
      const parseResult = generateBioSchema.safeParse(req.body);
      
      if (!parseResult.success) {
        return res.status(400).json({ 
          error: parseResult.error.errors[0]?.message || 'Invalid request data'
        });
      }
      
      const { name, species, breed, age, sex, childFriendly, dogFriendly, catFriendly, specialNeeds, tags } = parseResult.data;
      
      const result = await generateAnimalBio(
        {
          name,
          species,
          breed: breed || undefined,
          age: age || undefined,
          sex: sex || undefined,
          childFriendly: childFriendly ?? null,
          dogFriendly: dogFriendly ?? null,
          catFriendly: catFriendly ?? null,
          specialNeeds: specialNeeds ?? null,
        },
        tags
      );
      
      if (!result) {
        return res.status(500).json({ error: 'Failed to generate bio' });
      }
      
      res.json({ 
        success: true, 
        bio: result.bio,
      });
    } catch (error) {
      next(error);
    }
  });

