  /**
   * POST /api/animals
   * Create new animal (staff only)
   */
  app.post('/api/animals', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { createAnimal } = await import('./services/animals');
      const { insertAnimalSchema } = await import('@shared/schema');
      const { ObjectStorageService } = await import('./objectStorage');
      
      // Extract and validate surrender-specific metadata before schema validation
      const surrenderRequestId = typeof req.body.surrenderRequestId === 'string' ? req.body.surrenderRequestId : undefined;
      const surrenderInternalNotes = typeof req.body.internalNotes === 'string' ? req.body.internalNotes : undefined;
      let surrenderOwnerInfo: { name?: string; email?: string; phone?: string; address?: string } | undefined;
      if (req.body.ownerInfo && typeof req.body.ownerInfo === 'object') {
        surrenderOwnerInfo = {
          name: typeof req.body.ownerInfo.name === 'string' ? req.body.ownerInfo.name : undefined,
          email: typeof req.body.ownerInfo.email === 'string' ? req.body.ownerInfo.email : undefined,
          phone: typeof req.body.ownerInfo.phone === 'string' ? req.body.ownerInfo.phone : undefined,
          address: typeof req.body.ownerInfo.address === 'string' ? req.body.ownerInfo.address : undefined,
        };
      }
      let surrenderAttachedDocuments: Array<{ id?: string; name?: string; fileUrl: string; fileType?: string }> | undefined;
      if (Array.isArray(req.body.attachedDocuments)) {
        surrenderAttachedDocuments = req.body.attachedDocuments.filter(
          (d: any) => d && typeof d.fileUrl === 'string' && d.fileUrl.length > 0
        ).map((d: any) => ({
          id: typeof d.id === 'string' ? d.id : undefined,
          name: typeof d.name === 'string' ? d.name : 'Surrender Document',
          fileUrl: d.fileUrl,
          fileType: typeof d.fileType === 'string' ? d.fileType : 'application/octet-stream',
        }));
      }

      // Convert ISO date strings to Date objects before validation
      const payload = { ...req.body };
      delete payload.ownerInfo;
      delete payload.surrenderRequestId;
      delete payload.internalNotes;
      delete payload.attachedDocuments;
      if (payload.dateOfBirth && typeof payload.dateOfBirth === 'string') {
        payload.dateOfBirth = new Date(payload.dateOfBirth);
      }
      if (payload.petfinderSyncedAt && typeof payload.petfinderSyncedAt === 'string') {
        payload.petfinderSyncedAt = new Date(payload.petfinderSyncedAt);
      }
      if (!payload.intakeDate) {
        payload.intakeDate = new Date();
      } else if (typeof payload.intakeDate === 'string') {
        payload.intakeDate = new Date(payload.intakeDate);
      }
      if (payload.strayHoldUntil && typeof payload.strayHoldUntil === 'string') {
        payload.strayHoldUntil = new Date(payload.strayHoldUntil);
      }
      
      // Convert empty strings to null for unique-constrained text fields
      // This prevents empty string conflicts in the unique microchip index
      if (payload.microchipNumber === '' || payload.microchipNumber?.trim() === '') {
        payload.microchipNumber = null;
      }
      
      const data = insertAnimalSchema.omit({ tenantId: true }).parse(payload);
      
      if (data.photoUrls && data.photoUrls.length > 0) {
        const photoValidation = validatePhotoUrls(data.photoUrls);
        if (!photoValidation.valid) {
          return res.status(400).json({
            error: 'Invalid photo URLs detected. Please upload photos directly instead of using external links (like Google Drive).',
            invalidUrls: photoValidation.invalidUrls
          });
        }
        const objectStorageService = new ObjectStorageService();
        const normalizedPhotoUrls = [];
        for (const photoUrl of data.photoUrls) {
          const normalizedPath = await objectStorageService.trySetObjectEntityAclPolicy(
            photoUrl,
            {
              owner: req.session.userId!,
              visibility: "public",
            }
          );
          normalizedPhotoUrls.push(normalizedPath);
        }
        data.photoUrls = normalizedPhotoUrls;
      }
      
      const animal = await createAnimal(req.tenant!.id, data);
      
      // Handle surrender-to-animal conversion post-processing
      if (surrenderRequestId && surrenderOwnerInfo) {
        try {
          const { contacts, animals: animalsTable, surrenderRequests, documents } = await import('@shared/schema');

          // 1. Create or find contact record for previous owner
          let sourceContactId: string | null = null;
          if (surrenderOwnerInfo.email) {
            // Check if contact already exists with same email
            const [existingContact] = await db.select()
              .from(contacts)
              .where(and(
                eq(contacts.tenantId, req.tenant!.id),
                eq(contacts.email, surrenderOwnerInfo.email)
              ))
              .limit(1);

            if (existingContact) {
              sourceContactId = existingContact.id;
              // Add 'manual' source if not already present
              const currentSources = existingContact.source || [];
              if (!currentSources.includes('manual')) {
                await db.update(contacts)
                  .set({ source: [...currentSources, 'manual'] as any })
                  .where(eq(contacts.id, existingContact.id));
              }
            } else {
              const [newContact] = await db.insert(contacts).values({
                tenantId: req.tenant!.id,
                name: surrenderOwnerInfo.name || 'Unknown Owner',
                email: surrenderOwnerInfo.email,
                phone: surrenderOwnerInfo.phone || null,
                address: surrenderOwnerInfo.address || null,
                source: ['manual'],
                notes: `Previous owner who surrendered ${animal.name}`,
              }).returning();
              sourceContactId = newContact?.id || null;
            }
          } else if (surrenderOwnerInfo.name) {
            const placeholderEmail = `surrender-${surrenderRequestId}@noemail.placeholder`;
            const [newContact] = await db.insert(contacts).values({
              tenantId: req.tenant!.id,
              name: surrenderOwnerInfo.name,
              email: placeholderEmail,
              phone: surrenderOwnerInfo.phone || null,
              address: surrenderOwnerInfo.address || null,
              source: ['manual'],
              notes: `Previous owner who surrendered ${animal.name} (no email provided)`,
            }).returning();
            sourceContactId = newContact?.id || null;
          }

          // 2. Update animal with sourceContactId and surrenderRequestId
          const updateFields: Record<string, any> = {
            sourceContactId,
            surrenderRequestId,
          };
          if (surrenderInternalNotes) {
            updateFields.internalNotes = animal.internalNotes 
              ? `${animal.internalNotes}\n\n${surrenderInternalNotes}` 
              : surrenderInternalNotes;
          }
          await db.update(animalsTable)
            .set(updateFields)
            .where(eq(animalsTable.id, animal.id));

          // 3. Copy document references to point to the new animal
          if (surrenderAttachedDocuments?.length > 0) {
            for (const doc of surrenderAttachedDocuments) {
              await db.insert(documents).values({
                tenantId: req.tenant!.id,
                name: doc.name || 'Surrender Document',
                fileUrl: doc.fileUrl,
                fileType: doc.fileType || 'application/octet-stream',
                sourceTable: 'animals',
                sourceId: animal.id,
              }).catch(err => console.error('[SURRENDER INTAKE] Failed to copy document:', err));
            }
          }

          // 4. Mark surrender request as 'intaken'
          await db.update(surrenderRequests)
            .set({ status: 'intaken' })
            .where(and(
              eq(surrenderRequests.id, surrenderRequestId),
              eq(surrenderRequests.tenantId, req.tenant!.id)
            ));
        } catch (surrenderError) {
          console.error('[SURRENDER INTAKE] Post-processing error (animal was still created):', surrenderError);
        }
      }

      // Log activity (non-blocking - failures won't affect response)
      try {
        const { logActivity } = await import('./lib/activity-logger');
        await logActivity({
          tenantId: req.tenant!.id,
          userId: req.session.userId,
          entityType: 'Animal',
          entityId: animal.id,
          action: 'created',
          description: surrenderRequestId 
            ? `intaked ${animal.species || 'animal'} "${animal.name}" from surrender application`
            : `added ${animal.species || 'animal'} "${animal.name}" to the shelter`,
          category: 'intake',
          metadata: { species: animal.species, breed: animal.breed, status: animal.status, surrenderRequestId: surrenderRequestId || undefined }
        });
      } catch (logError) {
        console.error('Failed to log animal creation activity:', logError);
      }
      
      // Create Google Drive/Object Storage folder for the animal (non-blocking)
      try {
        const { createAnimalBackup } = await import('./lib/animalBackupService');
        createAnimalBackup(req.tenant!.id, {
          id: animal.id,
          name: animal.name,
          intakeDate: animal.intakeDate,
        }).catch(err => console.error('[ANIMAL BACKUP] Background folder creation failed:', err));
      } catch (backupError) {
        console.error('[ANIMAL BACKUP] Failed to initiate backup:', backupError);
      }
      
      res.json({ success: true, animal });
    } catch (error: any) {
      if (error?.status === 409) {
        return res.status(409).json({ error: error.message });
      }
      // Handle duplicate microchip number constraint violation
      if (error?.code === '23505' && error?.constraint?.includes('tenant_name_unique')) {
        return res.status(409).json({ error: 'An animal with this name already exists. Please use a unique name.' });
      }
      if (error?.code === '23505' && error?.constraint?.includes('microchip')) {
        return res.status(400).json({ 
          error: 'This microchip number is already registered to another animal. Please verify the microchip number is correct.' 
        });
      }
      next(error);
    }
  });

  /**
   * PATCH /api/animals/:id
   * Update animal (staff only, or users with explicit animals page permission)
   */
  app.patch('/api/animals/:id', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { updateAnimal } = await import('./services/animals');
      const { ObjectStorageService } = await import('./objectStorage');
      
      // Convert ISO date strings to Date objects for all timestamp fields
      const data = { ...req.body };
      const timestampFields = [
        'dateOfBirth', 
        'petfinderSyncedAt', 
        'scheduledSurgeryDate', 
        'intakeDate', 
        'adoptionDate', 
        'deceasedDate', 'strayHoldUntil'
      ];
      for (const field of timestampFields) {
        if (data[field] && typeof data[field] === 'string') {
          data[field] = new Date(data[field]);
        }
      }
      
      // Convert empty strings to null for numeric/decimal fields
      const numericFields = ['medicalFundGoal', 'medicalFundRaised'];
      for (const field of numericFields) {
        if (data[field] === '' || data[field] === undefined) {
          data[field] = null;
        }
      }
      
      // Convert empty strings to null for unique-constrained text fields
      // This prevents empty string conflicts in the unique microchip index
      if (data.microchipNumber === '' || data.microchipNumber?.trim() === '') {
        data.microchipNumber = null;
      }
      
      // Preserve kennel assignment when status changes to statuses where
      // the animal should remain in their kennel (e.g. transfer_pending, medical_hold, stray_hold)
      // The frontend form may send null kennel fields if the kennel selector wasn't loaded
      const kennelPreservingStatuses = ['transfer_pending', 'medical_hold', 'stray_hold'];
      if (data.status && kennelPreservingStatuses.includes(data.status)) {
        if (data.kennelBuildingId === null && data.kennelRowId === null && data.kennelPosition === null) {
          delete data.kennelBuildingId;
          delete data.kennelRowId;
          delete data.kennelPosition;
        }
      }
      
      // Validate and normalize photo URLs if provided
      if (data.photoUrls && data.photoUrls.length > 0) {
        const photoValidation = validatePhotoUrls(data.photoUrls);
        if (!photoValidation.valid) {
          return res.status(400).json({
            error: 'Invalid photo URLs detected. Please upload photos directly instead of using external links (like Google Drive).',
            invalidUrls: photoValidation.invalidUrls
          });
        }
        const objectStorageService = new ObjectStorageService();
        const normalizedPhotoUrls = [];
        for (const photoUrl of data.photoUrls) {
          const normalizedPath = await objectStorageService.trySetObjectEntityAclPolicy(
            photoUrl,
            {
              owner: req.session.userId!,
              visibility: "public",
            }
          );
          normalizedPhotoUrls.push(normalizedPath);
        }
        data.photoUrls = normalizedPhotoUrls;
      }
      
      const [existingAnimal] = await db.select({ status: animals.status, locationType: animals.locationType, locationName: animals.locationName })
        .from(animals)
        .where(and(eq(animals.id, req.params.id), eq(animals.tenantId, req.tenant!.id)))
        .limit(1);

      // Safety: always clear fosterId FK when animal is no longer in foster
      if (data.locationType && data.locationType !== 'foster') {
        data.fosterId = null;
      }

      // Safety: auto-set adoptionDate when status changes to 'adopted' if not already provided
      if (data.status === 'adopted' && !data.adoptionDate) {
        data.adoptionDate = new Date();
      }

      const animal = await updateAnimal(req.tenant!.id, req.params.id, data);
      
      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }
      
      // Log activity for significant changes (non-blocking - failures won't affect response)
      try {
        const { logActivity } = await import('./lib/activity-logger');
        const changes: string[] = [];
        if (data.status) changes.push(`status to "${data.status}"`);
        if (data.weight) changes.push(`weight to ${data.weight}`);
        if (data.name) changes.push(`name to "${data.name}"`);
        await logActivity({
          tenantId: req.tenant!.id,
          userId: req.session.userId,
          entityType: 'Animal',
          entityId: animal.id,
          action: 'updated',
          description: changes.length > 0 
            ? `updated "${animal.name}": ${changes.join(', ')}`
            : `updated "${animal.name}"`,
          category: data.locationType === 'foster' || data.status === 'available' ? 'movement' : 'intake',
          metadata: { changes: Object.keys(data) }
        });
      } catch (logError) {
        console.error('Failed to log animal update activity:', logError);
      }
      
      if (data.status) {
        try {
          const { createAuditLog } = await import('./audit');
          await createAuditLog({
            userId: req.user!.id,
            tenantId: req.tenant!.id,
            action: 'animal.status_change',
            entityType: 'animal',
            entityId: animal.id,
            changes: {
              before: { status: existingAnimal?.status },
              after: { status: data.status },
            },
            metadata: { animalName: animal.name },
            req,
          });
        } catch (auditErr) {
          console.error('Failed to create audit log:', auditErr);
        }

        const { TERMINAL_STATUSES } = await import('@shared/schema');
        if (TERMINAL_STATUSES.includes(data.status)) {
          try {
            await db.update(medicationTasks)
              .set({ status: 'skipped', skipReason: `Animal status changed to ${data.status}` })
              .where(and(
                eq(medicationTasks.animalId, animal.id),
                eq(medicationTasks.status, 'pending')
              ));

            await db.update(medicationPlans)
              .set({ active: false })
              .where(and(
                eq(medicationPlans.animalId, animal.id),
                eq(medicationPlans.active, true)
              ));

            await db.update(fosterAnimals)
              .set({ status: 'completed', endDate: new Date() })
              .where(and(
                eq(fosterAnimals.animalId, animal.id),
                eq(fosterAnimals.status, 'active')
              ));

            if (data.status === 'deceased' || data.status === 'transported') {
              const { complianceObligations } = await import('@shared/schema');
              await db.update(complianceObligations)
                .set({
                  status: 'waived' as const,
                  notes: `Auto-waived: animal status changed to ${data.status}`,
                  updatedAt: new Date(),
                })
                .where(and(
                  eq(complianceObligations.animalId, animal.id),
                  eq(complianceObligations.tenantId, req.tenant!.id),
                  eq(complianceObligations.status, 'pending')
                ));
            }

            console.log(`Terminal status "${data.status}" applied to ${animal.name}: cancelled pending medical tasks, foster assignments, and compliance obligations`);
          } catch (terminalErr) {
            console.error('Failed to process terminal status cleanup:', terminalErr);
          }
        }
      }

      try {
        const { logAnimalAudit } = await import('./lib/animal-audit-logger');
        await logAnimalAudit({
          tenantId: req.tenant!.id,
          animalId: animal.id,
          previousStatus: existingAnimal?.status,
          newStatus: animal.status,
          previousLocationType: existingAnimal?.locationType,
          newLocationType: animal.locationType,
          previousLocationName: existingAnimal?.locationName,
          newLocationName: animal.locationName,
          changedBy: req.user!.id,
          changedByName: req.user!.fullName || req.user!.email,
          notes: 'Updated via animal edit form',
        });
      } catch (auditErr) {
        console.error('Failed to log animal audit:', auditErr);
      }

      res.json({ success: true, animal });
    } catch (error: any) {
      // Handle duplicate microchip number constraint violation
      if (error?.status === 409) {
        return res.status(409).json({ error: error.message });
      }
      if (error?.code === '23505' && error?.constraint?.includes('tenant_name_unique')) {
        return res.status(409).json({ error: 'An animal with this name already exists. Please use a unique name.' });
      }
      if (error?.code === '23505' && error?.constraint?.includes('microchip')) {
        return res.status(400).json({ 
          error: 'This microchip number is already registered to another animal. Please verify the microchip number is correct.' 
        });
      }
      next(error);
    }
  });

  /**
   * PATCH /api/animals/:id/deceased
   * Mark animal as deceased (admin/staff only)
   */
  app.patch('/api/animals/:id/deceased', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { animals } = await import('@shared/schema');
      const { z } = await import('zod');
      
      const markDeceasedSchema = z.object({
        deceasedDate: z.string().transform(str => new Date(str)),
        causeOfDeath: z.enum(['natural_death', 'euthanasia']),
        deceasedNotes: z.string().min(1),
      });

      const data = markDeceasedSchema.parse(req.body);

      const [existingAnimalForAudit] = await db.select({ status: animals.status, locationType: animals.locationType, locationName: animals.locationName })
        .from(animals)
        .where(and(eq(animals.id, req.params.id), eq(animals.tenantId, req.tenant!.id)))
        .limit(1);

      const [animal] = await db
        .update(animals)
        .set({
          status: 'deceased',
          deceasedDate: data.deceasedDate,
          causeOfDeath: data.causeOfDeath,
          deceasedNotes: data.deceasedNotes,
          locationType: null,
          locationName: null,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(animals.id, req.params.id),
            eq(animals.tenantId, req.tenant!.id)
          )
        )
        .returning();

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      try {
        const { logAnimalAudit } = await import('./lib/animal-audit-logger');
        await logAnimalAudit({
          tenantId: req.tenant!.id,
          animalId: animal.id,
          previousStatus: existingAnimalForAudit?.status,
          newStatus: 'deceased',
          previousLocationType: existingAnimalForAudit?.locationType,
          newLocationType: null,
          previousLocationName: existingAnimalForAudit?.locationName,
          newLocationName: null,
          changedBy: req.user!.id,
          changedByName: req.user!.fullName || req.user!.email,
          notes: `Marked deceased: ${data.causeOfDeath.replace('_', ' ')}`,
        });
      } catch (auditErr) {
        console.error('Failed to log animal audit:', auditErr);
      }

      const { fosterAnimals, medicationTasks, medicationPlans } = await import('@shared/schema');
      await db
        .update(fosterAnimals)
        .set({
          status: 'completed',
          actualReturnDate: data.deceasedDate,
          notes: `Animal deceased - ${data.causeOfDeath.replace('_', ' ')}`,
          updatedAt: new Date(),
        })
        .where(
          and(
            eq(fosterAnimals.animalId, req.params.id),
            eq(fosterAnimals.tenantId, req.tenant!.id),
            eq(fosterAnimals.status, 'active')
          )
        );

      await db.update(medicationTasks)
        .set({ status: 'skipped', skipReason: 'Animal deceased' })
        .where(and(
          eq(medicationTasks.animalId, animal.id),
          eq(medicationTasks.status, 'pending')
        ));

      await db.update(medicationPlans)
        .set({ active: false })
        .where(and(
          eq(medicationPlans.animalId, animal.id),
          eq(medicationPlans.active, true)
        ));

      res.json({ success: true, animal });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/animals/:id/quarantine
   * Set or clear quarantine status for an animal
   */
  app.patch('/api/animals/:id/quarantine', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { animals } = await import('@shared/schema');
      const { z } = await import('zod');

      const quarantineSchema = z.object({
        isQuarantined: z.boolean(),
        quarantineReason: z.string().nullable().optional(),
      });

      const data = quarantineSchema.parse(req.body);

      const updateData: Record<string, any> = {
        isQuarantined: data.isQuarantined,
        quarantineReason: data.isQuarantined ? (data.quarantineReason || null) : null,
        quarantineStartDate: data.isQuarantined ? new Date() : null,
        updatedAt: new Date(),
      };

      const [animal] = await db
        .update(animals)
        .set(updateData)
        .where(
          and(
            eq(animals.id, req.params.id),
            eq(animals.tenantId, req.tenant!.id)
          )
        )
        .returning();

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      res.json({ success: true, animal });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:id/reclaim-payment
   * Create a Stripe PaymentIntent or record a manual payment for a reclaim fee
   */
  app.post('/api/animals/:id/reclaim-payment', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { animals } = await import('@shared/schema');
      const { z } = await import('zod');

      const paymentSchema = z.object({
        amount: z.number().positive(),
        description: z.string().optional(),
        ownerEmail: z.string().email().optional(),
      });

      const data = paymentSchema.parse(req.body);

      const [animal] = await db.select()
        .from(animals)
        .where(and(eq(animals.id, req.params.id), eq(animals.tenantId, req.tenant!.id)))
        .limit(1);

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      const hasStripeConnect = !!req.tenant!.stripeConnectedAccountId;
      const hasOwnStripeKeys = req.tenant!.stripeEnabled && !!req.tenant!.stripeSecretKeyEncrypted;
      const stripeConfigured = hasStripeConnect || hasOwnStripeKeys;

      if (stripeConfigured) {
        try {
          const { stripeService } = await import('./lib/stripe-service');
          const { calculatePlatformFee } = await import('./config/platform');
          const platformFeeAmount = hasStripeConnect
            ? calculatePlatformFee(data.amount, req.tenant!.subscriptionTier || 'free', req.tenant!.platformFeePercent)
            : 0;

          const paymentIntent = await stripeService.createPaymentIntent(req.tenant! as any, {
            amount: data.amount,
            description: data.description || `Reclaim fee for ${animal.name}`,
            receiptEmail: data.ownerEmail,
            metadata: {
              type: 'reclaim_fee',
              animalId: animal.id,
              animalName: animal.name || 'Unknown',
            },
            connectedAccountId: req.tenant!.stripeConnectedAccountId || undefined,
            platformFeeAmount: platformFeeAmount > 0 ? platformFeeAmount : undefined,
          });

          return res.json({
            paymentIntentId: paymentIntent.id,
            clientSecret: paymentIntent.client_secret,
            status: paymentIntent.status,
          });
        } catch (stripeErr: any) {
          console.error('Stripe payment intent creation failed for RTO:', stripeErr.message);
          return res.status(500).json({
            error: `Stripe payment failed: ${stripeErr.message}. You can try again or use manual payment recording.`,
          });
        }
      }

      const manualPaymentId = `manual_rto_${Date.now()}_${animal.id.slice(0, 8)}`;
      res.json({
        paymentIntentId: manualPaymentId,
        status: 'manual',
        message: 'Payment recorded manually (Stripe not configured)',
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:id/reclaim
   * Process a Return to Owner (RTO) - link owner contact, record fee, change status
   */
  app.post('/api/animals/:id/reclaim', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { animals, contacts, fosterAnimals, medicationTasks, medicationPlans, complianceObligations } = await import('@shared/schema');
      const { z } = await import('zod');

      const reclaimSchema = z.object({
        contactId: z.string().uuid().optional(),
        newContact: z.object({
          name: z.string().min(1),
          email: z.string().email().optional().or(z.literal('')),
          phone: z.string().optional().or(z.literal('')),
          address: z.string().optional().or(z.literal('')),
        }).optional(),
        reclaimFeePaid: z.string().optional(),
        waiveFee: z.boolean().optional(),
        ownershipVerified: z.boolean(),
        governmentIdUrls: z.array(z.string()).optional(),
        vetRecordUrls: z.array(z.string()).optional(),
        signatureData: z.string().optional(),
        paymentIntentId: z.string().optional(),
      });

      const data = reclaimSchema.parse(req.body);

      if (!data.ownershipVerified) {
        return res.status(400).json({ error: 'Ownership verification is required to process a reclaim.' });
      }

      const [existingAnimal] = await db.select()
        .from(animals)
        .where(and(eq(animals.id, req.params.id), eq(animals.tenantId, req.tenant!.id)))
        .limit(1);

      if (!existingAnimal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      let ownerContactId = data.contactId || null;

      if (!ownerContactId && data.newContact) {
        const contactEmail = data.newContact.email || `rto-${Date.now()}@placeholder.local`;
        const existingContacts = await db.select()
          .from(contacts)
          .where(and(
            eq(contacts.tenantId, req.tenant!.id),
            eq(contacts.email, contactEmail)
          ))
          .limit(1);

        if (existingContacts.length > 0 && data.newContact.email) {
          ownerContactId = existingContacts[0].id;
          await db.update(contacts)
            .set({
              name: data.newContact.name,
              phone: data.newContact.phone || existingContacts[0].phone,
              address: data.newContact.address || existingContacts[0].address,
              updatedAt: new Date(),
            })
            .where(eq(contacts.id, ownerContactId));
        } else {
          const [newContact] = await db.insert(contacts)
            .values({
              tenantId: req.tenant!.id,
              name: data.newContact.name,
              email: contactEmail,
              phone: data.newContact.phone || null,
              address: data.newContact.address || null,
              source: ['manual'],
              tags: ['rto-owner'],
            })
            .returning();
          ownerContactId = newContact.id;
        }
      }

      const feeAmount = data.waiveFee ? '0.00' : (data.reclaimFeePaid || '0.00');

      const [animal] = await db.update(animals)
        .set({
          status: 'returned_to_owner',
          reclaimedByContactId: ownerContactId,
          reclaimFeePaid: feeAmount,
          reclaimDate: new Date(),
          locationType: null,
          locationName: null,
          kennelBuildingId: null,
          kennelRowId: null,
          kennelPosition: null,
          updatedAt: new Date(),
        })
        .where(and(eq(animals.id, req.params.id), eq(animals.tenantId, req.tenant!.id)))
        .returning();

      try {
        const { logAnimalAudit } = await import('./lib/animal-audit-logger');
        await logAnimalAudit({
          tenantId: req.tenant!.id,
          animalId: animal.id,
          previousStatus: existingAnimal.status,
          newStatus: 'returned_to_owner',
          previousLocationType: existingAnimal.locationType,
          newLocationType: null,
          previousLocationName: existingAnimal.locationName,
          newLocationName: null,
          changedBy: req.user!.id,
          changedByName: req.user!.fullName || req.user!.email,
          notes: `Returned to owner (RTO). Fee: $${feeAmount}`,
        });
      } catch (auditErr) {
        console.error('Failed to log animal audit:', auditErr);
      }

      // Save RTO documents (government ID, vet records, signature) as medical files linked to the animal
      try {
        const { medicalFiles } = await import('@shared/schema');
        const { ObjectStorageService } = await import('./objectStorage');
        const { documents } = await import('@shared/schema');
        const objectStorage = new ObjectStorageService();
        const allDocs: { url: string; desc: string; mimeType: string; fileSize: number }[] = [];
        if (data.governmentIdUrls && data.governmentIdUrls.length > 0) {
          data.governmentIdUrls.forEach((url, i) => allDocs.push({ url, desc: `RTO - Owner Government ID ${i + 1}`, mimeType: 'application/octet-stream', fileSize: 0 }));
        }
        if (data.vetRecordUrls && data.vetRecordUrls.length > 0) {
          data.vetRecordUrls.forEach((url, i) => allDocs.push({ url, desc: `RTO - Owner Vet Records / Proof of Ownership ${i + 1}`, mimeType: 'application/octet-stream', fileSize: 0 }));
        }
        if (data.signatureData) {
          try {
            const base64Match = data.signatureData.match(/^data:image\/\w+;base64,(.+)$/);
            if (base64Match) {
              const imageBuffer = Buffer.from(base64Match[1], 'base64');
              const sigFilename = `rto-signature-${animal.id}-${Date.now()}.png`;
              const result = await objectStorage.uploadTenantFile(
                req.tenant!.id,
                'rto-documents',
                imageBuffer,
                'image/png',
                sigFilename,
              );
              allDocs.push({ url: result.objectPath, desc: 'RTO - Owner Signature on Waiver', mimeType: 'image/png', fileSize: imageBuffer.length });
              console.log(`RTO: Uploaded signature to object storage: ${result.objectPath}`);
            } else {
              allDocs.push({ url: data.signatureData, desc: 'RTO - Owner Signature on Waiver', mimeType: 'image/png', fileSize: data.signatureData.length });
            }
          } catch (sigErr: any) {
            console.error('Failed to upload RTO signature to object storage, saving inline:', sigErr.message);
            allDocs.push({ url: data.signatureData, desc: 'RTO - Owner Signature on Waiver', mimeType: 'image/png', fileSize: data.signatureData.length });
          }
        }

        // Attempt to resolve file sizes for uploaded docs from object storage metadata
        for (const doc of allDocs) {
          if (doc.fileSize === 0 && doc.url.startsWith('/objects/')) {
            try {
              const objFile = await objectStorage.getObjectEntityFile(doc.url);
              const [metadata] = await objFile.getMetadata();
              doc.fileSize = parseInt(String(metadata.size || '0'), 10);
            } catch {
              doc.fileSize = 0;
            }
          }
        }

        for (const doc of allDocs) {
          await db.insert(medicalFiles).values({
            animalId: animal.id,
            tenantId: req.tenant!.id,
            fileName: doc.desc,
            fileUrl: doc.url,
            mimeType: doc.mimeType,
            description: doc.desc,
            uploadedBy: req.user!.id,
          });
        }

        // Also save to tenant documents page
        const reclaimDate = new Date().toISOString().split('T')[0];
        for (const doc of allDocs) {
          try {
            await db.insert(documents).values({
              tenantId: req.tenant!.id,
              title: `${doc.desc} - ${animal.name} (${reclaimDate})`,
              description: `Return to Owner document for ${animal.name}, processed on ${reclaimDate}`,
              category: 'forms' as const,
              fileUrl: doc.url,
              fileSize: doc.fileSize || 0,
              fileName: doc.desc,
              uploadedBy: req.user!.id,
              storageType: doc.url.startsWith('/objects/') ? 'replit_object_storage' as const : null,
            });
          } catch (tenantDocErr: any) {
            console.error(`Failed to save RTO document to tenant documents: ${tenantDocErr.message}`);
          }
        }

        if (allDocs.length > 0) {
          console.log(`RTO: Saved ${allDocs.length} documents for ${animal.name} (medical files + tenant documents)`);
        }
      } catch (docErr) {
        console.error('Failed to save RTO documents:', docErr);
      }

      try {
        await db.update(fosterAnimals)
          .set({ status: 'completed', actualReturnDate: new Date(), notes: 'Animal returned to owner (RTO)', updatedAt: new Date() })
          .where(and(eq(fosterAnimals.animalId, animal.id), eq(fosterAnimals.tenantId, req.tenant!.id), eq(fosterAnimals.status, 'active')));

        await db.update(medicationTasks)
          .set({ status: 'skipped', skipReason: 'Animal returned to owner' })
          .where(and(eq(medicationTasks.animalId, animal.id), eq(medicationTasks.status, 'pending')));

        await db.update(medicationPlans)
          .set({ active: false })
          .where(and(eq(medicationPlans.animalId, animal.id), eq(medicationPlans.active, true)));

        await db.update(complianceObligations)
          .set({ status: 'waived' as const, notes: 'Auto-waived: animal returned to owner', updatedAt: new Date() })
          .where(and(eq(complianceObligations.animalId, animal.id), eq(complianceObligations.tenantId, req.tenant!.id), eq(complianceObligations.status, 'pending')));

        console.log(`RTO processed for ${animal.name}: cancelled pending tasks, foster assignments, and compliance obligations`);
      } catch (cleanupErr) {
        console.error('Failed to process RTO cleanup:', cleanupErr);
      }

      res.json({ success: true, animal });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:id/re-intake
   * Re-intake a previously adopted or deceased animal that has returned to the rescue
   * Resets status to intake and creates a new intake record
   */
  app.post('/api/animals/:id/re-intake', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { animals, animalNotes } = await import('@shared/schema');
      const { z } = await import('zod');
      
      const reintakeSchema = z.object({
        reason: z.string().min(1, "Re-intake reason is required"),
        notes: z.string().optional(),
      });

      const data = reintakeSchema.parse(req.body);
      const animalId = req.params.id;
      const tenantId = req.tenant!.id;

      // Get current animal - explicit field selection for dynamic import compatibility
      const [existingAnimal] = await db.select({
        id: animals.id,
        name: animals.name,
        species: animals.species,
        breed: animals.breed,
        status: animals.status,
        intakeDate: animals.intakeDate,
        tenantId: animals.tenantId,
      }).from(animals)
        .where(and(
          eq(animals.id, animalId),
          eq(animals.tenantId, tenantId)
        ));

      if (!existingAnimal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      // Only allow re-intake for animals with certain statuses
      const reintakeableStatuses = ['adopted', 'deceased', 'transported'];
      if (!reintakeableStatuses.includes(existingAnimal.status)) {
        return res.status(400).json({ 
          error: 'Invalid status for re-intake',
          message: `Cannot re-intake an animal with status "${existingAnimal.status}". Only adopted, deceased, or transported animals can be re-intaken.`
        });
      }

      const previousStatus = existingAnimal.status;

      // Update animal status to available (for returning animals)
      const [updatedAnimal] = await db
        .update(animals)
        .set({
          status: 'available',
          intakeDate: new Date(),
          updatedAt: new Date(),
          // Clear previous outcome data
          deceasedDate: null,
          causeOfDeath: null,
          deceasedNotes: null,
        })
        .where(
          and(
            eq(animals.id, animalId),
            eq(animals.tenantId, tenantId)
          )
        )
        .returning();

      // Add a note documenting the re-intake
      await db.insert(animalNotes).values({
        animalId,
        tenantId,
        userId: req.user!.id,
        content: `**Re-Intake**: ${data.reason}${data.notes ? `\n\n${data.notes}` : ''}\n\n_Previous status: ${previousStatus}_`,
        isInternal: true,
        createdAt: new Date(),
        updatedAt: new Date(),
      });

      res.json({ 
        success: true, 
        animal: updatedAnimal,
        message: `${existingAnimal.name} has been re-intaken successfully.`
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/photos/upload
   * Upload animal photos directly (proxied through backend to avoid CORS)
   * Uses Google Drive if configured, otherwise falls back to Replit object storage
   */
  app.post('/api/animals/photos/upload', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { TenantFileStorage } = await import('./lib/tenantFileStorage');
      
      const imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'heic', 'heif', 'bmp', 'ico', 'avif'];
      
      const upload = multer({
        storage: multer.memoryStorage(),
        limits: {
          fileSize: 10 * 1024 * 1024, // 10MB
        },
        fileFilter: (_req, file, cb) => {
          if (file.mimetype.startsWith('image/')) {
            cb(null, true);
          } else {
            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext && imageExtensions.includes(ext)) {
              cb(null, true);
            } else {
              cb(new Error('Only image files are allowed'));
            }
          }
        },
      }).array('files', 10);

      // Process upload
      upload(req, res, async (err) => {
        if (err) {
          return res.status(400).json({ error: err.message });
        }

        const files = req.files as Express.Multer.File[];
        if (!files || files.length === 0) {
          return res.status(400).json({ error: 'No files uploaded' });
        }

        try {
          const tenantId = req.tenant!.id;
          const userId = req.session.userId!;
          const storage = await TenantFileStorage.forTenant(tenantId);
          const uploadedPaths: string[] = [];
          
          // Get optional animalId from query params for folder organization
          const animalId = req.query.animalId as string | undefined;
          let animalContext: { id: string; name: string; status: string } | undefined;
          
          if (animalId) {
            const animal = await db.query.animals.findFirst({
              where: and(eq(animals.id, animalId), eq(animals.tenantId, tenantId)),
            });
            if (animal) {
              animalContext = {
                id: animal.id,
                name: animal.name,
                status: animal.status,
              };
            }
          }

          // Upload each file using TenantFileStorage (Google Drive or Replit)
          for (const file of files) {
            // Detect mobile cloud storage reference files (shortcuts from iOS/Android Files app)
            // Only trigger for files with explicit mobile SDK patterns in filename AND tiny size
            const filename = file.originalname.toLowerCase();
            const isMobileCloudRef = 
              file.buffer.length < 1024 && // Less than 1KB (real images are larger)
              (filename.includes('drivesdk') || filename.includes('_gdrive'));
            
            if (isMobileCloudRef) {
              console.warn(`Detected mobile cloud reference: ${file.originalname}, size: ${file.buffer.length} bytes`);
              return res.status(400).json({ 
                error: 'It looks like you selected a file from cloud storage. Please select photos directly from your Camera Roll or Photos app instead.',
                isCloudReference: true
              });
            }
            
            let fileBuffer = file.buffer;
            let contentType = file.mimetype;
            
            // Convert HEIC/HEIF to JPEG for browser compatibility
            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext === 'heic' || ext === 'heif' || file.mimetype === 'image/heic' || file.mimetype === 'image/heif') {
              try {
                const heicConvert = (await import('heic-convert')).default;
                const convertedBuffer = await heicConvert({
                  buffer: file.buffer,
                  format: 'JPEG',
                  quality: 0.9
                });
                fileBuffer = Buffer.from(convertedBuffer);
                contentType = 'image/jpeg';
                console.log(`Converted HEIC file to JPEG: ${file.originalname}`);
              } catch (conversionError) {
                console.error('HEIC conversion failed, uploading original:', conversionError);
              }
            }
            
            const result = await storage.uploadFile({
              tenantId,
              userId,
              category: 'animal-photos',
              visibility: 'public',
              fileName: file.originalname,
              mimeType: contentType,
              content: fileBuffer,
              animal: animalContext as any,
            });

            if (result.success) {
              uploadedPaths.push(result.fileUrl);
              
              try {
                const sharpModule = (await import('sharp')).default;
                const thumbBuffer = await sharpModule(fileBuffer)
                  .rotate()
                  .resize(400, 300, { fit: 'cover' })
                  .jpeg({ quality: 75 })
                  .toBuffer();
                
                const { parseObjectPath, objectStorageClient } = await import('./objectStorage');
                const privateDir = process.env.PRIVATE_OBJECT_DIR || '';
                const entityId = result.fileUrl.slice('/objects/'.length);
                const thumbFullPath = `${privateDir}/${entityId}-thumb`;
                const { bucketName, objectName } = parseObjectPath(thumbFullPath);
                const thumbFile = objectStorageClient.bucket(bucketName).file(objectName);
                await thumbFile.save(thumbBuffer, { contentType: 'image/jpeg', resumable: false });
                console.log(`[THUMBNAIL] Generated thumbnail for ${file.originalname} (${(thumbBuffer.length / 1024).toFixed(0)}KB)`);
              } catch (thumbErr) {
                console.error('[THUMBNAIL] Failed to generate thumbnail:', thumbErr);
              }
            } else {
              console.error('Failed to upload file:', result.error);
            }
          }

          res.json({ uploadedPaths });
        } catch (error: any) {
          console.error('Error uploading files:', error);
          return res.status(500).json({ error: 'Failed to upload files' });
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/documents/upload
   * Dedicated endpoint for uploading document files (PDF, DOC, DOCX, etc.)
   * Used by RTO reclaim flow for vet records and other document uploads
   */
  app.post('/api/documents/upload', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { TenantFileStorage } = await import('./lib/tenantFileStorage');

      const allowedExtensions = ['pdf', 'doc', 'docx', 'txt', 'rtf', 'jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'heif'];
      const allowedMimeTypes = [
        'application/pdf',
        'application/msword',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'text/plain',
        'application/rtf',
      ];

      const upload = multer({
        storage: multer.memoryStorage(),
        limits: {
          fileSize: 15 * 1024 * 1024,
        },
        fileFilter: (_req, file, cb) => {
          if (file.mimetype.startsWith('image/') || allowedMimeTypes.includes(file.mimetype)) {
            cb(null, true);
          } else {
            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext && allowedExtensions.includes(ext)) {
              cb(null, true);
            } else {
              cb(new Error('Only document files (PDF, DOC, DOCX) and images are allowed'));
            }
          }
        },
      }).array('files', 10);

      upload(req, res, async (err) => {
        if (err) {
          return res.status(400).json({ error: err.message });
        }

        const files = req.files as Express.Multer.File[];
        if (!files || files.length === 0) {
          return res.status(400).json({ error: 'No files uploaded' });
        }

        try {
          const tenantId = req.tenant!.id;
          const userId = req.session.userId!;
          const storage = await TenantFileStorage.forTenant(tenantId);
          const uploadedPaths: string[] = [];
          const category = (req.query.category as string) || 'documents';

          for (const file of files) {
            const result = await storage.uploadFile({
              tenantId,
              userId,
              category,
              visibility: 'private',
              fileName: file.originalname,
              mimeType: file.mimetype,
              content: file.buffer,
            });

            if (result.success) {
              uploadedPaths.push(result.fileUrl);
            } else {
              console.error('Failed to upload document:', result.error);
            }
          }

          res.json({ uploadedPaths });
        } catch (error: any) {
          console.error('Error uploading documents:', error);
          return res.status(500).json({ error: 'Failed to upload documents' });
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/custom-pages/images/upload
   * Upload custom page images (for use in website builder custom pages)
   * Uses Google Drive if configured, otherwise falls back to Replit object storage
   */
  app.post('/api/custom-pages/images/upload', requireTenant, requireAuth, requireRole('admin'), async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { TenantFileStorage } = await import('./lib/tenantFileStorage');
      
      // Allowed image extensions (for HEIC/HEIF files that may have incorrect MIME types)
      const imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'heic', 'heif', 'bmp', 'ico', 'avif'];
      
      // Configure multer for memory storage
      const upload = multer({
        storage: multer.memoryStorage(),
        limits: {
          fileSize: 10 * 1024 * 1024, // 10MB
        },
        fileFilter: (_req, file, cb) => {
          // Check MIME type first
          if (file.mimetype.startsWith('image/')) {
            cb(null, true);
          } else {
            // Fallback to extension check for HEIC/HEIF files (often have incorrect MIME types)
            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext && imageExtensions.includes(ext)) {
              cb(null, true);
            } else {
              cb(new Error('Only image files are allowed'));
            }
          }
        },
      }).array('files', 10); // Accept up to 10 files

      // Process upload
      upload(req, res, async (err) => {
        if (err) {
          return res.status(400).json({ error: err.message });
        }

        const files = req.files as Express.Multer.File[];
        if (!files || files.length === 0) {
          return res.status(400).json({ error: 'No files uploaded' });
        }

        try {
          const tenantId = req.tenant!.id;
          const userId = req.session.userId!;
          const storage = await TenantFileStorage.forTenant(tenantId);
          const uploadedPaths: string[] = [];

          // Upload each file using TenantFileStorage (Google Drive or Replit)
          for (const file of files) {
            let fileBuffer = file.buffer;
            let contentType = file.mimetype;
            
            // Convert HEIC/HEIF to JPEG for browser compatibility
            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext === 'heic' || ext === 'heif' || file.mimetype === 'image/heic' || file.mimetype === 'image/heif') {
              try {
                const heicConvert = (await import('heic-convert')).default;
                const convertedBuffer = await heicConvert({
                  buffer: file.buffer,
                  format: 'JPEG',
                  quality: 0.9
                });
                fileBuffer = Buffer.from(convertedBuffer);
                contentType = 'image/jpeg';
                console.log(`Converted HEIC file to JPEG: ${file.originalname}`);
              } catch (conversionError) {
                console.error('HEIC conversion failed, uploading original:', conversionError);
              }
            }
            
            const result = await storage.uploadFile({
              tenantId,
              userId,
              category: 'website-assets',
              visibility: 'public',
              fileName: file.originalname,
              mimeType: contentType,
              content: fileBuffer,
            });

            if (result.success) {
              uploadedPaths.push(result.fileUrl);
            } else {
              console.error('Failed to upload file:', result.error);
            }
          }

          res.json({ uploadedPaths });
        } catch (error: any) {
          console.error('Error uploading custom page images:', error);
          return res.status(500).json({ error: 'Failed to upload images' });
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PUT /api/animals/:id/photos
   * Update animal photos after upload
   */
  app.put('/api/animals/:id/photos', requireTenant, requireAuth, requireRoleOrPageAccess('animals', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { ObjectStorageService } = await import('./objectStorage');
      const { getAnimalById, updateAnimal } = await import('./services/animals');
      
      if (!req.body.photoUrls || !Array.isArray(req.body.photoUrls)) {
        return res.status(400).json({ error: 'photoUrls array is required' });
      }

      const photoValidation = validatePhotoUrls(req.body.photoUrls);
      if (!photoValidation.valid) {
        return res.status(400).json({
          error: 'Invalid photo URLs detected. Please upload photos directly instead of using external links (like Google Drive).',
          invalidUrls: photoValidation.invalidUrls
        });
      }

      const animal = await getAnimalById(req.tenant!.id, req.params.id);
      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      const objectStorageService = new ObjectStorageService();
      const normalizedPhotoUrls = [];

      for (const photoUrl of req.body.photoUrls) {
        const normalizedPath = await objectStorageService.trySetObjectEntityAclPolicy(
          photoUrl,
          {
            owner: req.session.userId!,
            visibility: "public",
          }
        );
        normalizedPhotoUrls.push(normalizedPath);
      }

      const updatedAnimal = await updateAnimal(req.tenant!.id, req.params.id, {
        photoUrls: normalizedPhotoUrls,
      });

      res.json({ success: true, animal: updatedAnimal });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /objects/:objectPath(*)
   * Serve uploaded objects with tenant-scoped access control
   * - Public files are accessible to everyone
   * - Private files require matching tenant ID from session
   */
  app.get('/objects/:objectPath(*)', async (req, res, next) => {
    try {
      // Allow embedding from external contexts (email clients, social media, etc.).
      // Helmet's default `Cross-Origin-Resource-Policy: same-origin` causes
      // WebKit-based mail clients (Apple Mail, iOS Mail) to refuse to render
      // images linked from emails, even when the underlying request succeeds.
      res.setHeader('Cross-Origin-Resource-Policy', 'cross-origin');

      const { ObjectStorageService, ObjectNotFoundError } = await import('./objectStorage');
      const { ObjectPermission, getObjectAclPolicy } = await import('./objectAcl');
      const objectStorageService = new ObjectStorageService();
      const objectFile = await objectStorageService.getObjectEntityFile(req.path);

      // Short-lived view token bypass (issued by /api/help-documents/:id/view-token)
      // Allows embedding private docs in iframes without re-authenticating
      const viewToken = req.query.view_token as string | undefined;
      if (viewToken) {
        const tokenData = docViewTokens.get(viewToken);
        if (tokenData && tokenData.expiresAt > Date.now() && req.path === tokenData.fileUrl) {
          // Set Content-Disposition: inline so browsers render PDFs/images in-place
          res.setHeader('Content-Disposition', 'inline');
          await objectStorageService.downloadObject(objectFile, res);
          return;
        }
        return res.sendStatus(403);
      }
      
      // Extract tenant ID from path if present (new tenant-scoped paths)
      const pathTenantId = objectStorageService.extractTenantIdFromPath(req.path);
      
      // Get session tenant ID if available
      const sessionTenantId = req.tenant?.id;
      const userId = req.session?.userId;
      
      // Debug: Log ACL info for troubleshooting social media crawler access
      const userAgent = req.get('User-Agent') || '';
      const isCrawler = ['facebookexternalhit', 'Facebot', 'Twitterbot', 'LinkedInBot'].some(
        c => userAgent.toLowerCase().includes(c.toLowerCase())
      );
      if (isCrawler) {
        const aclPolicy = await getObjectAclPolicy(objectFile);
        console.log(`[OBJECT-ACCESS] Crawler request for: ${req.path}`);
        console.log(`[OBJECT-ACCESS] User-Agent: ${userAgent.substring(0, 60)}`);
        console.log(`[OBJECT-ACCESS] ACL Policy: ${JSON.stringify(aclPolicy)}`);
        console.log(`[OBJECT-ACCESS] Session: userId=${userId}, tenantId=${sessionTenantId}`);
      }
      
      // Check if user can access this object
      const canAccess = await objectStorageService.canAccessObjectEntity({
        userId,
        tenantId: sessionTenantId,
        objectFile,
        requestedPermission: ObjectPermission.READ,
      });
      
      if (isCrawler) {
        console.log(`[OBJECT-ACCESS] canAccess result: ${canAccess}`);
      }
      
      if (!canAccess) {
        // For tenant-scoped paths, verify the path tenant matches session tenant
        if (pathTenantId && sessionTenantId && pathTenantId !== sessionTenantId) {
          console.log(`[OBJECT-ACCESS] Denied: tenant mismatch path=${pathTenantId} session=${sessionTenantId}`);
          return res.sendStatus(403);
        }
        // If no session and file is private, deny access
        console.log(`[OBJECT-ACCESS] Denied: no session and file is private`);
        return res.sendStatus(403);
      }
      
      await objectStorageService.downloadObject(objectFile, res);
    } catch (error: any) {
      if (error.name === 'ObjectNotFoundError') {
        console.log(`[OBJECT-ACCESS] 404: Object not found at ${req.path}`);
        return res.sendStatus(404);
      }
      next(error);
    }
  });

