  /**
   * GET /api/applications
   * Get all applications (staff only)
   * Supports filtering by animalId query parameter
   */
  app.get('/api/applications', requireTenant, requireAuth, requireRoleOrPageAccess('applications', 'admin', 'owner', 'board_member', 'staff', 'intake_coordinator'), async (req, res, next) => {
    try {
      const { animalId, stage } = req.query;
      
      // If animalId filter is provided, use direct query with filtering
      if (animalId && typeof animalId === 'string') {
        // Using static imports from top of file for production reliability
        const conditions = [eq(applications.tenantId, req.tenant!.id)];
        conditions.push(eq(applications.animalId, animalId));
        if (stage && typeof stage === 'string') {
          conditions.push(eq(applications.stage, stage as any));
        }
        const applicationsList = await db
          .select({
            id: applications.id,
            tenantId: applications.tenantId,
            animalId: applications.animalId,
            applicantName: applications.applicantName,
            applicantEmail: applications.applicantEmail,
            applicantPhone: applications.applicantPhone,
            stage: applications.stage,
            createdAt: applications.createdAt,
            notes: applications.notes,
            updatedAt: applications.updatedAt,
            customResponses: applications.customResponses,
          })
          .from(applications)
          .where(and(...conditions));
        // Add animal name to each application
        const animalsData = await db.select({ id: animals.id, name: animals.name })
          .from(animals)
          .where(eq(animals.tenantId, req.tenant!.id));
        const animalsMap = new Map(animalsData.map(a => [a.id, a.name]));
        const applicationsWithAnimal = applicationsList.map(app => ({
          ...app,
          animalName: app.animalId ? animalsMap.get(app.animalId) || null : null,
        }));
        return res.json({ applications: applicationsWithAnimal });
      }
      
      // Otherwise get all applications
      const { getApplicationsByTenant } = await import('./services/applications');
      const allApplications = await getApplicationsByTenant(req.tenant!.id);
      
      res.json({ applications: allApplications });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/applications
   * Submit adoption application (public)
   * Supports Google Ads conversion tracking via gclid parameter
   */
  app.post('/api/applications', requireTenant, async (req, res, next) => {
    try {
      const { createApplication } = await import('./services/applications');
      const { insertApplicationSchema } = await import('@shared/schema');
      
      const { gclid, isBypass, ...applicationData } = req.body;
      const data = insertApplicationSchema.omit({ tenantId: true }).parse({
        ...applicationData,
        gclid: gclid || null,
        gclidCapturedAt: gclid ? new Date() : null,
      });
      
      if (isBypass && data.animalId && data.applicantEmail) {
        const { applications } = await import('@shared/schema');
        const [existing] = await db
          .select()
          .from(applications)
          .where(and(
            eq(applications.tenantId, req.tenant!.id),
            eq(applications.animalId, data.animalId),
            eq(applications.applicantEmail, data.applicantEmail),
            eq(applications.stage, 'approved')
          ))
          .limit(1);
        if (existing) {
          return res.json({ success: true, application: existing });
        }
      }

      const application = await createApplication(req.tenant!.id, data);
      
      if (gclid && application) {
        try {
          const { uploadConversionToGoogleAds } = await import('./googleAds');
          const conversionResult = await uploadConversionToGoogleAds(
            req.tenant!.id,
            application.id,
            gclid
          );
          if (!conversionResult.success) {
            console.log('Google Ads conversion upload skipped or failed:', conversionResult.error);
          }
        } catch (conversionError) {
          console.error('Error uploading Google Ads conversion:', conversionError);
        }
      }
      
      // Get animal name for notification
      let animalName: string | undefined;
      if (data.animalId) {
        try {
          const { animals } = await import('@shared/schema');
          const [animal] = await db
            .select({ name: animals.name })
            .from(animals)
            .where(eq(animals.id, data.animalId))
            .limit(1);
          if (animal) {
            animalName = animal.name;
          }
        } catch (err) {
          console.error('Failed to fetch animal name for notification:', err);
        }
      }

      // Send email notification to staff if enabled (skip for internal bypass applications)
      if (!isBypass) {
        try {
          const { sendFormSubmissionNotification } = await import('./services/form-notifications');
          await sendFormSubmissionNotification({
            formType: 'adoption',
            tenantId: req.tenant!.id,
            applicantName: data.applicantName,
            applicantEmail: data.applicantEmail,
            applicantPhone: data.applicantPhone,
            applicationId: application.id,
            animalName,
          });
        } catch (error) {
          console.error('Failed to send form notification email:', error);
        }
      }
      
      res.json({ success: true, application });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/applications/:id/stage
   * Update application stage (staff only)
   */
  app.patch('/api/applications/:id/stage', requireTenant, requireAuth, requireRoleOrPageAccess('applications', 'admin', 'staff'), async (req, res, next) => {
    try {
      const { updateApplicationStage } = await import('./services/applications');
      const stageSchema = z.object({ stage: z.enum(['new', 'screening', 'vet_check', 'home_visit', 'approved', 'trial', 'adopted', 'denied', 'trial_failed']) });
      
      const { stage } = stageSchema.parse(req.body);
      // Pass user ID for auto-dismiss functionality
      const application = await updateApplicationStage(req.tenant!.id, req.params.id, stage, req.user!.id);
      
      if (!application) {
        return res.status(404).json({ error: 'Application not found' });
      }
      
      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'application.stage_change',
          entityType: 'adoption_application',
          entityId: req.params.id,
          changes: { after: { stage } },
          metadata: { applicantName: application.applicantName || null },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      res.json({ success: true, application });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/applications/:id/change-animal
   * Change the animal associated with an application (only before agreement is sent)
   */
  app.post('/api/applications/:id/change-animal', requireTenant, requireAuth, requireRole('admin', 'manager', 'staff'), async (req, res, next) => {
    try {
      const { applications, animals, adoptionCheckoutSessions } = await import('@shared/schema');
      const changeAnimalSchema = z.object({ newAnimalId: z.string().uuid() });
      const { newAnimalId } = changeAnimalSchema.parse(req.body);
      const [application] = await db.select({
        id: applications.id,
        stage: applications.stage,
        animalId: applications.animalId,
      }).from(applications).where(
        and(eq(applications.id, req.params.id), eq(applications.tenantId, req.tenant!.id))
      );
      
      if (!application) {
        return res.status(404).json({ error: 'Application not found' });
      }
      
      const eligibleStages = ['new', 'screening', 'vet_check', 'home_visit', 'approved'];
      if (!eligibleStages.includes(application.stage)) {
        return res.status(400).json({ 
          error: 'Cannot change animal at this stage',
          message: 'Animal can only be changed before the agreement is sent'
        });
      }
      
      const [existingCheckout] = await db.select({
        id: adoptionCheckoutSessions.id,
        status: adoptionCheckoutSessions.status,
      }).from(adoptionCheckoutSessions).where(
        and(
          eq(adoptionCheckoutSessions.applicationId, req.params.id),
          eq(adoptionCheckoutSessions.tenantId, req.tenant!.id)
        )
      );
      
      if (existingCheckout && existingCheckout.status !== 'pending') {
        return res.status(400).json({ 
          error: 'Cannot change animal',
          message: 'A checkout process has already been started for this application'
        });
      }
      
      const [animal] = await db.select({
        id: animals.id,
        name: animals.name,
        status: animals.status,
      }).from(animals).where(
        and(eq(animals.id, newAnimalId), eq(animals.tenantId, req.tenant!.id))
      );
      
      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }
      
      const originalAnimalId = application.animalId;
      
      const [updated] = await db.update(applications)
        .set({ animalId: newAnimalId })
        .where(and(eq(applications.id, req.params.id), eq(applications.tenantId, req.tenant!.id)))
        .returning();
      
      if (originalAnimalId && originalAnimalId !== newAnimalId) {
        const otherActiveApps = await db
          .select({ id: applications.id, stage: applications.stage })
          .from(applications)
          .where(and(
            eq(applications.tenantId, req.tenant!.id),
            eq(applications.animalId, originalAnimalId)
          ));
        
        const hasOtherAdvancedApps = otherActiveApps.some(
          app => app.id !== req.params.id &&
                 ['home_visit', 'approved', 'trial'].includes(app.stage)
        );
        
        if (!hasOtherAdvancedApps) {
          const [originalAnimal] = await db
            .select({ id: animals.id, status: animals.status })
            .from(animals)
            .where(and(
              eq(animals.id, originalAnimalId),
              eq(animals.tenantId, req.tenant!.id)
            ))
            .limit(1);
          
          if (originalAnimal && originalAnimal.status === 'adoption_pending') {
            await db
              .update(animals)
              .set({ status: 'available', updatedAt: new Date() })
              .where(and(
                eq(animals.id, originalAnimalId),
                eq(animals.tenantId, req.tenant!.id)
              ));
            console.log(`Animal ${originalAnimalId} status reverted to available after being swapped off application ${req.params.id}`);
          }
        }
      }
      
      res.json({ success: true, application: updated, newAnimal: animal });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/applications/approve-and-send
   * Approve an application and optionally create checkout session + send contract for e-signature
   * This is the automated adoption workflow trigger
   */
  app.post('/api/applications/approve-and-send', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { updateApplicationStage, getApplicationById } = await import('./services/applications');
      const { createCheckoutSession, sendCheckoutLink } = await import('./services/adoption-checkout');
      const { adoptionCheckoutSessions } = await import('@shared/schema');
      
      const approveSchema = z.object({
        applicationId: z.string().uuid(),
        sendContract: z.boolean().default(false),
        baseFee: z.string().optional(),
        grantId: z.string().uuid().optional().nullable(),
        contractTemplateId: z.string().optional().nullable(),
        vetAppointmentDate: z.string().optional().nullable(),
        spayNeuterDate: z.string().optional().nullable(),
        staffConfirmValues: z.record(z.string()).optional().nullable(),
        medicalDueDates: z.object({
          rabiesDueDate: z.string(),
          dhppDueDate: z.string(),
          bordetellaDueDate: z.string().optional(),
          heartwormDueDate: z.string().optional(),
          fleaTickDueDate: z.string().optional(),
        }).optional().nullable(),
        carePriorities: z.object({
          enabled: z.boolean(),
          flags: z.object({
            medicalNeeds: z.object({ checked: z.boolean(), notes: z.string() }).optional(),
            behavioral: z.object({ checked: z.boolean(), notes: z.string() }).optional(),
            diet: z.object({ checked: z.boolean(), notes: z.string() }).optional(),
            flightRisk: z.object({ checked: z.boolean(), notes: z.string() }).optional(),
          }),
        }).optional().nullable(),
        customComplianceObligations: z.array(z.object({
          obligationType: z.string(),
          label: z.string(),
          contractualDueDate: z.string(),
          notes: z.string().optional(),
        })).optional().nullable(),
        isFeeWaived: z.boolean().optional(),
        feeWaiverReason: z.string().max(500).optional().nullable(),
        sendMethod: z.enum(['sms', 'email']).optional(),
      });
      
      const { applicationId, sendContract, baseFee, grantId, contractTemplateId, vetAppointmentDate, spayNeuterDate, staffConfirmValues, medicalDueDates, carePriorities, customComplianceObligations, isFeeWaived, feeWaiverReason, sendMethod } = approveSchema.parse(req.body);
      
      // Get the application details
      const application = await getApplicationById(req.tenant!.id, applicationId);
      if (!application) {
        return res.status(404).json({ error: 'Application not found' });
      }
      
      // Validate contract template if sending contract
      let parsedTemplateId: number | undefined;
      if (sendContract) {
        // Validate that contractTemplateId is provided and is a valid positive integer
        if (!contractTemplateId || contractTemplateId.trim() === '') {
          return res.status(400).json({ 
            error: 'Contract template required', 
            message: 'A contract template must be selected to send an agreement' 
          });
        }
        parsedTemplateId = parseInt(contractTemplateId, 10);
        if (isNaN(parsedTemplateId) || parsedTemplateId <= 0) {
          return res.status(400).json({ 
            error: 'Invalid contract template', 
            message: 'Please select a valid contract template' 
          });
        }
        
        // Validate mandatory medical due dates are present when sending contract (rabies + DHPP)
        if (!medicalDueDates || !medicalDueDates.rabiesDueDate || !medicalDueDates.dhppDueDate) {
          return res.status(400).json({ 
            error: 'Medical due dates required', 
            message: 'Rabies and DHPP due dates must be provided when sending an agreement' 
          });
        }
        
        // Validate date formats for mandatory fields
        const dateFields = [medicalDueDates.rabiesDueDate, medicalDueDates.dhppDueDate].filter(Boolean);
        for (const dateStr of dateFields) {
          if (isNaN(new Date(dateStr).getTime())) {
            return res.status(400).json({
              error: 'Invalid date format',
              message: 'All medical due dates must be valid dates'
            });
          }
        }
      }
      
      // Update application stage to approved (auto-dismisses from pending widget)
      const updatedApplication = await updateApplicationStage(req.tenant!.id, applicationId, 'approved', req.user!.id);
      if (!updatedApplication) {
        return res.status(500).json({ error: 'Failed to update application status' });
      }
      
      let contractSent = false;
      let checkoutSession = null;
      let smsQuietHoursWarning: string | null = null;
      
      // If sendContract is true, create checkout session and send contract email
      if (sendContract && parsedTemplateId) {
        // Create checkout session - this generates and stores the secure token
        const sessionResult = await createCheckoutSession(req.tenant!.id, {
          applicationId,
          animalId: application.animalId,
          staffInitiatedBy: req.user!.id,
          baseFee: baseFee || '200',
          grantId: grantId || undefined,
          contractTemplateId: parsedTemplateId,
          vetAppointmentDate: vetAppointmentDate || undefined,
          spayNeuterDate: spayNeuterDate || undefined,
          staffConfirmValues: staffConfirmValues || undefined,
          medicalDueDates: medicalDueDates || undefined,
          carePriorities: carePriorities || undefined,
          customComplianceObligations: customComplianceObligations || undefined,
          isFeeWaived: isFeeWaived || false,
          feeWaiverReason: feeWaiverReason || undefined,
        });
        checkoutSession = sessionResult.session;
        // Use the token returned by createCheckoutSession - it matches the stored hash
        const token = sessionResult.token;
        // Update session status to awaiting_signature
        await db
          .update(adoptionCheckoutSessions)
          .set({
            status: 'awaiting_signature',
            updatedAt: new Date(),
          })
          .where(eq(adoptionCheckoutSessions.id, checkoutSession.id));
        // Send the checkout link via preferred method (default to email)
        const deliveryMethod = sendMethod || 'email';
        try {
          await sendCheckoutLink(checkoutSession.id, token, deliveryMethod);
          contractSent = true;
        } catch (sendErr: any) {
          if (sendErr.isQuietHours || sendErr.statusCode === 422) {
            contractSent = false;
            smsQuietHoursWarning = sendErr.message || 'SMS cannot be sent during quiet hours (8 PM – 6 AM CST). The adoption was approved — please resend the link during business hours or switch to email.';
          } else {
            throw sendErr;
          }
        }
      }
      
      res.json({ 
        success: true, 
        application: updatedApplication,
        contractSent,
        checkoutSession: checkoutSession ? { id: checkoutSession.id } : null,
        ...(smsQuietHoursWarning ? { warning: smsQuietHoursWarning } : {}),
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Adoption Checkout Routes - Smart Adoption Workflow
  // ============================================================================

  /**
   * POST /api/adoptions/checkouts
   * Create a new adoption checkout session (staff only)
   */
  app.post('/api/adoptions/checkouts', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { createCheckoutSession } = await import('./services/adoption-checkout');
      
      const sessionSchema = z.object({
        applicationId: z.string().uuid(),
        animalId: z.string().uuid(),
        adopterContactId: z.string().uuid().optional(),
        grantId: z.string().uuid().optional(),
        contractTemplateId: z.string().optional(),
        baseFee: z.string(),
        donationBoost: z.string().optional(),
        coverFees: z.boolean().optional(),
        processor: z.enum(['stripe']).optional(),
        isFeeWaived: z.boolean().optional(),
        feeWaiverReason: z.string().max(500).optional().nullable(),
      });

      const data = sessionSchema.parse(req.body);
      
      // Security: Validate grantId belongs to this tenant if provided
      if (data.grantId) {
        const { grants } = await import('@shared/schema');
        const [grant] = await db
          .select({
            id: grants.id,
            tenantId: grants.tenantId,
          })
          .from(grants)
          .where(and(
            eq(grants.id, data.grantId),
            eq(grants.tenantId, req.tenant!.id)
          ))
          .limit(1);
        if (!grant) {
          return res.status(400).json({ error: 'Grant not found or does not belong to this organization' });
        }
      }
      
      const result = await createCheckoutSession(req.tenant!.id, {
        ...data,
        contractTemplateId: data.contractTemplateId ? parseInt(data.contractTemplateId) : undefined,
        staffInitiatedBy: req.user!.id,
      });

      res.json({
        success: true,
        session: result.session,
        token: result.token,
      });
    } catch (error: any) {
      next(error);
    }
  });

