  /**
   * POST /api/public/adoption-checkouts/:token/sign
   * Submit signature for contract (public, token-protected)
   * After signing, automatically sends payment link email to adopter
   */
  app.post('/api/public/adoption-checkouts/:token/sign', async (req, res, next) => {
    try {
      const { getCheckoutSessionByToken, captureSignature, sendPaymentLinkEmail } = await import('./services/adoption-checkout');
      
      const session = await getCheckoutSessionByToken(req.params.token);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      if (session.status === 'awaiting_payment') {
        return res.json({ success: true, alreadySigned: true, message: 'Contract already signed' });
      }

      const signatureSchema = z.object({
        signerName: z.string().min(1),
        signerEmail: z.string().email(),
        signatureImageData: z.string(), // Base64 image
        templateId: z.number().optional(),
        driversLicenseNumber: z.string().min(1, "Driver's license number is required"),
      });

      const signatureData = signatureSchema.parse(req.body);

      const contract = await captureSignature(session.id, {
        ...signatureData,
        ipAddress: req.ip,
        userAgent: req.get('user-agent'),
      });

      // Automatically send payment link email after signature (only for paid adoptions)
      // For fee-waived adoptions, skip the payment email entirely
      const isFeeWaived = session.isFeeWaived === true;
      const sessionBaseFee = parseFloat(session.baseFee || '0');
      if (!isFeeWaived && sessionBaseFee > 0) {
        try {
          await sendPaymentLinkEmail(session.id, req.params.token);
        } catch (emailError) {
          console.error('Failed to send payment link email:', emailError);
        }
      } else {
        console.log(`[Adoption] Skipping payment email for $0 adoption (session ${session.id})`);
      }

      // Send notification email to rescue contact person
      try {
        const { EmailService } = await import('./lib/email-service');
        const [tenant] = await db
          .select({ name: tenants.name, contactEmail: tenants.contactEmail })
          .from(tenants)
          .where(eq(tenants.id, session.tenantId))
          .limit(1);

        if (tenant?.contactEmail) {
          const [animal] = await db
            .select({ name: animals.name, animalId: animals.animalId })
            .from(animals)
            .where(eq(animals.id, session.animalId))
            .limit(1);

          const emailService = await EmailService.forTenant(session.tenantId);
          if (emailService) {
            const animalName = animal?.name || 'Unknown';
            const animalIdStr = animal?.animalId || '';
            const safeName = escapeHtml(signatureData.signerName);
            const safeEmail = escapeHtml(signatureData.signerEmail);
            const signedDate = new Date().toLocaleString();

            await emailService.send({
              to: tenant.contactEmail,
              subject: `Adoption Contract Signed: ${animalName} — ${signatureData.signerName}`,
              html: `
                <div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto;">
                  <h2 style="color: #22c55e;">Adoption Contract Signed</h2>
                  <p>An adoption contract has been signed:</p>
                  <ul style="line-height: 1.8;">
                    <li><strong>Animal:</strong> ${escapeHtml(animalName)} (${escapeHtml(animalIdStr)})</li>
                    <li><strong>Adopter Name:</strong> ${safeName}</li>
                    <li><strong>Adopter Email:</strong> ${safeEmail}</li>
                    <li><strong>Signed:</strong> ${signedDate}</li>
                    <li><strong>Adoption Fee:</strong> $${session.baseFee || '0'}</li>
                  </ul>
                  ${sessionBaseFee > 0
                    ? '<p>A payment link has been sent to the adopter. You will be notified when payment is completed.</p>'
                    : '<p>This is a $0 adoption — no payment is required.</p>'
                  }
                  <p style="color: #666; font-size: 12px; margin-top: 20px;">
                    IP Address: ${escapeHtml(req.ip || 'Unknown')}
                  </p>
                </div>
              `.trim(),
            });
            console.log(`[Adoption] Sent contract signed notification to: ${tenant.contactEmail}`);
          }
        }
      } catch (notifyError) {
        console.error('[Adoption] Failed to send contract signed notification:', notifyError);
      }

      res.json({ success: true, contract: { id: contract.id }, status: isFeeWaived ? 'completed' : 'awaiting_payment' });
    } catch (error: any) {
      next(error);
    }
  });

  /**
   * POST /api/public/adoption-checkouts/:token/create-payment-intent
   * Create a Stripe PaymentIntent for the adoption checkout (public, token-protected)
   * Called after contract is signed, before payment is collected
   */
  app.post('/api/public/adoption-checkouts/:token/create-payment-intent', async (req, res, next) => {
    try {
      const { getCheckoutSessionByToken, createAdoptionPaymentIntent, updateCheckoutSession, getCheckoutSession } = await import('./services/adoption-checkout');
      
      const session = await getCheckoutSessionByToken(req.params.token);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      if (session.status !== 'awaiting_payment') {
        return res.status(400).json({ error: 'Contract must be signed before creating payment intent' });
      }

      // Parse optional donation boost and cover fees from request
      const updateSchema = z.object({
        donationBoost: z.string()
          .optional()
          .refine(val => !val || !isNaN(parseFloat(val)), 'Must be a valid number')
          .refine(val => !val || parseFloat(val) >= 0, 'Must be non-negative')
          .refine(val => !val || parseFloat(val) <= 10000, 'Donation cannot exceed $10,000')
          .transform(val => val || '0'),
        coverFees: z.boolean().optional().default(false),
      });

      const updates = updateSchema.parse(req.body);

      // Update session with donation/fee selections if provided
      if (updates.donationBoost !== undefined || updates.coverFees !== undefined) {
        await updateCheckoutSession(session.tenantId, session.id, {
          donationBoost: updates.donationBoost,
          coverFees: updates.coverFees,
        });
      }

      // Create the PaymentIntent with real Stripe
      const { clientSecret, paymentIntentId } = await createAdoptionPaymentIntent(session.id);

      // Fetch updated session to get final totals
      const updatedSession = await getCheckoutSession(session.tenantId, session.id);
      
      res.json({ 
        clientSecret, 
        paymentIntentId,
        totals: updatedSession?.totals,
        message: 'PaymentIntent created successfully' 
      });
    } catch (error: any) {
      console.error('Failed to create PaymentIntent:', error);
      if (error.message?.includes('Stripe is not configured')) {
        return res.status(400).json({ 
          error: 'Payment not available',
          message: 'This organization has not configured payment processing. Please contact them directly.'
        });
      }
      next(error);
    }
  });

  /**
   * POST /api/public/adoption-checkouts/:token/payment
   * Process payment for adoption (public, token-protected)
   */
  app.post('/api/public/adoption-checkouts/:token/payment', async (req, res, next) => {
    try {
      const { getCheckoutSessionByToken, updateCheckoutSession, processPayment, finalizeAdoption, validatePaymentInputs, getCheckoutSession } = await import('./services/adoption-checkout');
      
      const session = await getCheckoutSessionByToken(req.params.token);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      const paymentSchema = z.object({
        processor: z.enum(['stripe']),
        paymentMethodId: z.string().optional(),
        // Validate donationBoost: must be numeric string, >= 0, reasonable upper limit
        donationBoost: z.string()
          .optional()
          .refine(val => !val || !isNaN(parseFloat(val)), 'Must be a valid number')
          .refine(val => !val || parseFloat(val) >= 0, 'Must be non-negative')
          .refine(val => !val || parseFloat(val) <= 10000, 'Donation cannot exceed $10,000')
          .transform(val => val || '0'), // Default to '0' if undefined
        // Validate coverFees: must be boolean
        coverFees: z.boolean().optional().default(false),
      });

      const paymentData = paymentSchema.parse(req.body);

      // Validate payment inputs using helper function
      validatePaymentInputs(
        paymentData.donationBoost, 
        paymentData.coverFees, 
        session.baseFee
      );

      // Update session with donation/fee selections if provided
      if (paymentData.donationBoost !== undefined || paymentData.coverFees !== undefined) {
        await updateCheckoutSession(session.tenantId, session.id, {
          donationBoost: paymentData.donationBoost,
          coverFees: paymentData.coverFees,
        });
      }

      // Get updated session to verify totals
      const updatedSession = await getCheckoutSession(session.tenantId, session.id);
      if (!updatedSession) {
        throw new Error('Failed to retrieve updated session');
      }

      // Business logic validation: verify final totals
      if (updatedSession.totals) {
        const totals = updatedSession.totals as { subtotal: string; fees: string; total: string };
        const finalTotal = parseFloat(totals.total);
        const baseFee = parseFloat(updatedSession.baseFee);

        // Ensure final total is at least the base fee (can't be negative or less than base)
        if (finalTotal < baseFee) {
          throw new Error('Invalid payment amount: total cannot be less than base adoption fee');
        }

        // Ensure total is reasonable (not absurdly high due to manipulation)
        if (finalTotal > baseFee + 10000) {
          throw new Error('Invalid payment amount: total exceeds reasonable limits');
        }
      }

      const payment = await processPayment(session.id, paymentData);

      // Finalize adoption (update animal status, create journey, send emails)
      await finalizeAdoption(session.id);

      res.json({ success: true, payment: { id: payment.id, status: payment.status } });
    } catch (error: any) {
      next(error);
    }
  });

  /**
   * POST /api/public/adoption-checkouts/:token/finalize-free
   * Finalize a $0 adoption without payment (public, token-protected)
   */
  app.post('/api/public/adoption-checkouts/:token/finalize-free', async (req, res, next) => {
    try {
      const { getCheckoutSessionByToken, finalizeAdoption, updateCheckoutSession } = await import('./services/adoption-checkout');
      
      const session = await getCheckoutSessionByToken(req.params.token);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      // Verify this is actually a $0 adoption - prevent abuse
      const baseFee = parseFloat(session.baseFee || '0');
      const donationBoost = parseFloat(session.donationBoost || '0');
      const total = baseFee + donationBoost;
      
      if (total > 0) {
        return res.status(400).json({ 
          error: 'This adoption requires payment', 
          message: 'Cannot use free finalization for adoptions with fees' 
        });
      }

      // Verify contract has been signed (captureSignature sets status to 'awaiting_payment', but also accept 'signed' for backwards compatibility)
      if (session.status !== 'awaiting_payment' && session.status !== 'signed') {
        return res.status(400).json({ 
          error: 'Contract not signed', 
          message: 'Please sign the contract before finalizing' 
        });
      }
      // Update session to mark payment as complete (even though $0)
      // Direct DB update since updateCheckoutSession does not support status/metadata
      await db
        .update(adoptionCheckoutSessions)
        .set({
          status: "completed",
          paidAt: new Date(),
          donationBoost: "0",
          metadata: {
            ...((session.metadata as object) || {}),
            zeroFeeAdoption: true,
            finalizedAt: new Date().toISOString(),
          },
          updatedAt: new Date(),
        })
        .where(eq(adoptionCheckoutSessions.id, session.id));

      // Finalize adoption (update animal status, create journey, send emails)
      await finalizeAdoption(session.id);

      res.json({ success: true, message: 'Adoption finalized successfully' });
    } catch (error: any) {
      next(error);
    }
  });

  /**
   * GET /api/public/adoption-checkouts/:token/status
   * Check completion status (public, token-protected)
   */
  app.get('/api/public/adoption-checkouts/:token/status', async (req, res, next) => {
    try {
      const { getCheckoutSessionByToken } = await import('./services/adoption-checkout');
      
      const session = await getCheckoutSessionByToken(req.params.token);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      res.json({
        status: session.status,
        signedAt: session.signedAt,
        paidAt: session.paidAt,
        isComplete: session.status === 'completed',
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/public/adoption-checkouts/:token/contract
   * Download signed contract PDF (public, token-protected)
   * Security: Only allows download after session is completed (signed + paid)
   * Returns a time-limited signed URL (valid for 15 minutes)
   */
  app.get('/api/public/adoption-checkouts/:token/contract', async (req, res, next) => {
    try {
      const { getCheckoutSessionByTokenForDownload } = await import('./services/adoption-checkout');
      const { adoptionContracts } = await import('@shared/schema');
      const { generateSignedContractUrl } = await import('./services/contract-pdf');
      
      const session = await getCheckoutSessionByTokenForDownload(req.params.token);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      // Security: Only allow downloading contract after session is completed (signed + paid)
      // This ensures the adopter has fully completed the process before accessing their contract
      if (session.status !== 'completed') {
        return res.status(403).json({ error: 'Contract is not yet available. Please complete the adoption process first.' });
      }

      // Verify signature exists
      if (!session.signedAt) {
        return res.status(400).json({ error: 'Contract has not been signed yet' });
      }

      // Fetch the contract record
      const [contract] = await db
        .select({
          id: adoptionContracts.id,
          sessionId: adoptionContracts.sessionId,
          contractPdfUrl: adoptionContracts.contractPdfUrl,
          signerName: adoptionContracts.signerName,
          signerEmail: adoptionContracts.signerEmail,
          signedAt: adoptionContracts.signedAt,
        })
        .from(adoptionContracts)
        .where(eq(adoptionContracts.sessionId, session.id))
        .limit(1);

      if (!contract || !contract.contractPdfUrl) {
        return res.status(404).json({ error: 'Signed contract not found' });
      }

      // Generate time-limited signed URL (15 minutes expiry) for secure download
      const signedUrl = await generateSignedContractUrl(contract.contractPdfUrl, 900);

      res.json({
        contractPdfUrl: signedUrl,
        signedAt: contract.signedAt,
        signerName: contract.signerName,
        signerEmail: contract.signerEmail,
        expiresIn: 900, // URL expires in 15 minutes
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Foster Agreement Sessions Routes (Public, token-protected)
  // ============================================================================

  /**
   * GET /api/public/foster-agreements/:token
   * Get foster agreement session data for signing (public, token-protected)
   */
  app.get('/api/public/foster-agreements/:token', async (req, res, next) => {
    try {
      const { fosterAgreementSessions, fosterContractTemplates, fosterApplications, animals, tenants } = await import('@shared/schema');
      const crypto = await import('crypto');
      
      const tokenHash = crypto.createHash('sha256').update(req.params.token).digest('hex');
      
      const [session] = await db
        .select({
          id: fosterAgreementSessions.id,
          tenantId: fosterAgreementSessions.tenantId,
          fosterApplicationId: fosterAgreementSessions.fosterApplicationId,
          templateId: fosterAgreementSessions.templateId,
          fosterName: fosterAgreementSessions.fosterName,
          fosterEmail: fosterAgreementSessions.fosterEmail,
          fosterPhone: fosterAgreementSessions.fosterPhone,
          status: fosterAgreementSessions.status,
          expiresAt: fosterAgreementSessions.expiresAt,
          signedAt: fosterAgreementSessions.signedAt,
        })
        .from(fosterAgreementSessions)
        .where(eq(fosterAgreementSessions.secureTokenHash, tokenHash))
        .limit(1);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      // Check expiration
      if (session.expiresAt && new Date(session.expiresAt) < new Date()) {
        return res.status(410).json({ error: 'Session has expired' });
      }

      const [tenant] = await db
        .select({ name: tenants.name })
        .from(tenants)
        .where(eq(tenants.id, session.tenantId))
        .limit(1);

      // Fetch and process contract template
      let contractData: { html: string; name: string } | null = null;
      if (session.templateId) {
        const DOMPurify = (await import('isomorphic-dompurify')).default;
        const [template] = await db
          .select({
            id: fosterContractTemplates.id,
            name: fosterContractTemplates.name,
            htmlTemplate: fosterContractTemplates.htmlTemplate,
          })
          .from(fosterContractTemplates)
          .where(eq(fosterContractTemplates.id, session.templateId))
          .limit(1);
        if (template) {
          const { mergeFosterPlaceholders, buildFosterMergeData } = await import('./services/foster-contract-template');
          
          // Fetch foster application for address
          let fosterAddress = '';
          const [fosterApp] = await db
            .select({ address: fosterApplications.address })
            .from(fosterApplications)
            .where(eq(fosterApplications.id, session.fosterApplicationId))
            .limit(1);
          if (fosterApp) {
            fosterAddress = fosterApp.address || '';
          }
          
          const mergeData = buildFosterMergeData({
            tenantName: tenant?.name || '',
            fosterName: session.fosterName || '',
            fosterEmail: session.fosterEmail || '',
            fosterPhone: session.fosterPhone,
            fosterAddress,
          });
          
          const processedHtml = mergeFosterPlaceholders(template.htmlTemplate, mergeData);
          
          // Sanitize HTML
          const sanitizedHtml = DOMPurify.sanitize(processedHtml, {
            ALLOWED_TAGS: ['div', 'span', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'strong', 'em', 'u', 'br', 'hr', 'ul', 'ol', 'li', 'table', 'thead', 'tbody', 'tr', 'th', 'td', 'img'],
            ALLOWED_ATTR: ['class', 'style', 'src', 'alt'],
            ALLOW_DATA_ATTR: false,
          });
          
          contractData = {
            html: sanitizedHtml,
            name: template.name,
          };
        }
      }

      res.json({
        session: {
          id: session.id,
          status: session.status,
          expiresAt: session.expiresAt,
          signedAt: session.signedAt,
          fosterName: session.fosterName,
          fosterEmail: session.fosterEmail,
        },
        animal: null,
        applicant: {
          name: session.fosterName,
          email: session.fosterEmail,
          phone: session.fosterPhone,
        },
        contract: contractData,
        organization: tenant ? { name: tenant.name } : null,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/public/foster-agreements/:token/sign
   * Submit signature for foster agreement (public, token-protected)
   */
  app.post('/api/public/foster-agreements/:token/sign', async (req, res, next) => {
    try {
      const { fosterAgreementSessions, fosterContractTemplates, fosterApplications, tenants } = await import('@shared/schema');
      const crypto = await import('crypto');
      
      const tokenHash = crypto.createHash('sha256').update(req.params.token).digest('hex');
      
      const [session] = await db
        .select({
          id: fosterAgreementSessions.id,
          tenantId: fosterAgreementSessions.tenantId,
          fosterApplicationId: fosterAgreementSessions.fosterApplicationId,
          templateId: fosterAgreementSessions.templateId,
          fosterName: fosterAgreementSessions.fosterName,
          fosterEmail: fosterAgreementSessions.fosterEmail,
          fosterPhone: fosterAgreementSessions.fosterPhone,
          status: fosterAgreementSessions.status,
          expiresAt: fosterAgreementSessions.expiresAt,
        })
        .from(fosterAgreementSessions)
        .where(eq(fosterAgreementSessions.secureTokenHash, tokenHash))
        .limit(1);

      if (!session) {
        return res.status(404).json({ error: 'Session not found or expired' });
      }

      if (session.status === 'signed') {
        return res.status(400).json({ error: 'Agreement has already been signed' });
      }

      if (session.expiresAt && new Date(session.expiresAt) < new Date()) {
        return res.status(410).json({ error: 'Session has expired' });
      }

      const signatureSchema = z.object({
        signerName: z.string().min(1),
        signerEmail: z.string().email(),
        signatureImageData: z.string(),
      });

      const signatureData = signatureSchema.parse(req.body);

      // Render final contract with signature
      let renderedContract = '';
      if (session.templateId) {
        const [template] = await db
          .select({
            id: fosterContractTemplates.id,
            htmlTemplate: fosterContractTemplates.htmlTemplate,
          })
          .from(fosterContractTemplates)
          .where(eq(fosterContractTemplates.id, session.templateId))
          .limit(1);
        if (template) {
          const [tenant] = await db
            .select({ name: tenants.name })
            .from(tenants)
            .where(eq(tenants.id, session.tenantId))
            .limit(1);
          
          // Fetch foster application for address
          let fosterAddress = '';
          const [fosterApp] = await db
            .select({ address: fosterApplications.address })
            .from(fosterApplications)
            .where(eq(fosterApplications.id, session.fosterApplicationId))
            .limit(1);
          if (fosterApp) {
            fosterAddress = fosterApp.address || '';
          }
          
          const { mergeFosterPlaceholders, buildFosterMergeData } = await import('./services/foster-contract-template');
          const mergeData = buildFosterMergeData({
            tenantName: tenant?.name || '',
            fosterName: signatureData.signerName,
            fosterEmail: signatureData.signerEmail,
            fosterPhone: session.fosterPhone,
            fosterAddress,
            signatureImageUrl: signatureData.signatureImageData,
            signedTimestamp: new Date().toISOString(),
            signedIp: req.ip || '',
          });
          
          renderedContract = mergeFosterPlaceholders(template.htmlTemplate, mergeData);
        }
      }

      // Update session with signature
      const signedAt = new Date();
      await db
        .update(fosterAgreementSessions)
        .set({
          status: 'signed',
          signedAt,
          signatureData: signatureData.signatureImageData,
          signedIp: req.ip,
          renderedContract,
          updatedAt: new Date(),
        })
        .where(eq(fosterAgreementSessions.id, session.id));

      // Generate PDF of the signed agreement
      let contractPdfUrl: string | undefined;
      try {
        const { generateFosterAgreementPDF } = await import('./services/foster-agreement-pdf');
        if (renderedContract) {
          contractPdfUrl = await generateFosterAgreementPDF(session.id, renderedContract, {
            ipAddress: req.ip,
            signedAt,
          });
          
          // Update session with PDF URL
          await db
            .update(fosterAgreementSessions)
            .set({ contractPdfUrl })
            .where(eq(fosterAgreementSessions.id, session.id));
          
          console.log(`[Foster Agreement] Generated PDF for session ${session.id}: ${contractPdfUrl}`);
        }
      } catch (pdfError) {
        console.error('[Foster Agreement] Failed to generate PDF:', pdfError);
        // Don't fail the signing process if PDF generation fails
      }

      // Update foster application to 'active_pool' status (approved foster)
      await db
        .update(fosterApplications)
        .set({
          pipelineStatus: 'active_pool',
          status: 'approved',
          updatedAt: new Date(),
        })
        .where(eq(fosterApplications.id, session.fosterApplicationId));
      
      console.log(`[Foster Agreement] Updated application ${session.fosterApplicationId} to active_pool status`);

      // Sync foster to contacts directory & user system
      try {
        const { activateFosterInDirectory } = await import('./services/contacts');
        await activateFosterInDirectory({
          tenantId: session.tenantId,
          applicantName: signatureData.signerName,
          applicantEmail: signatureData.signerEmail,
          fosterApplicationId: session.fosterApplicationId,
        });
      } catch (syncError) {
        console.error('[Foster Agreement] Error syncing foster to directory:', syncError);
      }

      // Create Google Drive folder for the foster (same automation as when manually moved to active_pool)
      // Check if folder already exists to avoid duplicates
      const [fosterAppForFolder] = await db
        .select({ driveFolderId: fosterApplications.driveFolderId })
        .from(fosterApplications)
        .where(eq(fosterApplications.id, session.fosterApplicationId))
        .limit(1);
      
      if (!fosterAppForFolder?.driveFolderId) {
        try {
          const { VolunteerFosterBackupService } = await import('./lib/volunteerFosterBackupService');
          const backupService = new VolunteerFosterBackupService(session.tenantId);
          
          const result = await backupService.createFosterFolder({
            id: session.fosterApplicationId,
            applicantName: signatureData.signerName,
            applicantEmail: signatureData.signerEmail,
          });
          
          if (result.success) {
            console.log(`[Foster Agreement] Created ${result.storageType} folder for ${signatureData.signerName}`);
          }
        } catch (folderError) {
          console.error('[Foster Agreement] Error creating folder:', folderError);
        }
      } else {
        console.log(`[Foster Agreement] Folder already exists for application ${session.fosterApplicationId}, skipping creation`);
      }

      // Send confirmation emails with signed agreement
      try {
        const { EmailService } = await import('./lib/email-service');
        const [tenant] = await db
          .select({ name: tenants.name, contactEmail: tenants.contactEmail })
          .from(tenants)
          .where(eq(tenants.id, session.tenantId))
          .limit(1);
        const emailService = await EmailService.forTenant(session.tenantId);
        // Download PDF from object storage to attach to emails
        let pdfAttachments: { filename: string; content: Buffer; contentType: string }[] = [];
        if (contractPdfUrl) {
          try {
            const privateObjectDir = process.env.PRIVATE_OBJECT_DIR;
            if (privateObjectDir) {
              const pdfFilename = contractPdfUrl.split('/').pop();
              if (pdfFilename) {
                const objectPath = `${privateObjectDir}/foster-contracts/${pdfFilename}`;
                const pathParts = objectPath.split('/');
                const bucketName = pathParts[1];
                const objectName = pathParts.slice(2).join('/');
                const { objectStorageClient } = await import('./objectStorage');
                const bucket = objectStorageClient.bucket(bucketName);
                const file = bucket.file(objectName);
                const [pdfBuffer] = await file.download();
                pdfAttachments.push({
                  filename: `foster-agreement-${escapeHtml(signatureData.signerName).replace(/\s+/g, '-').toLowerCase()}.pdf`,
                  content: Buffer.from(pdfBuffer),
                  contentType: 'application/pdf',
                });
                console.log(`[Foster Agreement] Downloaded PDF for email attachment: ${pdfBuffer.length} bytes`);
              }
            }
          } catch (pdfDownloadError) {
            console.error('[Foster Agreement] Failed to download PDF for attachment:', pdfDownloadError);
          }
        }
        const signedDate = new Date().toLocaleString();
        // Sanitize user-provided data for email HTML
        const safeName = escapeHtml(signatureData.signerName);
        const safeEmail = escapeHtml(signatureData.signerEmail);
        const safePhone = escapeHtml(session.fosterPhone || 'Not provided');
        const safeTenantName = escapeHtml(tenant?.name || 'Animal Rescue Organization');
        const safeIp = escapeHtml(req.ip || 'Not recorded');
        // Build the signed agreement HTML with embedded signature
        const signedAgreementHtml = `
          <div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; border: 1px solid #ddd;">
            <div style="text-align: center; margin-bottom: 20px; padding-bottom: 20px; border-bottom: 2px solid #333;">
              <h1 style="color: #333; margin: 0;">Foster Agreement</h1>
              <p style="color: #666; margin: 5px 0;">${safeTenantName}</p>
            </div>
            
            ${renderedContract || '<p>Agreement content not available.</p>'}
            
            <div style="margin-top: 40px; padding-top: 20px; border-top: 2px solid #333;">
              <h3 style="color: #333;">Electronic Signature</h3>
              <div style="margin: 20px 0;">
                <img src="${signatureData.signatureImageData}" alt="Signature" style="max-width: 300px; border-bottom: 1px solid #333;" />
              </div>
              <p style="margin: 5px 0;"><strong>Signed by:</strong> ${safeName}</p>
              <p style="margin: 5px 0;"><strong>Email:</strong> ${safeEmail}</p>
              <p style="margin: 5px 0;"><strong>Date:</strong> ${signedDate}</p>
              <p style="margin: 5px 0;"><strong>IP Address:</strong> ${safeIp}</p>
            </div>
            
            <div style="margin-top: 30px; padding: 15px; background-color: #f5f5f5; border-radius: 5px;">
              <p style="color: #666; font-size: 12px; margin: 0;">
                This document was electronically signed and is legally binding. A copy has been sent to all parties.
              </p>
            </div>
          </div>
        `;
        // Send confirmation email to foster applicant with signed agreement
        await emailService.send({
          to: signatureData.signerEmail,
          subject: `Your Signed Foster Agreement - ${safeTenantName}`,
          html: `
            <div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto;">
              <h2 style="color: #333;">Thank You for Signing!</h2>
              <p>Hi ${safeName},</p>
              <p>Thank you for signing the foster agreement with <strong>${safeTenantName}</strong>.</p>
              ${pdfAttachments.length > 0
                ? '<p>Your signed agreement is attached to this email as a PDF for your records.</p>'
                : '<p>Your signed agreement is included below for your records.</p>'}
              <p>The rescue organization has been notified and will be in touch with next steps.</p>
              ${pdfAttachments.length === 0 ? `
              <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
              <h3 style="color: #333;">Your Signed Agreement</h3>
              ${signedAgreementHtml}
              ` : ''}
              <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
              <p style="color: #666; font-size: 12px;">
                Please keep this email for your records.
              </p>
            </div>
          `,
          attachments: pdfAttachments.length > 0 ? pdfAttachments : undefined,
        });
        console.log(`[Foster Agreement] Sent confirmation to foster: ${signatureData.signerEmail}`);
        // Send notification to rescue organization's contact email
        if (tenant?.contactEmail) {
          await emailService.send({
            to: tenant.contactEmail,
            subject: `Foster Agreement Signed - ${safeName}`,
            html: `
              <div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto;">
                <h2 style="color: #22c55e;">Foster Agreement Signed!</h2>
                <p>Great news! A foster agreement has been signed:</p>
                <ul style="line-height: 1.8;">
                  <li><strong>Foster Name:</strong> ${safeName}</li>
                  <li><strong>Email:</strong> ${safeEmail}</li>
                  <li><strong>Phone:</strong> ${safePhone}</li>
                  <li><strong>Signed:</strong> ${signedDate}</li>
                </ul>
                <p>The foster applicant has been moved to "In Foster" status and is ready for their foster pet!</p>
                ${pdfAttachments.length > 0
                  ? '<p>The signed foster agreement PDF is attached to this email.</p>'
                  : `<hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
                <h3 style="color: #333;">Signed Agreement Copy</h3>
                ${signedAgreementHtml}`}
              </div>
            `,
            attachments: pdfAttachments.length > 0 ? pdfAttachments : undefined,
          });
          
          console.log(`[Foster Agreement] Sent notification to org: ${tenant.contactEmail}`);
        }
      } catch (emailError) {
        console.error('Failed to send foster agreement confirmation emails:', emailError);
      }

      // Save foster agreement PDF to person documents
      if (contractPdfUrl) {
        try {
          const { personDocuments, contacts } = await import('@shared/schema');
          const normalizedEmail = signatureData.signerEmail.toLowerCase().trim();
          const [contact] = await db
            .select({ id: contacts.id })
            .from(contacts)
            .where(
              and(
                eq(contacts.tenantId, session.tenantId),
                sql`LOWER(TRIM(${contacts.email})) = ${normalizedEmail}`
              )
            )
            .limit(1);

          await db.insert(personDocuments).values({
            tenantId: session.tenantId,
            personType: 'contact',
            personId: contact?.id || null,
            personEmail: signatureData.signerEmail,
            documentType: 'agreement',
            documentSubtype: 'foster_agreement',
            title: `Foster Agreement - ${signatureData.signerName}`,
            description: `Signed foster agreement. Signed on ${new Date().toLocaleDateString()}.`,
            objectPath: contractPdfUrl,
            sourceId: session.id,
            sourceTable: 'foster_agreement_sessions',
            fileName: `foster-agreement-${signatureData.signerName.replace(/\s+/g, '-').toLowerCase()}.pdf`,
            contentType: 'application/pdf',
          });
          console.log(`[Foster Agreement] Saved signed agreement to person documents`);
        } catch (docError) {
          console.error('[Foster Agreement] Failed to save to person documents:', docError);
        }
      }

      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
