  /**
   * POST /api/custom-forms/:id/send
   * Send a form to someone to fill out (creates a pending submission)
   */
  app.post('/api/custom-forms/:id/send', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { getFormById, createSubmission, generateSecureToken } = await import('./services/custom-form');
      const { insertCustomFormSubmissionSchema } = await import('@shared/schema');
      
      const form = await getFormById(req.params.id, req.tenant!.id);
      if (!form) {
        return res.status(404).json({ error: 'Form not found' });
      }

      const { signerName, signerEmail, signerPhone, animalId } = req.body;
      
      if (!signerName || !signerEmail) {
        return res.status(400).json({ error: 'Signer name and email are required' });
      }

      // Validate animal ID for animal-specific forms
      if (form.formType === 'animal_specific' && !animalId) {
        return res.status(400).json({ error: 'Animal selection is required for this form type' });
      }

      const { token, hash } = generateSecureToken();
      const expiresAt = new Date();
      expiresAt.setHours(expiresAt.getHours() + 72); // 72 hours expiry

      const submission = await createSubmission({
        tenantId: req.tenant!.id,
        formId: form.id,
        animalId: animalId || null,
        signerName,
        signerEmail,
        signerPhone: signerPhone || null,
        secureTokenHash: hash,
        expiresAt,
        status: 'pending',
      });

      // TODO: Send email to signer with link to complete form
      // For now, return the token so it can be shared
      // Build the form signing URL - use custom domain if available
      let formUrl: string;
      if (req.tenant!.customDomain) {
        formUrl = `https://${req.tenant!.customDomain}/forms/sign/${token}`;
      } else {
        const isProduction = process.env.REPLIT_DEPLOYMENT === '1';
        const baseUrl = isProduction 
          ? 'https://irescue.life'
          : process.env.REPLIT_DEV_DOMAIN 
            ? `https://${process.env.REPLIT_DEV_DOMAIN}`
            : 'http://localhost:5000';
        formUrl = `${baseUrl}/${req.tenant!.subdomain}/forms/sign/${token}`;
      }

      res.json({ 
        submission, 
        formUrl,
        message: 'Form submission created. Share this link with the signer.' 
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Public Waiver Routes (walk-in volunteer hold harmless)
  // ============================================================================

  /**
   * GET /api/public-waiver
   * Get the tenant's active hold harmless / volunteer waiver form for public display
   */
  app.get('/api/public-waiver', requireTenant, async (req, res, next) => {
    try {
      const tenantId = req.tenant!.id;

      const [form] = await db
        .select({
          id: customForms.id,
          name: customForms.name,
          description: customForms.description,
          htmlTemplate: customForms.htmlTemplate,
          requiresSignature: customForms.requiresSignature,
        })
        .from(customForms)
        .where(
          and(
            eq(customForms.tenantId, tenantId),
            eq(customForms.isActive, true),
            sql`(LOWER(${customForms.name}) LIKE '%hold harmless%' OR (LOWER(${customForms.name}) LIKE '%volunteer%' AND (LOWER(${customForms.name}) LIKE '%waiver%' OR LOWER(${customForms.name}) LIKE '%liability%')))`
          )
        )
        .limit(1);

      if (!form) {
        return res.status(404).json({ error: 'No volunteer waiver form has been configured for this organization.' });
      }

      const [tenant] = await db
        .select({ name: tenants.name, logoUrl: tenants.logoUrl })
        .from(tenants)
        .where(eq(tenants.id, tenantId))
        .limit(1);

      res.json({
        form: {
          id: form.id,
          name: form.name,
          description: form.description,
          htmlTemplate: form.htmlTemplate,
          requiresSignature: form.requiresSignature,
        },
        tenant: {
          name: tenant?.name || 'Organization',
          logo: tenant?.logoUrl || null,
        },
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/public-waiver/sign
   * Submit a signed walk-in volunteer waiver (no token/auth required)
   * Same post-signing flow as /api/public/forms/:token/submit but without pipeline automation
   */
  app.post('/api/public-waiver/sign', requireTenant, async (req, res, next) => {
    try {
      const tenantId = req.tenant!.id;
      const { signerName, signerEmail, signerPhone, signatureData, formData: extraFormData } = req.body;

      if (!signerName || !signerEmail) {
        return res.status(400).json({ error: 'Name and email are required' });
      }

      const [form] = await db
        .select()
        .from(customForms)
        .where(
          and(
            eq(customForms.tenantId, tenantId),
            eq(customForms.isActive, true),
            sql`(LOWER(${customForms.name}) LIKE '%hold harmless%' OR (LOWER(${customForms.name}) LIKE '%volunteer%' AND (LOWER(${customForms.name}) LIKE '%waiver%' OR LOWER(${customForms.name}) LIKE '%liability%')))`
          )
        )
        .limit(1);

      if (!form) {
        return res.status(404).json({ error: 'No volunteer waiver form found' });
      }

      if (form.requiresSignature && !signatureData) {
        return res.status(400).json({ error: 'Signature is required' });
      }

      const ipAddress = req.headers['x-forwarded-for'] as string || req.socket.remoteAddress || '';

      const { createSubmission, updateSubmission, renderFormHtml } = await import('./services/custom-form');

      const submission = await createSubmission({
        tenantId,
        formId: form.id,
        signerName: signerName.trim(),
        signerEmail: signerEmail.trim().toLowerCase(),
        signerPhone: signerPhone?.trim() || null,
        formData: extraFormData || null,
        signatureData,
        signedAt: new Date(),
        signerIpAddress: ipAddress,
        status: 'completed',
      });

      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, tenantId))
        .limit(1);

      const renderedHtml = await renderFormHtml(form as any, submission, tenant?.name || 'Organization');

      await updateSubmission(submission.id, tenantId, { renderedHtml });

      let agreementPdfAttachments: { filename: string; content: Buffer; contentType: string }[] = [];
      let agreementPdfObjectPath: string | undefined;

      if (renderedHtml) {
        try {
          const { generateCustomFormPDF } = await import('./services/custom-form-pdf');
          const { objectPath, pdfBuffer } = await generateCustomFormPDF(renderedHtml, 'volunteer-agreements', {
            ipAddress,
            signedAt: new Date(),
            sessionId: submission.id,
          });
          agreementPdfObjectPath = objectPath;

          const signerNameSlug = (signerName || 'unknown').replace(/\s+/g, '-').toLowerCase();
          agreementPdfAttachments.push({
            filename: `volunteer-agreement-${signerNameSlug}.pdf`,
            content: pdfBuffer,
            contentType: 'application/pdf',
          });

          await updateSubmission(submission.id, tenantId, { pdfUrl: objectPath });
          console.log(`[Public Waiver] Generated PDF: ${pdfBuffer.length} bytes at ${objectPath}`);
        } catch (pdfError) {
          console.error('[Public Waiver] Failed to generate PDF:', pdfError);
        }
      }

      if (tenant?.contactEmail && renderedHtml) {
        try {
          const { EmailService } = await import('./lib/email-service');
          const emailService = await EmailService.forTenant(tenantId);

          if (emailService) {
            const escapeHtml = (str: string) => str
              .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
              .replace(/"/g, '&quot;').replace(/'/g, '&#039;');

            const emailSubject = `Volunteer Waiver Signed: ${signerName}`;
            const emailHtml = `
<h2>Volunteer Waiver Signed</h2>
<p>A walk-in volunteer has signed the hold harmless waiver via the public waiver page.</p>
<p><strong>Name:</strong> ${escapeHtml(signerName)}</p>
<p><strong>Email:</strong> ${escapeHtml(signerEmail)}</p>
${signerPhone ? `<p><strong>Phone:</strong> ${escapeHtml(signerPhone)}</p>` : ''}
<p><strong>Submitted:</strong> ${new Date().toLocaleString()}</p>
<hr>
<h3>Signed Document</h3>
${renderedHtml}
<p style="color:#888;font-size:12px;">This is an automated notification from your iRescue platform.</p>
            `.trim();

            await emailService.send({
              to: tenant.contactEmail,
              subject: emailSubject,
              html: emailHtml,
              attachments: agreementPdfAttachments.length > 0 ? agreementPdfAttachments : undefined,
            });
            console.log(`[Public Waiver] Emailed waiver to ${tenant.contactEmail}`);
          }
        } catch (emailError) {
          console.error('[Public Waiver] Error sending org email:', emailError);
        }
      }

      if (signerEmail && renderedHtml) {
        try {
          const { EmailService } = await import('./lib/email-service');
          const emailService = await EmailService.forTenant(tenantId);

          if (emailService) {
            const escapeHtml = (str: string) => str
              .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
              .replace(/"/g, '&quot;').replace(/'/g, '&#039;');

            const safeTenantName = tenant?.name ? escapeHtml(tenant.name) : 'the organization';

            await emailService.send({
              to: signerEmail,
              subject: `Your Signed Document: ${form.name}`,
              html: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <h2 style="color: #333;">Your Signed Document</h2>
  <p>Hi ${escapeHtml(signerName)},</p>
  <p>Thank you for completing and signing the <strong>${escapeHtml(form.name)}</strong> with ${safeTenantName}.</p>
  <p>A copy of your signed document is included below for your records.</p>
  <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
  <div style="background: #f9f9f9; padding: 20px; border-radius: 8px;">
    ${renderedHtml}
  </div>
  <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
  <p style="color: #666; font-size: 12px;">
    Signed on: ${new Date().toLocaleString()}<br />
    This is your copy of the signed document. Please keep it for your records.
  </p>
</div>
              `.trim(),
              attachments: agreementPdfAttachments.length > 0 ? agreementPdfAttachments : undefined,
            });
            console.log(`[Public Waiver] Sent confirmation to signer ${signerEmail}`);
          }
        } catch (signerEmailError) {
          console.error('[Public Waiver] Error sending signer email:', signerEmailError);
        }
      }

      if (agreementPdfObjectPath && signerEmail) {
        try {
          const { personDocuments, contacts: contactsTable } = await import('@shared/schema');
          const normalizedEmail = signerEmail.toLowerCase().trim();
          const [contact] = await db
            .select({ id: contactsTable.id })
            .from(contactsTable)
            .where(
              and(
                eq(contactsTable.tenantId, tenantId),
                sql`LOWER(TRIM(${contactsTable.email})) = ${normalizedEmail}`
              )
            )
            .limit(1);

          const [existingDoc] = await db
            .select({ id: personDocuments.id })
            .from(personDocuments)
            .where(and(
              eq(personDocuments.tenantId, tenantId),
              eq(personDocuments.documentType, 'agreement'),
              eq(personDocuments.documentSubtype, 'volunteer_hold_harmless'),
              sql`LOWER(TRIM(${personDocuments.personEmail})) = ${normalizedEmail}`
            ))
            .limit(1);

          if (!existingDoc) {
            await db.insert(personDocuments).values({
              tenantId,
              personType: 'contact',
              personId: contact?.id || null,
              personEmail: signerEmail,
              documentType: 'agreement',
              documentSubtype: 'volunteer_hold_harmless',
              title: `Volunteer Hold Harmless - ${signerName}`,
              description: `Walk-in volunteer waiver signed on ${new Date().toLocaleDateString()}.`,
              objectPath: agreementPdfObjectPath,
              sourceId: submission.id,
              sourceTable: 'custom_form_submissions',
              fileName: `volunteer-hold-harmless-${(signerName || 'unknown').replace(/\s+/g, '-').toLowerCase()}.pdf`,
              contentType: 'application/pdf',
            });
            console.log(`[Public Waiver] Saved to person documents for ${signerEmail}`);
          }
        } catch (docError) {
          console.error('[Public Waiver] Failed to save to person documents:', docError);
        }
      }

      const { logActivity } = await import('./lib/activity-logger');
      await logActivity({
        tenantId,
        userId: null,
        action: 'waiver_signed_public',
        category: 'user',
        entityType: 'custom_form_submission',
        entityId: submission.id,
        description: `Walk-in volunteer ${signerName} (${signerEmail}) signed "${form.name}" via public waiver page`,
        metadata: { formId: form.id, signerName, signerEmail },
      });

      res.json({
        success: true,
        message: 'Waiver signed successfully',
        submissionId: submission.id,
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Public Custom Form Routes (for form signing)
  // ============================================================================

  /**
   * GET /api/public/forms/:token
   * Get form for public signing
   */
  app.get('/api/public/forms/:token', requireTenant, async (req, res, next) => {
    try {
      const { getSubmissionByToken, getFormById, hashToken } = await import('./services/custom-form');
      
      const tokenHash = hashToken(req.params.token);
      const submission = await getSubmissionByToken(tokenHash);
      
      if (!submission) {
        return res.status(404).json({ error: 'Form not found or link has expired' });
      }

      if (submission.status !== 'pending') {
        return res.status(400).json({ error: 'This form has already been completed' });
      }

      if (submission.expiresAt && new Date() > submission.expiresAt) {
        return res.status(400).json({ error: 'This form link has expired' });
      }

      const form = await getFormById(submission.formId, submission.tenantId);
      if (!form) {
        return res.status(404).json({ error: 'Form template not found' });
      }

      // Get animal if animal-specific
      let animal = null;
      if (form.formType === 'animal_specific' && submission.animalId) {
        const [animalRecord] = await db
          .select({ id: animals.id, name: animals.name, species: animals.species, breed: animals.breed, photoUrls: animals.photoUrls })
          .from(animals)
          .where(eq(animals.id, submission.animalId))
          .limit(1);
        animal = animalRecord || null;
      }

      // Get tenant info
      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, submission.tenantId))
        .limit(1);

      res.json({ 
        form: {
          id: form.id,
          name: form.name,
          description: form.description,
          formType: form.formType,
          requiresSignature: form.requiresSignature,
          htmlTemplate: form.htmlTemplate,
        },
        submission: {
          id: submission.id,
          signerName: submission.signerName,
          signerEmail: submission.signerEmail,
          signerPhone: submission.signerPhone,
        },
        animal,
        tenant: {
          name: tenant?.name,
          logo: tenant?.logoUrl,
        },
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/public/forms/:token/submit
   * Submit a completed form with signature
   */
  app.post('/api/public/forms/:token/submit', requireTenant, async (req, res, next) => {
    try {
      const { getSubmissionByToken, getFormById, updateSubmission, renderFormHtml, hashToken } = await import('./services/custom-form');
      
      const tokenHash = hashToken(req.params.token);
      const submission = await getSubmissionByToken(tokenHash);
      
      if (!submission) {
        return res.status(404).json({ error: 'Form not found' });
      }

      if (submission.status !== 'pending') {
        return res.status(400).json({ error: 'This form has already been completed' });
      }

      if (submission.expiresAt && new Date() > submission.expiresAt) {
        return res.status(400).json({ error: 'This form link has expired' });
      }

      const form = await getFormById(submission.formId, submission.tenantId);
      if (!form) {
        return res.status(404).json({ error: 'Form template not found' });
      }

      const { signatureData, formData } = req.body;

      if (form.requiresSignature && !signatureData) {
        return res.status(400).json({ error: 'Signature is required' });
      }

      // Get IP address
      const ipAddress = req.headers['x-forwarded-for'] as string || req.socket.remoteAddress || '';

      // Get animal if animal-specific
      let animal = null;
      if (form.formType === 'animal_specific' && submission.animalId) {
        const [animalRecord] = await db
          .select({ id: animals.id, name: animals.name, species: animals.species, breed: animals.breed, photoUrls: animals.photoUrls })
          .from(animals)
          .where(eq(animals.id, submission.animalId))
          .limit(1);
        animal = animalRecord || null;
      }

      // Get tenant info
      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, submission.tenantId))
        .limit(1);

      // Create updated submission object for rendering
      const updatedData = {
        ...submission,
        signatureData,
        formData,
        signedAt: new Date(),
        signerIpAddress: ipAddress,
      };

      // Render HTML with merged data
      const renderedHtml = await renderFormHtml(form, updatedData as any, tenant?.name || 'Organization', animal);

      // Update submission
      const updated = await updateSubmission(submission.id, submission.tenantId, {
        signatureData,
        formData,
        signedAt: new Date(),
        signerIpAddress: ipAddress,
        renderedHtml,
        status: 'completed',
      });

      // ========================================================================
      // AUTOMATION: Auto-advance volunteer pipeline when Hold Harmless waiver is signed
      // ========================================================================
      const formNameLower = form.name.toLowerCase();
      // More specific detection: must include "hold harmless" OR ("volunteer" AND ("waiver" OR "liability"))
      const isVolunteerWaiver = formNameLower.includes('hold harmless') || 
                                (formNameLower.includes('volunteer') && 
                                 (formNameLower.includes('waiver') || formNameLower.includes('liability')));
      
      if (isVolunteerWaiver && submission.signerEmail) {
        try {
          const { volunteerApplications } = await import('@shared/schema');
          
          // Normalize email for case-insensitive matching
          const normalizedSignerEmail = submission.signerEmail.toLowerCase().trim();
          
          // Find volunteer application matching signer email with waiver_needed status
          // Use case-insensitive email comparison
          const [volunteerApp] = await db
            .select({ id: volunteerApplications.id, tenantId: volunteerApplications.tenantId, applicantName: volunteerApplications.applicantName, applicantEmail: volunteerApplications.applicantEmail, applicantPhone: volunteerApplications.applicantPhone, pipelineStatus: volunteerApplications.pipelineStatus, driveFolderId: volunteerApplications.driveFolderId })
            .from(volunteerApplications)
            .where(
              and(
                eq(volunteerApplications.tenantId, submission.tenantId),
                sql`LOWER(TRIM(${volunteerApplications.applicantEmail})) = ${normalizedSignerEmail}`,
                eq(volunteerApplications.pipelineStatus, 'waiver_needed')
              )
            )
            .limit(1);
          
          if (volunteerApp) {
            // Auto-advance to active_pool
            await db
              .update(volunteerApplications)
              .set({
                pipelineStatus: 'active_pool',
                status: 'approved',
                updatedAt: new Date(),
              })
              .where(eq(volunteerApplications.id, volunteerApp.id));
            
            // Log activity for the auto-advancement
            const { logActivity } = await import('./lib/activity-logger');
            await logActivity({
              tenantId: submission.tenantId,
              userId: null, // System action
              action: 'volunteer_auto_advanced',
              category: 'user',
              entityType: 'volunteer_application',
              entityId: volunteerApp.id.toString(),
              description: `Volunteer ${volunteerApp.applicantName} automatically advanced to Active Pool after signing "${form.name}"`,
              metadata: {
                formName: form.name,
                formId: form.id,
                submissionId: updated?.id,
                previousStatus: 'waiver_needed',
                newStatus: 'active_pool',
              },
            });
            
            console.log(`[Volunteer Automation] Auto-advanced ${volunteerApp.applicantEmail} from waiver_needed to active_pool`);

            // Sync volunteer to contacts directory
            try {
              const { activateVolunteerInDirectory } = await import('./services/contacts');
              await activateVolunteerInDirectory({
                tenantId: submission.tenantId,
                applicantName: volunteerApp.applicantName,
                applicantEmail: volunteerApp.applicantEmail,
                applicantPhone: volunteerApp.applicantPhone || undefined,
              });
            } catch (syncError) {
              console.error('[Volunteer Automation] Error syncing volunteer to directory:', syncError);
            }
            
            // Create Google Drive folder for the volunteer (if not already created)
            if (!volunteerApp.driveFolderId) {
              try {
                const { VolunteerFosterBackupService } = await import('./lib/volunteerFosterBackupService');
                const backupService = new VolunteerFosterBackupService(submission.tenantId);
                
                const folderResult = await backupService.createVolunteerFolder({
                  id: volunteerApp.id,
                  applicantName: volunteerApp.applicantName,
                  applicantEmail: volunteerApp.applicantEmail,
                });
                
                if (folderResult.success) {
                  console.log(`[Volunteer Automation] Created ${folderResult.storageType} folder for ${volunteerApp.applicantName}`);
                }
              } catch (folderError) {
                console.error('[Volunteer Automation] Error creating folder:', folderError);
              }
            } else {
              console.log(`[Volunteer Automation] Folder already exists for ${volunteerApp.applicantName}, skipping creation`);
            }

            // ========================================================================
            // AUTOMATION: Send volunteer welcome email with account setup link
            // ========================================================================
            try {
              const { createAndSendVolunteerWelcome } = await import('./services/invitations');
              const welcomeResult = await createAndSendVolunteerWelcome(
                submission.tenantId,
                volunteerApp.applicantEmail,
                volunteerApp.applicantName,
              );
              if (welcomeResult?.skipped) {
                console.log(`[Volunteer Automation] Welcome email skipped (${welcomeResult.reason}) for ${volunteerApp.applicantEmail}`);
              } else {
                console.log(`[Volunteer Automation] Sent welcome email to ${volunteerApp.applicantEmail}`);
              }
            } catch (emailError) {
              console.error('[Volunteer Automation] Error sending welcome email:', emailError);
            }

            // ========================================================================
            // AUTOMATION: Notify staff via notification preferences
            // ========================================================================
            try {
              const { dispatchEventNotification } = await import('./services/notification-dispatcher');
              await dispatchEventNotification({
                tenantId: submission.tenantId,
                eventKey: 'volunteer_activated',
                subject: `Volunteer Activated: ${volunteerApp.applicantName}`,
                htmlBody: `<p><strong>${volunteerApp.applicantName}</strong> (${volunteerApp.applicantEmail}) has been moved to the Active Volunteer Pool after signing their waiver.</p>`,
                textBody: `${volunteerApp.applicantName} (${volunteerApp.applicantEmail}) has been moved to the Active Volunteer Pool after signing their waiver.`,
                metadata: { volunteerId: volunteerApp.id, volunteerName: volunteerApp.applicantName },
              });
            } catch (notifyError) {
              console.error('[Volunteer Automation] Error dispatching staff notification:', notifyError);
            }
          }
        } catch (automationError) {
          // Log error but don't fail the form submission
          console.error('[Volunteer Automation] Error auto-advancing volunteer:', automationError);
        }
      }

      // ========================================================================
      // AUTOMATION: Auto-advance foster pipeline when Foster Agreement is signed
      // ========================================================================
      // Detect foster agreement: must include "foster" AND ("agreement" OR "contract")
      const isFosterAgreement = formNameLower.includes('foster') && 
                                (formNameLower.includes('agreement') || formNameLower.includes('contract'));
      
      if (isFosterAgreement && submission.signerEmail) {
        try {
          const { fosterApplications } = await import('@shared/schema');
          
          // Normalize email for case-insensitive matching
          const normalizedSignerEmail = submission.signerEmail.toLowerCase().trim();
          
          // Find foster application matching signer email with 'agreement' status
          const [fosterApp] = await db
            .select({ id: fosterApplications.id, tenantId: fosterApplications.tenantId, applicantName: fosterApplications.applicantName, applicantEmail: fosterApplications.applicantEmail, applicantPhone: fosterApplications.applicantPhone, pipelineStatus: fosterApplications.pipelineStatus, driveFolderId: fosterApplications.driveFolderId })
            .from(fosterApplications)
            .where(
              and(
                eq(fosterApplications.tenantId, submission.tenantId),
                sql`LOWER(TRIM(${fosterApplications.applicantEmail})) = ${normalizedSignerEmail}`,
                eq(fosterApplications.pipelineStatus, 'agreement')
              )
            )
            .limit(1);
          
          if (fosterApp) {
            // Auto-advance to active_pool
            await db
              .update(fosterApplications)
              .set({
                pipelineStatus: 'active_pool',
                status: 'approved',
                updatedAt: new Date(),
              })
              .where(eq(fosterApplications.id, fosterApp.id));
            
            // Log activity for the auto-advancement
            const { logActivity } = await import('./lib/activity-logger');
            await logActivity({
              tenantId: submission.tenantId,
              userId: null, // System action
              action: 'foster_auto_advanced',
              category: 'user', // Matches volunteer waiver automation pattern
              entityType: 'foster_application',
              entityId: fosterApp.id.toString(),
              description: `Foster ${fosterApp.applicantName} automatically advanced to Active Pool after signing "${form.name}"`,
              metadata: {
                formName: form.name,
                formId: form.id,
                submissionId: updated?.id,
                previousStatus: 'agreement',
                newStatus: 'active_pool',
              },
            });
            
            console.log(`[Foster Automation] Auto-advanced ${fosterApp.applicantEmail} from agreement to active_pool`);

            // Sync foster to contacts directory & user system
            try {
              const { activateFosterInDirectory } = await import("./services/contacts");
              await activateFosterInDirectory({
                tenantId: submission.tenantId,
                applicantName: fosterApp.applicantName || submission.signerName || fosterApp.applicantEmail,
                applicantEmail: fosterApp.applicantEmail,
                fosterApplicationId: fosterApp.id,
              });
            } catch (syncError) {
              console.error("[Foster Automation] Error syncing foster to directory:", syncError);
            }
            
            // Create Google Drive folder for the foster (if not already created)
            if (!fosterApp.driveFolderId) {
              try {
                const { VolunteerFosterBackupService } = await import('./lib/volunteerFosterBackupService');
                const backupService = new VolunteerFosterBackupService(submission.tenantId);
                
                const folderResult = await backupService.createFosterFolder({
                  id: fosterApp.id,
                  applicantName: fosterApp.applicantName,
                  applicantEmail: fosterApp.applicantEmail,
                });
                
                if (folderResult.success) {
                  console.log(`[Foster Automation] Created ${folderResult.storageType} folder for ${fosterApp.applicantName}`);
                }
              } catch (folderError) {
                console.error('[Foster Automation] Error creating folder:', folderError);
              }
            } else {
              console.log(`[Foster Automation] Folder already exists for ${fosterApp.applicantName}, skipping creation`);
            }
          }
        } catch (automationError) {
          // Log error but don't fail the form submission
          console.error('[Foster Automation] Error auto-advancing foster:', automationError);
        }
      }

      // ========================================================================
      // PDF GENERATION: Generate PDF for volunteer/surrender agreements
      // ========================================================================
      let agreementPdfAttachments: { filename: string; content: Buffer; contentType: string }[] = [];
      let agreementPdfObjectPath: string | undefined;

      const isSurrenderAgreement = formNameLower.includes('surrender') && 
                                   (formNameLower.includes('agreement') || formNameLower.includes('contract') || formNameLower.includes('release'));

      if ((isVolunteerWaiver || isSurrenderAgreement) && renderedHtml) {
        try {
          const { generateCustomFormPDF } = await import('./services/custom-form-pdf');
          const folder = isVolunteerWaiver ? 'volunteer-agreements' : 'surrender-agreements';
          const { objectPath, pdfBuffer } = await generateCustomFormPDF(renderedHtml, folder, {
            ipAddress: req.headers['x-forwarded-for'] as string || req.socket.remoteAddress || '',
            signedAt: new Date(),
            sessionId: updated?.id?.toString(),
          });
          agreementPdfObjectPath = objectPath;
          
          const agreementType = isVolunteerWaiver ? 'volunteer-agreement' : 'surrender-agreement';
          const signerNameSlug = (submission.signerName || 'unknown').replace(/\s+/g, '-').toLowerCase();
          agreementPdfAttachments.push({
            filename: `${agreementType}-${signerNameSlug}.pdf`,
            content: pdfBuffer,
            contentType: 'application/pdf',
          });
          console.log(`[Custom Form] Generated ${agreementType} PDF: ${pdfBuffer.length} bytes at ${objectPath}`);

          if (updated?.id) {
            await updateSubmission(updated.id, submission.tenantId, {
              pdfUrl: objectPath,
            });
          }
        } catch (pdfError) {
          console.error('[Custom Form] Failed to generate agreement PDF:', pdfError);
        }
      }

      // ========================================================================
      // EMAIL: Send copy of submitted form to tenant's contact email
      // ========================================================================
      if (tenant?.contactEmail && renderedHtml) {
        try {
          const { EmailService } = await import('./lib/email-service');
          const emailService = await EmailService.forTenant(submission.tenantId);
          
          if (emailService) {
            // Helper to escape HTML entities for safe display
            const escapeHtml = (str: string) => str
              .replace(/&/g, '&amp;')
              .replace(/</g, '&lt;')
              .replace(/>/g, '&gt;')
              .replace(/"/g, '&quot;')
              .replace(/'/g, '&#039;');
            
            // Escape user-provided text fields
            const safeFormName = escapeHtml(form.name);
            const safeSignerName = escapeHtml(submission.signerName);
            const safeSignerEmail = escapeHtml(submission.signerEmail);
            const safeSignerPhone = submission.signerPhone ? escapeHtml(submission.signerPhone) : null;
            const safeAnimalName = animal?.name ? escapeHtml(animal.name) : null;
            
            const emailSubject = `Form Submitted: ${form.name} - ${submission.signerName}`;
            const emailHtml = `
<h2>Form Submission Received</h2>
<p><strong>Form Name:</strong> ${safeFormName}</p>
<p><strong>Signed By:</strong> ${safeSignerName}</p>
<p><strong>Email:</strong> ${safeSignerEmail}</p>
${safeSignerPhone ? `<p><strong>Phone:</strong> ${safeSignerPhone}</p>` : ''}
<p><strong>Submitted:</strong> ${new Date().toLocaleString()}</p>
${safeAnimalName ? `<p><strong>Animal:</strong> ${safeAnimalName}</p>` : ''}
<hr>
<h3>Completed Form Document</h3>
${renderedHtml}
<p style="color:#888;font-size:12px;">This is an automated notification from your iRescue platform.</p>
            `.trim();
            
            await emailService.send({
              to: tenant.contactEmail,
              subject: emailSubject,
              html: emailHtml,
              attachments: agreementPdfAttachments.length > 0 ? agreementPdfAttachments : undefined,
            });
            
            console.log(`[Form Submission] Emailed copy of "${form.name}" to ${tenant.contactEmail}`);
          }
        } catch (emailError) {
          // Log error but don't fail the form submission
          console.error('[Form Submission] Error sending form copy email:', emailError);
        }
      }

      // ========================================================================
      // EMAIL: Send confirmation copy to the signer
      // ========================================================================
      if (submission.signerEmail && renderedHtml) {
        try {
          const { EmailService } = await import('./lib/email-service');
          const emailService = await EmailService.forTenant(submission.tenantId);
          
          if (emailService) {
            const escapeHtml = (str: string) => str
              .replace(/&/g, '&amp;')
              .replace(/</g, '&lt;')
              .replace(/>/g, '&gt;')
              .replace(/"/g, '&quot;')
              .replace(/'/g, '&#039;');
            
            const safeFormName = escapeHtml(form.name);
            const safeSignerName = escapeHtml(submission.signerName);
            const safeTenantName = tenant?.name ? escapeHtml(tenant.name) : 'the organization';
            
            const signerEmailSubject = `Your Signed Document: ${form.name}`;
            const signerEmailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <h2 style="color: #333;">Your Signed Document</h2>
  <p>Hi ${safeSignerName},</p>
  <p>Thank you for completing and signing the <strong>${safeFormName}</strong> with ${safeTenantName}.</p>
  <p>A copy of your signed document is included below for your records.</p>
  <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
  <div style="background: #f9f9f9; padding: 20px; border-radius: 8px;">
    ${renderedHtml}
  </div>
  <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;" />
  <p style="color: #666; font-size: 12px;">
    Signed on: ${new Date().toLocaleString()}<br />
    This is your copy of the signed document. Please keep it for your records.
  </p>
</div>
            `.trim();
            
            await emailService.send({
              to: submission.signerEmail,
              subject: signerEmailSubject,
              html: signerEmailHtml,
              attachments: agreementPdfAttachments.length > 0 ? agreementPdfAttachments : undefined,
            });
            
            console.log(`[Form Submission] Sent confirmation copy of "${form.name}" to signer ${submission.signerEmail}`);
          }
        } catch (signerEmailError) {
          // Log error but don't fail the form submission
          console.error('[Form Submission] Error sending signer confirmation email:', signerEmailError);
        }
      }

      // ========================================================================
      // PERSON DOCUMENTS: Save agreement PDF to person documents
      // ========================================================================
      if (agreementPdfObjectPath && submission.signerEmail) {
        try {
          const { personDocuments, contacts: contactsTable } = await import('@shared/schema');
          const normalizedEmail = submission.signerEmail.toLowerCase().trim();
          const [contact] = await db
            .select({ id: contactsTable.id })
            .from(contactsTable)
            .where(
              and(
                eq(contactsTable.tenantId, submission.tenantId),
                sql`LOWER(TRIM(${contactsTable.email})) = ${normalizedEmail}`
              )
            )
            .limit(1);

          const docSubtype = isVolunteerWaiver ? 'volunteer_hold_harmless' : 'surrender_agreement';
          const docTitle = isVolunteerWaiver
            ? `Volunteer Hold Harmless - ${submission.signerName}`
            : `Owner Surrender Agreement - ${submission.signerName}`;

          const [existingDoc] = await db
            .select({ id: personDocuments.id })
            .from(personDocuments)
            .where(and(
              eq(personDocuments.tenantId, submission.tenantId),
              eq(personDocuments.documentType, 'agreement'),
              eq(personDocuments.documentSubtype, isVolunteerWaiver ? 'volunteer_hold_harmless' : 'surrender_agreement'),
              sql`LOWER(TRIM(${personDocuments.personEmail})) = ${normalizedEmail}`
            ))
            .limit(1);

          if (!existingDoc) {
            await db.insert(personDocuments).values({
              tenantId: submission.tenantId,
              personType: 'contact',
            personId: contact?.id || null,
            personEmail: submission.signerEmail,
            documentType: 'agreement',
            documentSubtype: docSubtype,
            title: docTitle,
            description: `Signed ${isVolunteerWaiver ? 'volunteer hold harmless waiver' : 'owner surrender agreement'}. Signed on ${new Date().toLocaleDateString()}.`,
            objectPath: agreementPdfObjectPath,
            sourceId: updated?.id?.toString() || null,
            sourceTable: 'custom_form_submissions',
            fileName: `${docSubtype.replace(/_/g, '-')}-${(submission.signerName || 'unknown').replace(/\s+/g, '-').toLowerCase()}.pdf`,
            contentType: 'application/pdf',
          });
          console.log(`[Custom Form] Saved ${docSubtype} to person documents for ${submission.signerEmail}`);
          }

          if (isVolunteerWaiver) {
            const { users: usersTable } = await import('@shared/schema');
            const [volunteerUser] = await db
              .select({ id: usersTable.id })
              .from(usersTable)
              .where(
                and(
                  eq(usersTable.tenantId, submission.tenantId),
                  sql`LOWER(TRIM(${usersTable.email})) = ${normalizedEmail}`
                )
              )
              .limit(1);

            if (volunteerUser) {
              const [existingVolDoc] = await db
                .select({ id: personDocuments.id })
                .from(personDocuments)
                .where(and(
                  eq(personDocuments.tenantId, submission.tenantId),
                  eq(personDocuments.personType, 'volunteer'),
                  eq(personDocuments.personId, volunteerUser.id),
                  eq(personDocuments.documentSubtype, 'volunteer_hold_harmless')
                ))
                .limit(1);

              if (!existingVolDoc) {
                await db.insert(personDocuments).values({
                tenantId: submission.tenantId,
                personType: 'volunteer',
                personId: volunteerUser.id,
                personEmail: submission.signerEmail,
                documentType: 'agreement',
                documentSubtype: 'volunteer_hold_harmless',
                title: docTitle,
                description: `Signed volunteer hold harmless waiver. Signed on ${new Date().toLocaleDateString()}.`,
                objectPath: agreementPdfObjectPath,
                sourceId: updated?.id?.toString() || null,
                sourceTable: 'custom_form_submissions',
                fileName: `volunteer-hold-harmless-${(submission.signerName || 'unknown').replace(/\s+/g, '-').toLowerCase()}.pdf`,
                contentType: 'application/pdf',
              });
              console.log(`[Custom Form] Saved volunteer hold harmless to person documents for volunteer user ${volunteerUser.id}`);
              }
            }
          }
        } catch (docError) {
          console.error('[Custom Form] Failed to save agreement to person documents:', docError);
        }
      }

      res.json({ 
        success: true, 
        message: 'Form submitted successfully',
        submissionId: updated?.id,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/volunteers/hold-harmless-status
   * Get hold harmless agreement status for all volunteers (by email)
   */
  app.get('/api/volunteers/hold-harmless-status', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { personDocuments } = await import('@shared/schema');
      const tenantId = req.tenant!.id;

      const docs = await db
        .select({
          personEmail: personDocuments.personEmail,
          signedAt: personDocuments.createdAt,
          title: personDocuments.title,
        })
        .from(personDocuments)
        .where(and(
          eq(personDocuments.tenantId, tenantId),
          eq(personDocuments.documentType, 'agreement'),
          eq(personDocuments.documentSubtype, 'volunteer_hold_harmless')
        ))
        .orderBy(desc(personDocuments.createdAt));

      const statusByEmail: Record<string, { signedAt: string; title: string }> = {};
      for (const doc of docs) {
        if (doc.personEmail) {
          const email = doc.personEmail.toLowerCase().trim();
          if (!statusByEmail[email]) {
            statusByEmail[email] = {
              signedAt: doc.signedAt ? new Date(doc.signedAt).toISOString() : '',
              title: doc.title,
            };
          }
        }
      }

      res.json({ holdHarmlessStatus: statusByEmail });
    } catch (error) {
      next(error);
    }
  });

