  /**
   * PATCH /api/foster-applications/:id
   * Update foster application status (admin/staff only)
   * Auto-dismisses from pending widget when status changes from 'pending' to other statuses
   */
  app.patch('/api/foster-applications/:id', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { fosterApplications, dismissedWidgetItems } = await import('@shared/schema');
      
      // Support both legacy status field and new pipelineStatus field
      const updateSchema = z.object({
        status: z.enum(['pending', 'approved', 'rejected']).optional(),
        pipelineStatus: z.enum(['new_app', 'interview', 'home_check', 'orientation', 'agreement', 'active_pool', 'rejected']).optional(),
        notes: z.string().optional(),
        skipAutomation: z.boolean().optional(),
        sendMethod: z.enum(["email", "sms", "both"]).optional(),
      });

      const data = updateSchema.parse(req.body);
      
      // Get current application to check status before update
      const [currentApp] = await db.select({ status: fosterApplications.status, pipelineStatus: fosterApplications.pipelineStatus })
        .from(fosterApplications)
        .where(
          and(
            eq(fosterApplications.id, req.params.id),
            eq(fosterApplications.tenantId, req.tenant!.id)
          )
        )
        .limit(1);
      
      if (!currentApp) {
        return res.status(404).json({ error: 'Foster application not found' });
      }
      
      const oldStatus = currentApp.status;
      const oldPipelineStatus = currentApp.pipelineStatus;
      
      // Build update object
      const updateData: Record<string, any> = {
        updatedAt: new Date(),
      };
      
      if (data.status !== undefined) {
        updateData.status = data.status;
      }
      
      if (data.pipelineStatus !== undefined) {
        updateData.pipelineStatus = data.pipelineStatus;
        // Sync legacy status field based on pipelineStatus
        if (data.pipelineStatus === 'active_pool') {
          updateData.status = 'approved';
        } else if (data.pipelineStatus === 'rejected') {
          updateData.status = 'rejected';
        } else if (['new_app', 'interview', 'home_check', 'orientation', 'agreement'].includes(data.pipelineStatus)) {
          updateData.status = 'pending';
        }
      }
      
      if (data.notes !== undefined) {
        updateData.notes = data.notes;
      }

      const [updatedApplication] = await db
        .update(fosterApplications)
        .set(updateData)
        .where(
          and(
            eq(fosterApplications.id, req.params.id),
            eq(fosterApplications.tenantId, req.tenant!.id)
          )
        )
        .returning();

      if (!updatedApplication) {
        return res.status(500).json({ error: 'Failed to update foster application' });
      }
      
      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'foster_application.status_change',
          entityType: 'foster_application',
          entityId: req.params.id,
          changes: {
            before: { status: oldStatus, pipelineStatus: oldPipelineStatus },
            after: { status: updatedApplication.status, pipelineStatus: updatedApplication.pipelineStatus },
          },
          metadata: { applicantName: updatedApplication.applicantName || null },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      // Auto-dismiss from widget if moving from 'new_app' to another pipeline status
      const shouldAutoDismiss = (oldPipelineStatus === 'new_app' && data.pipelineStatus && data.pipelineStatus !== 'new_app') ||
                                 (oldStatus === 'pending' && data.status && data.status !== 'pending');
      if (shouldAutoDismiss) {
        try {
          const existing = await db.select({
            id: dismissedWidgetItems.id,
          })
            .from(dismissedWidgetItems)
            .where(
              and(
                eq(dismissedWidgetItems.tenantId, req.tenant!.id),
                eq(dismissedWidgetItems.applicationType, 'foster'),
                eq(dismissedWidgetItems.applicationId, req.params.id)
              )
            )
            .limit(1);
          
          if (existing.length === 0) {
            await db.insert(dismissedWidgetItems).values({
              tenantId: req.tenant!.id,
              applicationType: 'foster',
              applicationId: req.params.id,
              dismissedBy: req.user!.id,
            });
            console.log(`[AUTO-DISMISS] Foster application ${req.params.id} auto-dismissed (${oldStatus} -> ${data.status})`);
          } else {
            console.log(`[AUTO-DISMISS] Foster application ${req.params.id} already dismissed`);
          }
        } catch (error) {
          console.error('Failed to auto-dismiss foster application:', error);
        }
      }

      // ========================================================================
      // AUTOMATION: Send foster agreement email when status changes to 'agreement'
      // Uses Foster Contract Templates (not Custom Forms)
      // ========================================================================
      const statusChangedToAgreement = data.pipelineStatus === 'agreement' && oldPipelineStatus !== 'agreement' && !data.skipAutomation;
      const agreementSendMethod = data.sendMethod || 'email';
      if (statusChangedToAgreement && updatedApplication.applicantEmail) {
        try {
          const { EmailService } = await import('./lib/email-service');
          const { fosterContractTemplates, fosterAgreementSessions } = await import('@shared/schema');
          const crypto = await import('crypto');
          const bcrypt = await import('bcrypt');
          
          // Find the default foster contract template for this tenant
          const [fosterTemplate] = await db
            .select({ id: fosterContractTemplates.id, tenantId: fosterContractTemplates.tenantId, name: fosterContractTemplates.name, htmlTemplate: fosterContractTemplates.htmlTemplate, isDefault: fosterContractTemplates.isDefault, isActive: fosterContractTemplates.isActive, guidedSections: fosterContractTemplates.guidedSections })
            .from(fosterContractTemplates)
            .where(
              and(
                eq(fosterContractTemplates.tenantId, req.tenant!.id),
                eq(fosterContractTemplates.isActive, true),
                eq(fosterContractTemplates.isDefault, true)
              )
            )
            .limit(1);
          
          // If no default, try to get any active foster template
          const template = fosterTemplate || (await db
            .select({ id: fosterContractTemplates.id, tenantId: fosterContractTemplates.tenantId, name: fosterContractTemplates.name, htmlTemplate: fosterContractTemplates.htmlTemplate, isDefault: fosterContractTemplates.isDefault, isActive: fosterContractTemplates.isActive, guidedSections: fosterContractTemplates.guidedSections })
            .from(fosterContractTemplates)
            .where(
              and(
                eq(fosterContractTemplates.tenantId, req.tenant!.id),
                eq(fosterContractTemplates.isActive, true)
              )
            )
            .limit(1))[0];
          
          if (template) {
            // Generate secure token - use SHA256 for consistent lookup
            const token = crypto.randomBytes(32).toString('hex');
            const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
            const expiresAt = new Date();
            expiresAt.setDate(expiresAt.getDate() + 14); // 14 day expiration
            
            // Create foster agreement session
            await db.insert(fosterAgreementSessions).values({
              tenantId: req.tenant!.id,
              fosterApplicationId: updatedApplication.id,
              templateId: template.id,
              fosterName: updatedApplication.applicantName,
              fosterEmail: updatedApplication.applicantEmail,
              fosterPhone: updatedApplication.applicantPhone || null,
              status: 'pending',
              secureTokenHash: tokenHash,
              expiresAt,
            });
            
            // Build the form signing URL - use custom domain if available
            let formUrl: string;
            if (req.tenant!.customDomain) {
              formUrl = `https://${req.tenant!.customDomain}/foster-agreement/sign/${token}`;
            } else {
              const isProduction = process.env.REPLIT_DEPLOYMENT === '1';
              const baseUrl = isProduction 
                ? 'https://irescue.life'
                : process.env.REPLIT_DEV_DOMAIN 
                  ? `https://${process.env.REPLIT_DEV_DOMAIN}`
                  : 'http://localhost:5000';
              formUrl = `${baseUrl}/${req.tenant!.subdomain}/foster-agreement/sign/${token}`;
            }
            
            // Get email service for tenant (may be null if SMS-only)
            const emailService = await EmailService.forTenant(req.tenant!.id);
            if (!emailService && (agreementSendMethod === 'email' || agreementSendMethod === 'both')) {
              console.error('[Foster Automation] No email service configured for tenant');
            }
            
            // Send email if method is email or both
            if ((agreementSendMethod === 'email' || agreementSendMethod === 'both') && updatedApplication.applicantEmail && emailService) {
              const buttonStyle = 'display:inline-block;padding:12px 24px;background-color:#f59e0b;color:white;text-decoration:none;border-radius:6px;';
              
              await emailService.send({
                to: updatedApplication.applicantEmail,
                subject: `Action Required: Sign Foster Agreement - ${req.tenant!.name}`,
                html: `
<h2>Foster Agreement Ready for Signature</h2>
<p>Hello ${updatedApplication.applicantName},</p>
<p>Your foster application with <strong>${req.tenant!.name}</strong> has advanced to the agreement stage.</p>
<p>Please review and sign the Foster Agreement to complete your onboarding.</p>
<p><a href="${formUrl}" style="${buttonStyle}">Sign Foster Agreement</a></p>
<p style="color:#666;font-size:14px;">Or copy and paste this link into your browser:</p>
<p><a href="${formUrl}" style="color:#f59e0b;">${formUrl}</a></p>
<p style="color:#666;font-size:14px;">This link will expire in 14 days.</p>
<p style="color:#666;font-size:14px;">Questions? Contact us at ${req.tenant!.contactEmail || 'our contact email'}.</p>
                `.trim(),
              });
            }

            // Send SMS if method is sms or both
            if ((agreementSendMethod === 'sms' || agreementSendMethod === 'both') && updatedApplication.applicantPhone) {
              try {
                const { sendSms } = await import('./lib/twilio-service');
                const smsMessage = `${req.tenant!.name}: Hi ${updatedApplication.applicantName}, please sign your Foster Agreement to complete your onboarding: ${formUrl}`;
                await sendSms(
                  req.tenant!.id,
                  updatedApplication.applicantPhone,
                  smsMessage,
                  'notification',
                  { source: 'foster_agreement', applicationId: updatedApplication.id }
                );
                console.log(`[Foster Automation] Sent foster agreement SMS to ${updatedApplication.applicantPhone}`);
              } catch (smsError) {
                console.error('[Foster Automation] Error sending foster agreement SMS:', smsError);
              }
            }
            
            // Log activity
            const { logActivity } = await import('./lib/activity-logger');
            const deliveryMethods: string[] = [];
            if ((agreementSendMethod === 'email' || agreementSendMethod === 'both') && updatedApplication.applicantEmail) deliveryMethods.push('email');
            if ((agreementSendMethod === 'sms' || agreementSendMethod === 'both') && updatedApplication.applicantPhone) deliveryMethods.push('SMS');
            await logActivity({
              tenantId: req.tenant!.id,
              userId: req.user!.id,
              action: 'foster_agreement_sent',
              category: 'user',
              entityType: 'foster_application',
              entityId: updatedApplication.id,
              description: `Foster agreement sent via ${deliveryMethods.join(' & ')} to ${updatedApplication.applicantName} (${updatedApplication.applicantEmail || updatedApplication.applicantPhone})`,
              metadata: {
                templateId: template.id,
                templateName: template.name,
                sendMethod: agreementSendMethod,
              },
            });
            
            console.log(`[Foster Automation] Sent foster agreement via ${deliveryMethods.join(' & ')} to ${updatedApplication.applicantEmail || updatedApplication.applicantPhone} using template "${template.name}"`);

          } else {
            console.log(`[Foster Automation] No foster contract template found for tenant ${req.tenant!.id} - skipping email`);
          }
        } catch (agreementError) {
          // Log error but don't fail the status update
          console.error('[Foster Automation] Error sending foster agreement email:', agreementError);
        }
      }

      // ========================================================================
      // AUTOMATION: Sync foster to contacts directory & user system on active_pool
      // ========================================================================
      const statusChangedToActivePool = data.pipelineStatus === 'active_pool' && oldPipelineStatus !== 'active_pool';
      if (statusChangedToActivePool) {
        try {
          const { activateFosterInDirectory } = await import('./services/contacts');
          await activateFosterInDirectory({
            tenantId: req.tenant!.id,
            applicantName: updatedApplication.applicantName,
            applicantEmail: updatedApplication.applicantEmail,
            applicantPhone: updatedApplication.applicantPhone,
            address: updatedApplication.address,
            fosterApplicationId: updatedApplication.id,
          });
        } catch (syncError) {
          console.error('[Foster Automation] Error syncing foster to directory:', syncError);
        }
      }

      // ========================================================================
      // AUTOMATION: Create Google Drive folder when foster moves to active_pool
      // ========================================================================
      if (statusChangedToActivePool && !updatedApplication.driveFolderId) {
        try {
          const { VolunteerFosterBackupService } = await import('./lib/volunteerFosterBackupService');
          const backupService = new VolunteerFosterBackupService(req.tenant!.id);
          
          const result = await backupService.createFosterFolder({
            id: updatedApplication.id,
            applicantName: updatedApplication.applicantName,
            applicantEmail: updatedApplication.applicantEmail,
          });
          
          if (result.success) {
            console.log(`[Foster Automation] Created ${result.storageType} folder for ${updatedApplication.applicantName}`);
          }
        } catch (folderError) {
          console.error('[Foster Automation] Error creating folder:', folderError);
        }
      }

      res.json({ success: true, application: updatedApplication });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Public Contact Form Route
  // ============================================================================

  /**
   * POST /api/public/contact
   * Submit contact form (public route - no auth required)
   * Rate limited to prevent spam (10 emails per hour)
   */
  app.post('/api/public/contact', requireTenant, emailLimiter, async (req, res, next) => {
    try {
      const { inboundEmails } = await import('@shared/schema');
      const { EmailService } = await import('./lib/email-service');
      
      const contactSchema = z.object({
        name: z.string().min(1),
        email: z.string().email(),
        phone: z.string().optional(),
        subject: z.string().min(1),
        message: z.string().min(10),
      });

      const data = contactSchema.parse(req.body);

      // Send email notification to tenant contact email
      try {
        if (req.tenant!.contactEmail) {
          const emailService = await EmailService.forTenant(req.tenant!.id);
          if (!emailService) {
            console.warn(`[Contact Form] No email service configured for tenant ${req.tenant!.id}`);
            throw new Error('Email service not configured');
          }
          await emailService.send({
            to: req.tenant!.contactEmail,
            subject: `Contact Form: ${data.subject}`,
            html: `
              <h2>New Contact Form Submission</h2>
              <p><strong>From:</strong> ${data.name} (${data.email})</p>
              ${data.phone ? `<p><strong>Phone:</strong> ${data.phone}</p>` : ''}
              <p><strong>Subject:</strong> ${data.subject}</p>
              <p><strong>Message:</strong></p>
              <p style="white-space: pre-wrap;">${data.message}</p>
              <hr>
              <p style="color: #666; font-size: 12px;">Submitted via ${req.tenant!.name} website contact form</p>
            `,
            text: `
New Contact Form Submission

From: ${data.name} (${data.email})
${data.phone ? `Phone: ${data.phone}\n` : ''}Subject: ${data.subject}

Message:
${data.message}

---
Submitted via ${req.tenant!.name} website contact form
            `.trim(),
          });
        } else {
          // Log warning if no contact email configured
          console.warn(`Contact form submission received but tenant ${req.tenant!.id} has no contactEmail configured`);
        }
      } catch (error) {
        console.error('Failed to send contact form email:', error);
        // Don't fail the request - submission is still saved to inbox
      }

      // Create inbound email record for inbox
      try {
        const emailBody = `
Contact Form Message

From: ${data.name}
Email: ${data.email}
Phone: ${data.phone || 'Not provided'}
Subject: ${data.subject}

Message:
${data.message}

Submitted: ${new Date().toLocaleString()}
        `.trim();

        await db.insert(inboundEmails).values({
          tenantId: req.tenant!.id,
          messageId: `contact-${Date.now()}-${Math.random().toString(36).substring(7)}`,
          from: data.email,
          fromName: data.name,
          to: req.tenant!.contactEmail || `${req.tenant!.subdomain}@mail.irescue.life`,
          emailSubject: `Contact Form: ${data.subject}`,
          textBody: emailBody,
          htmlBody: emailBody.replace(/\n/g, '<br>'),
          status: 'unprocessed',
          createdAt: new Date(),
        });
      } catch (error) {
        console.error('Failed to create inbound email record:', error);
      }

      res.json({ 
        success: true,
        message: "Thank you for contacting us! We'll get back to you as soon as possible." 
      });
    } catch (error) {
      next(error);
    }
  });

