  /**
   * PATCH /api/volunteer-applications/:id
   * Update volunteer application status (admin/staff only)
   * Auto-dismisses from pending widget when status changes from 'pending' to other statuses
   */
  app.patch('/api/volunteer-applications/:id', requireTenant, requireAuth, requireRoleOrPageAccess(['volunteers', 'volunteer-pipeline'], 'admin', 'staff'), async (req, res, next) =>{
    try {
      const { volunteerApplications, dismissedWidgetItems } = await import('@shared/schema');
      
      // Support both legacy status field and new pipelineStatus field
      const updateSchema = z.object({
        status: z.enum(['pending', 'approved', 'rejected']).optional(),
        pipelineStatus: z.enum(['new_applicant', 'orientation_scheduled', 'waiver_needed', 'active_pool', 'rejected']).optional(),
        notes: z.string().optional(),
        skipAutomation: z.boolean().optional(),
        sendMethod: z.enum(['email', 'sms', 'both']).optional(),
      });

      const data = updateSchema.parse(req.body);
      
      // Get current application to check status before update
      const [currentApp] = await db.select({ status: volunteerApplications.status, pipelineStatus: volunteerApplications.pipelineStatus })
        .from(volunteerApplications)
        .where(
          and(
            eq(volunteerApplications.id, req.params.id),
            eq(volunteerApplications.tenantId, req.tenant!.id)
          )
        )
        .limit(1);
      
      if (!currentApp) {
        return res.status(404).json({ error: 'Volunteer application not found' });
      }
      
      const oldStatus = currentApp.status;
      const oldPipelineStatus = currentApp.pipelineStatus;
      
      // Build update object
      const updateData: Record<string, any> = {
        updatedAt: new Date(),
      };
      
      if (data.status !== undefined) {
        updateData.status = data.status;
      }
      
      if (data.pipelineStatus !== undefined) {
        updateData.pipelineStatus = data.pipelineStatus;
        // Sync legacy status field based on pipelineStatus
        if (data.pipelineStatus === 'active_pool') {
          updateData.status = 'approved';
        } else if (data.pipelineStatus === 'rejected') {
          updateData.status = 'rejected';
        } else if (['new_applicant', 'orientation_scheduled', 'waiver_needed'].includes(data.pipelineStatus)) {
          updateData.status = 'pending';
        }
      }
      
      if (data.notes !== undefined) {
        updateData.notes = data.notes;
      }

      const [updatedApplication] = await db
        .update(volunteerApplications)
        .set(updateData)
        .where(
          and(
            eq(volunteerApplications.id, req.params.id),
            eq(volunteerApplications.tenantId, req.tenant!.id)
          )
        )
        .returning();

      if (!updatedApplication) {
        return res.status(500).json({ error: 'Failed to update volunteer application' });
      }
      
      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'volunteer_application.status_change',
          entityType: 'volunteer_application',
          entityId: req.params.id,
          changes: {
            before: { status: oldStatus, pipelineStatus: oldPipelineStatus },
            after: { status: updatedApplication.status, pipelineStatus: updatedApplication.pipelineStatus },
          },
          metadata: { applicantName: updatedApplication.applicantName || null },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      // Auto-dismiss from widget if moving from 'pending' to another status
      if (oldStatus === 'pending' && updateData.status && updateData.status !== 'pending') {
        try {
          const existing = await db.select({
            id: dismissedWidgetItems.id,
          })
            .from(dismissedWidgetItems)
            .where(
              and(
                eq(dismissedWidgetItems.tenantId, req.tenant!.id),
                eq(dismissedWidgetItems.applicationType, 'volunteer'),
                eq(dismissedWidgetItems.applicationId, req.params.id)
              )
            )
            .limit(1);
          
          if (existing.length === 0) {
            await db.insert(dismissedWidgetItems).values({
              tenantId: req.tenant!.id,
              applicationType: 'volunteer',
              applicationId: req.params.id,
              dismissedBy: req.user!.id,
            });
            console.log(`[AUTO-DISMISS] Volunteer application ${req.params.id} auto-dismissed (${oldStatus} -> ${data.status})`);
          } else {
            console.log(`[AUTO-DISMISS] Volunteer application ${req.params.id} already dismissed`);
          }
        } catch (error) {
          console.error('Failed to auto-dismiss volunteer application:', error);
        }
      }

      // ========================================================================
      // AUTOMATION: Send hold harmless waiver via email/SMS when status changes to 'waiver_needed'
      // ========================================================================
      const statusChangedToWaiverNeeded = data.pipelineStatus === 'waiver_needed' && oldPipelineStatus !== 'waiver_needed' && !data.skipAutomation;
      const waiverSendMethod = data.sendMethod || 'email';
      if (statusChangedToWaiverNeeded && (updatedApplication.applicantEmail || updatedApplication.applicantPhone)) {
        try {
          const { EmailService } = await import('./lib/email-service');
          const { customForms, customFormSubmissions } = await import('@shared/schema');
          const { generateSecureToken } = await import('./services/custom-form');
          
          // Find a hold harmless waiver form for this tenant
          // Look for forms with "hold harmless" OR ("volunteer" AND ("waiver" OR "liability")) in the name
          const [volunteerWaiverForm] = await db
            .select({ id: customForms.id, tenantId: customForms.tenantId, name: customForms.name, isActive: customForms.isActive, htmlTemplate: customForms.htmlTemplate, requiresSignature: customForms.requiresSignature, formType: customForms.formType })
            .from(customForms)
            .where(
              and(
                eq(customForms.tenantId, req.tenant!.id),
                eq(customForms.isActive, true),
                sql`(LOWER(${customForms.name}) LIKE '%hold harmless%' OR (LOWER(${customForms.name}) LIKE '%volunteer%' AND (LOWER(${customForms.name}) LIKE '%waiver%' OR LOWER(${customForms.name}) LIKE '%liability%')))`
              )
            )
            .limit(1);
          
          if (volunteerWaiverForm) {
            // Generate a form submission token for the volunteer applicant
            const { token, hash: tokenHash } = generateSecureToken();
            const expiresAt = new Date();
            expiresAt.setDate(expiresAt.getDate() + 14); // 14 day expiration
            
            // Create pending submission
            await db.insert(customFormSubmissions).values({
              tenantId: req.tenant!.id,
              formId: volunteerWaiverForm.id,
              signerName: updatedApplication.applicantName,
              signerEmail: updatedApplication.applicantEmail,
              signerPhone: updatedApplication.applicantPhone || null,
              status: 'pending',
              secureTokenHash: tokenHash,
              expiresAt,
            });
            
            // Build the form signing URL - use custom domain if available
            let formUrl: string;
            if (req.tenant!.customDomain) {
              formUrl = `https://${req.tenant!.customDomain}/forms/sign/${token}`;
            } else {
              const isProduction = process.env.REPLIT_DEPLOYMENT === '1';
              const baseUrl = isProduction 
                ? 'https://irescue.life'
                : process.env.REPLIT_DEV_DOMAIN 
                  ? `https://${process.env.REPLIT_DEV_DOMAIN}`
                  : 'http://localhost:5000';
              formUrl = `${baseUrl}/${req.tenant!.subdomain}/forms/sign/${token}`;
            }
            
            // Send email if method is email or both
            if ((waiverSendMethod === 'email' || waiverSendMethod === 'both') && updatedApplication.applicantEmail) {
            const emailService = await EmailService.forTenant(req.tenant!.id);
            if (!emailService) {
              console.error('[Volunteer Automation] No email service configured for tenant');
            } else {
            
            // Send email to volunteer applicant
            await emailService.send({
              to: updatedApplication.applicantEmail,
              subject: `Action Required: Please Sign the Hold Harmless Agreement - ${req.tenant!.name}`,
              html: `
                <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                  <h2 style="color: #333;">Hold Harmless Agreement Ready for Signature</h2>
                  <p>Hello ${updatedApplication.applicantName},</p>
                  <p>Great news! Your volunteer application with <strong>${req.tenant!.name}</strong> has advanced to the waiver stage.</p>
                  <p>Please review and sign the Hold Harmless Agreement to complete your onboarding as a volunteer.</p>
                  <div style="margin: 30px 0; text-align: center;">
                    <a href="${formUrl}" style="background-color: #22c55e; color: white; padding: 14px 28px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;">Sign Hold Harmless Agreement</a>
                  </div>
                  <p style="color: #666; font-size: 14px;">Or copy and paste this link into your browser:</p>
                  <p style="font-size: 14px; word-break: break-all;"><a href="${formUrl}" style="color: #2563eb; text-decoration: underline;">${formUrl}</a></p>
                  <p style="color: #666; font-size: 14px;">This link will expire in 14 days.</p>
                  <p style="color: #666; font-size: 14px;">If you have any questions, please contact us at ${req.tenant!.contactEmail || 'our contact email'}.</p>
                  <hr style="border: none; border-top: 1px solid #eee; margin: 30px 0;">
                  <p style="color: #999; font-size: 12px;">You're receiving this email because you applied to volunteer with ${req.tenant!.name}.</p>
                </div>
              `,
              text: `
Hello ${updatedApplication.applicantName},

Your volunteer application with ${req.tenant!.name} has advanced to the waiver stage.

Please sign the Hold Harmless Agreement to complete your onboarding:
${formUrl}

This link will expire in 14 days.

If you have any questions, please contact us.

- ${req.tenant!.name}
              `.trim(),
            });
            
            } // close emailService else
            } // close email method check

            // Send SMS if requested and phone number available
            if ((waiverSendMethod === 'sms' || waiverSendMethod === 'both') && updatedApplication.applicantPhone) {
              try {
                const { sendSms } = await import('./lib/twilio-service');
                const smsMessage = `${req.tenant!.name}: Hi ${updatedApplication.applicantName}, please sign the Hold Harmless Agreement to complete your volunteer onboarding: ${formUrl}`;
                await sendSms(
                  req.tenant!.id,
                  updatedApplication.applicantPhone,
                  smsMessage,
                  'notification',
                  { source: 'volunteer_waiver', applicationId: updatedApplication.id }
                );
                console.log(`[Volunteer Automation] Sent hold harmless waiver SMS to ${updatedApplication.applicantPhone}`);
              } catch (smsError) {
                console.error('[Volunteer Automation] Error sending hold harmless waiver SMS:', smsError);
              }
            }

            // Log activity
            const { logActivity } = await import('./lib/activity-logger');
            const deliveryMethods: string[] = [];
            if ((waiverSendMethod === 'email' || waiverSendMethod === 'both') && updatedApplication.applicantEmail) deliveryMethods.push('email');
            if ((waiverSendMethod === 'sms' || waiverSendMethod === 'both') && updatedApplication.applicantPhone) deliveryMethods.push('SMS');
            await logActivity({
              tenantId: req.tenant!.id,
              userId: req.user!.id,
              action: 'volunteer_waiver_sent',
              category: 'user',
              entityType: 'volunteer_application',
              entityId: updatedApplication.id,
              description: `Hold harmless waiver sent via ${deliveryMethods.join(' & ')} to ${updatedApplication.applicantName} (${updatedApplication.applicantEmail || updatedApplication.applicantPhone})`,
              metadata: {
                formId: volunteerWaiverForm.id,
                formName: volunteerWaiverForm.name,
              },
            });
          } else {
            console.log(`[Volunteer Automation] No hold harmless waiver form found for tenant ${req.tenant!.id} - skipping waiver send`);
          }
        } catch (waiverError) {
          // Log error but don't fail the status update
          console.error('[Volunteer Automation] Error sending hold harmless waiver email:', waiverError);
        }
      }

      // ========================================================================
      // AUTOMATION: Sync volunteer to contacts directory on active_pool
      // ========================================================================
      const statusChangedToActivePool = data.pipelineStatus === 'active_pool' && oldPipelineStatus !== 'active_pool';
      if (statusChangedToActivePool) {
        try {
          const { activateVolunteerInDirectory } = await import('./services/contacts');
          await activateVolunteerInDirectory({
            tenantId: req.tenant!.id,
            applicantName: updatedApplication.applicantName,
            applicantEmail: updatedApplication.applicantEmail,
            applicantPhone: updatedApplication.applicantPhone || undefined,
          });
        } catch (syncError) {
          console.error('[Volunteer Automation] Error syncing volunteer to directory:', syncError);
        }
      }

      // ========================================================================
      // AUTOMATION: Create Google Drive folder when volunteer moves to active_pool
      // ========================================================================
      if (statusChangedToActivePool && !updatedApplication.driveFolderId) {
        try {
          const { VolunteerFosterBackupService } = await import('./lib/volunteerFosterBackupService');
          const backupService = new VolunteerFosterBackupService(req.tenant!.id);
          
          const result = await backupService.createVolunteerFolder({
            id: updatedApplication.id,
            applicantName: updatedApplication.applicantName,
            applicantEmail: updatedApplication.applicantEmail,
          });
          
          if (result.success) {
            console.log(`[Volunteer Automation] Created ${result.storageType} folder for ${updatedApplication.applicantName}`);
          }
        } catch (folderError) {
          console.error('[Volunteer Automation] Error creating folder:', folderError);
        }
      }

      // ========================================================================
      // AUTOMATION: Send volunteer welcome email with account setup link
      // ========================================================================
      if (statusChangedToActivePool) {
        try {
          const { createAndSendVolunteerWelcome } = await import('./services/invitations');
          const result = await createAndSendVolunteerWelcome(
            req.tenant!.id,
            updatedApplication.applicantEmail,
            updatedApplication.applicantName,
          );
          if (result?.skipped) {
            console.log(`[Volunteer Automation] Welcome email skipped (${result.reason}) for ${updatedApplication.applicantEmail}`);
          } else {
            console.log(`[Volunteer Automation] Sent welcome email to ${updatedApplication.applicantEmail}`);
          }
        } catch (emailError) {
          console.error('[Volunteer Automation] Error sending welcome email:', emailError);
        }

        // ========================================================================
        // AUTOMATION: Notify staff via notification preferences
        // ========================================================================
        try {
          const { dispatchEventNotification } = await import('./services/notification-dispatcher');
          await dispatchEventNotification({
            tenantId: req.tenant!.id,
            eventKey: 'volunteer_activated',
            subject: `Volunteer Activated: ${updatedApplication.applicantName}`,
            htmlBody: `<p><strong>${updatedApplication.applicantName}</strong> (${updatedApplication.applicantEmail}) has been moved to the Active Volunteer Pool.</p>`,
            textBody: `${updatedApplication.applicantName} (${updatedApplication.applicantEmail}) has been moved to the Active Volunteer Pool.`,
            metadata: { volunteerId: updatedApplication.id, volunteerName: updatedApplication.applicantName },
          });
        } catch (notifyError) {
          console.error('[Volunteer Automation] Error dispatching staff notification:', notifyError);
        }
      }

      res.json({ success: true, application: updatedApplication });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/volunteer-applications/:id/send-waiver
   * Manually send/resend hold harmless waiver email to volunteer applicant
   */
  app.post('/api/volunteer-applications/:id/send-waiver', requireTenant, requireAuth, requireRoleOrPageAccess(['volunteers', 'volunteer-pipeline'], 'admin', 'staff'), async (req, res, next) => {
    try {
      const { volunteerApplications, customForms, customFormSubmissions } = await import('@shared/schema');
      const { generateSecureToken, hashToken } = await import('./services/custom-form');
      const { EmailService } = await import('./lib/email-service');
      
      // Get the volunteer application
      const [application] = await db
        .select({
        id: fosterApplications.id,
        tenantId: fosterApplications.tenantId,
        applicantName: fosterApplications.applicantName,
        applicantEmail: fosterApplications.applicantEmail,
        applicantPhone: fosterApplications.applicantPhone,
        address: fosterApplications.address,
        housingType: fosterApplications.housingType,
        hasYard: fosterApplications.hasYard,
        hasOtherPets: fosterApplications.hasOtherPets,
        otherPetsDetails: fosterApplications.otherPetsDetails,
        experience: fosterApplications.experience,
        availability: fosterApplications.availability,
        preferences: fosterApplications.preferences,
        vetReference: fosterApplications.vetReference,
        personalReference: fosterApplications.personalReference,
        status: fosterApplications.status,
        pipelineStatus: fosterApplications.pipelineStatus,
        notes: fosterApplications.notes,
        customResponses: fosterApplications.customResponses,
        smsConsent: fosterApplications.smsConsent,
        driveFolderId: fosterApplications.driveFolderId,
        createdAt: fosterApplications.createdAt,
        updatedAt: fosterApplications.updatedAt,
      })
        .from(volunteerApplications)
        .where(and(
          eq(volunteerApplications.id, req.params.id),
          eq(volunteerApplications.tenantId, req.tenant!.id)
        ))
        .limit(1);
      
      if (!application) {
        return res.status(404).json({ error: 'Volunteer application not found' });
      }
      
      if (!application.applicantEmail) {
        return res.status(400).json({ error: 'Application has no email address' });
      }
      
      // Find a hold harmless waiver form for this tenant
      const [volunteerWaiverForm] = await db
        .select({ id: customForms.id, tenantId: customForms.tenantId, name: customForms.name, isActive: customForms.isActive, htmlTemplate: customForms.htmlTemplate, requiresSignature: customForms.requiresSignature, formType: customForms.formType })
        .from(customForms)
        .where(and(
          eq(customForms.tenantId, req.tenant!.id),
          eq(customForms.isActive, true),
          sql`(LOWER(${customForms.name}) LIKE '%hold harmless%' OR (LOWER(${customForms.name}) LIKE '%volunteer%' AND (LOWER(${customForms.name}) LIKE '%waiver%' OR LOWER(${customForms.name}) LIKE '%liability%')))`
        ))
        .limit(1);
      
      if (!volunteerWaiverForm) {
        return res.status(400).json({ 
          error: 'No hold harmless waiver form found. Please create a form with "Hold Harmless" or "Volunteer Waiver/Liability" in the name.' 
        });
      }
      
      // Generate secure token and create submission
      const { token, hash: tokenHash } = generateSecureToken();
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 14); // 14 days expiry
      
      await db.insert(customFormSubmissions).values({
        tenantId: req.tenant!.id,
        formId: volunteerWaiverForm.id,
        signerName: application.applicantName,
        signerEmail: application.applicantEmail,
        signerPhone: application.applicantPhone || null,
        status: 'pending',
        secureTokenHash: tokenHash,
        expiresAt,
      });
      
      // Build the form signing URL - use custom domain if available
      let formUrl: string;
      if (req.tenant!.customDomain) {
        formUrl = `https://${req.tenant!.customDomain}/forms/sign/${token}`;
      } else {
        const isProduction = process.env.REPLIT_DEPLOYMENT === '1';
        const baseUrl = isProduction 
          ? 'https://irescue.life'
          : process.env.REPLIT_DEV_DOMAIN 
            ? `https://${process.env.REPLIT_DEV_DOMAIN}`
            : 'http://localhost:5000';
        formUrl = `${baseUrl}/${req.tenant!.subdomain}/forms/sign/${token}`;
      }
      
      // Get email service for tenant
      const emailService = await EmailService.forTenant(req.tenant!.id);
      if (!emailService) {
        return res.status(400).json({ error: 'Email service not configured for this organization' });
      }
      
      // Send email to volunteer applicant
      // Build HTML with shorter lines to avoid encoding issues
      const buttonStyle = 'display:inline-block;padding:12px 24px;background-color:#22c55e;color:white;text-decoration:none;border-radius:6px;';
      
      await emailService.send({
        to: application.applicantEmail,
        subject: `Action Required: Sign Hold Harmless Agreement - ${req.tenant!.name}`,
        html: `
<h2>Hold Harmless Agreement Ready for Signature</h2>
<p>Hello ${application.applicantName},</p>
<p>Your volunteer application with <strong>${req.tenant!.name}</strong> has advanced to the waiver stage.</p>
<p>Please review and sign the Hold Harmless Agreement to complete your onboarding.</p>
<p><a href="${formUrl}" style="${buttonStyle}">Sign Hold Harmless Agreement</a></p>
<p style="color:#666;font-size:14px;">Or copy and paste this link into your browser:</p>
<p><a href="${formUrl}" style="color:#22c55e;">${formUrl}</a></p>
<p style="color:#666;font-size:14px;">This link will expire in 14 days.</p>
<p style="color:#666;font-size:14px;">Questions? Contact us at ${req.tenant!.contactEmail || 'our contact email'}.</p>
        `.trim(),
      });
      
      // Log activity
      const { logActivity } = await import('./lib/activity-logger');
      await logActivity({
        tenantId: req.tenant!.id,
        userId: req.user!.id,
        action: 'volunteer_waiver_sent',
        category: 'user',
        entityType: 'volunteer_application',
        entityId: application.id,
        description: `Hold harmless waiver email manually sent to ${application.applicantName} (${application.applicantEmail})`,
        metadata: {
          formId: volunteerWaiverForm.id,
          formName: volunteerWaiverForm.name,
        },
      });
      
      console.log(`[Volunteer Waiver] Manually sent hold harmless waiver to ${application.applicantEmail}`);
      
      res.json({ 
        success: true, 
        message: `Waiver email sent to ${application.applicantEmail}`,
        formUrl 
      });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Signed Documents Routes (for Volunteers/Fosters)
  // ============================================================================

  /**
   * GET /api/signed-documents/by-email/:email
   * Get all signed documents for a person by their email (admin/staff only)
   * Used by Volunteer and Foster profile pages to show "Documents" tab
   */
  app.get('/api/signed-documents/by-email/:email', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { customFormSubmissions, customForms } = await import('@shared/schema');
      
      const email = decodeURIComponent(req.params.email).toLowerCase().trim();
      
      // Fetch all completed form submissions for this email
      const submissions = await db
        .select({
          id: customFormSubmissions.id,
          formId: customFormSubmissions.formId,
          formName: customForms.name,
          signerName: customFormSubmissions.signerName,
          signerEmail: customFormSubmissions.signerEmail,
          signedAt: customFormSubmissions.signedAt,
          status: customFormSubmissions.status,
          renderedHtml: customFormSubmissions.renderedHtml,
          createdAt: customFormSubmissions.createdAt,
        })
        .from(customFormSubmissions)
        .innerJoin(customForms, eq(customFormSubmissions.formId, customForms.id))
        .where(
          and(
            eq(customFormSubmissions.tenantId, req.tenant!.id),
            sql`LOWER(TRIM(${customFormSubmissions.signerEmail})) = ${email}`,
            eq(customFormSubmissions.status, 'completed')
          )
        )
        .orderBy(desc(customFormSubmissions.signedAt));
      
      res.json({ documents: submissions });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/signed-documents/:id/download
   * Download a signed document as PDF (admin/staff only)
   */
  app.get('/api/signed-documents/:id/download', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { customFormSubmissions, customForms } = await import('@shared/schema');
      
      // Fetch the submission with form name
      const [submission] = await db
        .select({
          id: customFormSubmissions.id,
          formName: customForms.name,
          signerName: customFormSubmissions.signerName,
          renderedHtml: customFormSubmissions.renderedHtml,
          signedAt: customFormSubmissions.signedAt,
          status: customFormSubmissions.status,
        })
        .from(customFormSubmissions)
        .innerJoin(customForms, eq(customFormSubmissions.formId, customForms.id))
        .where(
          and(
            eq(customFormSubmissions.id, req.params.id),
            eq(customFormSubmissions.tenantId, req.tenant!.id)
          )
        )
        .limit(1);
      
      if (!submission) {
        return res.status(404).json({ error: 'Document not found' });
      }
      
      if (!submission.renderedHtml) {
        return res.status(400).json({ error: 'No document content available' });
      }
      
      // Generate PDF using puppeteer
      const puppeteer = await import('puppeteer');
      const browser = await puppeteer.default.launch({
        headless: true,
        args: ['--no-sandbox', '--disable-setuid-sandbox'],
      });
      
      const page = await browser.newPage();
      
      // Create full HTML document with styling
      const signedDate = submission.signedAt 
        ? new Date(submission.signedAt).toLocaleDateString('en-US', { 
            year: 'numeric', month: 'long', day: 'numeric' 
          })
        : 'Unknown date';
      
      const fullHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>${submission.formName} - ${submission.signerName}</title>
  <style>
    body { 
      font-family: Arial, sans-serif; 
      padding: 40px; 
      max-width: 800px; 
      margin: 0 auto;
      line-height: 1.6;
    }
    h1, h2, h3 { color: #333; }
    .header { 
      border-bottom: 2px solid #333; 
      padding-bottom: 20px; 
      margin-bottom: 30px; 
    }
    .footer { 
      border-top: 1px solid #ccc; 
      padding-top: 20px; 
      margin-top: 30px; 
      font-size: 12px; 
      color: #666; 
    }
    img { max-width: 300px; }
  </style>
</head>
<body>
  <div class="header">
    <h2>${submission.formName}</h2>
    <p>Signed by: <strong>${submission.signerName}</strong></p>
    <p>Date: ${signedDate}</p>
  </div>
  
  ${submission.renderedHtml}
  
  <div class="footer">
    <p>This document was electronically signed on ${signedDate}.</p>
    <p>Document ID: ${submission.id}</p>
  </div>
</body>
</html>`;
      
      await page.setContent(fullHtml, { waitUntil: 'networkidle0' });
      
      const pdfBuffer = await page.pdf({
        format: 'A4',
        printBackground: true,
        margin: { top: '20px', right: '20px', bottom: '20px', left: '20px' },
      });
      
      await browser.close();
      
      // Sanitize filename
      const sanitizedFormName = submission.formName.replace(/[^a-zA-Z0-9\s-]/g, '').substring(0, 50);
      const sanitizedSignerName = submission.signerName.replace(/[^a-zA-Z0-9\s-]/g, '').substring(0, 30);
      const filename = `${sanitizedFormName}_${sanitizedSignerName}.pdf`;
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
      res.send(pdfBuffer);
    } catch (error) {
      console.error('[PDF Download] Error generating PDF:', error);
      next(error);
    }
  });

  /**
   * GET /api/signed-documents/:id/view
   * View a signed document as HTML (admin/staff only)
   */
  app.get('/api/signed-documents/:id/view', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { customFormSubmissions, customForms } = await import('@shared/schema');
      
      const [submission] = await db
        .select({
          id: customFormSubmissions.id,
          formName: customForms.name,
          signerName: customFormSubmissions.signerName,
          signerEmail: customFormSubmissions.signerEmail,
          renderedHtml: customFormSubmissions.renderedHtml,
          signedAt: customFormSubmissions.signedAt,
        })
        .from(customFormSubmissions)
        .innerJoin(customForms, eq(customFormSubmissions.formId, customForms.id))
        .where(
          and(
            eq(customFormSubmissions.id, req.params.id),
            eq(customFormSubmissions.tenantId, req.tenant!.id)
          )
        )
        .limit(1);
      
      if (!submission) {
        return res.status(404).json({ error: 'Document not found' });
      }
      
      res.json({ document: submission });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Surrender Requests Routes (Phase 1 Intake Pipeline)
  // ============================================================================

  /**
   * POST /api/surrender
   * Submit surrender request (public route - Phase 1 Intake Pipeline)
   */
  app.post('/api/surrender', requireTenant, async (req, res, next) => {
    try {
      
      
      // Debug logging for custom responses
      console.log('[Surrender API] Received request body keys:', Object.keys(req.body));
      console.log('[Surrender API] Received customResponses:', JSON.stringify(req.body.customResponses));
      console.log('[Surrender API] Received photoUrl:', req.body.photoUrl);
      
      const surrenderSubmissionSchema = insertSurrenderRequestSchema.extend({
        ownerAddress: z.string().trim().min(3, "Street address is required"),
        ownerCity: z.string().trim().min(1, "City is required"),
        ownerState: z.string().trim().min(2, "State is required"),
        ownerZip: z.string().trim().min(5, "ZIP code is required"),
        dogWeight: z.string().trim().min(1, "Weight is required"),
        dogSize: z.enum(["Small", "Medium", "Large", "Extra Large"], { required_error: "Size is required" }),
        spayedNeutered: z.boolean({ required_error: "Spayed/Neutered is required" }),
        microchipped: z.boolean({ required_error: "Microchip status is required" }),
        goodWithKids: z.enum(["yes", "no", "unknown"], { required_error: "Required" }),
        goodWithDogs: z.enum(["yes", "no", "unknown"], { required_error: "Required" }),
        goodWithCats: z.enum(["yes", "no", "unknown"], { required_error: "Required" }),
        medicalIssues: z.string().trim().min(1, "Medical issues is required"),
        behavioralIssues: z.string().trim().min(1, "Behavioral issues is required"),
        preferredSurrenderDate: z.string().min(1, "Preferred surrender date is required"),
        photoUrl: z.string().trim().min(1, "A photo of the animal is required"),
        customResponses: z.record(z.any()).optional().default({}),
      });
      const data = surrenderSubmissionSchema.parse({
        ...req.body,
        tenantId: req.tenant!.id,
      });

      const requiredFields = await db.select({
        id: surrenderFormFields.id,
        label: surrenderFormFields.label,
        fieldType: surrenderFormFields.fieldType,
      })
      .from(surrenderFormFields)
      .where(
        and(
          eq(surrenderFormFields.tenantId, req.tenant!.id),
          eq(surrenderFormFields.required, true)
        )
      );

      const missingFields: string[] = [];
      for (const field of requiredFields) {
        const value = data.customResponses?.[field.id];
        if (field.fieldType === 'checkbox') {
          if (!value || !Array.isArray(value) || value.length === 0) {
            missingFields.push(field.label);
          }
        } else {
          if (value === undefined || value === null || (typeof value === 'string' && value.trim() === '')) {
            missingFields.push(field.label);
          }
        }
      }

      if (missingFields.length > 0) {
        return res.status(400).json({
          error: 'Missing required fields',
          message: `Please fill out the following required fields: ${missingFields.join(', ')}`,
          missingFields,
        });
      }

      const [surrender] = await db
        .insert(surrenderRequests)
        .values([data as any])
        .returning();

      // Fetch form field labels for email notification
      let formFieldLabels: { id: string; label: string; fieldType: string }[] = [];
      try {
        const fields = await db.select({
          id: surrenderFormFields.id,
          label: surrenderFormFields.label,
          fieldType: surrenderFormFields.fieldType,
        })
        .from(surrenderFormFields)
        .where(eq(surrenderFormFields.tenantId, req.tenant!.id));
        formFieldLabels = fields;
      } catch (fieldsError) {
        console.error('Failed to fetch surrender form fields for email:', fieldsError);
      }

      // Create/update contact from this surrender request
      try {
        const { upsertContact } = await import('./services/contacts');
        await upsertContact({
          tenantId: req.tenant!.id,
          name: data.ownerName,
          email: data.ownerEmail,
          phone: data.ownerPhone,
          source: 'manual',
          tags: ['surrender-request'],
          smsConsent: data.smsConsent,
        });
      } catch (contactError) {
        console.error('Failed to create contact from surrender request:', contactError);
      }

      // Format custom responses for inbound email - show ALL fields, never skip
      let customResponsesText = '';
      const knownFieldIds = new Set(formFieldLabels.map(f => f.id));
      const orphanedResponseEntries = Object.entries(data.customResponses || {}).filter(([id]) => !knownFieldIds.has(id));
      if (formFieldLabels.length > 0 || orphanedResponseEntries.length > 0) {
        customResponsesText = '\n\nAdditional Form Responses:\n';
        const formatTextValue = (label: string, value: any) => {
          const isEmpty = value === undefined || value === null || value === '';
          if (isEmpty) return `${label}: Not provided\n`;
          if (Array.isArray(value)) return `${label}: ${value.join(', ')}\n`;
          if (typeof value === 'boolean') return `${label}: ${value ? 'Yes' : 'No'}\n`;
          return `${label}: ${String(value)}\n`;
        };
        for (const field of formFieldLabels) {
          customResponsesText += formatTextValue(field.label, data.customResponses?.[field.id]);
        }
        for (const [fieldId, value] of orphanedResponseEntries) {
          customResponsesText += formatTextValue(fieldId, value);
        }
      }

      // Helper function for escaping HTML
      const escapeHtml = (text: string): string => {
        if (!text) return '';
        return String(text)
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#039;');
      };

      // Create inbound email record for inbox
      const fullAddress = [data.ownerAddress, data.ownerCity, data.ownerState, data.ownerZip].filter(Boolean).join(', ');

      const emailSubject = `Surrender Request from ${data.ownerName}`;
      const emailBody = `
Surrender Request - ${data.dogName}

Owner Information:
Name: ${data.ownerName}
Email: ${data.ownerEmail}
Phone: ${data.ownerPhone}
Address: ${fullAddress}
SMS Consent: ${data.smsConsent ? 'Yes' : 'No'}

Dog Information:
Name: ${data.dogName}
Breed: ${data.dogBreed}
Age: ${data.dogAge}
Date of Birth: ${data.dogDateOfBirth ? new Date(data.dogDateOfBirth).toLocaleDateString() : 'Not provided'}
Gender: ${data.dogGender}
Weight: ${data.dogWeight || 'Not provided'}
Size: ${data.dogSize || 'Not provided'}

Spayed/Neutered: ${data.spayedNeutered === true ? 'Yes' : data.spayedNeutered === false ? 'No' : 'Unknown'}
Microchipped: ${data.microchipped === true ? 'Yes' : data.microchipped === false ? 'No' : 'Unknown'}${data.microchipNumber ? ` (${data.microchipNumber})` : ''}

Compatibility:
Good with Kids: ${data.goodWithKids || 'Unknown'}
Good with Dogs: ${data.goodWithDogs || 'Unknown'}
Good with Cats: ${data.goodWithCats || 'Unknown'}

Preferred Surrender Date: ${data.preferredSurrenderDate ? new Date(data.preferredSurrenderDate).toLocaleDateString() : 'Not provided'}

Reason for Surrender:
${data.reasonForSurrender}

Medical Issues:
${data.medicalIssues || 'None provided'}

Behavioral Issues:
${data.behavioralIssues || 'None provided'}

${data.photoUrl ? `Photo: ${data.photoUrl}` : ''}
${customResponsesText}
Surrender Request ID: ${surrender.id}
Submitted: ${new Date().toLocaleString()}
      `.trim();

      // Format custom responses as HTML for inbox (with embedded photos) - show ALL fields, never skip
      let customResponsesHtml = '';
      if (formFieldLabels.length > 0 || orphanedResponseEntries.length > 0) {
        customResponsesHtml = '<div style="margin-top: 15px; border-top: 1px solid #e2e8f0; padding-top: 15px;"><h4 style="margin: 0 0 10px 0;">Additional Form Responses</h4>';
        const formatHtmlValue = (label: string, fieldType: string, value: any) => {
          const isEmpty = value === undefined || value === null || value === '';
          if (isEmpty) {
            return `<div style="margin: 5px 0;"><strong>${escapeHtml(label)}:</strong> <em>Not provided</em></div>`;
          } else if (fieldType === 'photo' && typeof value === 'string' && (value.startsWith('http') || value.startsWith('/objects/') || value.startsWith('objects/'))) {
            return `<div style="margin: 10px 0;"><strong>${escapeHtml(label)}:</strong><br><img src="${escapeHtml(String(value))}" alt="${escapeHtml(label)}" style="max-width: 300px; max-height: 300px; border-radius: 8px; margin-top: 5px;" /></div>`;
          } else if (Array.isArray(value)) {
            return `<div style="margin: 5px 0;"><strong>${escapeHtml(label)}:</strong> ${value.map(v => escapeHtml(String(v))).join(', ')}</div>`;
          } else if (typeof value === 'boolean') {
            return `<div style="margin: 5px 0;"><strong>${escapeHtml(label)}:</strong> ${value ? 'Yes' : 'No'}</div>`;
          } else {
            return `<div style="margin: 5px 0;"><strong>${escapeHtml(label)}:</strong> ${escapeHtml(String(value))}</div>`;
          }
        };
        for (const field of formFieldLabels) {
          customResponsesHtml += formatHtmlValue(field.label, field.fieldType || 'text', data.customResponses?.[field.id]);
        }
        for (const [fieldId, value] of orphanedResponseEntries) {
          customResponsesHtml += formatHtmlValue(fieldId, 'text', value);
        }
        customResponsesHtml += '</div>';
      }

      // Create HTML version of email body with embedded photos
      const emailHtmlBody = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6;">
  <h2 style="color: #1e293b; margin-bottom: 20px;">Surrender Request - ${escapeHtml(data.dogName)}</h2>
  
  <div style="background: #f8fafc; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Owner Information</h3>
    <div><strong>Name:</strong> ${escapeHtml(data.ownerName)}</div>
    <div><strong>Email:</strong> <a href="mailto:${escapeHtml(data.ownerEmail)}">${escapeHtml(data.ownerEmail)}</a></div>
    <div><strong>Phone:</strong> ${escapeHtml(data.ownerPhone)}</div>
    <div><strong>Address:</strong> ${escapeHtml(fullAddress)}</div>
    <div><strong>SMS Consent:</strong> ${data.smsConsent ? 'Yes' : 'No'}</div>
  </div>
  
  <div style="background: #f8fafc; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Dog Information</h3>
    <div><strong>Name:</strong> ${escapeHtml(data.dogName)}</div>
    <div><strong>Breed:</strong> ${escapeHtml(data.dogBreed)}</div>
    <div><strong>Age:</strong> ${escapeHtml(data.dogAge)}</div>
    <div><strong>Date of Birth:</strong> ${data.dogDateOfBirth ? new Date(data.dogDateOfBirth).toLocaleDateString() : 'Not provided'}</div>
    <div><strong>Gender:</strong> ${escapeHtml(data.dogGender)}</div>
    <div><strong>Weight:</strong> ${escapeHtml(data.dogWeight || 'Not provided')}</div>
    <div><strong>Size:</strong> ${escapeHtml(data.dogSize || 'Not provided')}</div>
  </div>
  
  <div style="background: #f8fafc; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Health &amp; Medical</h3>
    <div><strong>Spayed/Neutered:</strong> ${data.spayedNeutered === true ? 'Yes' : data.spayedNeutered === false ? 'No' : 'Unknown'}</div>
    <div><strong>Microchipped:</strong> ${data.microchipped === true ? 'Yes' : data.microchipped === false ? 'No' : 'Unknown'}${data.microchipNumber ? ` (${escapeHtml(data.microchipNumber)})` : ''}</div>
  </div>
  
  <div style="background: #f8fafc; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Compatibility</h3>
    <div><strong>Good with Kids:</strong> ${escapeHtml(data.goodWithKids || 'Unknown')}</div>
    <div><strong>Good with Dogs:</strong> ${escapeHtml(data.goodWithDogs || 'Unknown')}</div>
    <div><strong>Good with Cats:</strong> ${escapeHtml(data.goodWithCats || 'Unknown')}</div>
  </div>
  
  <div style="background: #f8fafc; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Preferred Surrender Date</h3>
    <p style="margin: 0;">${data.preferredSurrenderDate ? new Date(data.preferredSurrenderDate).toLocaleDateString() : 'Not provided'}</p>
  </div>
  
  <div style="margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Reason for Surrender</h3>
    <p style="margin: 0; white-space: pre-wrap;">${escapeHtml(data.reasonForSurrender)}</p>
  </div>
  
  <div style="margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Medical Issues</h3>
    <p style="margin: 0; white-space: pre-wrap;">${escapeHtml(data.medicalIssues || 'None provided')}</p>
  </div>
  
  <div style="margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Behavioral Issues</h3>
    <p style="margin: 0; white-space: pre-wrap;">${escapeHtml(data.behavioralIssues || 'None provided')}</p>
  </div>
  
  ${data.photoUrl ? `
  <div style="margin-bottom: 15px;">
    <h3 style="margin: 0 0 10px 0; color: #334155;">Photo</h3>
    <img src="${escapeHtml(data.photoUrl)}" alt="Dog photo" style="max-width: 300px; max-height: 300px; border-radius: 8px;" />
  </div>
  ` : ''}
  
  ${customResponsesHtml}
  
  <div style="margin-top: 20px; padding-top: 15px; border-top: 1px solid #e2e8f0; color: #64748b; font-size: 14px;">
    <div><strong>Surrender Request ID:</strong> ${surrender.id}</div>
    <div><strong>Submitted:</strong> ${new Date().toLocaleString()}</div>
  </div>
</div>
      `.trim();

      // Send email notification to staff if enabled
      try {
        const { sendFormSubmissionNotification } = await import('./services/form-notifications');
        await sendFormSubmissionNotification({
          formType: 'surrender',
          tenantId: req.tenant!.id,
          applicantName: data.ownerName,
          applicantEmail: data.ownerEmail,
          applicantPhone: data.ownerPhone,
          applicationId: surrender.id,
          animalName: data.dogName,
          additionalDetails: `Breed: ${data.dogBreed} | Age: ${data.dogAge} | Gender: ${data.dogGender} | Weight: ${data.dogWeight || 'N/A'} | Size: ${data.dogSize || 'N/A'} | Spayed/Neutered: ${data.spayedNeutered === true ? 'Yes' : data.spayedNeutered === false ? 'No' : 'Unknown'} | Microchipped: ${data.microchipped === true ? 'Yes' : data.microchipped === false ? 'No' : 'Unknown'}${data.microchipNumber ? ' (' + data.microchipNumber + ')' : ''} | Kids: ${data.goodWithKids || 'Unknown'} | Dogs: ${data.goodWithDogs || 'Unknown'} | Cats: ${data.goodWithCats || 'Unknown'} | Address: ${fullAddress} | Preferred Date: ${data.preferredSurrenderDate ? new Date(data.preferredSurrenderDate).toLocaleDateString() : 'N/A'} | DOB: ${data.dogDateOfBirth ? new Date(data.dogDateOfBirth).toLocaleDateString() : 'N/A'} | Reason: ${data.reasonForSurrender} | Medical: ${data.medicalIssues || 'None'} | Behavioral: ${data.behavioralIssues || 'None'}${data.photoUrl ? ' | Photo: ' + data.photoUrl : ''}`,
          customResponses: data.customResponses,
          formFieldLabels: formFieldLabels,
        });
      } catch (notificationError) {
        console.error('Failed to send surrender notification email:', notificationError);
      }

      res.status(201).json({ success: true, surrender });
    } catch (error) {
      next(error);
    }
  });

