  /**
   * POST /api/surrender-requests/:id/payment
   * Create a Stripe PaymentIntent or record a manual payment for a surrender fee
   */
  app.post('/api/surrender-requests/:id/payment', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const paymentSchema = z.object({
        amount: z.number().positive(),
        description: z.string().optional(),
        ownerEmail: z.string().email().optional(),
      });

      const data = paymentSchema.parse(req.body);

      const [request] = await db.select()
        .from(surrenderRequests)
        .where(and(eq(surrenderRequests.id, req.params.id), eq(surrenderRequests.tenantId, req.tenant!.id)))
        .limit(1);

      if (!request) {
        return res.status(404).json({ error: 'Surrender request not found' });
      }

      const hasStripeConnect = !!req.tenant!.stripeConnectedAccountId;
      const hasOwnStripeKeys = req.tenant!.stripeEnabled && !!req.tenant!.stripeSecretKeyEncrypted;
      const stripeConfigured = hasStripeConnect || hasOwnStripeKeys;

      if (stripeConfigured) {
        try {
          const { stripeService } = await import('./lib/stripe-service');
          const { calculatePlatformFee } = await import('./config/platform');
          const platformFeeAmount = hasStripeConnect
            ? calculatePlatformFee(data.amount, req.tenant!.subscriptionTier || 'free', req.tenant!.platformFeePercent)
            : 0;

          const paymentIntent = await stripeService.createPaymentIntent(req.tenant! as any, {
            amount: data.amount,
            description: data.description || `Owner surrender fee for ${request.dogName}`,
            receiptEmail: data.ownerEmail || request.ownerEmail || undefined,
            metadata: {
              type: 'surrender_fee',
              surrenderRequestId: request.id,
              dogName: request.dogName || 'Unknown',
            },
            connectedAccountId: req.tenant!.stripeConnectedAccountId || undefined,
            platformFeeAmount: platformFeeAmount > 0 ? platformFeeAmount : undefined,
          });

          return res.json({
            paymentIntentId: paymentIntent.id,
            clientSecret: paymentIntent.client_secret,
            status: paymentIntent.status,
          });
        } catch (stripeErr: any) {
          console.error('Stripe payment intent creation failed for surrender fee:', stripeErr.message);
          return res.status(500).json({
            error: `Stripe payment failed: ${stripeErr.message}. You can try again or use manual payment recording.`,
          });
        }
      }

      const manualPaymentId = `manual_surrender_${Date.now()}_${request.id.slice(0, 8)}`;
      res.json({
        paymentIntentId: manualPaymentId,
        status: 'manual',
        message: 'Payment recorded manually (Stripe not configured)',
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/surrender-requests/:id/fee
   * Record surrender fee payment result on a surrender request
   */
  app.patch('/api/surrender-requests/:id/fee', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const feeSchema = z.object({
        surrenderFeePaid: z.string().optional(),
        surrenderFeeWaived: z.boolean().optional(),
        paymentIntentId: z.string().optional(),
      });

      const data = feeSchema.parse(req.body);

      const feeAmount = data.surrenderFeeWaived ? '0.00' : (data.surrenderFeePaid || '0.00');

      const [updated] = await db.update(surrenderRequests)
        .set({
          surrenderFeePaid: feeAmount,
          surrenderFeeWaived: data.surrenderFeeWaived || false,
          paymentIntentId: data.paymentIntentId || null,
          updatedAt: new Date(),
        })
        .where(and(
          eq(surrenderRequests.id, req.params.id),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ))
        .returning();

      if (!updated) {
        return res.status(404).json({ error: 'Surrender request not found' });
      }

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/surrender-requests/:id/status
   * Update a surrender request's status (admin, board_member, or staff)
   */
  app.patch('/api/surrender-requests/:id/status', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff'), async (req, res, next) => {
    try {
      
      
      
      const schema = z.object({
        status: z.enum(['new', 'review', 'spacecheck', 'waitlist', 'scheduled', 'intaken', 'declined']),
      });
      
      const { status } = schema.parse(req.body);
      
      // For 'declined' status, require using the dedicated decline endpoint
      if (status === 'declined') {
        return res.status(400).json({ 
          error: 'Use the decline endpoint to reject a request',
          message: 'Please use the Decline button to reject this request with a reason.'
        });
      }
      
      const [updated] = await db.update(surrenderRequests)
        .set({ status, updatedAt: new Date() })
        .where(and(
          eq(surrenderRequests.id, req.params.id),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ))
        .returning();
      
      if (!updated) {
        return res.status(404).json({ error: 'Surrender request not found' });
      }
      
      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'surrender_request.status_change',
          entityType: 'surrender_request',
          entityId: req.params.id,
          changes: { after: { status } },
          metadata: { ownerName: updated.ownerName || null, dogName: updated.dogName || null },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/surrender/:id/decline
   * Decline a surrender request with a reason
   */
  app.post('/api/surrender/:id/decline', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff'), async (req, res, next) => {
    try {
      
      
      
      const schema = z.object({
        reason: z.string().min(1, 'Decline reason is required'),
      });
      
      const { reason } = schema.parse(req.body);
      const surrenderId = req.params.id;
      
      // Validate UUID format
      const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      if (!uuidRegex.test(surrenderId)) {
        return res.status(400).json({ error: 'Invalid surrender request ID' });
      }
      
      // Fetch and verify the request exists
      const [existing] = await db.select({
        id: surrenderRequests.id,
        status: surrenderRequests.status,
      })
        .from(surrenderRequests)
        .where(and(
          eq(surrenderRequests.id, surrenderId),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ))
        .limit(1);
      
      if (!existing) {
        return res.status(404).json({ error: 'Surrender request not found' });
      }
      
      // Check if already declined or intaken
      if (existing.status === 'declined') {
        return res.status(400).json({ error: 'This request has already been declined' });
      }
      if (existing.status === 'intaken') {
        return res.status(400).json({ error: 'Cannot decline a request that has already been intaken' });
      }
      
      // Update to declined status
      const [updated] = await db.update(surrenderRequests)
        .set({ 
          status: 'declined',
          declinedReason: reason,
          declinedAt: new Date(),
          updatedAt: new Date()
        })
        .where(and(
          eq(surrenderRequests.id, surrenderId),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ))
        .returning();
      
      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'surrender_request.declined',
          entityType: 'surrender_request',
          entityId: req.params.id,
          changes: { before: { status: existing.status }, after: { status: 'declined' } },
          metadata: { reason },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      res.json({ 
        success: true, 
        message: 'Surrender request has been declined',
        request: updated
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/surrender/:id/promote
   * Promote a surrender request to an animal in the medical intake queue
   * Converts SurrenderRequest → Animal with medicalStatus='needs_vetting'
   */
  app.post('/api/surrender/:id/promote', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff'), async (req, res, next) => {
    try {
      
      
      const { createAnimal } = await import('./services/animals');
      
      const surrenderId = req.params.id;
      
      // Validate that surrenderId is a valid format (surrender requests use text IDs that look like UUIDs)
      const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      if (!uuidRegex.test(surrenderId)) {
        return res.status(400).json({ error: 'Invalid surrender request ID', message: 'The provided ID is not valid.' });
      }
      
      // Fetch the surrender request
      const [surrenderRequest] = await db.select({
        id: surrenderRequests.id,
        tenantId: surrenderRequests.tenantId,
        status: surrenderRequests.status,
        dogName: surrenderRequests.dogName,
        dogAge: surrenderRequests.dogAge,
        dogGender: surrenderRequests.dogGender,
        dogDateOfBirth: surrenderRequests.dogDateOfBirth,
        dogWeight: surrenderRequests.dogWeight,
        dogSize: surrenderRequests.dogSize,
        spayedNeutered: surrenderRequests.spayedNeutered,
        microchipped: surrenderRequests.microchipped,
        microchipNumber: surrenderRequests.microchipNumber,
        goodWithDogs: surrenderRequests.goodWithDogs,
        goodWithCats: surrenderRequests.goodWithCats,
        goodWithKids: surrenderRequests.goodWithKids,
        dogBreed: surrenderRequests.dogBreed,
        reasonForSurrender: surrenderRequests.reasonForSurrender,
        medicalIssues: surrenderRequests.medicalIssues,
        behavioralIssues: surrenderRequests.behavioralIssues,
        ownerName: surrenderRequests.ownerName,
        ownerEmail: surrenderRequests.ownerEmail,
        ownerPhone: surrenderRequests.ownerPhone,
        photoUrl: surrenderRequests.photoUrl,
        customResponses: surrenderRequests.customResponses,
      })
        .from(surrenderRequests)
        .where(and(
          eq(surrenderRequests.id, surrenderId),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ))
        .limit(1);
      
      if (!surrenderRequest) {
        return res.status(404).json({ error: 'Surrender request not found' });
      }
      
      // Check if already intaken
      if (surrenderRequest.status === 'intaken') {
        return res.status(400).json({ error: 'This surrender request has already been promoted to inventory' });
      }
      
      // Build the animal bio from surrender details
      const bioParts: string[] = [];
      if (surrenderRequest.reasonForSurrender) {
        bioParts.push(`Surrender Reason: ${surrenderRequest.reasonForSurrender}`);
      }
      if (surrenderRequest.medicalIssues) {
        bioParts.push(`Medical Notes: ${surrenderRequest.medicalIssues}`);
      }
      if (surrenderRequest.behavioralIssues) {
        bioParts.push(`Behavioral Notes: ${surrenderRequest.behavioralIssues}`);
      }
      
      // Map gender to sex field
      const sexMap: Record<string, 'male' | 'female' | 'unknown'> = {
        'male': 'male',
        'female': 'female',
        'unknown': 'unknown'
      };
      
      // Validate photo URL if provided (skip external URLs like Google Drive)
      let validatedPhotoUrls: string[] | undefined;
      if (surrenderRequest.photoUrl) {
        const photoValidation = validatePhotoUrls([surrenderRequest.photoUrl]);
        if (photoValidation.valid) {
          validatedPhotoUrls = [surrenderRequest.photoUrl];
        }
        // If invalid (e.g., Google Drive URL), we silently skip it rather than blocking the conversion
      }
      
      const petfinderGenderMap: Record<string, 'Male' | 'Female' | 'Unknown'> = {
        'male': 'Male',
        'female': 'Female',
        'unknown': 'Unknown',
      };

      const inferPetfinderAge = (ageStr: string | null): 'Baby' | 'Young' | 'Adult' | 'Senior' | undefined => {
        if (!ageStr) return undefined;
        const lower = ageStr.toLowerCase();
        if (/puppy|kitten|baby|newborn|neonat/.test(lower)) return 'Baby';
        if (/senior|elderly|geriatric/.test(lower)) return 'Senior';
        if (/young|juvenile|adolescent/.test(lower)) return 'Young';
        if (/adult/.test(lower)) return 'Adult';
        const m = lower.match(/(\d+)\s*(year|yr|month|mo|week|wk|day)/);
        if (m) {
          const num = parseInt(m[1]);
          const unit = m[2];
          if (unit.startsWith('year') || unit.startsWith('yr')) {
            if (num < 1) return 'Baby';
            if (num <= 2) return 'Young';
            if (num <= 7) return 'Adult';
            return 'Senior';
          }
          if (unit.startsWith('month') || unit.startsWith('mo')) {
            return num <= 6 ? 'Baby' : 'Young';
          }
          return 'Baby';
        }
        return undefined;
      };

      const { mapSpeciesToPetfinderType } = await import('@shared/petfinder-breeds');

      const animal = await createAnimal(req.tenant!.id, {
        name: surrenderRequest.dogName,
        species: 'Dog',
        breed: surrenderRequest.dogBreed,
        age: surrenderRequest.dogAge,
        sex: sexMap[surrenderRequest.dogGender] || 'unknown',
        petfinderType: mapSpeciesToPetfinderType('Dog') || 'Dog',
        petfinderBreed: surrenderRequest.dogBreed || undefined,
        petfinderGender: petfinderGenderMap[surrenderRequest.dogGender] || 'Unknown',
        petfinderAge: inferPetfinderAge(surrenderRequest.dogAge) || undefined,
        petfinderSize: surrenderRequest.dogSize || undefined,
        weight: surrenderRequest.dogWeight || undefined,
        intakeSource: 'owner_surrender',
        intakeDate: new Date(),
        medicalStatus: 'needs_vetting',
        status: 'intake',
        bio: bioParts.length > 0 ? bioParts.join('\n\n') : undefined,
        photoUrls: validatedPhotoUrls,
        microchipNumber: surrenderRequest.microchipNumber || undefined,
      });
      
      // If microchip number provided, create a microchip record
      if (surrenderRequest.microchipNumber) {
        const { microchipRecords } = await import('@shared/schema');
        await db.insert(microchipRecords).values({
          animalId: animal.id,
          tenantId: req.tenant!.id,
          microchipNumber: surrenderRequest.microchipNumber,
          chipOrigin: 'intake_with_chip',
          registrationStatus: 'found_unknown',
          createdBy: req.user!.id,
        });
      }
      
      // Create Google Drive/Object Storage folder for the animal (non-blocking)
      try {
        const { createAnimalBackup } = await import('./lib/animalBackupService');
        createAnimalBackup(req.tenant!.id, {
          id: animal.id,
          name: animal.name,
          intakeDate: new Date(),
        }).catch(err => console.error('[ANIMAL BACKUP] Background folder creation failed:', err));
      } catch (backupError) {
        console.error('[ANIMAL BACKUP] Failed to initiate backup:', backupError);
      }
      
      // Update the surrender request status to 'intaken'
      await db.update(surrenderRequests)
        .set({ 
          status: 'intaken',
          updatedAt: new Date()
        })
        .where(and(
          eq(surrenderRequests.id, surrenderId),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ));
      
      res.json({ 
        success: true, 
        animalId: animal.id,
        animalName: animal.name,
        message: `${animal.name} has been added to the medical intake queue`
      });
    } catch (error: any) {
      if (error?.status === 409) {
        return res.status(409).json({ error: error.message });
      }
      if (error?.code === '23505' && error?.constraint?.includes('tenant_name_unique')) {
        return res.status(409).json({ error: 'An animal with this name already exists. Please use a unique name.' });
      }
      next(error);
    }
  });

  /**
   * GET /api/surrender/:id/prepare-intake
   * Returns mapped surrender data for pre-filling the animal creation form
   * Does NOT create the animal - just returns the data for the form
   */
  app.get('/api/surrender/:id/prepare-intake', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff'), async (req, res, next) => {
    try {
      const surrenderId = req.params.id;
      const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      if (!uuidRegex.test(surrenderId)) {
        return res.status(400).json({ error: 'Invalid surrender request ID' });
      }

      const [surrenderRequest] = await db.select()
        .from(surrenderRequests)
        .where(and(
          eq(surrenderRequests.id, surrenderId),
          eq(surrenderRequests.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!surrenderRequest) {
        return res.status(404).json({ error: 'Surrender request not found' });
      }

      if (surrenderRequest.status === 'intaken') {
        return res.status(400).json({ error: 'This surrender request has already been converted to an animal' });
      }

      const sexMap: Record<string, 'male' | 'female' | 'unknown'> = {
        'male': 'male', 'female': 'female', 'unknown': 'unknown'
      };

      const petfinderGenderMap: Record<string, 'Male' | 'Female' | 'Unknown'> = {
        'male': 'Male', 'female': 'Female', 'unknown': 'Unknown',
      };

      const inferPetfinderAge = (ageStr: string | null): 'Baby' | 'Young' | 'Adult' | 'Senior' | undefined => {
        if (!ageStr) return undefined;
        const lower = ageStr.toLowerCase();
        if (/puppy|kitten|baby|newborn|neonat/.test(lower)) return 'Baby';
        if (/senior|elderly|geriatric/.test(lower)) return 'Senior';
        if (/young|juvenile|adolescent/.test(lower)) return 'Young';
        if (/adult/.test(lower)) return 'Adult';
        const m = lower.match(/(\d+)\s*(year|yr|month|mo|week|wk|day)/);
        if (m) {
          const num = parseInt(m[1]);
          const unit = m[2];
          if (unit.startsWith('year') || unit.startsWith('yr')) {
            if (num < 1) return 'Baby';
            if (num <= 2) return 'Young';
            if (num <= 7) return 'Adult';
            return 'Senior';
          }
          if (unit.startsWith('month') || unit.startsWith('mo')) {
            return num <= 6 ? 'Baby' : 'Young';
          }
          return 'Baby';
        }
        return undefined;
      };

      const internalNotesParts: string[] = [];
      if (surrenderRequest.reasonForSurrender) {
        internalNotesParts.push(`Surrender Reason: ${surrenderRequest.reasonForSurrender}`);
      }
      if (surrenderRequest.medicalIssues) {
        internalNotesParts.push(`Medical Notes: ${surrenderRequest.medicalIssues}`);
      }
      if (surrenderRequest.behavioralIssues) {
        internalNotesParts.push(`Behavioral Notes: ${surrenderRequest.behavioralIssues}`);
      }

      const { personDocuments } = await import('@shared/schema');
      const attachedDocs = await db.select()
        .from(personDocuments)
        .where(and(
          eq(personDocuments.tenantId, req.tenant!.id),
          eq(personDocuments.sourceTable, 'surrender_requests'),
          eq(personDocuments.sourceId, surrenderId)
        ));

      res.json({
        surrenderRequestId: surrenderRequest.id,
        animalFields: {
          name: surrenderRequest.dogName,
          species: 'Dog',
          breed: surrenderRequest.dogBreed,
          age: surrenderRequest.dogAge,
          sex: sexMap[surrenderRequest.dogGender] || 'unknown',
          dateOfBirth: surrenderRequest.dogDateOfBirth || undefined,
          weight: surrenderRequest.dogWeight || undefined,
          petfinderSize: surrenderRequest.dogSize || undefined,
          petfinderGender: petfinderGenderMap[surrenderRequest.dogGender] || 'Unknown',
          petfinderAge: inferPetfinderAge(surrenderRequest.dogAge) || undefined,
          petfinderType: 'Dog',
          petfinderBreed: surrenderRequest.dogBreed || undefined,
          intakeSource: 'owner_surrender',
          medicalStatus: 'needs_vetting',
          status: 'intake',
          microchipNumber: surrenderRequest.microchipNumber || undefined,
          microchipped: surrenderRequest.microchipped || undefined,
          spayedNeutered: surrenderRequest.spayedNeutered || undefined,
          neuterStatus: surrenderRequest.spayedNeutered
            ? (surrenderRequest.dogGender === 'female' ? 'spayed' : 'neutered')
            : (surrenderRequest.spayedNeutered === false ? 'intact' : undefined),
          childFriendly: surrenderRequest.goodWithKids === 'yes' ? true : surrenderRequest.goodWithKids === 'no' ? false : undefined,
          dogFriendly: surrenderRequest.goodWithDogs === 'yes' ? true : surrenderRequest.goodWithDogs === 'no' ? false : undefined,
          catFriendly: surrenderRequest.goodWithCats === 'yes' ? true : surrenderRequest.goodWithCats === 'no' ? false : undefined,
          photoUrls: surrenderRequest.photoUrl ? [surrenderRequest.photoUrl] : undefined,
          internalNotes: internalNotesParts.length > 0 ? internalNotesParts.join('\n\n') : undefined,
        },
        ownerInfo: {
          name: surrenderRequest.ownerName,
          email: surrenderRequest.ownerEmail,
          phone: surrenderRequest.ownerPhone,
          address: surrenderRequest.ownerAddress || undefined,
        },
        attachedDocuments: attachedDocs.map(doc => ({
          id: doc.id,
          name: doc.title,
          fileUrl: doc.objectPath || '',
          fileType: doc.contentType || '',
        })),
      });
    } catch (error) {
      next(error);
    }
  });




