  /**
   * GET /api/foster-animals/:animalId/history
   * Get all foster records (current and past) for a specific animal (staff/admin only)
   */
  app.get('/api/foster-animals/:animalId/history', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { fosterAnimals, animals, users, placementAgreementSessions } = await import('@shared/schema');
      const { animalId } = req.params;

      const [animal] = await db
        .select({ id: animals.id, name: animals.name })
        .from(animals)
        .where(and(eq(animals.id, animalId), eq(animals.tenantId, req.tenant!.id)))
        .limit(1);

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      const history = await db
        .select({
          id: fosterAnimals.id,
          fosterId: fosterAnimals.fosterId,
          fosterName: users.fullName,
          fosterEmail: users.email,
          status: fosterAnimals.status,
          startDate: fosterAnimals.startDate,
          endDate: fosterAnimals.actualReturnDate,
          placementAgreementStatus: placementAgreementSessions.status,
          notes: fosterAnimals.notes,
          createdAt: fosterAnimals.createdAt,
          contractPdfUrl: placementAgreementSessions.contractPdfUrl,
        })
        .from(fosterAnimals)
        .leftJoin(users, eq(fosterAnimals.fosterId, users.id))
        .leftJoin(placementAgreementSessions, and(
          eq(placementAgreementSessions.animalId, fosterAnimals.animalId),
          eq(placementAgreementSessions.fosterId, fosterAnimals.fosterId),
          eq(placementAgreementSessions.tenantId, req.tenant!.id),
          eq(placementAgreementSessions.status, 'signed')
        ))
        .where(
          and(
            eq(fosterAnimals.tenantId, req.tenant!.id),
            eq(fosterAnimals.animalId, animalId)
          )
        )
        .orderBy(desc(fosterAnimals.startDate));

      res.json({ animal, history });
    } catch (error) {
      next(error);
    }
  });

