  /**
   * PATCH /api/tenant/settings
   * Update tenant payment settings (admin only)
   */
  app.patch('/api/tenant/settings', requireTenant, requireAuth, requireRole('admin'), async (req, res, next) => {
    try {
      const settingsSchema = z.object({
        stripeLink: z.string().url().optional().or(z.literal("")),
        passFeesToAdopter: z.boolean().optional(),
        requireSpayNeuterContract: z.boolean().optional(),
        defaultSurrenderFee: z.string().optional().nullable(),
        autoSendTaxReceipts: z.boolean().optional(),
        shopEnabled: z.boolean().optional(),
        impactLoopEnabled: z.boolean().optional(),
      });

      const parsedSettings = settingsSchema.parse(req.body);
      
      const settingsToUpdate: Record<string, any> = {};
      if (parsedSettings.stripeLink !== undefined) settingsToUpdate.stripeLink = parsedSettings.stripeLink;
      if (parsedSettings.passFeesToAdopter !== undefined) settingsToUpdate.passFeesToAdopter = parsedSettings.passFeesToAdopter;
      if (parsedSettings.requireSpayNeuterContract !== undefined) settingsToUpdate.requireSpayNeuterContract = parsedSettings.requireSpayNeuterContract;
      if (parsedSettings.defaultSurrenderFee !== undefined) settingsToUpdate.defaultSurrenderFee = parsedSettings.defaultSurrenderFee;
      if (parsedSettings.autoSendTaxReceipts !== undefined) settingsToUpdate.autoSendTaxReceipts = parsedSettings.autoSendTaxReceipts;
      if (parsedSettings.shopEnabled !== undefined) settingsToUpdate.shopEnabled = parsedSettings.shopEnabled;
      if (parsedSettings.impactLoopEnabled !== undefined) settingsToUpdate.impactLoopEnabled = parsedSettings.impactLoopEnabled;

      const [updatedTenant] = await db
        .update(tenants)
        .set(settingsToUpdate)
        .where(eq(tenants.id, req.tenant!.id))
        .returning();

      res.json({ success: true, tenant: updatedTenant });
    } catch (error) {
      next(error);
    }
  });

  app.get('/api/tenant/notification-preferences', requireTenant, requireAuth, requireRole('owner', 'admin'), async (req, res, next) => {
    try {
      const { notificationPreferences, NOTIFICATION_EVENT_KEYS } = await import('@shared/schema');
      
      const existing = await db
        .select()
        .from(notificationPreferences)
        .where(eq(notificationPreferences.tenantId, req.tenant!.id))
        .orderBy(notificationPreferences.eventKey);

      const existingMap = new Map(existing.map(p => [`${p.eventKey}_${p.channel}`, p]));

      const allPrefs = NOTIFICATION_EVENT_KEYS.map(eventKey => {
        const key = `${eventKey}_email`;
        if (existingMap.has(key)) {
          return existingMap.get(key)!;
        }
        return {
          id: null,
          tenantId: req.tenant!.id,
          eventKey,
          channel: "email" as const,
          isEnabled: false,
          recipientRoles: ["admin"],
          recipientEmails: [],
          createdAt: new Date(),
          updatedAt: new Date(),
        };
      });

      res.json({ preferences: allPrefs });
    } catch (error) {
      next(error);
    }
  });

  app.patch('/api/tenant/notification-preferences', requireTenant, requireAuth, requireRole('owner', 'admin'), async (req, res, next) => {
    try {
      const { notificationPreferences, NOTIFICATION_EVENT_KEYS } = await import('@shared/schema');
      
      const updateSchema = z.object({
        preferences: z.array(z.object({
          eventKey: z.enum(NOTIFICATION_EVENT_KEYS as unknown as [string, ...string[]]),
          channel: z.enum(["email", "sms"]),
          isEnabled: z.boolean(),
          recipientRoles: z.array(z.string()).optional().default([]),
          recipientEmails: z.array(z.string().email()).optional().default([]),
          recipientPhones: z.array(z.string()).optional().default([]),
        })),
      });

      const { preferences } = updateSchema.parse(req.body);
      const tenantId = req.tenant!.id;

      const results = [];
      for (const pref of preferences) {
        const existing = await db
          .select()
          .from(notificationPreferences)
          .where(
            and(
              eq(notificationPreferences.tenantId, tenantId),
              eq(notificationPreferences.eventKey, pref.eventKey),
              eq(notificationPreferences.channel, pref.channel),
            )
          )
          .limit(1);

        if (existing.length > 0) {
          const [updated] = await db
            .update(notificationPreferences)
            .set({
              isEnabled: pref.isEnabled,
              recipientRoles: pref.recipientRoles,
              recipientEmails: pref.recipientEmails,
              recipientPhones: pref.recipientPhones,
              updatedAt: new Date(),
            })
            .where(eq(notificationPreferences.id, existing[0].id))
            .returning();
          results.push(updated);
        } else {
          const [inserted] = await db
            .insert(notificationPreferences)
            .values({
              tenantId,
              eventKey: pref.eventKey as any,
              channel: pref.channel as any,
              isEnabled: pref.isEnabled,
              recipientRoles: pref.recipientRoles,
              recipientEmails: pref.recipientEmails,
              recipientPhones: pref.recipientPhones,
            })
            .returning();
          results.push(inserted);
        }
      }

      res.json({ success: true, preferences: results });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/impact-loop/opt-out?token=...
   * Public, token-authenticated link from the Impact Loop section in monthly
   * receipt emails. Sets the donor's per-loop preference without affecting
   * the underlying receipt or any other email subscription.
   */
  app.get('/api/impact-loop/opt-out', async (req, res) => {
    try {
      const token = String(req.query.token || '');
      const { verifyImpactOptOutToken } = await import('./services/impact-loop');
      const donorId = verifyImpactOptOutToken(token);
      if (!donorId) {
        return res.status(400).type('html').send(
          `<!doctype html><meta charset="utf-8"><title>Invalid link</title>
          <div style="font-family:Arial,sans-serif;max-width:520px;margin:60px auto;padding:24px;text-align:center;color:#374151;">
            <h2 style="color:#111827;">This link is invalid or expired</h2>
            <p>If you'd like to opt out of impact updates, please reply to your most recent receipt and we'll handle it.</p>
          </div>`
        );
      }
      await db.update(donors).set({ impactLoopOptOut: true }).where(eq(donors.id, donorId));
      return res.status(200).type('html').send(
        `<!doctype html><meta charset="utf-8"><title>Preference updated</title>
        <div style="font-family:Arial,sans-serif;max-width:520px;margin:60px auto;padding:24px;text-align:center;color:#374151;">
          <h2 style="color:#111827;">You're all set</h2>
          <p>You'll keep receiving your monthly receipts, but we won't include the "who you helped save" section anymore.</p>
          <p style="font-size:13px;color:#6b7280;margin-top:24px;">Thank you for your continued support.</p>
        </div>`
      );
    } catch (err) {
      console.error('[ImpactLoop] Opt-out failed:', err);
      return res.status(500).type('html').send('<p>Sorry, something went wrong. Please try again later.</p>');
    }
  });

  /**
   * POST /api/tenant/settings/impact-loop-test
   * Sends a sample monthly receipt with the Impact Loop section to the
   * requesting admin, so they can preview what donors will receive before
   * enabling the feature.
   */
  app.post('/api/tenant/settings/impact-loop-test', requireTenant, requireAuth, requireRole('admin'), async (req, res, next) => {
    try {
      const adminEmail = req.user?.email;
      if (!adminEmail) {
        return res.status(400).json({ error: 'Your account does not have an email address on file.' });
      }

      const [fullTenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, req.tenant!.id))
        .limit(1);

      if (!fullTenant) {
        return res.status(404).json({ error: 'Tenant not found' });
      }

      const { getMostRecentlyAdoptedAnimal } = await import('./services/impact-loop');
      const animal = await getMostRecentlyAdoptedAnimal(fullTenant.id);
      if (!animal) {
        return res.status(409).json({
          error: 'Mark an animal as adopted (with at least one photo on file) to preview the Impact Loop section.',
        });
      }

      const { sendImpactLoopPreviewEmail } = await import('./services/vip-emails');
      const result = await sendImpactLoopPreviewEmail({
        tenant: fullTenant,
        recipientEmail: adminEmail,
        fallbackOrigin: `${req.protocol}://${req.get('host')}`,
      });

      if (!result.success) {
        return res.status(502).json({ error: result.error || 'Failed to send preview email.' });
      }

      return res.json({ success: true, sentTo: adminEmail, featuredAnimal: animal.name });
    } catch (error) {
      next(error);
    }
  });

