  /**
   * POST /api/tenant/settings/twilio/test
   * Send a test SMS (admin only)
   */
  app.post('/api/tenant/settings/twilio/test', requireTenant, requireAuth, requireRole('admin'), async (req, res, next) => {
    try {
      const { sendSms } = await import('./lib/twilio-service');
      
      const testSchema = z.object({
        phoneNumber: z.string()
          .transform((v) => {
            const stripped = v.replace(/[\s\-().]/g, '');
            if (/^\d{10}$/.test(stripped)) return `+1${stripped}`;
            if (/^1\d{10}$/.test(stripped)) return `+${stripped}`;
            return stripped;
          })
          .refine((v) => /^\+[1-9]\d{1,14}$/.test(v), "Phone number must be in E.164 format (e.g. 555-867-5309 or +15558675309)"),
      });

      const { phoneNumber } = testSchema.parse(req.body);

      const result = await sendSms(
        req.tenant!.id,
        phoneNumber,
        `Your Twilio SMS integration is working! This is a test message.`,
        'other',
        { sentBy: { id: req.user!.id, name: req.user!.name || req.user!.email } }
      );

      if (result.status === 'failed') {
        return res.status(400).json({ error: result.error });
      }

      let deliveryStatus: string | null = null;
      let deliveryError: string | null = null;
      if (result.sid) {
        try {
          const { getTwilioConfigForTenant } = await import('./lib/twilio-service');
          const config = await getTwilioConfigForTenant(req.tenant!.id);
          if (config) {
            const twilioLib = await import('twilio');
            const client = twilioLib.default(config.accountSid, config.authToken);
            await new Promise(resolve => setTimeout(resolve, 2000));
            const msg = await client.messages(result.sid).fetch();
            deliveryStatus = msg.status;
            deliveryError = msg.errorCode ? `${msg.errorCode}: ${msg.errorMessage}` : null;
            console.log(`[TWILIO TEST] SID=${result.sid} status=${msg.status} errorCode=${msg.errorCode} errorMessage=${msg.errorMessage}`);
          }
        } catch (fetchErr: any) {
          console.error('[TWILIO TEST] Failed to fetch message status:', fetchErr.message);
        }
      }

      res.json({ success: true, sid: result.sid, deliveryStatus, deliveryError });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/notifications/send
   * Send an SMS notification to a phone number (staff/admin)
   */
  app.post('/api/notifications/send', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const allowedRoles = ['admin', 'manager', 'staff'];
      if (!allowedRoles.includes(req.user!.activeRole || '')) {
        return res.status(403).json({ error: 'Access denied' });
      }

      const sendSchema = z.object({
        phoneNumber: z.string().min(1, "Phone number is required"),
        message: z.string().min(1, "Message is required"),
        recipientName: z.string().optional(),
      });

      const { phoneNumber, message, recipientName } = sendSchema.parse(req.body);

      const { sendSms } = await import('./lib/twilio-service');
      const result = await sendSms(
        req.tenant!.id,
        phoneNumber,
        message,
        'reminder',
        { sentBy: { id: req.user!.id, name: req.user!.name || req.user!.email } }
      );

      if (result.status === 'failed') {
        return res.status(400).json({ error: result.error || 'Failed to send SMS' });
      }

      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'notification.sms_sent',
          entityType: 'notification',
          entityId: result.sid || '',
          changes: { after: { phoneNumber, recipientName } },
          metadata: { recipientName: recipientName || null, messagePreview: message.substring(0, 100) },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      res.json({ success: true, sid: result.sid });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/notifications/send-batch
   * Send SMS reminders to multiple phone numbers (admin/manager)
   */
  app.post('/api/notifications/send-batch', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const allowedRoles = ['admin', 'manager'];
      if (!allowedRoles.includes(req.user!.activeRole || '')) {
        return res.status(403).json({ error: 'Access denied' });
      }

      const batchSchema = z.object({
        recipients: z.array(z.object({
          phoneNumber: z.string().min(1),
          message: z.string().min(1),
          recipientName: z.string().optional(),
        })).min(1).max(50),
      });

      const { recipients } = batchSchema.parse(req.body);

      const { sendSms } = await import('./lib/twilio-service');
      const results = await Promise.all(
        recipients.map(async (r) => {
          const result = await sendSms(
            req.tenant!.id,
            r.phoneNumber,
            r.message,
            'reminder',
            { sentBy: { id: req.user!.id, name: req.user!.name || req.user!.email } }
          );
          return { phoneNumber: r.phoneNumber, recipientName: r.recipientName, ...result };
        })
      );

      const sent = results.filter(r => r.status === 'sent').length;
      const failed = results.filter(r => r.status === 'failed').length;

      try {
        const { createAuditLog } = await import('./audit');
        await createAuditLog({
          userId: req.user!.id,
          tenantId: req.tenant!.id,
          action: 'notification.batch_sms_sent',
          entityType: 'notification',
          entityId: '',
          changes: { after: { totalRecipients: recipients.length, sent, failed } },
          metadata: { sent, failed },
          req,
        });
      } catch (auditErr) {
        console.error('Failed to create audit log:', auditErr);
      }

      res.json({ success: true, sent, failed, results });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/webhooks/twilio/incoming
   * Webhook for incoming SMS messages (no auth - Twilio validates with signature)
   */
  app.post('/api/webhooks/twilio/incoming', async (req, res, next) => {
    try {
      const { handleIncomingSms } = await import('./lib/twilio-service');
      const { decrypt } = await import('./lib/encryption');
      
      const { From, To, Body } = req.body;
      
      if (!From || !To) {
        return res.status(400).send('Missing required fields');
      }

      // Collect any attached media URLs (Twilio MMS support)
      const numMedia = parseInt(req.body.NumMedia || '0', 10);
      const mediaUrls: string[] = [];
      for (let i = 0; i < numMedia && i < 10; i++) {
        const url = req.body[`MediaUrl${i}`];
        if (url) mediaUrls.push(url);
      }

      // Twilio webhook signature validation — look up tenant by the 'To' phone number
      const twilioSignature = req.headers['x-twilio-signature'] as string | undefined;
      if (twilioSignature) {
        try {
          const [tenantRecord] = await db
            .select({ twilioAuthTokenEncrypted: tenants.twilioAuthTokenEncrypted })
            .from(tenants)
            .where(eq(tenants.twilioPhoneNumber, To))
            .limit(1);

          if (tenantRecord?.twilioAuthTokenEncrypted) {
            const twilio = (await import('twilio')).default;
            const authToken = decrypt(tenantRecord.twilioAuthTokenEncrypted);
            const webhookUrl = `${process.env.APP_BASE_URL || `${req.protocol}://${req.get('host')}`}${req.originalUrl || req.url}`;
            const isValid = twilio.validateRequest(authToken, twilioSignature, webhookUrl, req.body);
            if (!isValid) {
              console.warn('[TWILIO] Webhook signature validation failed — rejecting request');
              return res.status(403).send('Invalid Twilio signature');
            }
          }
        } catch (validationError) {
          console.error('[TWILIO] Signature validation error:', validationError);
          // Fail open so we don't drop messages on validation errors (e.g. tenant lookup failure)
        }
      }

      const result = await handleIncomingSms(From, To, Body || '', mediaUrls);
      
      res.set('Content-Type', 'text/xml');
      if (result.routedAs === 'medication_confirmed') {
        res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Message>Got it, thanks! Meds confirmed.</Message></Response>');
      } else if (result.routedAs === 'fuzzy_done_hint') {
        res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Message>Did you mean DONE? Reply DONE to confirm meds were given.</Message></Response>');
      } else if (result.routedAs === 'supply_request') {
        res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Message>Got it! Your supply request has been logged. The team will follow up soon.</Message></Response>');
      } else if (result.routedAs === 'foster_update') {
        res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Message>Thanks for the update! Your message has been received by the rescue team.</Message></Response>');
      } else if (result.routedAs === 'volunteer_signup' && result.signupDetails) {
        res.send(`<?xml version="1.0" encoding="UTF-8"?><Response><Message>You're signed up for ${result.signupDetails.calendarName} on ${result.signupDetails.dayLabel}! Thanks!</Message></Response>`);
      } else if (result.routedAs === 'volunteer_signup_duplicate' && result.signupDetails) {
        res.send(`<?xml version="1.0" encoding="UTF-8"?><Response><Message>You're already signed up for ${result.signupDetails.calendarName} on ${result.signupDetails.dayLabel}!</Message></Response>`);
      } else if (result.routedAs === 'volunteer_signup_pick_number') {
        res.send(`<?xml version="1.0" encoding="UTF-8"?><Response><Message>Multiple shifts need help! Reply with a number:\n${result.message}</Message></Response>`);
      } else if (result.routedAs === 'volunteer_signup_full') {
        res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Message>All shifts are currently covered — thanks for being willing to help!</Message></Response>');
      } else {
        res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
      }
    } catch (error) {
      console.error('Twilio webhook error:', error);
      res.set('Content-Type', 'text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
    }
  });

  app.post('/api/webhooks/twilio/inbound', (req, res, next) => {
    req.url = '/api/webhooks/twilio/incoming';
    app.handle(req, res, next);
  });

  /**
   * POST /api/webhooks/twilio/status
   * Twilio Delivery Status callback — updates sms_message_logs.status when Twilio delivers/fails a message.
   * Configure in Twilio dashboard as the "Status Callback URL" for your messaging service.
   * No auth required — public webhook. Responds with TwiML <Response/> as required by Twilio.
   */
  app.post('/api/webhooks/twilio/status', async (req, res) => {
    try {
      const messageSid = req.body?.MessageSid as string | undefined;
      const twilioStatus = req.body?.MessageStatus as string | undefined;

      if (messageSid && twilioStatus) {
        let newStatus: 'sent' | 'delivered' | 'failed' | 'received' | null = null;
        if (twilioStatus === 'delivered') newStatus = 'delivered';
        else if (twilioStatus === 'undelivered' || twilioStatus === 'failed') newStatus = 'failed';

        if (newStatus) {
          await db
            .update(smsMessageLogs)
            .set({ status: newStatus })
            .where(eq(smsMessageLogs.twilioMessageSid, messageSid));
          console.log(`[TWILIO STATUS] ${messageSid} → ${newStatus}`);
        }
      }
    } catch (err) {
      console.error('[TWILIO STATUS WEBHOOK] Error:', err);
    }
    res.set('Content-Type', 'text/xml');
    res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
  });

  /**
   * POST /api/transports/:id/sms-broadcast
   * Send SMS broadcast to transport subscribers (staff only)
   */
  app.post('/api/transports/:id/sms-broadcast', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { broadcastTransportUpdate, getTransportSmsSubscribers } = await import('./lib/twilio-service');
      
      const broadcastSchema = z.object({
        message: z.string().min(1).max(1600), // SMS length limit
      });

      const { message } = broadcastSchema.parse(req.body);
      const transportId = req.params.id;

      // Verify transport exists and belongs to tenant
      const [transport] = await db
        .select()
        .from(transportEvents)
        .where(and(
          eq(transportEvents.id, transportId),
          eq(transportEvents.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!transport) {
        return res.status(404).json({ error: 'Transport not found' });
      }

      const subscribers = await getTransportSmsSubscribers(transportId);
      
      if (subscribers.length === 0) {
        return res.status(400).json({ error: 'No SMS subscribers for this transport' });
      }

      const results = await broadcastTransportUpdate(
        req.tenant!.id,
        transportId,
        message,
        subscribers,
        { id: req.user!.id, name: req.user!.name || req.user!.email }
      );

      const sent = results.filter(r => r.status === 'sent').length;
      const failed = results.filter(r => r.status === 'failed').length;

      res.json({ 
        success: true, 
        sent, 
        failed,
        results 
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/transports/:id/sms-subscribe
   * Subscribe a phone number to transport updates
   */
  app.post('/api/transports/:id/sms-subscribe', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { addTransportSmsSubscriber } = await import('./lib/twilio-service');
      
      const subscribeSchema = z.object({
        phoneNumber: z.string()
          .transform((v) => {
            const stripped = v.replace(/[\s\-().]/g, '');
            if (/^\d{10}$/.test(stripped)) return `+1${stripped}`;
            if (/^1\d{10}$/.test(stripped)) return `+${stripped}`;
            return stripped;
          })
          .regex(/^\+[1-9]\d{1,14}$/, "Phone number must be in E.164 format (e.g. 555-867-5309 or +15558675309)"),
      });

      const { phoneNumber } = subscribeSchema.parse(req.body);
      const transportId = req.params.id;

      // Verify transport exists and belongs to tenant
      const [transport] = await db
        .select()
        .from(transportEvents)
        .where(and(
          eq(transportEvents.id, transportId),
          eq(transportEvents.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!transport) {
        return res.status(404).json({ error: 'Transport not found' });
      }

      await addTransportSmsSubscriber(transportId, phoneNumber);
      res.json({ success: true });
    } catch (error) {
      next(error);
    }
  });

