  /**
   * GET /api/stripe/payment-ledger
   * Get all Stripe payments with type classification and details
   */
  app.get('/api/stripe/payment-ledger', requireTenant, requireAuth, requireRoleOrPageAccess('finance', 'admin', 'board_member', 'staff', 'owner'), async (req, res, next) => {
    try {
      const { stripeService } = await import('./lib/stripe-service');
      const { adoptionCheckoutSessions, applications: applicationsTable, animals: animalsTable, customFormSubmissions, customForms, shopOrders } = await import('@shared/schema');

      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, req.tenant!.id))
        .limit(1);

      if (!tenant) {
        return res.status(404).json({ error: 'Tenant not found' });
      }

      const hasStripe = tenant.stripeConnectedAccountId || (tenant.stripeEnabled && tenant.stripeSecretKeyEncrypted);
      if (!hasStripe) {
        return res.json({ configured: false, payments: [] });
      }

      const result = await stripeService.getCheckoutSessions(tenant, 100);
      if (!result.sessions) {
        return res.json({ configured: true, payments: [], error: result.error });
      }

      // Cross-reference with DB tables to classify payments
      const adoptionSessions = await db
        .select({
          paymentIntentId: adoptionCheckoutSessions.paymentIntentId,
          animalName: animalsTable.name,
          applicantName: applicationsTable.applicantName,
          baseFee: adoptionCheckoutSessions.baseFee,
          donationBoost: adoptionCheckoutSessions.donationBoost,
          status: adoptionCheckoutSessions.status,
        })
        .from(adoptionCheckoutSessions)
        .leftJoin(animalsTable, eq(adoptionCheckoutSessions.animalId, animalsTable.id))
        .leftJoin(applicationsTable, eq(adoptionCheckoutSessions.applicationId, applicationsTable.id))
        .where(eq(adoptionCheckoutSessions.tenantId, req.tenant!.id));

      const adoptionMap = new Map();
      for (const a of adoptionSessions) {
        if (a.paymentIntentId) adoptionMap.set(a.paymentIntentId, a);
      }

      // Note: customFormSubmissions does not store paymentIntentId, so form_fee classification
      // is reserved for future use when form payments are tracked with payment intent references
      const formMap = new Map();

      const orders = await db
        .select({
          paymentIntentId: shopOrders.stripePaymentIntentId,
          orderNumber: shopOrders.orderNumber,
          customerName: shopOrders.customerName,
          totalAmount: shopOrders.totalAmount,
        })
        .from(shopOrders)
        .where(and(
          eq(shopOrders.tenantId, req.tenant!.id),
          isNotNull(shopOrders.stripePaymentIntentId)
        ));

      const orderMap = new Map();
      for (const o of orders) {
        if (o.paymentIntentId) orderMap.set(o.paymentIntentId, o);
      }

      // Classify each checkout session
      const payments = result.sessions
        .filter(s => s.status === 'complete' && s.payment_status === 'paid')
        .map(session => {
          const meta = session.metadata || {};
          const paymentIntentId = typeof session.payment_intent === 'string'
            ? session.payment_intent
            : (session.payment_intent as any)?.id || null;

          let paymentType = 'donation';
          let details = '';
          let quantity = null;

          if (meta.eventTicketId || meta.eventName) {
            paymentType = 'event_ticket';
            const qty = parseInt(meta.quantity || '1', 10);
            quantity = qty;
            details = meta.eventName || 'Event Ticket';
          } else if (paymentIntentId && adoptionMap.has(paymentIntentId)) {
            paymentType = 'adoption_fee';
            const adoption = adoptionMap.get(paymentIntentId);
            details = adoption.animalName ? `Adoption: ${adoption.animalName}` : 'Adoption Fee';
          } else if (paymentIntentId && formMap.has(paymentIntentId)) {
            paymentType = 'form_fee';
            const form = formMap.get(paymentIntentId);
            details = form.formName || 'Form Payment';
          } else if (paymentIntentId && orderMap.has(paymentIntentId)) {
            paymentType = 'shop_order';
            const order = orderMap.get(paymentIntentId);
            details = `Order #${order.orderNumber}`;
          } else if (meta.sponsoredAnimalName) {
            details = `Sponsored: ${meta.sponsoredAnimalName}`;
          }

          const donorCoveredFees = meta.donorCoveredFees === 'true' || meta.donorCoversFees === 'true';
          const baseAmount = meta.baseAmount ? parseInt(meta.baseAmount, 10) : null;
          const feesCovered = meta.feesCovered ? parseInt(meta.feesCovered, 10) : null;

          return {
            id: session.id,
            paymentIntentId,
            paymentType,
            amount: session.amount_total || 0,
            baseAmount,
            feesCovered,
            currency: session.currency || 'usd',
            customerName: session.customer_details?.name || 'Anonymous',
            customerEmail: session.customer_details?.email || session.customer_email || '',
            details,
            quantity,
            donorCoveredFees,
            created: new Date(session.created * 1000).toISOString(),
          };
        });

      payments.sort((a, b) => new Date(b.created).getTime() - new Date(a.created).getTime());

      res.json({ configured: true, payments });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/event-ticket-sales
   * Get event ticket purchase data from Stripe checkout sessions
   * Filtered to event_ticket type only, with optional event name and date range filters
   * Designed for real-time monitoring at live events from mobile devices
   */
  app.get('/api/event-ticket-sales', requireTenant, requireAuth, requireRoleOrPageAccess('event-ticket-sales', 'admin', 'board_member', 'staff', 'owner'), async (req, res, next) => {
    try {
      const { stripeService } = await import('./lib/stripe-service');
      const { eventTickets: eventTicketsTable } = await import('@shared/schema');

      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, req.tenant!.id))
        .limit(1);

      if (!tenant) {
        return res.status(404).json({ error: 'Tenant not found' });
      }

      const hasStripe = tenant.stripeConnectedAccountId || (tenant.stripeEnabled && tenant.stripeSecretKeyEncrypted);
      if (!hasStripe) {
        return res.json({ configured: false, sales: [], summary: { totalRevenue: 0, totalTickets: 0, eventBreakdown: [] } });
      }

      const result = await stripeService.getCheckoutSessions(tenant, 100);
      if (!result.sessions) {
        return res.json({ configured: true, sales: [], summary: { totalRevenue: 0, totalTickets: 0, eventBreakdown: [] }, error: result.error });
      }

      const eventFilter = req.query.eventName as string | undefined;
      const dateFrom = req.query.dateFrom ? new Date(req.query.dateFrom as string) : null;
      const dateTo = req.query.dateTo ? new Date(req.query.dateTo as string) : null;

      const sales = result.sessions
        .filter(s => s.status === 'complete' && s.payment_status === 'paid')
        .map(session => {
          const meta = session.metadata || {};
          if (!meta.eventTicketId && !meta.eventName) return null;

          const qty = parseInt(meta.quantity || '1', 10);
          const eventName = meta.eventName || 'Unknown Event';
          const created = new Date(session.created * 1000);

          return {
            id: session.id,
            eventName,
            eventTicketId: meta.eventTicketId || null,
            customerName: session.customer_details?.name || 'Anonymous',
            customerEmail: session.customer_details?.email || session.customer_email || '',
            quantity: qty,
            amount: session.amount_total || 0,
            baseAmount: meta.baseAmount ? parseInt(meta.baseAmount, 10) : null,
            donorCoveredFees: meta.donorCoveredFees === 'true' || meta.donorCoversFees === 'true',
            currency: session.currency || 'usd',
            created: created.toISOString(),
          };
        })
        .filter((sale): sale is NonNullable<typeof sale> => {
          if (!sale) return false;
          if (eventFilter && sale.eventName.toLowerCase() !== eventFilter.toLowerCase()) return false;
          if (dateFrom && new Date(sale.created) < dateFrom) return false;
          if (dateTo) {
            const endOfDay = new Date(dateTo);
            endOfDay.setHours(23, 59, 59, 999);
            if (new Date(sale.created) > endOfDay) return false;
          }
          return true;
        });

      sales.sort((a, b) => new Date(b.created).getTime() - new Date(a.created).getTime());

      const eventBreakdownMap = new Map<string, { eventName: string; totalRevenue: number; totalTickets: number; purchaseCount: number }>();
      let totalRevenue = 0;
      let totalTickets = 0;

      for (const sale of sales) {
        totalRevenue += sale.amount;
        totalTickets += sale.quantity;
        const existing = eventBreakdownMap.get(sale.eventName);
        if (existing) {
          existing.totalRevenue += sale.amount;
          existing.totalTickets += sale.quantity;
          existing.purchaseCount += 1;
        } else {
          eventBreakdownMap.set(sale.eventName, {
            eventName: sale.eventName,
            totalRevenue: sale.amount,
            totalTickets: sale.quantity,
            purchaseCount: 1,
          });
        }
      }

      const summary = {
        totalRevenue,
        totalTickets,
        eventBreakdown: Array.from(eventBreakdownMap.values()),
      };

      const { fundraiserOrders, fundraiserEvents } = await import('@shared/schema');
      const fundraiserPaidOrders = await db
        .select({
          orderId: fundraiserOrders.id,
          customerName: fundraiserOrders.customerName,
          customerEmail: fundraiserOrders.customerEmail,
          quantity: fundraiserOrders.quantity,
          stripeSessionId: fundraiserOrders.stripeSessionId,
          createdAt: fundraiserOrders.createdAt,
          eventTitle: fundraiserEvents.title,
          eventId: fundraiserEvents.id,
          priceCents: fundraiserEvents.priceCents,
          passFeesToBuyer: fundraiserEvents.passFeesToBuyer,
        })
        .from(fundraiserOrders)
        .innerJoin(fundraiserEvents, eq(fundraiserOrders.eventId, fundraiserEvents.id))
        .where(and(
          eq(fundraiserEvents.tenantId, req.tenant!.id),
          eq(fundraiserOrders.paymentStatus, 'paid')
        ))
        .orderBy(desc(fundraiserOrders.createdAt));

      for (const fo of fundraiserPaidOrders) {
        const created = new Date(fo.createdAt!);
        if (dateFrom && created < dateFrom) continue;
        if (dateTo) {
          const endOfDay = new Date(dateTo);
          endOfDay.setHours(23, 59, 59, 999);
          if (created > endOfDay) continue;
        }
        if (eventFilter && fo.eventTitle.toLowerCase() !== eventFilter.toLowerCase()) continue;

        const amount = fo.priceCents * fo.quantity;
        const sale = {
          id: fo.orderId,
          eventName: fo.eventTitle,
          eventTicketId: null,
          customerName: fo.customerName,
          customerEmail: fo.customerEmail,
          quantity: fo.quantity,
          amount,
          baseAmount: amount,
          donorCoveredFees: !!fo.passFeesToBuyer,
          currency: 'usd',
          created: created.toISOString(),
        };

        sales.push(sale);

        totalRevenue += sale.amount;
        totalTickets += sale.quantity;
        const existing = eventBreakdownMap.get(sale.eventName);
        if (existing) {
          existing.totalRevenue += sale.amount;
          existing.totalTickets += sale.quantity;
          existing.purchaseCount += 1;
        } else {
          eventBreakdownMap.set(sale.eventName, {
            eventName: sale.eventName,
            totalRevenue: sale.amount,
            totalTickets: sale.quantity,
            purchaseCount: 1,
          });
        }
      }

      summary.totalRevenue = totalRevenue;
      summary.totalTickets = totalTickets;
      summary.eventBreakdown = Array.from(eventBreakdownMap.values());

      sales.sort((a, b) => new Date(b.created).getTime() - new Date(a.created).getTime());

      const allEvents = await db
        .select({ id: eventTicketsTable.id, eventName: eventTicketsTable.eventName, isActive: eventTicketsTable.isActive })
        .from(eventTicketsTable)
        .where(eq(eventTicketsTable.tenantId, req.tenant!.id))
        .orderBy(eventTicketsTable.eventName);

      const fundraiserEventsList = await db
        .select({ id: fundraiserEvents.id, title: fundraiserEvents.title, isActive: fundraiserEvents.isActive })
        .from(fundraiserEvents)
        .where(eq(fundraiserEvents.tenantId, req.tenant!.id))
        .orderBy(fundraiserEvents.title);

      const allEventsWithFundraisers = [
        ...allEvents,
        ...fundraiserEventsList.map(fe => ({ id: fe.id, eventName: fe.title, isActive: fe.isActive })),
      ];

      res.json({ configured: true, sales, summary, events: allEventsWithFundraisers });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/stripe/create-checkout-session
   * Create a Stripe checkout session for donations
   */
  app.post('/api/stripe/create-checkout-session', requireTenant, async (req, res, next) => {
    try {
      const { stripeService } = await import('./lib/stripe-service');

      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, req.tenant!.id))
        .limit(1);

      if (!tenant || !tenant.stripeEnabled) {
        return res.status(400).json({ 
          error: "Stripe is not configured for this rescue" 
        });
      }

      const { calculateDonorCoversFees } = await import('./config/platform');
      
      const checkoutSchema = z.object({
        amount: z.number().int().min(100),
        currency: z.string().default("usd"),
        customerEmail: z.string().email().optional(),
        isRecurring: z.boolean().default(false),
        interval: z.enum(["month", "year"]).optional(),
        donorCoversFees: z.boolean().default(false),
        metadata: z.record(z.string()).optional(),
      });

      const data = checkoutSchema.parse(req.body);

      const { calculatePlatformFee, getPlatformFeePercent } = await import('./config/platform');

      // If donor covers fees, calculate the grossed-up amount
      let chargeAmount = data.amount;
      let feesCovered = 0;
      if (data.donorCoversFees) {
        const feeCalc = calculateDonorCoversFees(data.amount, tenant.subscriptionTier || 'free', tenant.platformFeePercent);
        chargeAmount = feeCalc.totalAmount;
        feesCovered = feeCalc.feesCovered;
      }

      // Calculate platform fee on the charge amount
      const platformFeeAmount = calculatePlatformFee(chargeAmount, tenant.subscriptionTier || 'free', tenant.platformFeePercent);
      const platformFeePercent = getPlatformFeePercent(tenant.subscriptionTier || 'free', tenant.platformFeePercent);

      const host = req.get('host') || '';
      const baseUrl = `${req.protocol}://${host}`;
      const hasCustomDomain = (tenant as any).customDomain && host.includes((tenant as any).customDomain);
      const tenantPath = hasCustomDomain ? '' : (tenant.subdomain ? `/${tenant.subdomain}` : '');
      
      const session = await stripeService.createCheckoutSession(tenant, {
        amount: chargeAmount,
        currency: data.currency,
        customerEmail: data.customerEmail,
        isRecurring: data.isRecurring,
        interval: data.interval,
        // 'donation' surface enables ACH on one-time gifts >= $250 and on
        // monthly subs >= $50 (per shared/ach-eligibility.ts). Below those
        // thresholds the donor only sees card.
        surface: 'donation',
        successUrl: `${baseUrl}${tenantPath}/?donation=success&session_id={CHECKOUT_SESSION_ID}`,
        cancelUrl: `${baseUrl}${tenantPath}/donate`,
        platformFeeAmount: platformFeeAmount,
        connectedAccountId: tenant.stripeConnectedAccountId || undefined,
        metadata: {
          ...data.metadata,
          baseAmount: data.amount.toString(),
          chargeAmount: chargeAmount.toString(),
          donorCoveredFees: data.donorCoversFees.toString(),
          feesCovered: feesCovered.toString(),
          platformFeeAmount: platformFeeAmount.toString(),
          platformFeePercent: platformFeePercent.toString(),
          // Fee is actually collected only when Connect is configured AND fee > 0
          platformFeeCollected: (tenant.stripeConnectedAccountId && platformFeeAmount > 0 ? 'true' : 'false'),
        },
      });

      if (!session) {
        return res.status(500).json({ 
          error: "Failed to create checkout session" 
        });
      }

      res.json({ sessionId: session.id, url: session.url });
    } catch (error: any) {
      console.error('[Stripe Checkout Error]', {
        message: error?.message,
        type: error?.type,
        code: error?.code,
        statusCode: error?.statusCode,
        tenantId: req.tenant?.id,
        stack: error?.stack?.split('\n').slice(0, 5).join('\n'),
      });
      
      // Return a more descriptive error to the client
      const errorMessage = error?.message || 'Failed to create checkout session';
      res.status(error?.statusCode || 500).json({ 
        error: errorMessage,
        code: error?.code,
      });
    }
  });

  /**
   * Refresh the cached card-on-file (brand/last4) for every subscription
   * row belonging to a Stripe customer. Bumps `cardUpdatedAt` only when the
   * displayed card details actually change, so the giving history view can
   * use that timestamp to surface a "Card on file updated" confirmation
   * banner without false positives on unrelated webhook traffic.
   */
  async function refreshSubscriptionCardsForCustomer(
    tenant: { id: string },
    stripeCustomerId: string,
    card: { brand: string | null; last4: string | null },
  ) {
    if (!card.brand && !card.last4) return;
    const { donors, subscriptions } = await import('@shared/schema');
    const [donor] = await db
      .select({ id: donors.id })
      .from(donors)
      .where(and(
        eq(donors.tenantId, tenant.id),
        eq(donors.stripeCustomerId, stripeCustomerId),
      ))
      .limit(1);
    if (!donor) return;

    const rows = await db
      .select({
        id: subscriptions.id,
        cardBrand: subscriptions.cardBrand,
        cardLast4: subscriptions.cardLast4,
      })
      .from(subscriptions)
      .where(and(
        eq(subscriptions.tenantId, tenant.id),
        eq(subscriptions.donorId, donor.id),
      ));

    for (const row of rows) {
      const changed = row.cardBrand !== card.brand || row.cardLast4 !== card.last4;
      await db
        .update(subscriptions)
        .set({
          cardBrand: card.brand,
          cardLast4: card.last4,
          ...(changed ? { cardUpdatedAt: new Date() } : {}),
        })
        .where(eq(subscriptions.id, row.id));
    }
  }

  /**
   * Refresh cached card details for a single subscription using the embedded
   * Stripe subscription object. If the subscription has a default_payment_method
   * we expand it via the Stripe API; otherwise we fall back to the customer's
   * invoice-default payment method.
   */
  async function refreshSubscriptionCardForStripeSub(
    tenant: any,
    stripeSubscription: any,
  ) {
    const { stripeService } = await import('./lib/stripe-service');
    const stripeClient = stripeService.getStripeClient(tenant);
    if (!stripeClient) return;

    let pmId: string | null = null;
    if (typeof stripeSubscription.default_payment_method === 'string') {
      pmId = stripeSubscription.default_payment_method;
    } else if (stripeSubscription.default_payment_method?.id) {
      pmId = stripeSubscription.default_payment_method.id;
    }

    if (!pmId && stripeSubscription.customer) {
      const customerId = typeof stripeSubscription.customer === 'string'
        ? stripeSubscription.customer
        : stripeSubscription.customer?.id;
      if (customerId) {
        const customer = await stripeClient.customers.retrieve(customerId);
        if (customer && !customer.deleted) {
          const invoiceDefault = (customer as any).invoice_settings?.default_payment_method;
          if (typeof invoiceDefault === 'string') pmId = invoiceDefault;
          else if (invoiceDefault?.id) pmId = invoiceDefault.id;
        }
      }
    }

    if (!pmId) return;
    const pm = await stripeClient.paymentMethods.retrieve(pmId);
    if (!pm?.card) return;

    const customerId = typeof stripeSubscription.customer === 'string'
      ? stripeSubscription.customer
      : stripeSubscription.customer?.id;
    if (!customerId) return;

    await refreshSubscriptionCardsForCustomer(tenant, customerId, {
      brand: pm.card.brand || null,
      last4: pm.card.last4 || null,
    });
  }

  /**
   * POST /api/stripe/webhook
   * Handle Stripe webhook events for automatic donation tracking
   */
  app.post('/api/stripe/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
    try {
      const signature = req.headers['stripe-signature'];
      if (!signature || typeof signature !== 'string') {
        return res.status(400).send('Missing stripe-signature header');
      }

      const { decrypt } = await import('./lib/encryption');
      const { donors, payments, subscriptions, donations } = await import('@shared/schema');
      const { stripeService } = await import('./lib/stripe-service');
      
      console.log('[STRIPE-WEBHOOK] Received webhook event');

      const rawBody = (req as any).rawBody;
      if (!rawBody || !Buffer.isBuffer(rawBody)) {
        console.error('[STRIPE-WEBHOOK] ERROR: rawBody not available or not a Buffer');
        return res.status(400).send('Webhook raw body not available');
      }
      const bodyStr = rawBody.toString('utf8');
      const payload = JSON.parse(bodyStr);
      console.log(`[STRIPE-WEBHOOK] Event type: ${payload.type}, event ID: ${payload.id}`);
      
      let metadata = payload.data?.object?.metadata || {};
      let tenantId = metadata.tenantId;
      console.log(`[STRIPE-WEBHOOK] Metadata tenantId: ${tenantId || 'not found in metadata'}`);

      if (!tenantId && payload.data?.object?.subscription) {
        const subscriptionId = payload.data.object.subscription;
        const { subscriptions } = await import('@shared/schema');
        const subscription = await db
          .select()
          .from(subscriptions)
          .where(eq(subscriptions.stripeSubscriptionId, subscriptionId))
          .limit(1)
          .then(rows => rows[0]);
        if (subscription) {
          tenantId = subscription.tenantId;
          console.log(`[STRIPE-WEBHOOK] Resolved tenantId from subscription: ${tenantId}`);
        }
      }

      if (!tenantId && payload.account) {
        console.log(`[STRIPE-WEBHOOK] Attempting tenant resolution from Connect account: ${payload.account}`);
        const connectTenant = await db
          .select({ id: tenants.id, name: tenants.name })
          .from(tenants)
          .where(eq(tenants.stripeConnectedAccountId, payload.account))
          .limit(1)
          .then(rows => rows[0]);
        if (connectTenant) {
          tenantId = connectTenant.id;
          console.log(`[STRIPE-WEBHOOK] Resolved tenantId from Connect account ${payload.account}: ${tenantId} (${connectTenant.name})`);
        }
      }

      if (!tenantId) {
        console.warn(`[STRIPE-WEBHOOK] Ignoring event ${payload.type} (${payload.id}) - no tenantId resolved from metadata, subscription, or Connect account`);
        return res.status(200).json({ received: true, skipped: true, reason: 'no_tenant' });
      }
      
      console.log(`[STRIPE-WEBHOOK] Resolved tenantId: ${tenantId}`);

      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, tenantId))
        .limit(1);

      if (!tenant || !tenant.stripeEnabled) {
        console.error('[STRIPE-WEBHOOK] ERROR: Tenant not found or Stripe not enabled:', tenantId);
        console.error(`[STRIPE-WEBHOOK]   tenant found: ${!!tenant}, stripeEnabled: ${tenant?.stripeEnabled}`);
        return res.status(400).send('Webhook not configured for this tenant');
      }

      const secretsToTry: { secret: string; label: string }[] = [];
      if (tenant.stripeWebhookSecretEncrypted) {
        secretsToTry.push({ secret: decrypt(tenant.stripeWebhookSecretEncrypted), label: `tenant-specific (${tenant.name})` });
      }
      if (process.env.PLATFORM_STRIPE_WEBHOOK_SECRET) {
        secretsToTry.push({ secret: process.env.PLATFORM_STRIPE_WEBHOOK_SECRET, label: 'PLATFORM_STRIPE_WEBHOOK_SECRET (Connected accounts)' });
      }
      if (process.env.STRIPE_WEBHOOK_SECRET_PLATFORM) {
        secretsToTry.push({ secret: process.env.STRIPE_WEBHOOK_SECRET_PLATFORM, label: 'STRIPE_WEBHOOK_SECRET_PLATFORM (Your account)' });
      }
      if (process.env.STRIPE_WEBHOOK_SECRET) {
        secretsToTry.push({ secret: process.env.STRIPE_WEBHOOK_SECRET, label: 'STRIPE_WEBHOOK_SECRET (legacy)' });
      }

      if (secretsToTry.length === 0) {
        console.error(`[STRIPE-WEBHOOK] ERROR: No webhook secrets available for tenant ${tenant.name}`);
        return res.status(400).send('Webhook not configured for this tenant');
      }

      console.log(`[STRIPE-WEBHOOK] Tenant ${tenant.name} (${tenant.subdomain}) has Stripe configured, ${secretsToTry.length} secret(s) to try`);

      let event;
      let verified = false;
      for (const { secret, label } of secretsToTry) {
        try {
          event = await stripeService.handleWebhook(rawBody, signature, secret);
          console.log(`[STRIPE-WEBHOOK] Event verified successfully with ${label}: ${event.type}`);
          verified = true;
          break;
        } catch (err: any) {
          console.log(`[STRIPE-WEBHOOK] Verification failed with ${label}: ${err.message}`);
        }
      }

      if (!verified || !event) {
        console.error(`[STRIPE-WEBHOOK] ERROR: Failed to verify webhook signature with any of ${secretsToTry.length} secrets`);
        return res.status(400).send('Webhook signature verification failed');
      }

      switch (event.type) {
        case 'checkout.session.completed': {
          console.log('[STRIPE-WEBHOOK] Processing checkout.session.completed event');
          const session = event.data.object as any;

          // P2P Campaign donation fulfillment — early exit to avoid donation processing.
          //
          // For card payments, `checkout.session.completed` fires with
          // `payment_status === 'paid'` and we credit the campaign immediately.
          // For ACH, payment_status='unpaid' here; campaign credit happens in
          // async_payment_succeeded once the bank actually clears (~4 days).
          if (session.metadata?.peerCampaignId) {
            console.log('[STRIPE-WEBHOOK] P2P campaign donation received:', session.metadata.peerDonationId, 'payment_status:', session.payment_status);
            try {
              const { peerCampaignDonations, peerCampaigns } = await import('@shared/schema');

              if (session.payment_status !== 'paid') {
                // ACH still processing — leave the donation row at 'pending'
                // (or mark it 'processing' so staff can distinguish a stuck
                // checkout from a real-but-not-yet-cleared ACH transfer).
                await db
                  .update(peerCampaignDonations)
                  .set({ paymentStatus: 'processing' })
                  .where(and(
                    eq(peerCampaignDonations.stripeSessionId, session.id),
                    eq(peerCampaignDonations.paymentStatus, 'pending')
                  ));
                console.log('[STRIPE-WEBHOOK] P2P ACH donation pending bank clearance — campaign progress NOT incremented yet');
                break;
              }

              const [updated] = await db
                .update(peerCampaignDonations)
                .set({ paymentStatus: 'paid' })
                .where(and(
                  eq(peerCampaignDonations.stripeSessionId, session.id),
                  inArray(peerCampaignDonations.paymentStatus, ['pending', 'processing'])
                ))
                .returning({ id: peerCampaignDonations.id });

              if (!updated) {
                console.log('[STRIPE-WEBHOOK] P2P donation already processed (idempotency), skipping');
                break;
              }

              const amountPaid = session.metadata.baseAmount ? parseInt(session.metadata.baseAmount) : (session.amount_total || 0);
              await db
                .update(peerCampaigns)
                .set({ amountRaised: sql`${peerCampaigns.amountRaised} + ${amountPaid}` })
                .where(eq(peerCampaigns.id, session.metadata.peerCampaignId));

              console.log('[STRIPE-WEBHOOK] P2P campaign donation marked paid, amount:', amountPaid);
            } catch (err) {
              console.error('[STRIPE-WEBHOOK] Failed to process P2P campaign donation:', err);
            }
            break;
          }

                    // Voting Contest vote fulfillment — early exit
          if (session.metadata?.type === 'voting_contest' && session.metadata?.votingContestEntrantId) {
            console.log('[STRIPE-WEBHOOK] Voting contest vote received for entrant:', session.metadata.votingContestEntrantId);
            try {
              const { votingContestEntrants } = await import('@shared/schema');

              // Idempotency: check if this session was already processed
              if (session.payment_intent) {
                const existingPayment = await db
                  .select({ id: payments.id })
                  .from(payments)
                  .where(eq(payments.stripePaymentIntentId, session.payment_intent))
                  .limit(1)
                  .then(rows => rows[0]);
                if (existingPayment) {
                  console.log('[STRIPE-WEBHOOK] Voting contest payment already processed (idempotency), skipping');
                  break;
                }
              }

              const newVotes = Math.floor((session.amount_total || 0) / 100);
              if (newVotes > 0) {
                // Validate entrant belongs to the correct tenant and contest
                const [entrant] = await db
                  .select()
                  .from(votingContestEntrants)
                  .where(and(
                    eq(votingContestEntrants.id, session.metadata.votingContestEntrantId),
                    eq(votingContestEntrants.tenantId, tenant.id)
                  ))
                  .limit(1);

                if (!entrant) {
                  console.error('[STRIPE-WEBHOOK] Voting entrant not found or tenant mismatch');
                  break;
                }

                // Defense in depth: voting checkout is configured card-only
                // upstream, so this should always be 'paid'. But if some Stripe
                // configuration drift ever lets an ACH session through, we
                // refuse to credit votes until the payment actually clears.
                if (session.payment_status !== 'paid') {
                  console.warn('[STRIPE-WEBHOOK] Voting session payment_status is', session.payment_status, '- skipping vote credit until cleared');
                  break;
                }

                await db
                  .update(votingContestEntrants)
                  .set({ totalVotes: sql`${votingContestEntrants.totalVotes} + ${newVotes}` })
                  .where(eq(votingContestEntrants.id, entrant.id));

                // Record payment for idempotency
                const customerEmail = session.customer_email || session.customer_details?.email;
                if (session.payment_intent && customerEmail) {
                  let donor = await db
                    .select()
                    .from(donors)
                    .where(and(eq(donors.tenantId, tenant.id), eq(donors.email, customerEmail)))
                    .limit(1)
                    .then(rows => rows[0]);
                  if (!donor) {
                    [donor] = await db.insert(donors).values({
                      tenantId: tenant.id,
                      email: customerEmail,
                      name: session.customer_details?.name || 'Contest Voter',
                      totalDonated: session.amount_total || 0,
                      lastDonationDate: new Date(),
                    }).returning();
                  } else {
                    [donor] = await db.update(donors).set({
                      totalDonated: (donor.totalDonated || 0) + (session.amount_total || 0),
                      lastDonationDate: new Date(),
                    }).where(eq(donors.id, donor.id)).returning();
                  }
                  await db.insert(payments).values({
                    tenantId: tenant.id,
                    donorId: donor.id,
                    stripePaymentIntentId: session.payment_intent,
                    stripeCheckoutSessionId: session.id,
                    amount: session.amount_total || 0,
                    currency: session.currency || 'usd',
                    status: 'succeeded',
                    paymentMethod: 'stripe',
                    isRecurring: false,
                    description: `${newVotes} vote(s) for ${entrant.name}`,
                  });
                }

                console.log('[STRIPE-WEBHOOK] Added', newVotes, 'votes to entrant', entrant.id);
              }
            } catch (err) {
              console.error('[STRIPE-WEBHOOK] Failed to process voting contest vote:', err);
            }
            break;
          }

          // Fundraiser order fulfillment — early exit to avoid donation processing
          if (session.metadata?.fundraiser_event_id) {
            console.log('[STRIPE-WEBHOOK] Fundraiser order payment received:', session.metadata.fundraiser_order_id, 'payment_status:', session.payment_status);
            try {
              const { fundraiserOrders, fundraiserEvents } = await import('@shared/schema');
              // Defense in depth: ticket checkout is configured card-only, but
              // refuse to mark an order paid until the payment actually clears.
              if (session.payment_status !== 'paid') {
                console.warn('[STRIPE-WEBHOOK] Fundraiser order payment_status is', session.payment_status, '- leaving order pending until cleared');
                break;
              }
              const [updated] = await db
                .update(fundraiserOrders)
                .set({ paymentStatus: 'paid' })
                .where(and(
                  eq(fundraiserOrders.stripeSessionId, session.id),
                  eq(fundraiserOrders.paymentStatus, 'pending')
                ))
                .returning();

              if (!updated) {
                console.log('[STRIPE-WEBHOOK] Fundraiser order already processed or not found for session:', session.id);
                break;
              }

              console.log('[STRIPE-WEBHOOK] Fundraiser order marked paid:', updated.id, 'qty:', updated.quantity);

              // Send confirmation email to buyer
              try {
                const [event] = await db.select({ title: fundraiserEvents.title })
                  .from(fundraiserEvents)
                  .where(eq(fundraiserEvents.id, updated.eventId))
                  .limit(1);

                const { EmailService } = await import('./lib/email-service');
                const emailService = await EmailService.forTenant(tenantId);
                if (emailService && updated.customerEmail) {
                  const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
                  const amountPaid = session.amount_total ? (session.amount_total / 100).toFixed(2) : 'N/A';
                  const safeName = esc(updated.customerName || 'Valued Customer');
                  const safeTitle = esc(event?.title || 'Fundraiser Event');
                  const safeTenant = esc(tenant.name);
                  const safePickup = updated.pickupTime ? esc(updated.pickupTime) : '';
                  await emailService.send({
                    to: updated.customerEmail,
                    subject: `Order Confirmation - ${safeTitle} (${updated.quantity} ticket${updated.quantity > 1 ? 's' : ''})`,
                    html: `
                      <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                        <h2 style="color: #1a1a1a;">Thank you for your purchase, ${safeName}!</h2>
                        <p>Your order has been confirmed.</p>
                        <div style="background: #f9fafb; border-radius: 8px; padding: 16px; margin: 16px 0;">
                          <p style="margin: 4px 0;"><strong>Event:</strong> ${safeTitle}</p>
                          <p style="margin: 4px 0;"><strong>Quantity:</strong> ${updated.quantity}</p>
                          <p style="margin: 4px 0;"><strong>Amount Paid:</strong> $${amountPaid}</p>
                          ${safePickup ? `<p style="margin: 4px 0;"><strong>Pickup Time:</strong> ${safePickup}</p>` : ''}
                        </div>
                        <p style="color: #6b7280; font-size: 14px;">If you have any questions, please contact us directly.</p>
                        <p style="color: #6b7280; font-size: 14px;">— ${safeTenant}</p>
                      </div>
                    `,
                  });
                  console.log('[STRIPE-WEBHOOK] Sent fundraiser order confirmation email to:', updated.customerEmail);
                }
              } catch (emailErr) {
                console.error('[STRIPE-WEBHOOK] Failed to send fundraiser order confirmation email:', emailErr);
              }
            } catch (err) {
              console.error('[STRIPE-WEBHOOK] Failed to mark fundraiser order paid:', err);
            }
            break;
          }

          const customerEmail = session.customer_email || session.customer_details?.email;
          const customerName = session.customer_details?.name || 'Anonymous Donor';
          const billingAddr = session.customer_details?.address;

          console.log(`[STRIPE-WEBHOOK] session=${session.id} intent=${session.payment_intent} amount=${session.amount_total} customer=${customerEmail || 'none'}`);

          if (!customerEmail) {
            console.error('[STRIPE-WEBHOOK] No customer email — skipping donation processing');
            break;
          }

          // Idempotency check: Skip if this checkout session was already processed.
          // For subscription-mode checkouts, Stripe does NOT set session.payment_intent
          // (a Subscription + Invoice are created instead), so we must also key off
          // session.id via payments.stripeCheckoutSessionId — otherwise Stripe webhook
          // retries (1h/2h/2h backoff) will create duplicate donation rows for the same sign-up.
          {
            const idempotencyConditions = [eq(payments.stripeCheckoutSessionId, session.id)];
            if (session.payment_intent) {
              idempotencyConditions.push(eq(payments.stripePaymentIntentId, session.payment_intent));
            }
            const existingPayment = await db
              .select({ id: payments.id })
              .from(payments)
              .where(or(...idempotencyConditions))
              .limit(1)
              .then(rows => rows[0]);

            if (existingPayment) {
              console.log(`[Webhook] Checkout session ${session.id} (intent=${session.payment_intent || 'n/a'}) already processed, skipping (idempotency)`);
              return res.status(200).json({ received: true, idempotent: true });
            }
          }

          // For ACH payments, payment_status may be 'unpaid' until bank transfer completes
          // We still create the donor and payment record, but mark status appropriately
          const isPaymentComplete = session.payment_status === 'paid';
          const paymentStatus = isPaymentComplete ? 'succeeded' : 'pending';

          let donor = await db
            .select()
            .from(donors)
            .where(
              and(
                eq(donors.tenantId, tenant.id),
                eq(donors.email, customerEmail)
              )
            )
            .limit(1)
            .then(rows => rows[0]);

          if (!donor) {
            [donor] = await db.insert(donors).values({
              tenantId: tenant.id,
              email: customerEmail,
              name: customerName,
              stripeCustomerId: session.customer,
              totalDonated: isPaymentComplete ? (session.amount_total || 0) : 0,
              lastDonationDate: isPaymentComplete ? new Date() : null,
            }).returning();
            console.log(`[STRIPE-WEBHOOK] Created new donor ${donor.id} for ${customerEmail}`);
          } else if (isPaymentComplete) {
            [donor] = await db
              .update(donors)
              .set({
                totalDonated: (donor.totalDonated || 0) + (session.amount_total || 0),
                lastDonationDate: new Date(),
                stripeCustomerId: session.customer || donor.stripeCustomerId,
              })
              .where(eq(donors.id, donor.id))
              .returning();
            console.log(`[STRIPE-WEBHOOK] Updated existing donor ${donor.id} for ${customerEmail}`);
          }

          const [paymentRecord] = await db.insert(payments).values({
            tenantId: tenant.id,
            donorId: donor.id,
            stripePaymentIntentId: session.payment_intent,
            stripeCheckoutSessionId: session.id,
            amount: session.amount_total || 0,
            currency: session.currency || 'usd',
            status: paymentStatus,
            paymentMethod: 'stripe',
            isRecurring: session.mode === 'subscription',
            message: session.metadata?.message,
          }).returning();
          
          console.log(`[STRIPE-WEBHOOK] Created payment record ${paymentRecord.id} for intent ${session.payment_intent}, amount: ${session.amount_total}, status: ${paymentStatus}`);
          
          // Classify payment type from metadata and DB cross-references
          const sessionMetadata = session.metadata || {};
          const isEventTicket = !!(sessionMetadata.eventTicketId || sessionMetadata.eventName);
          let isDonation = true;
          let paymentTypeLabel = 'Donation';

          console.log(`[STRIPE-WEBHOOK] Ticket detection for tenant "${tenant.name}": isEventTicket=${isEventTicket}, eventTicketId=${sessionMetadata.eventTicketId || 'none'}, eventName=${sessionMetadata.eventName || 'none'}, isPaymentComplete=${isPaymentComplete}, metadata keys: ${Object.keys(sessionMetadata).join(', ')}`);

          if (isEventTicket) {
            isDonation = false;
            paymentTypeLabel = `Event Ticket: ${sessionMetadata.eventName || 'Unknown Event'} (${sessionMetadata.quantity || '1'} ticket(s))`;
          } else if (session.payment_intent) {
            const { adoptionCheckoutSessions, shopOrders } = await import('@shared/schema');
            const [adoptionMatch] = await db.select({ id: adoptionCheckoutSessions.id }).from(adoptionCheckoutSessions).where(eq(adoptionCheckoutSessions.paymentIntentId, session.payment_intent)).limit(1);
            if (adoptionMatch) {
              isDonation = false;
              paymentTypeLabel = 'Adoption Fee';
            } else {
              const [shopMatch] = await db.select({ id: shopOrders.id }).from(shopOrders).where(eq(shopOrders.stripePaymentIntentId, session.payment_intent)).limit(1);
              if (shopMatch) {
                isDonation = false;
                paymentTypeLabel = 'Shop Order';
              }
            }
          }
          console.log(`[STRIPE-WEBHOOK] Payment classified as: ${paymentTypeLabel}`);

          // Create donation record only for actual donations
          if (isPaymentComplete && isDonation) {
            const feeNote = sessionMetadata.donorCoveredFees === 'true' && sessionMetadata.feesCovered
              ? ` (donor covered $${(parseInt(sessionMetadata.feesCovered, 10) / 100).toFixed(2)} in processing fees)`
              : '';
            const donationDescription = sessionMetadata.sponsoredAnimalName
              ? `Sponsored: ${sessionMetadata.sponsoredAnimalName}${feeNote}`
              : feeNote || null;

            const donorCoveredFees = sessionMetadata.donorCoveredFees === 'true' || sessionMetadata.donorCoversFees === 'true';
            const baseAmountCents = sessionMetadata.baseAmount ? parseInt(sessionMetadata.baseAmount, 10) : (session.amount_total || 0);
            const grossAmountCents = donorCoveredFees ? (session.amount_total || 0) : baseAmountCents;
            const netAmountCents = baseAmountCents;

            const [donationRecord] = await db.insert(donations).values({
              tenantId: tenant.id,
              donorId: donor.id,
              donorName: customerName,
              donorEmail: customerEmail,
              donorAddress: billingAddr?.line1 || null,
              donorCity: billingAddr?.city || null,
              donorState: billingAddr?.state || null,
              donorZip: billingAddr?.postal_code || null,
              donorCountry: billingAddr?.country || null,
              amount: baseAmountCents,
              source: 'stripe' as any,
              date: new Date(),
              message: session.metadata?.message || null,
              isRecurring: session.mode === 'subscription',
              recurringFrequency: session.mode === 'subscription' ? 'monthly' : null,
              recurringStatus: session.mode === 'subscription' ? 'active' : null,
              donationType: 'online',
              paymentMethod: 'stripe',
              isPublic: true,
              description: donationDescription,
              feesCovered: donorCoveredFees,
              grossAmount: grossAmountCents,
              netAmount: netAmountCents,
            }).returning();
            
            console.log(`[STRIPE-WEBHOOK] Created donation record ${donationRecord.id} for Finance page, donor: ${customerName} (${donor.id}), amount: $${session.amount_total / 100}${feeNote}`);

            if (tenant.autoSendTaxReceipts && donationRecord.donorEmail) {
              try {
                const { generateAndEmailReceipt } = await import('./services/donation-receipt-service');
                const receiptResult = await generateAndEmailReceipt({
                  donationId: donationRecord.id,
                  tenantId: tenant.id,
                });
                if (receiptResult.success) {
                  console.log(`[STRIPE-WEBHOOK] Auto-sent tax receipt #${receiptResult.receiptNumber} to ${donationRecord.donorEmail}`);
                } else {
                  console.warn(`[STRIPE-WEBHOOK] Auto-send tax receipt failed for donation ${donationRecord.id}: ${receiptResult.message}`);
                }
              } catch (receiptErr) {
                console.error(`[STRIPE-WEBHOOK] Error auto-sending tax receipt for donation ${donationRecord.id}:`, receiptErr);
              }
            }
          } else if (isPaymentComplete && !isDonation) {
            console.log(`[STRIPE-WEBHOOK] Skipping donation record for non-donation payment: ${paymentTypeLabel}`);
          }
          
          // Create or update contact record
          if (isPaymentComplete) {
            try {
              const { createContactFromDonation } = await import('./services/contacts');
              if (customerEmail) { await createContactFromDonation(tenant.id, customerName, customerEmail, (session.amount_total || 0) / 100); }
              console.log(`[STRIPE-WEBHOOK] Created/updated contact for: ${customerEmail}`);
            } catch (contactError) {
              console.error('[STRIPE-WEBHOOK] Failed to create contact:', contactError);
            }
          }

          // Auto-record campaign contribution for emergency fund donations
          // Note: Duplicate webhook events are already handled by the payment-level
          // idempotency check above (returns early if stripePaymentIntentId already exists)
          if (isPaymentComplete && sessionMetadata.type === 'emergency_fund' && sessionMetadata.campaignId) {
            try {
              const { campaignContributions } = await import('@shared/schema');
              await db.insert(campaignContributions).values({
                tenantId: tenant.id,
                donationLinkId: sessionMetadata.campaignId,
                donorName: customerName,
                amount: session.amount_total || 0,
                message: sessionMetadata.message || null,
                isAnonymous: false,
              });
              console.log(`[STRIPE-WEBHOOK] Recorded campaign contribution for campaign ${sessionMetadata.campaignId}, amount: ${(session.amount_total || 0) / 100}`);
            } catch (contribError) {
              console.error('[STRIPE-WEBHOOK] Failed to record campaign contribution:', contribError);
            }
          }

          // Send appropriate email based on payment status
          try {
            const { EmailService } = await import('./lib/email-service');
            const emailService = await EmailService.forTenant(tenant.id);
            
            if (emailService && customerEmail) {
              const amountFormatted = new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: session.currency || 'usd'
              }).format((session.amount_total || 0) / 100);

              const isRecurring = session.mode === 'subscription';
              const dateFormatted = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
              
              // Escape user-provided content to prevent XSS
              const safeCustomerName = escapeHtml(customerName);
              const safeTenantName = escapeHtml(tenant.name);
              const safeMessage = escapeHtml(session.metadata?.message);
              const safeEin = escapeHtml(tenant.ein);
              const einSection = safeEin ? ` EIN: ${safeEin}` : '';
              const messageSection = safeMessage 
                ? `<p style="margin: 5px 0;"><strong>Your message:</strong> ${safeMessage}</p>` 
                : '';

              if (isPaymentComplete) {
                // Card payment - send immediate thank-you
                const donationType = isRecurring ? 'recurring donation' : 'donation';
                const recurringNote = isRecurring 
                  ? '<p>Your recurring donation will automatically process each month. You can manage your subscription at any time.</p>' 
                  : '';

                await emailService.send({
                  to: customerEmail,
                  subject: `Thank you for your ${donationType} to ${safeTenantName}!`,
                  html: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #2563eb;">Thank You, ${safeCustomerName}!</h2>
  
  <p>Your generous ${donationType} of <strong>${amountFormatted}</strong> to ${safeTenantName} has been received.</p>
  
  ${recurringNote}
  
  <div style="background: #f3f4f6; padding: 15px; border-radius: 8px; margin: 20px 0;">
    <p style="margin: 5px 0;"><strong>Amount:</strong> ${amountFormatted}</p>
    <p style="margin: 5px 0;"><strong>Date:</strong> ${dateFormatted}</p>
    ${messageSection}
  </div>
  
  <p>Your support makes a real difference in the lives of the animals we rescue and care for. Every dollar helps us provide food, shelter, medical care, and love to animals in need.</p>
  
  <p>With heartfelt gratitude,<br/>
  <strong>The ${safeTenantName} Team</strong></p>
  
  <hr style="border: none; border-top: 1px solid #e5e7eb; margin: 20px 0;" />
  
  <p style="font-size: 12px; color: #6b7280;">
    ${safeTenantName} is a registered 501(c)(3) nonprofit organization.${einSection}<br/>
    This email serves as your donation confirmation. An official tax receipt may be sent separately.
  </p>
</div>
                  `.trim()
                });
                console.log(`[Webhook] Thank-you email sent to ${customerEmail} for donation to ${tenant.name}`);
              } else {
                // ACH payment pending - send processing notice
                console.log(`[Webhook] ACH payment pending for ${customerEmail}, session ${session.id}`);
                await emailService.send({
                  to: customerEmail,
                  subject: `Your bank transfer to ${safeTenantName} is processing`,
                  html: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #2563eb;">Thank You, ${safeCustomerName}!</h2>
  
  <p>We've received your bank transfer donation request of <strong>${amountFormatted}</strong> to ${safeTenantName}.</p>
  
  <div style="background: #fef3c7; padding: 15px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #f59e0b;">
    <p style="margin: 0; color: #92400e;"><strong>Your bank transfer is processing</strong></p>
    <p style="margin: 5px 0 0 0; color: #92400e; font-size: 14px;">ACH bank transfers typically take 3-5 business days to complete. We'll send you a confirmation email once your donation has been received.</p>
  </div>
  
  <div style="background: #f3f4f6; padding: 15px; border-radius: 8px; margin: 20px 0;">
    <p style="margin: 5px 0;"><strong>Amount:</strong> ${amountFormatted}</p>
    <p style="margin: 5px 0;"><strong>Date Initiated:</strong> ${dateFormatted}</p>
    <p style="margin: 5px 0;"><strong>Payment Method:</strong> Bank Transfer (ACH)</p>
    ${messageSection}
  </div>
  
  <p>Thank you for choosing to support our mission. Your generosity makes a real difference!</p>
  
  <p>With gratitude,<br/>
  <strong>The ${safeTenantName} Team</strong></p>
  
  <hr style="border: none; border-top: 1px solid #e5e7eb; margin: 20px 0;" />
  
  <p style="font-size: 12px; color: #6b7280;">
    ${safeTenantName} is a registered 501(c)(3) nonprofit organization.${einSection}<br/>
    A tax receipt will be sent once your bank transfer has been processed.
  </p>
</div>
                  `.trim()
                });
                console.log(`[Webhook] ACH pending notice sent to ${customerEmail} for donation to ${tenant.name}`);
              }
            }
          } catch (emailError) {
            // Don't fail the webhook if email fails - log and continue
            console.error('[Webhook] Failed to send email:', emailError);
          }

          if (session.subscription) {
            const sessionMeta = session.metadata || {};
            let vipTierId: string | null = sessionMeta.vipTierId || null;
            let vipTierName: string | null = sessionMeta.vipTierName || null;
            const wallOptIn = sessionMeta.displayOnWallOfHeroes === 'true';
            // Accept the new `displayName` key first, then fall back to the
            // legacy `firstNameDisplay` for older sessions still in flight.
            const displayName =
              sessionMeta.displayName || sessionMeta.firstNameDisplay || null;

            // Determine the actual subscription interval from Stripe. We do
            // NOT trust user-supplied metadata (e.g. source=vip_club) — the
            // public checkout endpoint forwards arbitrary metadata so a
            // yearly sub could spoof itself as monthly. Instead we use
            // session.mode (Stripe-controlled, never user-set) as the trust
            // signal: when retrieval fails on a known subscription-mode
            // session, fall back to monthly tagging because every recurring
            // checkout endpoint in this app creates monthly prices today.
            // Yearly subs would only be misclassified if a future endpoint
            // begins creating year prices AND Stripe.retrieve happens to be
            // failing at the same moment.
            let actualInterval: 'month' | 'year' | null = null;
            let intervalFetchFailed = false;
            if (session.subscription && stripe) {
              try {
                const stripeSub = await stripe.subscriptions.retrieve(session.subscription as string);
                const interval = stripeSub.items?.data?.[0]?.price?.recurring?.interval;
                if (interval === 'month' || interval === 'year') {
                  actualInterval = interval;
                }
              } catch (subFetchErr) {
                intervalFetchFailed = true;
                console.warn('[Webhook] sub.retrieve failed; will fall back to monthly tagging if session.mode=subscription:', subFetchErr);
              }
            }
            const isSubscriptionMode = session.mode === 'subscription';
            // Treat as monthly when Stripe confirmed it, OR when retrieval
            // failed but Stripe itself flagged the session as subscription mode.
            const isMonthly = actualInterval === 'month'
              || (intervalFetchFailed && isSubscriptionMode);

            // Validate that any explicit vipTierId from metadata still exists
            // and belongs to this tenant. A stale id (e.g. tier deleted after
            // checkout was opened) would otherwise silently land as a NULL on
            // the snapshot via FK violation, or worse, point at a foreign
            // tenant's tier. If invalid, fall through to amount-match.
            if (vipTierId && isMonthly) {
              try {
                const { monthlyGivingTiers } = await import('@shared/schema');
                const [validTier] = await db
                  .select({ id: monthlyGivingTiers.id, name: monthlyGivingTiers.tierName })
                  .from(monthlyGivingTiers)
                  .where(and(
                    eq(monthlyGivingTiers.id, vipTierId),
                    eq(monthlyGivingTiers.tenantId, tenant.id),
                  ))
                  .limit(1);
                if (!validTier) {
                  console.warn('[Webhook] vipTierId from metadata not found on tenant, falling back to amount-match:', vipTierId);
                  vipTierId = null;
                  vipTierName = null;
                } else {
                  // Refresh the snapshot name in case the tier was renamed
                  vipTierName = validTier.name;
                }
              } catch (validateErr) {
                console.error('[Webhook] VIP tier validation failed (non-fatal):', validateErr);
              }
            }

            if (!vipTierId && isMonthly) {
              try {
                const { pickVipTierForAmount } = await import('./lib/vip-tiers');
                const matched = await pickVipTierForAmount(tenant.id, session.amount_total || 0);
                if (matched) {
                  vipTierId = matched.id;
                  vipTierName = matched.name;
                }
              } catch (tierErr) {
                console.error('[Webhook] VIP tier auto-tag failed (non-fatal):', tierErr);
              }
            }

            // Final guard: never persist a VIP snapshot on a non-monthly sub.
            // The roster query filters to interval='month', but staff might
            // also derive donor lists from snapshot presence elsewhere.
            if (!isMonthly) {
              vipTierId = null;
              vipTierName = null;
            }

            // ACH unpaid → 'incomplete'; flips to 'active' via customer.subscription.updated.
            const initialSubStatus = session.payment_status === 'paid' ? 'active' : 'incomplete';
            const inserted = await db.insert(subscriptions).values({
              tenantId: tenant.id,
              donorId: donor.id,
              stripeSubscriptionId: session.subscription,
              amount: session.amount_total || 0,
              currency: session.currency || 'usd',
              interval: actualInterval || 'month',
              status: initialSubStatus,
              vipTierIdSnapshot: vipTierId,
              vipTierNameSnapshot: vipTierName,
              displayOnWallOfHeroes: wallOptIn,
              displayName: displayName,
            })
            .onConflictDoNothing({ target: [subscriptions.tenantId, subscriptions.stripeSubscriptionId] })
            .returning({ id: subscriptions.id });

            // Send VIP welcome email + tax-deductible receipt for new VIP donors
            if (inserted.length > 0 && sessionMeta.source === 'vip_club' && customerEmail) {
              try {
                const { sendVipWelcomeEmail } = await import('./services/vip-emails');
                const fallbackOrigin = `${req.protocol}://${req.get('host')}`;
                await sendVipWelcomeEmail({
                  tenant,
                  donorEmail: customerEmail,
                  donorName: customerName || donor.name || 'Friend',
                  tierId: vipTierId,
                  tierName: vipTierName,
                  monthlyAmountCents: session.amount_total || 0,
                  currency: session.currency || 'usd',
                  fallbackOrigin,
                });
              } catch (welcomeErr) {
                console.error('[STRIPE-WEBHOOK] Failed to send VIP welcome email:', welcomeErr);
              }
            }
          }

          break;
        }

        case 'invoice.payment_succeeded': {
          const invoice = event.data.object as any;
          if (!invoice.subscription) break;

          // Idempotency check (status-aware): only skip if a SUCCEEDED payment row
          // already exists for this invoice. A prior 'failed' row from
          // invoice.payment_failed must NOT block a subsequent retry success.
          let existingFailedRowToUpgrade: { id: string } | null = null;
          if (invoice.id) {
            const existingPayment = await db
              .select({ id: payments.id, status: payments.status })
              .from(payments)
              .where(and(eq(payments.tenantId, tenant.id), eq(payments.stripeInvoiceId, invoice.id)))
              .limit(1)
              .then(rows => rows[0]);

            if (existingPayment?.status === 'succeeded') {
              console.log(`[Webhook] Invoice ${invoice.id} already succeeded, skipping (idempotency)`);
              return res.status(200).json({ received: true, idempotent: true });
            }
            if (existingPayment) {
              existingFailedRowToUpgrade = { id: existingPayment.id };
            }
          }

          const donor = await db
            .select()
            .from(donors)
            .where(
              and(
                eq(donors.tenantId, tenant.id),
                eq(donors.stripeCustomerId, invoice.customer)
              )
            )
            .limit(1)
            .then(rows => rows[0]);

          if (donor) {
            const subscription = await db
              .select()
              .from(subscriptions)
              .where(
                and(
                  eq(subscriptions.tenantId, tenant.id),
                  eq(subscriptions.stripeSubscriptionId, invoice.subscription)
                )
              )
              .limit(1)
              .then(rows => rows[0]);

            // If a prior 'failed' row exists for this invoice (from invoice.payment_failed),
            // upgrade it in place to 'succeeded' rather than inserting a duplicate row.
            if (existingFailedRowToUpgrade) {
              await db
                .update(payments)
                .set({
                  donorId: donor.id,
                  subscriptionId: subscription?.id,
                  amount: invoice.amount_paid,
                  currency: invoice.currency,
                  status: 'succeeded',
                  paymentMethod: 'stripe',
                  isRecurring: true,
                })
                .where(eq(payments.id, existingFailedRowToUpgrade.id));
            } else {
              await db.insert(payments).values({
                tenantId: tenant.id,
                donorId: donor.id,
                stripeInvoiceId: invoice.id,
                subscriptionId: subscription?.id,
                amount: invoice.amount_paid,
                currency: invoice.currency,
                status: 'succeeded',
                paymentMethod: 'stripe',
                isRecurring: true,
              });
            }

            await db
              .update(donors)
              .set({
                totalDonated: sql`GREATEST(0, ${donors.totalDonated} + ${invoice.amount_paid})`,
                lastDonationDate: new Date(),
              })
              .where(eq(donors.id, donor.id));

            // Create or update contact record for the recurring donor
            try {
              const { createContactFromDonation } = await import('./services/contacts');
              if (donor.email) { await createContactFromDonation(tenant.id, donor.name, donor.email, invoice.amount_paid / 100); }
              console.log(`[Webhook] Created/updated contact for recurring donor: ${donor.email}`);
            } catch (contactError) {
              console.error('[Webhook] Failed to create contact from recurring donation:', contactError);
            }

            // For VIP subscriptions, send a branded tax-deductible monthly receipt
            // Only fire on subsequent (recurring) cycles — the welcome email already
            // includes a receipt for the initial subscription_create invoice.
            const isVipSubscription = !!subscription?.vipTierIdSnapshot;
            const isInitialSubscriptionInvoice = invoice.billing_reason === 'subscription_create';
            if (isVipSubscription) {
              // First cycle is covered by the welcome email's embedded receipt; skip
              // any further email here to avoid duplicates.
              if (isInitialSubscriptionInvoice) {
                break;
              }
              if (donor.email) {
                try {
                  const { sendVipMonthlyReceiptEmail } = await import('./services/vip-emails');
                  const fallbackOrigin = `${req.protocol}://${req.get('host')}`;
                  const paidAtSeconds = invoice.status_transitions?.paid_at;
                  const paidAt = paidAtSeconds ? new Date(paidAtSeconds * 1000) : new Date();
                  await sendVipMonthlyReceiptEmail({
                    tenant,
                    donor: { id: donor.id, impactLoopOptOut: donor.impactLoopOptOut },
                    donorEmail: donor.email,
                    donorName: donor.name || 'Friend',
                    tierName: subscription?.vipTierNameSnapshot || null,
                    amountCents: invoice.amount_paid || 0,
                    currency: invoice.currency || 'usd',
                    paidAt,
                    invoiceNumber: invoice.number || null,
                    invoiceHostedUrl: invoice.hosted_invoice_url || null,
                    fallbackOrigin,
                  });
                } catch (vipReceiptErr) {
                  console.error('[Webhook] Failed to send VIP monthly receipt email:', vipReceiptErr);
                }
              }
              break;
            }

            // Send thank-you email for recurring payment (non-VIP recurring donors)
            try {
              const { EmailService } = await import('./lib/email-service');
              const emailService = await EmailService.forTenant(tenant.id);
              
              if (emailService && donor.email) {
                const amountFormatted = new Intl.NumberFormat('en-US', {
                  style: 'currency',
                  currency: invoice.currency || 'usd'
                }).format(invoice.amount_paid / 100);
                
                const dateFormatted = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
                
                // Escape user-provided content to prevent XSS
                const safeDonorName = escapeHtml(donor.name);
                const safeTenantName = escapeHtml(tenant.name);
                const tenantEin = tenant.orgTaxEin
                  || (tenant.transparencyVault as { ein?: string } | null | undefined)?.ein
                  || null;
                const safeEin = escapeHtml(tenantEin);
                const einSection = safeEin ? ` EIN: ${safeEin}` : '';

                const { buildImpactLoopSection } = await import('./services/impact-loop');
                const impactSection = await buildImpactLoopSection({
                  tenant,
                  donor: { id: donor.id, impactLoopOptOut: donor.impactLoopOptOut },
                  baseUrl: `${req.protocol}://${req.get('host')}`,
                });
                const impactBlock = impactSection ? `\n  ${impactSection}\n` : '';

                await emailService.send({
                  to: donor.email,
                  subject: `Thank you for your continued support of ${safeTenantName}!`,
                  ...(impactSection && tenant.contactEmail ? { replyTo: tenant.contactEmail } : {}),
                  html: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #2563eb;">Thank You, ${safeDonorName}!</h2>
  
  <p>Your recurring donation of <strong>${amountFormatted}</strong> to ${safeTenantName} has been processed successfully.</p>
  
  <div style="background: #f3f4f6; padding: 15px; border-radius: 8px; margin: 20px 0;">
    <p style="margin: 5px 0;"><strong>Amount:</strong> ${amountFormatted}</p>
    <p style="margin: 5px 0;"><strong>Date:</strong> ${dateFormatted}</p>
  </div>
  ${impactBlock}
  <p>Your ongoing support helps us continue our mission to rescue and care for animals in need. Thank you for being a vital part of our community!</p>
  
  <p>With heartfelt gratitude,<br/>
  <strong>The ${safeTenantName} Team</strong></p>
  
  <hr style="border: none; border-top: 1px solid #e5e7eb; margin: 20px 0;" />
  
  <p style="font-size: 12px; color: #6b7280;">
    ${safeTenantName} is a registered 501(c)(3) nonprofit organization.${einSection}<br/>
    This email serves as your donation confirmation for this payment period.
  </p>
</div>
                  `.trim()
                });
                console.log(`[Webhook] Recurring payment thank-you email sent to ${donor.email}${impactSection ? ' (with impact loop)' : ''}`);
              }
            } catch (emailError) {
              console.error('[Webhook] Failed to send recurring payment thank-you email:', emailError);
            }
          }
          break;
        }

        case 'customer.subscription.updated': 
        case 'customer.subscription.deleted': {
          const subscription = event.data.object as any;
          
          await db
            .update(subscriptions)
            .set({
              status: subscription.status,
              currentPeriodStart: new Date(subscription.current_period_start * 1000),
              currentPeriodEnd: new Date(subscription.current_period_end * 1000),
              canceledAt: subscription.canceled_at ? new Date(subscription.canceled_at * 1000) : null,
              cancelAtPeriodEnd: !!subscription.cancel_at_period_end,
            })
            .where(
              and(
                eq(subscriptions.tenantId, tenant.id),
                eq(subscriptions.stripeSubscriptionId, subscription.id)
              )
            );

          // Refresh cached card-on-file (brand/last4) so the giving history view
          // can confirm to the donor that a card update from the billing portal
          // actually took effect. Only bumps cardUpdatedAt when the displayed
          // card details actually changed, so we don't show a stale "card
          // updated" banner on unrelated subscription edits.
          if (event.type === 'customer.subscription.updated') {
            try {
              await refreshSubscriptionCardForStripeSub(tenant, subscription);
            } catch (cardErr) {
              console.error('[Webhook] Failed to refresh subscription card cache:', cardErr);
            }
          }
          break;
        }

        case 'payment_method.attached': {
          // A new payment method was attached to the customer (e.g. via the
          // Stripe billing portal "Update payment method" flow). Refresh the
          // cached card details on every active subscription for that customer
          // so the giving history view can surface a "Card on file updated"
          // confirmation banner.
          const pm = event.data.object as any;
          if (pm.customer && pm.card) {
            try {
              await refreshSubscriptionCardsForCustomer(tenant, pm.customer, {
                brand: pm.card.brand || null,
                last4: pm.card.last4 || null,
              });
            } catch (cardErr) {
              console.error('[Webhook] Failed to cache attached payment method:', cardErr);
            }
          }
          break;
        }

        case 'customer.updated': {
          // The customer's default invoice payment method may have changed.
          // Pull the new PM details from Stripe and update each subscription
          // row for this customer.
          const customer = event.data.object as any;
          const rawPmId = customer?.invoice_settings?.default_payment_method;
          // default_payment_method can be either an ID string or — when
          // expansion is enabled on the event — the full PaymentMethod object.
          const pmId = typeof rawPmId === 'string'
            ? rawPmId
            : (rawPmId && typeof rawPmId === 'object' ? rawPmId.id : null);
          if (typeof pmId === 'string' && pmId) {
            try {
              const stripeClient = stripeService.getStripeClient(tenant);
              if (stripeClient) {
                const pm = await stripeClient.paymentMethods.retrieve(pmId);
                if (pm?.card) {
                  await refreshSubscriptionCardsForCustomer(tenant, customer.id, {
                    brand: pm.card.brand || null,
                    last4: pm.card.last4 || null,
                  });
                }
              }
            } catch (cardErr) {
              console.error('[Webhook] Failed to refresh default payment method cache:', cardErr);
            }
          }
          break;
        }

        case 'checkout.session.async_payment_succeeded': {
          const session = event.data.object as any;
          console.log(`[Webhook] ACH payment succeeded for session ${session.id}`);

          // P2P Campaign donation fulfillment for ACH — credit the campaign
          // progress now that the bank transfer has actually cleared. We
          // intentionally never bumped amountRaised in checkout.session.completed
          // for ACH, so there's no double-counting risk here.
          if (session.metadata?.peerCampaignId) {
            try {
              const { peerCampaignDonations, peerCampaigns } = await import('@shared/schema');
              const [updated] = await db
                .update(peerCampaignDonations)
                .set({ paymentStatus: 'paid' })
                .where(and(
                  eq(peerCampaignDonations.stripeSessionId, session.id),
                  inArray(peerCampaignDonations.paymentStatus, ['pending', 'processing'])
                ))
                .returning({ id: peerCampaignDonations.id });

              if (updated) {
                const amountPaid = session.metadata.baseAmount
                  ? parseInt(session.metadata.baseAmount)
                  : (session.amount_total || 0);
                await db
                  .update(peerCampaigns)
                  .set({ amountRaised: sql`${peerCampaigns.amountRaised} + ${amountPaid}` })
                  .where(eq(peerCampaigns.id, session.metadata.peerCampaignId));
                console.log('[Webhook] ACH-cleared P2P donation credited to campaign:', session.metadata.peerCampaignId, 'amount:', amountPaid);
              } else {
                console.log('[Webhook] ACH-cleared P2P donation already finalised (idempotency), skipping');
              }
            } catch (err) {
              console.error('[Webhook] Failed to fulfil ACH-cleared P2P donation:', err);
            }
          }

          // Update the pending payment to succeeded — status='pending' guard
          // makes redelivered webhooks idempotent. For subscription checkouts,
          // also stamp the first invoice id (so invoice.payment_succeeded short-
          // circuits its existing-succeeded check, preventing double-counting
          // donor.totalDonated) AND link to the subscription row so the Wall of
          // Heroes EXISTS gate (payments.subscriptionId = subs.id) passes after
          // first ACH clear.
          const firstInvoiceId = session.invoice || null;
          let linkedSubscriptionId: string | null = null;
          if (session.subscription) {
            const [subRow] = await db
              .select({ id: subscriptions.id })
              .from(subscriptions)
              .where(and(
                eq(subscriptions.tenantId, tenant.id),
                eq(subscriptions.stripeSubscriptionId, session.subscription)
              ))
              .limit(1);
            linkedSubscriptionId = subRow?.id || null;
          }
          const [updatedPayment] = await db
            .update(payments)
            .set({
              status: 'succeeded',
              ...(firstInvoiceId ? { stripeInvoiceId: firstInvoiceId } : {}),
              ...(linkedSubscriptionId ? { subscriptionId: linkedSubscriptionId } : {}),
            })
            .where(
              and(
                eq(payments.tenantId, tenant.id),
                eq(payments.stripeCheckoutSessionId, session.id),
                eq(payments.status, 'pending')
              )
            )
            .returning();

          if (updatedPayment) {
            // Update donor totals now that payment succeeded
            const donor = await db
              .select()
              .from(donors)
              .where(eq(donors.id, updatedPayment.donorId!))
              .limit(1)
              .then(rows => rows[0]);

            if (donor) {
              await db
                .update(donors)
                .set({
                  totalDonated: (donor.totalDonated || 0) + updatedPayment.amount,
                  lastDonationDate: new Date(),
                })
                .where(eq(donors.id, donor.id));

              // ACH cleared: persist donation row tagged 'ach' for receipt/summary parity.
              try {
                const meta = (session.metadata || {}) as Record<string, string>;
                const donorCoveredFees = meta.donorCoveredFees === 'true' || meta.donorCoversFees === 'true';
                const baseAmountCents = meta.baseAmount ? parseInt(meta.baseAmount, 10) : updatedPayment.amount;
                const grossAmountCents = donorCoveredFees ? updatedPayment.amount : baseAmountCents;
                const feeNote = donorCoveredFees && meta.feesCovered
                  ? ` (donor covered $${(parseInt(meta.feesCovered, 10) / 100).toFixed(2)} in processing fees)`
                  : '';
                const description = meta.sponsoredAnimalName
                  ? `Sponsored: ${meta.sponsoredAnimalName}${feeNote}`
                  : (feeNote || null);

                const [donationRecord] = await db.insert(donations).values({
                  tenantId: tenant.id,
                  donorId: donor.id,
                  donorName: donor.name,
                  donorEmail: donor.email,
                  amount: baseAmountCents,
                  source: 'stripe' as any,
                  date: new Date(),
                  message: meta.message || null,
                  isRecurring: session.mode === 'subscription',
                  recurringFrequency: session.mode === 'subscription' ? 'monthly' : null,
                  recurringStatus: session.mode === 'subscription' ? 'active' : null,
                  donationType: 'ach',
                  paymentMethod: 'stripe_ach',
                  isPublic: true,
                  description,
                  feesCovered: donorCoveredFees,
                  grossAmount: grossAmountCents,
                  netAmount: baseAmountCents,
                }).returning();

                if (tenant.autoSendTaxReceipts && donationRecord?.donorEmail) {
                  try {
                    const { generateAndEmailReceipt } = await import('./services/donation-receipt-service');
                    await generateAndEmailReceipt({ donationId: donationRecord.id, tenantId: tenant.id });
                  } catch (rcptErr) {
                    console.error('[Webhook] Failed to generate ACH tax receipt:', rcptErr);
                  }
                }
              } catch (donationInsertErr) {
                console.error('[Webhook] Failed to create ACH donation record:', donationInsertErr);
              }

              try {
                const { createContactFromDonation } = await import('./services/contacts');
                if (donor.email) { await createContactFromDonation(tenant.id, donor.name, donor.email, updatedPayment.amount / 100); }
              } catch (contactError) {
                console.error('[Webhook] Failed to create contact from ACH donation:', contactError);
              }

              // Donor thank-you email now that ACH payment cleared
              try {
                const { EmailService } = await import('./lib/email-service');
                const emailService = await EmailService.forTenant(tenant.id);
                
                if (emailService && donor.email) {
                  const amountFormatted = new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: updatedPayment.currency || 'usd'
                  }).format(updatedPayment.amount / 100);

                  const dateFormatted = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
                  const safeDonorName = escapeHtml(donor.name);
                  const safeTenantName = escapeHtml(tenant.name);
                  const safeEin = escapeHtml(tenant.ein);
                  const einSection = safeEin ? ` EIN: ${safeEin}` : '';

                  await emailService.send({
                    to: donor.email,
                    subject: `Your bank transfer donation to ${safeTenantName} has been received!`,
                    html: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #2563eb;">Thank You, ${safeDonorName}!</h2>
  
  <p>Great news! Your bank transfer donation of <strong>${amountFormatted}</strong> to ${safeTenantName} has been successfully processed.</p>
  
  <div style="background: #f3f4f6; padding: 15px; border-radius: 8px; margin: 20px 0;">
    <p style="margin: 5px 0;"><strong>Amount:</strong> ${amountFormatted}</p>
    <p style="margin: 5px 0;"><strong>Date Cleared:</strong> ${dateFormatted}</p>
    <p style="margin: 5px 0;"><strong>Payment Method:</strong> Bank Transfer (ACH)</p>
  </div>
  
  <p>Your support makes a real difference in the lives of the animals we rescue and care for. Thank you for choosing to give via bank transfer!</p>
  
  <p>With heartfelt gratitude,<br/>
  <strong>The ${safeTenantName} Team</strong></p>
  
  <hr style="border: none; border-top: 1px solid #e5e7eb; margin: 20px 0;" />
  
  <p style="font-size: 12px; color: #6b7280;">
    ${safeTenantName} is a registered 501(c)(3) nonprofit organization.${einSection}<br/>
    This email serves as your donation confirmation.
  </p>
</div>
                    `.trim()
                  });
                  console.log(`[Webhook] ACH payment confirmation email sent to ${donor.email}`);
                }
              } catch (emailError) {
                console.error('[Webhook] Failed to send ACH payment confirmation email:', emailError);
              }
            }
          }
          break;
        }

        case 'invoice.payment_failed': {
          const invoice = event.data.object as any;
          if (!invoice.subscription) break;

          // Idempotency: skip if we've already recorded a 'failed' (or anything
          // that's already moved past failure) for this invoice. We capture the
          // existing row so we can update-in-place rather than insert and risk
          // duplicate rows for the same invoice.
          let existingInvoiceRow: { id: string; status: string } | null = null;
          if (invoice.id) {
            const existing = await db
              .select({ id: payments.id, status: payments.status })
              .from(payments)
              .where(and(eq(payments.tenantId, tenant.id), eq(payments.stripeInvoiceId, invoice.id)))
              .limit(1)
              .then(rows => rows[0]);
            if (existing) {
              if (existing.status === 'failed' || existing.status === 'succeeded' || existing.status === 'refunded') {
                console.log(`[Webhook] Invoice ${invoice.id} payment_failed already recorded (status=${existing.status}); skipping`);
                return res.status(200).json({ received: true, idempotent: true });
              }
              existingInvoiceRow = existing;
            }
          }

          const subscription = await db
            .select()
            .from(subscriptions)
            .where(and(
              eq(subscriptions.tenantId, tenant.id),
              eq(subscriptions.stripeSubscriptionId, invoice.subscription),
            ))
            .limit(1)
            .then(rows => rows[0]);

          const donor = await db
            .select()
            .from(donors)
            .where(and(
              eq(donors.tenantId, tenant.id),
              eq(donors.stripeCustomerId, invoice.customer),
            ))
            .limit(1)
            .then(rows => rows[0]);

          // Record a failed payment row so the giving history shows the lapse.
          // Upsert pattern: update an existing pending row in place, otherwise insert.
          if (donor && invoice.id) {
            const failedAmount = invoice.amount_due || invoice.amount_paid || subscription?.amount || 0;
            if (existingInvoiceRow) {
              await db.update(payments).set({
                donorId: donor.id,
                subscriptionId: subscription?.id,
                amount: failedAmount,
                currency: invoice.currency || 'usd',
                status: 'failed',
                paymentMethod: 'stripe',
                isRecurring: true,
              }).where(eq(payments.id, existingInvoiceRow.id));
            } else {
              await db.insert(payments).values({
                tenantId: tenant.id,
                donorId: donor.id,
                stripeInvoiceId: invoice.id,
                subscriptionId: subscription?.id,
                amount: failedAmount,
                currency: invoice.currency || 'usd',
                status: 'failed',
                paymentMethod: 'stripe',
                isRecurring: true,
              });
            }
          }

          // Notify VIP donors specifically — non-VIP recurring failures are out of scope here.
          const isVipSubscription = !!subscription?.vipTierIdSnapshot;
          if (isVipSubscription && donor?.email) {
            try {
              const { sendVipPaymentFailedEmail } = await import('./services/vip-emails');
              const tenantPath = (tenant as any).customDomain ? '' : (tenant.subdomain ? `/${tenant.subdomain}` : '');
              const fallbackOrigin = `${req.protocol}://${req.get('host')}`;
              const baseUrl = (tenant as any).customDomain
                ? `https://${(tenant as any).customDomain}`
                : `${fallbackOrigin}${tenantPath}`;
              await sendVipPaymentFailedEmail({
                tenant,
                donorEmail: donor.email,
                donorName: donor.name || 'Friend',
                tierName: subscription?.vipTierNameSnapshot || null,
                amountCents: invoice.amount_due || subscription?.amount || 0,
                currency: invoice.currency || 'usd',
                attemptNumber: invoice.attempt_count || null,
                nextRetryAt: invoice.next_payment_attempt ? new Date(invoice.next_payment_attempt * 1000) : null,
                hostedInvoiceUrl: invoice.hosted_invoice_url || null,
                manageUrl: `${baseUrl}/donor/giving-history`,
              });
            } catch (emailErr) {
              console.error('[Webhook] Failed to send VIP card-failure email:', emailErr);
            }
          }
          break;
        }

        case 'checkout.session.async_payment_failed': {
          const session = event.data.object as any;
          console.log(`[Webhook] ACH payment failed for session ${session.id}`);

          // P2P Campaign donation failure for ACH — mark donation row failed.
          // We never bumped campaign progress for a pending ACH, so there is
          // nothing to roll back on the campaign side.
          if (session.metadata?.peerCampaignId) {
            try {
              const { peerCampaignDonations } = await import('@shared/schema');
              await db
                .update(peerCampaignDonations)
                .set({ paymentStatus: 'failed' })
                .where(and(
                  eq(peerCampaignDonations.stripeSessionId, session.id),
                  inArray(peerCampaignDonations.paymentStatus, ['pending', 'processing'])
                ));
              console.log('[Webhook] P2P ACH donation marked failed for session:', session.id);
            } catch (err) {
              console.error('[Webhook] Failed to mark P2P ACH donation failed:', err);
            }
          }

          // Update the pending payment to failed — gated on status='pending'
          // so a redelivered async_payment_failed webhook can't re-fire the
          // admin alert + donor email. Only the first pending->failed transition
          // returns a row; all downstream notifications are wrapped in the
          // `if (failedPayment)` (admin alert) / null guards below.
          const [failedPayment] = await db
            .update(payments)
            .set({ status: 'failed' })
            .where(
              and(
                eq(payments.tenantId, tenant.id),
                eq(payments.stripeCheckoutSessionId, session.id),
                eq(payments.status, 'pending')
              )
            )
            .returning();

          // ACH bounce alert: routes through Notification Preferences
          // (event_key `donation_payment_failed`). Gated on `failedPayment`
          // for idempotency on redelivered webhooks.
          if (failedPayment) try {
            const sessionAmount = session.amount_total || failedPayment.amount || 0;
            const amountFormatted = new Intl.NumberFormat('en-US', {
              style: 'currency',
              currency: (session.currency || failedPayment.currency || 'usd'),
            }).format(sessionAmount / 100);
            const donorEmail = session.customer_details?.email || session.customer_email || 'unknown donor';
            const donorName = session.customer_details?.name || 'Unknown';
            const surface = session.metadata?.peerCampaignId
              ? 'P2P Campaign'
              : (session.metadata?.achSurface || session.metadata?.surface || 'donation');
            const safeTenantName = escapeHtml(tenant.name);
            const safeDonor = escapeHtml(`${donorName} <${donorEmail}>`);
            const safeSurface = escapeHtml(String(surface));

            const fallbackOrigin = `${req.protocol}://${req.get('host')}`;
            const tenantBaseUrl = (tenant as any).customDomain
              ? `https://${(tenant as any).customDomain}`
              : `${fallbackOrigin}${tenant.subdomain ? `/${tenant.subdomain}` : ''}`;
            const donorRecordUrl = failedPayment.donorId
              ? `${tenantBaseUrl}/dashboard/donors?donorId=${failedPayment.donorId}`
              : `${tenantBaseUrl}/dashboard/donors`;
            const safeDonorRecordUrl = escapeHtml(donorRecordUrl);

            const { dispatchEventNotification } = await import('./services/notification-dispatcher');
            await dispatchEventNotification({
              tenantId: tenant.id,
              eventKey: 'donation_payment_failed',
              subject: `[Action Needed] ACH bank transfer bounced — ${amountFormatted}`,
              htmlBody: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #dc2626; margin-top: 0;">ACH Bank Transfer Failed</h2>
  <p>A donor's bank transfer to ${safeTenantName} bounced before clearing. The campaign progress was <strong>not</strong> credited and any associated public recognition (e.g. Wall of Heroes, P2P leaderboard) has been held back.</p>
  <div style="background: #fef2f2; padding: 15px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #dc2626;">
    <p style="margin: 5px 0;"><strong>Amount:</strong> ${amountFormatted}</p>
    <p style="margin: 5px 0;"><strong>Donor:</strong> ${safeDonor}</p>
    <p style="margin: 5px 0;"><strong>Surface:</strong> ${safeSurface}</p>
    <p style="margin: 5px 0; font-family: monospace; font-size: 12px;"><strong>Stripe session:</strong> ${escapeHtml(session.id)}</p>
  </div>
  <p style="margin: 16px 0;"><a href="${safeDonorRecordUrl}" style="display:inline-block;padding:10px 18px;background:#0f766e;color:#fff;border-radius:6px;text-decoration:none;font-weight:600;">Open donor record</a></p>
  <p>The donor has been emailed automatically with a recovery link. You may want to follow up personally for larger pledges.</p>
</div>
              `.trim(),
              textBody: `ACH bank transfer bounced for ${safeTenantName}. Amount: ${amountFormatted}. Donor: ${donorName} <${donorEmail}>. Surface: ${surface}. Stripe session: ${session.id}. Donor record: ${donorRecordUrl}. Campaign progress was not credited; donor was emailed a recovery link automatically.`,
              smsBody: `[${tenant.name}] ACH bounce: ${amountFormatted} from ${donorName}. ${donorRecordUrl}`,
            });
          } catch (adminAlertErr) {
            console.error('[Webhook] Failed to dispatch ACH-bounce admin notification:', adminAlertErr);
          }

          // Notify donor that their bank transfer failed
          if (failedPayment) {
            const donor = await db
              .select()
              .from(donors)
              .where(eq(donors.id, failedPayment.donorId!))
              .limit(1)
              .then(rows => rows[0]);

            if (donor) {
              try {
                const { EmailService } = await import('./lib/email-service');
                const emailService = await EmailService.forTenant(tenant.id);
                
                if (emailService && donor.email) {
                  const amountFormatted = new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: failedPayment.currency || 'usd'
                  }).format(failedPayment.amount / 100);

                  const safeDonorName = escapeHtml(donor.name);
                  const safeTenantName = escapeHtml(tenant.name);

                  await emailService.send({
                    to: donor.email,
                    subject: `Your bank transfer to ${safeTenantName} could not be completed`,
                    html: `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #dc2626;">Bank Transfer Update</h2>
  
  <p>Hi ${safeDonorName},</p>
  
  <p>Unfortunately, your bank transfer donation of <strong>${amountFormatted}</strong> to ${safeTenantName} could not be completed.</p>
  
  <div style="background: #fef2f2; padding: 15px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #dc2626;">
    <p style="margin: 0; color: #991b1b;"><strong>Payment Failed</strong></p>
    <p style="margin: 5px 0 0 0; color: #991b1b; font-size: 14px;">This can happen if there were insufficient funds, the account was closed, or bank details were incorrect.</p>
  </div>
  
  <p>If you'd still like to support our mission, you can try again with a different payment method or contact your bank for more information.</p>
  
  <p>Thank you for your intended support. We appreciate your generosity!</p>
  
  <p>Best regards,<br/>
  <strong>The ${safeTenantName} Team</strong></p>
</div>
                    `.trim()
                  });
                  console.log(`[Webhook] ACH failure notification sent to ${donor.email}`);
                }
              } catch (emailError) {
                console.error('[Webhook] Failed to send ACH failure notification:', emailError);
              }
            }
          }
          break;
        }
      }

      res.json({ received: true });
    } catch (error) {
      console.error('[STRIPE-WEBHOOK] Unhandled error:', error instanceof Error ? error.stack : error);
      res.status(400).send(`Webhook Error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  });

  /**
   * POST /api/resend/inbound
   * Handle Resend inbound email webhook - Email to iRescue feature
   */
  app.post('/api/resend/inbound', express.json(), async (req, res) => {
    try {
      const event = req.body;
      
      // Verify this is an email.received event
      if (event.type !== 'email.received') {
        return res.json({ received: true });
      }

      const emailData = event.data;
      console.log(`[Inbound Email] Received webhook - subject: ${emailData.subject}, from: ${emailData.from}, to: ${JSON.stringify(emailData.to)}, has attachments field: ${!!emailData.attachments}, attachments count: ${emailData.attachments?.length || 0}`);
      
      // Extract the "to" address from the email payload
      const toAddress = Array.isArray(emailData.to) ? emailData.to[0] : emailData.to;
      const normalizedTo = toAddress.trim().toLowerCase();

      // Route to tenant: first try system_inbound_email match (supports forwarded emails),
      // then fall back to subdomain extraction for backward compatibility
      let [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.systemInboundEmail, normalizedTo))
        .limit(1);

      if (!tenant) {
        // Fallback: extract subdomain from "to" address (legacy routing)
        const emailMatch = normalizedTo.match(/^([^@]+)@/);
        if (emailMatch) {
          [tenant] = await db
            .select()
            .from(tenants)
            .where(eq(tenants.subdomain, emailMatch[1]))
            .limit(1);
        }
      }

      if (!tenant) {
        console.error('Tenant not found for inbound email address:', normalizedTo);
        return res.status(404).json({ error: 'Tenant not found' });
      }

      // Get Resend API key for this tenant or use platform key
      const { decrypt } = await import('./lib/encryption');
      const { Resend } = await import('resend');
      
      let resendApiKey = process.env.PLATFORM_RESEND_API_KEY;
      if (tenant.resendApiKeyEncrypted && tenant.resendEnabled) {
        resendApiKey = decrypt(tenant.resendApiKeyEncrypted);
      }

      if (!resendApiKey) {
        console.error('No Resend API key available for tenant:', tenant.id);
        return res.status(500).json({ error: 'Email service not configured' });
      }

      const resend = new Resend(resendApiKey);

      // Fetch full email content from Resend
      const { data: email, error: emailError } = await resend.emails.receiving.get(emailData.email_id);
      if (emailError || !email) {
        console.error('Failed to fetch email from Resend:', emailError);
        return res.status(500).json({ error: 'Failed to fetch email content' });
      }

      let attachmentsList: Array<{
        filename: string;
        contentType: string;
        size: number;
        url: string;
        resendAttachmentId?: string;
      }> = [];
      const pdfBuffers: Array<{
        filename: string;
        buffer: Buffer;
        size: number;
        storageUrl: string;
      }> = [];

      {
        try {
          console.log(`[Inbound Email] Checking for attachments on email ${emailData.email_id}...`);
          const attListResp = await fetch(`https://api.resend.com/emails/receiving/${emailData.email_id}/attachments`, {
            headers: { 'Authorization': `Bearer ${resendApiKey}` },
          });
          const attListJson = await attListResp.json() as { data?: Array<{ id: string; filename: string; content_type: string; size: number; download_url: string }> };
          const attachments = attListJson.data || [];
          console.log(`[Inbound Email] Found ${attachments.length} attachment(s)`);

          if (attachments.length > 0) {
            const { ObjectStorageService } = await import('./objectStorage');
            const storageService = new ObjectStorageService();

            for (const att of attachments) {
              try {
                const downloadResp = await fetch(att.download_url);
                if (!downloadResp.ok) {
                  console.error(`[Inbound Email] Failed to download attachment ${att.id}: ${downloadResp.status}`);
                  attachmentsList.push({
                    filename: att.filename || 'unknown',
                    contentType: att.content_type || 'application/octet-stream',
                    size: 0,
                    url: '',
                    resendAttachmentId: att.id,
                  });
                  continue;
                }

                const contentBuffer = Buffer.from(await downloadResp.arrayBuffer());
                const safeFilename = `${Date.now()}_${(att.filename || 'attachment').replace(/[^a-zA-Z0-9._-]/g, '_')}`;

                let storageUrl = '';
                try {
                  const uploaded = await storageService.uploadTenantFile(
                    tenant.id,
                    'inbound-email-attachments',
                    contentBuffer,
                    att.content_type || 'application/octet-stream',
                    safeFilename
                  );
                  storageUrl = uploaded.objectPath;
                } catch (uploadErr) {
                  console.error('Failed to upload attachment to storage:', uploadErr);
                }

                attachmentsList.push({
                  filename: att.filename || 'unknown',
                  contentType: att.content_type || 'application/octet-stream',
                  size: contentBuffer.length,
                  url: storageUrl,
                  resendAttachmentId: att.id,
                });

                const isPdf = (att.content_type || '').toLowerCase() === 'application/pdf' ||
                              (att.filename || '').toLowerCase().endsWith('.pdf');
                if (isPdf) {
                  pdfBuffers.push({
                    filename: att.filename || 'document.pdf',
                    buffer: contentBuffer,
                    size: contentBuffer.length,
                    storageUrl,
                  });
                }
              } catch (singleAttErr) {
                console.error(`Failed to process attachment ${att.id}:`, singleAttErr);
                attachmentsList.push({
                  filename: att.filename || 'unknown',
                  contentType: att.content_type || 'application/octet-stream',
                  size: 0,
                  url: '',
                  resendAttachmentId: att.id,
                });
              }
            }
          }
        } catch (attachError) {
          console.error('Failed to fetch attachments:', attachError);
        }
      }

      // Save to inbound_emails table
      const { inboundEmails } = await import('@shared/schema');
      
      const insertResult = await db.insert(inboundEmails).values({
        tenantId: tenant.id,
        messageId: emailData.email_id,
        from: emailData.from || '',
        fromName: emailData.from?.match(/^(.+?)\s*</) ? emailData.from.match(/^(.+?)\s*</)?.[1] : null,
        to: toAddress,
        subject: emailData.subject || '(no subject)',
        textBody: email.text || null,
        htmlBody: email.html || null,
        attachments: attachmentsList.length > 0 ? attachmentsList : null,
        status: 'unprocessed',
        receivedAt: new Date(event.created_at),
      }).onConflictDoNothing({ target: inboundEmails.messageId }).returning();

      if (insertResult.length === 0) {
        console.log(`[Inbound Email] Duplicate webhook for messageId ${emailData.email_id} — ignoring`);
        return res.json({ received: true, duplicate: true });
      }

      const savedEmail = insertResult[0];

      console.log(`Saved inbound email ${savedEmail.id} for tenant ${tenant.subdomain}`);

      if (pdfBuffers.length > 0) {
        const { processMedicalDocument } = await import('./services/aiMedicalParser');
        const { medicalImportBatches: mibTable, medicalImportItems: miiTable } = await import('@shared/schema');
        let successCount = 0;
        let failCount = 0;

        for (const pdf of pdfBuffers) {
          let batchId: string | null = null;
          try {
            console.log(`Auto-processing PDF "${pdf.filename}" from inbound email ${savedEmail.id}`);

            const [batch] = await db.insert(mibTable).values({
              tenantId: tenant.id,
              animalId: null,
              inboundEmailId: savedEmail.id,
              originalFileName: pdf.filename,
              fileUrl: pdf.storageUrl || null,
              fileSize: pdf.size,
              status: 'processing' as const,
            }).returning();
            batchId = batch.id;

            const result = await processMedicalDocument(pdf.buffer, 'Unknown', 'animal');

            if (!result.success) {
              await db.update(mibTable)
                .set({
                  status: 'failed' as const,
                  errorMessage: result.error,
                  extractedText: result.extractedText,
                  pageCount: result.pageCount,
                  processingNotes: result.processingNotes,
                })
                .where(eq(mibTable.id, batch.id));
              console.error(`Failed to parse PDF "${pdf.filename}":`, result.error);
              failCount++;
              continue;
            }

            const itemsToInsert: Array<{
              batchId: string;
              tenantId: string;
              animalId: string | null;
              recordType: 'vaccine' | 'procedure' | 'prescription' | 'diagnostic' | 'exam';
              extractedData: Record<string, unknown>;
              confidence: string;
              sourceText?: string;
            }> = [];

            for (const vaccine of result.vaccines) {
              itemsToInsert.push({
                batchId: batch.id,
                tenantId: tenant.id,
                animalId: null,
                recordType: 'vaccine',
                extractedData: {
                  itemName: vaccine.itemName,
                  dateGiven: vaccine.dateGiven,
                  dateDue: vaccine.dateDue,
                  manufacturer: vaccine.manufacturer,
                  lotNumber: vaccine.lotNumber,
                  administeredBy: vaccine.administeredBy,
                },
                confidence: String(Math.round(vaccine.confidence)),
                sourceText: vaccine.sourceText,
              });
            }

            for (const procedure of result.procedures) {
              itemsToInsert.push({
                batchId: batch.id,
                tenantId: tenant.id,
                animalId: null,
                recordType: 'procedure',
                extractedData: {
                  procedureName: procedure.procedureName,
                  procedureDate: procedure.procedureDate,
                  veterinarian: procedure.veterinarian,
                  notes: procedure.notes,
                },
                confidence: String(Math.round(procedure.confidence)),
                sourceText: procedure.sourceText,
              });
            }

            for (const prescription of result.prescriptions) {
              itemsToInsert.push({
                batchId: batch.id,
                tenantId: tenant.id,
                animalId: null,
                recordType: 'prescription',
                extractedData: {
                  medicationName: prescription.medicationName,
                  dosage: prescription.dosage,
                  route: prescription.route,
                  frequency: prescription.frequency,
                  startDate: prescription.startDate,
                  endDate: prescription.endDate,
                  notes: prescription.notes,
                },
                confidence: String(Math.round(prescription.confidence)),
                sourceText: prescription.sourceText,
              });
            }

            for (const diagnostic of result.diagnostics) {
              itemsToInsert.push({
                batchId: batch.id,
                tenantId: tenant.id,
                animalId: null,
                recordType: 'diagnostic',
                extractedData: {
                  testName: diagnostic.testName,
                  testDate: diagnostic.testDate,
                  result: diagnostic.result,
                  notes: diagnostic.notes,
                },
                confidence: String(Math.round(diagnostic.confidence)),
                sourceText: diagnostic.sourceText,
              });
            }

            for (const exam of result.exams) {
              itemsToInsert.push({
                batchId: batch.id,
                tenantId: tenant.id,
                animalId: null,
                recordType: 'exam',
                extractedData: {
                  examType: exam.examType,
                  examDate: exam.examDate,
                  performedBy: exam.performedBy,
                  subjective: exam.subjective,
                  objective: exam.objective,
                  assessment: exam.assessment,
                  plan: exam.plan,
                  weight: exam.weight,
                  temperature: exam.temperature,
                },
                confidence: String(Math.round(exam.confidence)),
                sourceText: exam.sourceText,
              });
            }

            if (itemsToInsert.length > 0) {
              await db.insert(miiTable).values(itemsToInsert);
            }

            await db.update(mibTable)
              .set({
                status: 'review' as const,
                extractedText: result.extractedText,
                pageCount: result.pageCount,
                overallConfidence: String(Math.round(result.overallConfidence)),
                processingNotes: result.processingNotes,
              })
              .where(eq(mibTable.id, batch.id));

            console.log(`Auto-parsed PDF "${pdf.filename}": ${itemsToInsert.length} items extracted (batch ${batch.id})`);
            successCount++;
          } catch (pdfErr) {
            console.error(`Failed to auto-process PDF "${pdf.filename}":`, pdfErr);
            failCount++;
            if (batchId) {
              try {
                await db.update(mibTable)
                  .set({
                    status: 'failed' as const,
                    errorMessage: pdfErr instanceof Error ? pdfErr.message : 'Unknown processing error',
                  })
                  .where(eq(mibTable.id, batchId));
              } catch (_) { /* best effort */ }
            }
          }
        }

        const emailStatus = successCount > 0 ? 'processed' : (failCount > 0 ? 'failed' : 'unprocessed');
        await db.update(inboundEmails)
          .set({ status: emailStatus })
          .where(eq(inboundEmails.id, savedEmail.id));
      }

      // Auto-CC: Send copies to configured recipients
      if (tenant.emailCopyRecipients && tenant.emailCopyRecipients.length > 0) {
        try {
          // Prepare from address for the copy
          const fromAddress = tenant.resendFromEmail || 'noreply@mail.irescue.life';
          const fromName = tenant.resendFromName || tenant.name;

          // Send a copy to each configured recipient
          for (const recipient of tenant.emailCopyRecipients) {
            await resend.emails.send({
              from: `${fromName} <${fromAddress}>`,
              to: recipient,
              subject: `[Copy] ${emailData.subject || '(no subject)'}`,
              html: `
                <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto;">
                  <div style="background: #f3f4f6; padding: 16px; border-radius: 8px; margin-bottom: 16px;">
                    <p style="margin: 0; font-size: 14px; color: #6b7280;">
                      <strong>Copy of inbound email to:</strong> ${toAddress}
                    </p>
                    <p style="margin: 4px 0 0 0; font-size: 14px; color: #6b7280;">
                      <strong>From:</strong> ${emailData.from}
                    </p>
                    <p style="margin: 4px 0 0 0; font-size: 14px; color: #6b7280;">
                      <strong>Received:</strong> ${new Date(event.created_at).toLocaleString()}
                    </p>
                  </div>
                  <div style="border-left: 4px solid #e5e7eb; padding-left: 16px;">
                    ${email.html || `<pre style="white-space: pre-wrap; font-family: sans-serif;">${email.text || '(no content)'}</pre>`}
                  </div>
                  ${attachmentsList.length > 0 ? `
                    <div style="margin-top: 16px; padding: 12px; background: #fef3c7; border-radius: 8px;">
                      <p style="margin: 0; font-size: 14px; color: #92400e;">
                        ⚠️ This email had ${attachmentsList.length} attachment(s). View them in the platform inbox.
                      </p>
                    </div>
                  ` : ''}
                </div>
              `,
              text: `
Copy of inbound email to: ${toAddress}
From: ${emailData.from}
Received: ${new Date(event.created_at).toLocaleString()}

---

${email.text || '(no content)'}

${attachmentsList.length > 0 ? `\n⚠️ This email had ${attachmentsList.length} attachment(s). View them in the platform inbox.` : ''}
              `.trim(),
            });
          }
          
          console.log(`Sent email copies to ${tenant.emailCopyRecipients.length} recipient(s) for tenant ${tenant.subdomain}`);
        } catch (copyError) {
          console.error('Failed to send email copies:', copyError);
          // Don't fail the whole webhook if copy fails
        }
      }
      
      res.json({ received: true, emailId: savedEmail.id });
    } catch (error) {
      console.error('Inbound email webhook error:', error);
      res.status(400).send(`Webhook Error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  });

  /**
   * GET /api/inbound-emails
   * List inbound emails for staff (admin, board_member, staff)
   */
  app.get('/api/inbound-emails', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { inboundEmails, animals, users } = await import('@shared/schema');
      const { status } = req.query;

      const conditions = [eq(inboundEmails.tenantId, req.tenant!.id)];
      
      if (status) {
        conditions.push(eq(inboundEmails.status, status as any));
      }

      const emails = await db
        .select({
          id: inboundEmails.id,
          from: inboundEmails.from,
          fromName: inboundEmails.fromName,
          to: inboundEmails.to,
          subject: inboundEmails.subject,
          status: inboundEmails.status,
          linkedAnimalId: inboundEmails.linkedAnimalId,
          linkedDocumentId: inboundEmails.linkedDocumentId,
          processedBy: inboundEmails.processedBy,
          processedAt: inboundEmails.processedAt,
          receivedAt: inboundEmails.receivedAt,
          attachments: inboundEmails.attachments,
          linkedAnimal: animals,
          processor: users,
        })
        .from(inboundEmails)
        .leftJoin(animals, eq(inboundEmails.linkedAnimalId, animals.id))
        .leftJoin(users, eq(inboundEmails.processedBy, users.id))
        .where(and(...conditions))
        .orderBy(desc(inboundEmails.receivedAt));

      res.json({ emails });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/inbound-emails/unprocessed/count
   * Get count of unprocessed emails for badge notification
   * NOTE: Must be defined before the :id route to avoid route conflicts
   */
  app.get('/api/inbound-emails/unprocessed/count', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { inboundEmails } = await import('@shared/schema');

      const result = await db
        .select({ count: sql<number>`count(*)::int` })
        .from(inboundEmails)
        .where(and(
          eq(inboundEmails.tenantId, req.tenant!.id),
          eq(inboundEmails.status, 'unprocessed')
        ));

      res.json({ count: result[0]?.count || 0 });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/inbound-emails/:id
   * Get specific inbound email with full content
   */
  app.get('/api/inbound-emails/:id', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { inboundEmails, animals, documents, users } = await import('@shared/schema');

      const [email] = await db
        .select({
          id: inboundEmails.id,
          from: inboundEmails.from,
          fromName: inboundEmails.fromName,
          to: inboundEmails.to,
          subject: inboundEmails.subject,
          textBody: inboundEmails.textBody,
          htmlBody: inboundEmails.htmlBody,
          attachments: inboundEmails.attachments,
          status: inboundEmails.status,
          linkedAnimalId: inboundEmails.linkedAnimalId,
          linkedDocumentId: inboundEmails.linkedDocumentId,
          processedBy: inboundEmails.processedBy,
          processedAt: inboundEmails.processedAt,
          notes: inboundEmails.notes,
          receivedAt: inboundEmails.receivedAt,
          linkedAnimal: animals,
          linkedDocument: documents,
          processor: users,
        })
        .from(inboundEmails)
        .leftJoin(animals, eq(inboundEmails.linkedAnimalId, animals.id))
        .leftJoin(documents, eq(inboundEmails.linkedDocumentId, documents.id))
        .leftJoin(users, eq(inboundEmails.processedBy, users.id))
        .where(and(
          eq(inboundEmails.id, req.params.id),
          eq(inboundEmails.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!email) {
        return res.status(404).json({ error: 'Email not found' });
      }

      res.json({ email });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/inbound-emails/:id
   * Update inbound email (mark processed, add notes, link to animal/document)
   */
  app.patch('/api/inbound-emails/:id', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { inboundEmails } = await import('@shared/schema');

      const updateSchema = z.object({
        status: z.enum(['unprocessed', 'processed', 'archived']).optional(),
        notes: z.string().optional(),
        linkedAnimalId: z.string().uuid().nullable().optional(),
        linkedDocumentId: z.string().uuid().nullable().optional(),
      });

      const data = updateSchema.parse(req.body);

      const updateData: any = {};
      if (data.status) updateData.status = data.status;
      if (data.notes !== undefined) updateData.notes = data.notes;
      if (data.linkedAnimalId !== undefined) updateData.linkedAnimalId = data.linkedAnimalId;
      if (data.linkedDocumentId !== undefined) updateData.linkedDocumentId = data.linkedDocumentId;

      // If marking as processed, record who processed it
      if (data.status === 'processed') {
        updateData.processedBy = req.user!.id;
        updateData.processedAt = new Date();
      }

      const [updated] = await db
        .update(inboundEmails)
        .set(updateData)
        .where(and(
          eq(inboundEmails.id, req.params.id),
          eq(inboundEmails.tenantId, req.tenant!.id)
        ))
        .returning();

      if (!updated) {
        return res.status(404).json({ error: 'Email not found' });
      }

      res.json({ email: updated });
    } catch (error) {
      next(error);
    }
  });

