  /**
   * POST /api/animals/:animalId/medical/vaccines
   * Create a vaccine record
   */
  app.post('/api/animals/:animalId/medical/vaccines', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { vaccineRecords, insertVaccineRecordSchema, medicalBills } = await import('@shared/schema');
      
      // Check permissions
      const permissions = await checkMedicalRecordPermissions(
        req.user!.id,
        req.params.animalId,
        req.tenant!.id,
        req.user!.roles
      );

      if (!permissions.canEdit) {
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'You do not have permission to edit medical records for this animal'
        });
      }
      
      const data = insertVaccineRecordSchema.parse(req.body);

      // Sanitize numeric fields - convert empty strings to null
      const sanitizedBillAmount = data.billAmount && data.billAmount.toString().trim() ? data.billAmount : null;
      const sanitizedPaidAmount = data.billPaidAmount && data.billPaidAmount.toString().trim() ? data.billPaidAmount : null;

      // If billing information is provided, create a medical bill
      let billId = data.billId || null;
      if (data.billVendor && sanitizedBillAmount) {
        const [bill] = await db
          .insert(medicalBills)
          .values({
            tenantId: req.tenant!.id,
            animalId: req.params.animalId,
            billDate: data.dateGiven,
            vendor: data.billVendor,
            amount: sanitizedBillAmount.toString(),
            description: `Vaccine: ${data.itemName}`,
            invoiceNumber: data.billInvoiceNumber || null,
            paymentStatus: (data.billPaymentStatus as any) || 'unpaid',
            paidAmount: sanitizedPaidAmount ? sanitizedPaidAmount.toString() : '0',
            notes: data.billNotes || null,
            createdBy: req.user!.id,
          })
          .returning();
        billId = bill.id;
      }

      const [vaccine] = await db
        .insert(vaccineRecords)
        .values({
          ...data,
          billAmount: sanitizedBillAmount,
          billPaidAmount: sanitizedPaidAmount,
          billId,
          animalId: req.params.animalId,
          tenantId: req.tenant!.id,
          createdBy: req.user!.id,
        })
        .returning();


      // Clear date_due on older records of the same vaccine type for this animal.
      // When a new dose is recorded, previous booster due dates are superseded.
      // Only runs when dateGiven is known so we can determine which records are older.
      if (vaccine.itemName && vaccine.dateGiven) {
        await db
          .update(vaccineRecords)
          .set({ dateDue: null })
          .where(and(
            eq(vaccineRecords.animalId, req.params.animalId),
            eq(vaccineRecords.tenantId, req.tenant!.id),
            eq(vaccineRecords.itemName, vaccine.itemName),
            ne(vaccineRecords.id, vaccine.id),
            isNotNull(vaccineRecords.dateDue),
            or(
              lt(vaccineRecords.dateGiven, vaccine.dateGiven),
              isNull(vaccineRecords.dateGiven)
            )
          ));
      }
      // Sync medical records to backup (non-blocking)
      try {
        const { syncAnimalMedicalRecords } = await import('./lib/animalBackupService');
        syncAnimalMedicalRecords(req.tenant!.id, req.params.animalId)
          .catch(err => console.error('[MEDICAL BACKUP] Background sync failed:', err));
      } catch (syncError) {
        console.error('[MEDICAL BACKUP] Failed to initiate sync:', syncError);
      }

      res.json({ vaccine });
    } catch (error) {
      next(error);
    }
  });

