  /**
   * GET /api/animals/:animalId/medical/prescriptions
   * Get all prescriptions for an animal
   */
  app.get('/api/animals/:animalId/medical/prescriptions', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalPrescriptions, medicalDoses } = await import('@shared/schema');
      
      // Check permissions
      const permissions = await checkMedicalRecordPermissions(
        req.user!.id,
        req.params.animalId,
        req.tenant!.id,
        req.user!.roles
      );

      if (!permissions.canView) {
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'You do not have permission to view medical records for this animal'
        });
      }
      
      const prescriptions = await db
        .select()
        .from(medicalPrescriptions)
        .where(and(
          eq(medicalPrescriptions.animalId, req.params.animalId),
          eq(medicalPrescriptions.tenantId, req.tenant!.id)
        ))
        .orderBy(desc(medicalPrescriptions.startDate));

      const rxEditorIds = [...new Set(prescriptions.map((p: any) => p.lastEditedBy).filter(Boolean))] as string[];
      let rxEditorMap: Record<string, string> = {};
      if (rxEditorIds.length > 0) {
        const eu = await db.select({ id: users.id, name: users.fullName }).from(users).where(inArray(users.id, rxEditorIds));
        rxEditorMap = Object.fromEntries(eu.map(u => [u.id, u.name]));
      }

      const prescriptionsWithLastGiven = await Promise.all(
        prescriptions.map(async (rx) => {
          const lastDose = await db
            .select({ givenAt: medicalDoses.givenAt })
            .from(medicalDoses)
            .where(and(
              eq(medicalDoses.prescriptionId, rx.id),
              eq(medicalDoses.tenantId, req.tenant!.id),
              eq(medicalDoses.status, 'given')
            ))
            .orderBy(desc(medicalDoses.givenAt))
            .limit(1);
          return {
            ...rx,
            lastGivenAt: lastDose[0]?.givenAt || null,
            lastEditedByName: rx.lastEditedBy ? (rxEditorMap[rx.lastEditedBy] || null) : null,
          };
        })
      );

      res.json({ prescriptions: prescriptionsWithLastGiven });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:animalId/medical/prescriptions
   * Create a prescription with doses
   */
  app.post('/api/animals/:animalId/medical/prescriptions', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalPrescriptions, medicalDoses, insertMedicalPrescriptionSchema, medicalBills } = await import('@shared/schema');
      
      // Check permissions
      const permissions = await checkMedicalRecordPermissions(
        req.user!.id,
        req.params.animalId,
        req.tenant!.id,
        req.user!.roles
      );

      if (!permissions.canEdit) {
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'You do not have permission to edit medical records for this animal'
        });
      }
      
      // Convert empty strings to undefined for optional fields (dates, numerics)
      const bodyData = {
        ...req.body,
        nextScheduledDose: req.body.nextScheduledDose === '' ? undefined : req.body.nextScheduledDose,
        endDate: req.body.endDate === '' ? undefined : req.body.endDate,
        billAmount: req.body.billAmount === '' ? undefined : req.body.billAmount,
        billPaidAmount: req.body.billPaidAmount === '' ? undefined : req.body.billPaidAmount,
        grantId: req.body.grantId === '' ? undefined : req.body.grantId,
      };
      
      const data = insertMedicalPrescriptionSchema.parse(bodyData);

      // Server-side enforcement: If startDate is in the past and nextScheduledDose is not provided,
      // automatically set nextScheduledDose to today to prevent generating overdue tasks
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const prescriptionStartDate = new Date(data.startDate);
      prescriptionStartDate.setHours(0, 0, 0, 0);
      
      if (prescriptionStartDate < today && !data.nextScheduledDose) {
        data.nextScheduledDose = today;
      }

      // Security: Validate grantId belongs to this tenant if provided
      if (data.grantId) {
        const { grants } = await import('@shared/schema');
        const [grant] = await db
          .select()
          .from(grants)
          .where(and(
            eq(grants.id, data.grantId),
            eq(grants.tenantId, req.tenant!.id)
          ))
          .limit(1);
        if (!grant) {
          return res.status(400).json({ 
            error: 'Invalid grant',
            message: 'Grant not found or does not belong to this organization'
          });
        }
      }

      // If billing information is provided, create a medical bill
      let billId = data.billId || null;
      if (data.billVendor && data.billAmount) {
        const [bill] = await db
          .insert(medicalBills)
          .values({
            tenantId: req.tenant!.id,
            animalId: req.params.animalId,
            billDate: data.startDate,
            vendor: data.billVendor,
            amount: data.billAmount.toString(),
            description: `Medication: ${data.medicationName}`,
            invoiceNumber: data.billInvoiceNumber || null,
            paymentStatus: (data.billPaymentStatus as any) || 'unpaid',
            paidAmount: data.billPaidAmount?.toString() || '0',
            notes: data.billNotes || null,
            grantId: data.grantId || null,
            createdBy: req.user!.id,
          })
          .returning();
        billId = bill.id;
      }

      const [prescription] = await db
        .insert(medicalPrescriptions)
        .values({
          ...data,
          billId,
          animalId: req.params.animalId,
          tenantId: req.tenant!.id,
          createdBy: req.user!.id,
        })
        .returning();

      // Generate doses using the centralized dose generator
      const { generateDosesForPrescription } = await import('./lib/dose-generator');
      const doses = generateDosesForPrescription({
        prescription,
        tenant: req.tenant!,
        tenantId: req.tenant!.id,
      });
      
      // Determine if this is a historical prescription for response
      const now = new Date();
      const isHistorical = prescription.endDate && new Date(prescription.endDate) < now;
      
      // Insert doses into database
      if (doses.length > 0) {
        await db.insert(medicalDoses).values(doses);
      }

      // Sync medical records to backup (non-blocking)
      try {
        const { syncAnimalMedicalRecords } = await import('./lib/animalBackupService');
        syncAnimalMedicalRecords(req.tenant!.id, req.params.animalId)
          .catch(err => console.error('[MEDICAL BACKUP] Background sync failed:', err));
      } catch (syncError) {
        console.error('[MEDICAL BACKUP] Failed to initiate sync:', syncError);
      }

      res.json({ prescription, dosesCreated: doses.length, isHistorical });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/medical/prescriptions/:prescriptionId
   * Update a prescription
   */
  app.patch('/api/medical/prescriptions/:prescriptionId', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalPrescriptions, insertMedicalPrescriptionSchema } = await import('@shared/schema');
      
      // First, fetch the prescription to get animalId for permission check
      const [existingPrescription] = await db
        .select()
        .from(medicalPrescriptions)
        .where(and(
          eq(medicalPrescriptions.id, req.params.prescriptionId),
          eq(medicalPrescriptions.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!existingPrescription) {
        return res.status(404).json({ error: 'Prescription not found' });
      }

      // Check permissions
      const permissions = await checkMedicalRecordPermissions(
        req.user!.id,
        existingPrescription.animalId,
        req.tenant!.id,
        req.user!.roles
      );

      if (!permissions.canEdit) {
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'You do not have permission to edit medical records for this animal'
        });
      }
      
      // Pre-process: convert empty strings to undefined for optional/typed fields before Zod validation
      const bodyToValidate = { ...req.body };
      const optionalFields = ["endDate", "nextScheduledDose", "billPaymentStatus", "billAmount", "billPaidAmount", "grantId", "billVendor", "billInvoiceNumber", "billNotes", "notes"];
      for (const field of optionalFields) {
        if (bodyToValidate[field] === "" || bodyToValidate[field] === null) {
          delete bodyToValidate[field];
        }
      }
      
      const parsed = insertMedicalPrescriptionSchema.partial().parse(bodyToValidate);
      
      // Exclude immutable fields
      const { tenantId, animalId, createdBy, createdAt, ...data } = parsed;
      
      // Handle endDate removal - if it was empty/null in original request, set to null in database
      if (req.body.endDate === '' || req.body.endDate === null) {
        (data as any).endDate = null;
      }
      
      // Handle nextScheduledDose removal - if it was empty/null in original request, set to null in database
      // This is important for "once only" medications that have already been given
      if (req.body.nextScheduledDose === '' || req.body.nextScheduledDose === null) {
        (data as any).nextScheduledDose = null;
      }

      // Handle clearing of optional fields - set to null in database when user removes the value
      const nullableFields = ['billPaymentStatus', 'billVendor', 'billInvoiceNumber', 'billNotes', 'notes', 'billAmount', 'billPaidAmount', 'grantId'];
      for (const field of nullableFields) {
        if (req.body[field] === '' || req.body[field] === null) {
          (data as any)[field] = null;
        }
      }

      // Check if schedule-affecting fields are actually changing (compare old vs new values)
      const frequencyChanged = data.frequency !== undefined && data.frequency !== existingPrescription.frequency;
      
      // Check if nextScheduledDose is being cleared (set to null for already-given once-only meds)
      const nextDoseCleared = (req.body.nextScheduledDose === '' || req.body.nextScheduledDose === null) && existingPrescription.nextScheduledDose !== null;
      const nextDoseChanged = data.nextScheduledDose !== undefined && data.nextScheduledDose !== null && (
        !existingPrescription.nextScheduledDose ||
        new Date(data.nextScheduledDose).getTime() !== new Date(existingPrescription.nextScheduledDose).getTime()
      );
      
      const startDateChanged = data.startDate !== undefined && 
        new Date(data.startDate).getTime() !== new Date(existingPrescription.startDate).getTime();
      
      const endDateCleared = (req.body.endDate === '' || req.body.endDate === null) && existingPrescription.endDate !== null;
      const endDateSet = data.endDate !== undefined && (
        !existingPrescription.endDate ||
        new Date(data.endDate).getTime() !== new Date(existingPrescription.endDate).getTime()
      );
      
      const scheduleFieldsChanged = frequencyChanged || nextDoseCleared || nextDoseChanged || startDateChanged || endDateCleared || endDateSet;
      
      console.log(`[PRESCRIPTION-UPDATE] Updating prescription ${req.params.prescriptionId}`);
      console.log(`[PRESCRIPTION-UPDATE]   frequencyChanged: ${frequencyChanged} (${existingPrescription.frequency} -> ${data.frequency})`);
      console.log(`[PRESCRIPTION-UPDATE]   scheduleFieldsChanged: ${scheduleFieldsChanged} (freq:${frequencyChanged}, nextDoseCleared:${nextDoseCleared}, nextDoseChanged:${nextDoseChanged}, startDateChanged:${startDateChanged}, endDateCleared:${endDateCleared}, endDateSet:${endDateSet})`);

      const [prescription] = await db
        .update(medicalPrescriptions)
        .set({ ...data, lastEditedAt: new Date(), lastEditedBy: req.user!.id })
        .where(and(
          eq(medicalPrescriptions.id, req.params.prescriptionId),
          eq(medicalPrescriptions.tenantId, req.tenant!.id)
        ))
        .returning();

      // Regenerate doses if schedule-affecting fields changed
      let dosesRegenerated = false;
      let regenerateResult = { deletedCount: 0, createdCount: 0 };
      
      if (scheduleFieldsChanged) {
        const { regeneratePrescriptionDoses } = await import('./lib/dose-generator');
        regenerateResult = await regeneratePrescriptionDoses({
          prescription,
          tenant: req.tenant!,
          tenantId: req.tenant!.id,
        });
        dosesRegenerated = true;
      }

      res.json({ 
        prescription,
        dosesRegenerated,
        ...(dosesRegenerated ? { 
          dosesDeleted: regenerateResult.deletedCount,
          dosesCreated: regenerateResult.createdCount 
        } : {}),
      });
    } catch (error) {
      next(error);
    }
  });

