  /**
   * GET /api/medical/doses/by-foster
   * Get medication doses grouped by foster household (for staff view)
   */
  app.get('/api/medical/doses/by-foster', requireTenant, requireAuth, requireRole('admin', 'staff', 'board_member'), async (req, res, next) => {
    try {
      const { medicalDoses, medicalPrescriptions, animals, fosterAnimals, users } = await import('@shared/schema');
      
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);

      // Get all active foster assignments with their animals
      const activeFosters = await db
        .select({
          fosterAssignmentId: fosterAnimals.id,
          fosterId: fosterAnimals.fosterId,
          fosterName: users.fullName,
          fosterEmail: users.email,
          fosterPhone: users.phone,
          animalId: fosterAnimals.animalId,
          animalName: animals.name,
          animalSpecies: animals.species,
          animalPhotoUrls: animals.photoUrls,
        })
        .from(fosterAnimals)
        .innerJoin(users, eq(fosterAnimals.fosterId, users.id))
        .innerJoin(animals, eq(fosterAnimals.animalId, animals.id))
        .where(and(
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.status, 'active')
        ));

      if (activeFosters.length === 0) {
        return res.json({ fosterGroups: [] });
      }

      // Get all animal IDs that are in foster care
      const fosterAnimalIds = activeFosters.map(f => f.animalId);

      // Get all due/overdue doses for fostered animals
      const doses = await db
        .select({
          id: medicalDoses.id,
          prescriptionId: medicalDoses.prescriptionId,
          dueDate: medicalDoses.dueDate,
          status: medicalDoses.status,
          givenAt: medicalDoses.givenAt,
          notes: medicalDoses.notes,
          medicationName: medicalPrescriptions.medicationName,
          dosage: medicalPrescriptions.dosage,
          route: medicalPrescriptions.route,
          frequency: medicalPrescriptions.frequency,
          isControlledSubstance: medicalPrescriptions.isControlledSubstance,
          requiresRefill: medicalPrescriptions.requiresRefill,
          animalId: medicalPrescriptions.animalId,
        })
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .where(and(
          eq(medicalDoses.tenantId, req.tenant!.id),
          eq(medicalDoses.status, 'due'),
          inArray(medicalPrescriptions.animalId, fosterAnimalIds),
          lt(medicalDoses.dueDate, tomorrow) // Due today or overdue
        ))
        .orderBy(medicalDoses.dueDate);

      // Group doses by foster
      const fosterMap = new Map<string, {
        fosterId: string;
        fosterName: string;
        fosterEmail: string;
        fosterPhone: string | null;
        animals: Map<string, {
          animalId: string;
          animalName: string;
          animalSpecies: string;
          animalPhotoUrl: string | null;
          doses: typeof doses;
        }>;
      }>();

      // Initialize foster groups
      for (const foster of activeFosters) {
        if (!fosterMap.has(foster.fosterId)) {
          fosterMap.set(foster.fosterId, {
            fosterId: foster.fosterId,
            fosterName: foster.fosterName,
            fosterEmail: foster.fosterEmail,
            fosterPhone: foster.fosterPhone,
            animals: new Map(),
          });
        }
        const fosterGroup = fosterMap.get(foster.fosterId)!;
        if (!fosterGroup.animals.has(foster.animalId)) {
          fosterGroup.animals.set(foster.animalId, {
            animalId: foster.animalId,
            animalName: foster.animalName,
            animalSpecies: foster.animalSpecies,
            animalPhotoUrl: foster.animalPhotoUrls?.[0] || null,
            doses: [],
          });
        }
      }

      // Assign doses to their animals/fosters
      for (const dose of doses) {
        // Find the foster who has this animal
        const fosterForAnimal = activeFosters.find(f => f.animalId === dose.animalId);
        if (fosterForAnimal) {
          const fosterGroup = fosterMap.get(fosterForAnimal.fosterId);
          const animalGroup = fosterGroup?.animals.get(dose.animalId);
          if (animalGroup) {
            animalGroup.doses.push(dose);
          }
        }
      }

      // Convert to array format and filter out fosters with no doses
      const fosterGroups = Array.from(fosterMap.values())
        .map(foster => ({
          fosterId: foster.fosterId,
          fosterName: foster.fosterName,
          fosterEmail: foster.fosterEmail,
          fosterPhone: foster.fosterPhone,
          animals: Array.from(foster.animals.values()).filter(a => a.doses.length > 0),
          totalDoses: Array.from(foster.animals.values()).reduce((sum, a) => sum + a.doses.length, 0),
        }))
        .filter(f => f.totalDoses > 0)
        .sort((a, b) => b.totalDoses - a.totalDoses); // Most doses first

      res.json({ fosterGroups });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/foster-portal/medications
   * Get consolidated medication view for the logged-in foster's animals
   */
  app.get('/api/foster-portal/medications', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalDoses, medicalPrescriptions, animals, fosterAnimals } = await import('@shared/schema');
      
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);

      // Get all animals currently fostered by this user
      const myFosterAnimals = await db
        .select({
          animalId: fosterAnimals.animalId,
          animalName: animals.name,
          animalSpecies: animals.species,
          animalPhotoUrls: animals.photoUrls,
        })
        .from(fosterAnimals)
        .innerJoin(animals, eq(fosterAnimals.animalId, animals.id))
        .where(and(
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.fosterId, req.user!.id),
          eq(fosterAnimals.status, 'active')
        ));

      if (myFosterAnimals.length === 0) {
        return res.json({ 
          animals: [],
          summary: { overdue: 0, dueToday: 0, completed: 0 }
        });
      }

      const animalIds = myFosterAnimals.map(a => a.animalId);

      // Get all doses for these animals (overdue and due today)
      const allDoses = await db
        .select({
          id: medicalDoses.id,
          prescriptionId: medicalDoses.prescriptionId,
          dueDate: medicalDoses.dueDate,
          status: medicalDoses.status,
          givenAt: medicalDoses.givenAt,
          notes: medicalDoses.notes,
          medicationName: medicalPrescriptions.medicationName,
          dosage: medicalPrescriptions.dosage,
          route: medicalPrescriptions.route,
          frequency: medicalPrescriptions.frequency,
          prescriptionNotes: medicalPrescriptions.notes,
          animalId: medicalPrescriptions.animalId,
        })
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .where(and(
          eq(medicalDoses.tenantId, req.tenant!.id),
          inArray(medicalPrescriptions.animalId, animalIds),
          lt(medicalDoses.dueDate, tomorrow)
        ))
        .orderBy(medicalDoses.dueDate);

      // Group doses by animal with overdue/due today categorization
      const now = new Date();
      const animalsWithMeds = myFosterAnimals.map(animal => {
        const animalDoses = allDoses.filter(d => d.animalId === animal.animalId);
        const overdue = animalDoses.filter(d => d.status === 'due' && new Date(d.dueDate) < today);
        const dueToday = animalDoses.filter(d => d.status === 'due' && new Date(d.dueDate) >= today && new Date(d.dueDate) < tomorrow);
        const completedToday = animalDoses.filter(d => d.status === 'given' && d.givenAt && new Date(d.givenAt) >= today);

        return {
          animalId: animal.animalId,
          animalName: animal.animalName,
          animalSpecies: animal.animalSpecies,
          animalPhotoUrl: animal.animalPhotoUrls?.[0] || null,
          overdue,
          dueToday,
          completedToday,
        };
      }).filter(a => a.overdue.length > 0 || a.dueToday.length > 0 || a.completedToday.length > 0);

      // Calculate summary
      const summary = {
        overdue: animalsWithMeds.reduce((sum, a) => sum + a.overdue.length, 0),
        dueToday: animalsWithMeds.reduce((sum, a) => sum + a.dueToday.length, 0),
        completed: animalsWithMeds.reduce((sum, a) => sum + a.completedToday.length, 0),
      };

      res.json({ animals: animalsWithMeds, summary });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/foster-portal/preventative-care
   * Get preventative care items for the logged-in foster's animals
   */
  app.get('/api/foster-portal/preventative-care', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords, preventativeCareTypes, animals, fosterAnimals } = await import('@shared/schema');
      
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const futureDate = new Date();
      futureDate.setDate(futureDate.getDate() + 7);
      futureDate.setHours(23, 59, 59, 999);

      // Get all animals currently fostered by this user
      const myFosterAnimals = await db
        .select({
          animalId: fosterAnimals.animalId,
          animalName: animals.name,
          animalSpecies: animals.species,
          animalPhotoUrls: animals.photoUrls,
        })
        .from(fosterAnimals)
        .innerJoin(animals, eq(fosterAnimals.animalId, animals.id))
        .where(and(
          eq(fosterAnimals.tenantId, req.tenant!.id),
          eq(fosterAnimals.fosterId, req.user!.id),
          eq(fosterAnimals.status, 'active')
        ));

      if (myFosterAnimals.length === 0) {
        return res.json({ overdue: [], dueToday: [], comingSoon: [] });
      }

      const animalIds = myFosterAnimals.map(a => a.animalId);
      const animalMap = new Map(myFosterAnimals.map(a => [a.animalId, a]));

      // Get all preventative care records for these animals that are due within 7 days or overdue
      // Filter out records with null nextDueDate (one-time items already completed)
      const records = await db
        .select({
          id: preventativeCareRecords.id,
          animalId: preventativeCareRecords.animalId,
          nextDueDate: preventativeCareRecords.nextDueDate,
          dateAdministered: preventativeCareRecords.dateAdministered,
          careName: preventativeCareTypes.name,
          careCategory: preventativeCareTypes.category,
          isCore: preventativeCareTypes.isCore,
        })
        .from(preventativeCareRecords)
        .innerJoin(preventativeCareTypes, eq(preventativeCareRecords.careTypeId, preventativeCareTypes.id))
        .where(and(
          eq(preventativeCareRecords.tenantId, req.tenant!.id),
          inArray(preventativeCareRecords.animalId, animalIds),
          isNotNull(preventativeCareRecords.nextDueDate),
          lte(preventativeCareRecords.nextDueDate, futureDate)
        ))
        .orderBy(preventativeCareRecords.nextDueDate);

      // Categorize into overdue, due today, coming soon
      interface PreventativeCareItem {
        record: {
          id: string;
          animalId: string;
          careName: string;
          careCategory: string;
          nextDueDate: Date | null;
          dateAdministered: Date | null;
          isCore: boolean;
        };
        animal: {
          id: string;
          name: string;
          species: string;
          photoUrls: string[] | null;
        };
      }
      
      const overdue: PreventativeCareItem[] = [];
      const dueToday: PreventativeCareItem[] = [];
      const comingSoon: PreventativeCareItem[] = [];

      records.forEach(record => {
        const animal = animalMap.get(record.animalId);
        // Skip records where animal info is missing (shouldn't happen with inner join but be safe)
        if (!animal) return;

        const dueDate = new Date(record.nextDueDate!);
        dueDate.setHours(0, 0, 0, 0);

        const item: PreventativeCareItem = {
          record: {
            id: record.id,
            animalId: record.animalId,
            careName: record.careName,
            careCategory: record.careCategory,
            nextDueDate: record.nextDueDate,
            dateAdministered: record.dateAdministered,
            isCore: record.isCore,
          },
          animal: {
            id: animal.animalId,
            name: animal.animalName,
            species: animal.animalSpecies,
            photoUrls: animal.animalPhotoUrls,
          },
        };

        if (dueDate < today) {
          overdue.push(item);
        } else if (dueDate.getTime() === today.getTime()) {
          dueToday.push(item);
        } else {
          comingSoon.push(item);
        }
      });

      res.json({ overdue, dueToday, comingSoon });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/medical/doses/:doseId/administer
   * Mark a dose as administered
   */
  app.patch('/api/medical/doses/:doseId/administer', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalDoses } = await import('@shared/schema');
      
      const updateSchema = z.object({
        notes: z.string().optional(),
        administeredAt: z.string().optional(),
      });

      const { notes, administeredAt } = updateSchema.parse(req.body);

      let givenAtDate = new Date();
      if (administeredAt) {
        givenAtDate = new Date(administeredAt);
        if (isNaN(givenAtDate.getTime())) {
          return res.status(400).json({ error: 'Invalid administeredAt date' });
        }
        const fiveMinutesFromNow = new Date(Date.now() + 5 * 60 * 1000);
        if (givenAtDate > fiveMinutesFromNow) {
          return res.status(400).json({ error: 'Cannot chart a dose in the future. Please select a current or past date/time.' });
        }
      }

      const [dose] = await db
        .update(medicalDoses)
        .set({
          status: 'given',
          givenAt: givenAtDate,
          administeredBy: req.user!.id,
          notes,
        })
        .where(and(
          eq(medicalDoses.id, req.params.doseId),
          eq(medicalDoses.tenantId, req.tenant!.id)
        ))
        .returning();

      if (!dose) {
        return res.status(404).json({ error: 'Dose not found' });
      }

      // Advance nextScheduledDose for recurring prescriptions
      if (dose.prescriptionId) {
        const { medicalPrescriptions } = await import('@shared/schema');
        const [prescription] = await db
          .select()
          .from(medicalPrescriptions)
          .where(and(
            eq(medicalPrescriptions.id, dose.prescriptionId),
            eq(medicalPrescriptions.tenantId, req.tenant!.id)
          ));

        if (prescription && prescription.frequency && prescription.frequency.toUpperCase() !== 'ONCE') {
          const protocol: ProtocolTimes = {
            morning: req.tenant?.defaultMorningRounds || '08:00',
            midday: req.tenant?.defaultMiddayRounds || '13:00',
            evening: req.tenant?.defaultEveningRounds || '17:00',
          };
          const nextDose = computeNextScheduledDose(givenAtDate, prescription.frequency, protocol);
          if (nextDose && (!prescription.endDate || isSameDayOrMissing(prescription.endDate, prescription.startDate) || nextDose <= new Date(prescription.endDate))) {
            await db
              .update(medicalPrescriptions)
              .set({ nextScheduledDose: nextDose })
              .where(eq(medicalPrescriptions.id, prescription.id));
          }
        }
      }

      res.json({ dose });
    } catch (error) {
      next(error);
    }
  });


  /**
   * GET /api/medical/prescriptions/:prescriptionId/doses
   * Get all doses for a specific prescription
   */
  app.get('/api/medical/prescriptions/:prescriptionId/doses', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalDoses } = await import('@shared/schema');

      const rawDoses = await db
        .select()
        .from(medicalDoses)
        .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
        .innerJoin(animals, eq(medicalPrescriptions.animalId, animals.id))
        .where(and(
          eq(medicalDoses.prescriptionId, req.params.prescriptionId),
          eq(medicalDoses.tenantId, req.tenant!.id),
          inArray(medicalDoses.status, ['given', 'skipped', 'missed', 'unable'])
        ))
        .orderBy(desc(medicalDoses.givenAt));

      const adminIds = [...new Set(rawDoses.map(d => d.medical_doses.administeredBy).filter(Boolean))] as string[];
      let userNameMap: Record<string, string> = {};
      if (adminIds.length > 0) {
        const adminUsers = await db
          .select({ id: users.id, fullName: users.fullName })
          .from(users)
          .where(inArray(users.id, adminIds));
        userNameMap = Object.fromEntries(adminUsers.map(u => [u.id, u.fullName]));
      }

      const doses = rawDoses.map(d => ({
        id: d.medical_doses.id,
        prescriptionId: d.medical_doses.prescriptionId,
        dueDate: d.medical_doses.dueDate,
        status: d.medical_doses.status,
        givenAt: d.medical_doses.givenAt,
        administeredBy: d.medical_doses.administeredBy,
        completionMethod: d.medical_doses.completionMethod,
        notes: d.medical_doses.notes,
        unableReason: d.medical_doses.unableReason,
        createdAt: d.medical_doses.createdAt,
        administeredByName: d.medical_doses.administeredBy ? (userNameMap[d.medical_doses.administeredBy] || null) : null,
      }));

      res.json({ doses });
    } catch (error) {
      next(error);
    }
  });

  // Helper: compute next scheduled dose based on frequency
  interface ProtocolTimes {
    morning: string;
    midday: string;
    evening: string;
  }

  function parseTimeToMinutes(time: string): number {
    const [h, m] = time.split(':').map(Number);
    return h * 60 + m;
  }

  function setTimeOnDate(date: Date, timeStr: string): Date {
    const result = new Date(date);
    const [h, m] = timeStr.split(':').map(Number);
    result.setHours(h, m, 0, 0);
    return result;
  }


  function isSameDayOrMissing(d1: Date | null, d2: Date | null): boolean {
    if (!d1 || !d2) return true;
    return d1.toISOString().split('T')[0] === d2.toISOString().split('T')[0];
  }

  function computeNextScheduledDose(
    lastGivenAt: Date,
    frequency: string,
    protocol: ProtocolTimes = { morning: '08:00', midday: '13:00', evening: '17:00' }
  ): Date | null {
    const now = lastGivenAt;
    const freq = frequency.toUpperCase();

    let roundTimes: string[];
    switch (freq) {
      case 'SID':
        roundTimes = [protocol.morning];
        break;
      case 'BID':
        roundTimes = [protocol.morning, protocol.evening];
        break;
      case 'TID':
        roundTimes = [protocol.morning, protocol.midday, protocol.evening];
        break;
      case 'QID': {
        const eveningMins = parseTimeToMinutes(protocol.evening);
        const lateRoundMins = eveningMins + Math.round((1440 - eveningMins + parseTimeToMinutes(protocol.morning)) / 2);
        const lateHour = Math.floor((lateRoundMins % 1440) / 60);
        const lateMin = (lateRoundMins % 1440) % 60;
        const lateRound = `${String(lateHour).padStart(2, '0')}:${String(lateMin).padStart(2, '0')}`;
        roundTimes = [protocol.morning, protocol.midday, protocol.evening, lateRound];
        break;
      }
      case 'EOD': {
        const next = new Date(now);
        next.setDate(next.getDate() + 2);
        return setTimeOnDate(next, protocol.morning);
      }
      case 'WEEKLY': {
        const next = new Date(now);
        next.setDate(next.getDate() + 7);
        return setTimeOnDate(next, protocol.morning);
      }
      case 'BIWEEKLY': {
        const next = new Date(now);
        next.setDate(next.getDate() + 14);
        return setTimeOnDate(next, protocol.morning);
      }
      case 'MONTHLY': {
        const next = new Date(now);
        next.setMonth(next.getMonth() + 1);
        return setTimeOnDate(next, protocol.morning);
      }
      case 'ANNUALLY': {
        const next = new Date(now);
        next.setFullYear(next.getFullYear() + 1);
        return setTimeOnDate(next, protocol.morning);
      }
      case 'Q6M': {
        const next = new Date(now);
        next.setMonth(next.getMonth() + 6);
        return setTimeOnDate(next, protocol.morning);
      }
      case 'PRN':
      case 'ONCE':
        return null;
      default:
        return null;
    }

    roundTimes.sort((a, b) => parseTimeToMinutes(a) - parseTimeToMinutes(b));

    for (const rt of roundTimes) {
      const candidate = setTimeOnDate(now, rt);
      if (candidate > now) {
        return candidate;
      }
    }

    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    return setTimeOnDate(tomorrow, roundTimes[0]);
  }

  /**
   * POST /api/medical/prescriptions/:prescriptionId/doses
   * Create an ad-hoc dose record (for charting from the animal medical page)
   */
  app.post('/api/medical/prescriptions/:prescriptionId/doses', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalDoses, medicalPrescriptions } = await import('@shared/schema');

      const createSchema = z.object({
        administeredAt: z.string(),
        notes: z.string().optional(),
        status: z.enum(['given', 'skipped', 'unable']).default('given'),
        unableReason: z.enum(['animal_sick', 'unable_to_swallow', 'other']).optional(),
      });

      const { administeredAt, notes, status, unableReason } = createSchema.parse(req.body);

      const givenAtDate = new Date(administeredAt);
      if (isNaN(givenAtDate.getTime())) {
        return res.status(400).json({ error: 'Invalid administeredAt date' });
      }
      const fiveMinutesFromNow = new Date(Date.now() + 5 * 60 * 1000);
      if (givenAtDate > fiveMinutesFromNow) {
        return res.status(400).json({ error: 'Cannot chart a dose in the future. Please select a current or past date/time.' });
      }

      const [prescription] = await db
        .select()
        .from(medicalPrescriptions)
        .where(and(
          eq(medicalPrescriptions.id, req.params.prescriptionId),
          eq(medicalPrescriptions.tenantId, req.tenant!.id)
        ));

      if (!prescription) {
        return res.status(404).json({ error: 'Prescription not found' });
      }

      const [dose] = await db
        .insert(medicalDoses)
        .values({
          prescriptionId: req.params.prescriptionId,
          tenantId: req.tenant!.id,
          dueDate: givenAtDate,
          status,
          givenAt: status === 'given' ? givenAtDate : null,
          administeredBy: req.user!.id,
          notes: notes || null,
          unableReason: unableReason || null,
        })
        .returning();

      // Advance nextScheduledDose for recurring prescriptions
      if (status === 'given' && prescription.frequency && prescription.frequency.toUpperCase() !== 'ONCE') {
        const protocol: ProtocolTimes = {
          morning: req.tenant?.defaultMorningRounds || '08:00',
          midday: req.tenant?.defaultMiddayRounds || '13:00',
          evening: req.tenant?.defaultEveningRounds || '17:00',
        };
        const nextDose = computeNextScheduledDose(givenAtDate, prescription.frequency, protocol);
        if (nextDose && (!prescription.endDate || isSameDayOrMissing(prescription.endDate, prescription.startDate) || nextDose <= new Date(prescription.endDate))) {
          await db
            .update(medicalPrescriptions)
            .set({ nextScheduledDose: nextDose })
            .where(eq(medicalPrescriptions.id, prescription.id));
        }
      }

      res.json({ dose });
    } catch (error) {
      next(error);
    }
  });
