  /**
   * POST /api/vet-visits/upload
   * Upload documents for a vet visit (foster-accessible)
   */
  app.post('/api/vet-visits/upload', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { ObjectStorageService } = await import('./objectStorage');
      const { randomUUID } = await import('crypto');

      const allowedExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'heif', 'pdf'];

      const upload = multer({
        storage: multer.memoryStorage(),
        limits: { fileSize: 15 * 1024 * 1024 },
        fileFilter: (_req, file, cb) => {
          if (file.mimetype.startsWith('image/') || file.mimetype === 'application/pdf') {
            cb(null, true);
          } else {
            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext && allowedExtensions.includes(ext)) {
              cb(null, true);
            } else {
              cb(new Error('Only images and PDF files are allowed'));
            }
          }
        },
      }).array('files', 10);

      upload(req, res, async (err) => {
        if (err) {
          return res.status(400).json({ error: err.message });
        }

        const files = req.files as Express.Multer.File[];
        if (!files || files.length === 0) {
          return res.status(400).json({ error: 'No files uploaded' });
        }

        try {
          const objectStorageService = new ObjectStorageService();
          const { objectStorageClient } = await import('./objectStorage');
          const privateObjectDir = objectStorageService.getPrivateObjectDir();
          const uploadedPaths: string[] = [];

          for (const file of files) {
            let fileBuffer = file.buffer;
            let contentType = file.mimetype;

            const ext = file.originalname.toLowerCase().split('.').pop();
            if (ext === 'heic' || ext === 'heif' || file.mimetype === 'image/heic' || file.mimetype === 'image/heif') {
              try {
                const heicConvert = (await import('heic-convert')).default;
                const convertedBuffer = await heicConvert({
                  buffer: file.buffer,
                  format: 'JPEG',
                  quality: 0.9
                });
                fileBuffer = Buffer.from(convertedBuffer);
                contentType = 'image/jpeg';
              } catch (conversionError) {
                console.error('HEIC conversion failed, uploading original:', conversionError);
              }
            }

            const fileId = randomUUID();
            const fileExt = contentType === 'application/pdf' ? 'pdf' : (contentType === 'image/jpeg' ? 'jpg' : 'png');
            const filePath = `${privateObjectDir}/vet-visits/${req.tenant!.id}/${fileId}.${fileExt}`;

            await objectStorageClient.uploadFromBytes(filePath, fileBuffer, {
              metadata: { contentType },
            });

            uploadedPaths.push(filePath);
          }

          res.json({ uploadedPaths });
        } catch (error: any) {
          console.error('Error uploading vet visit documents:', error);
          return res.status(500).json({ error: 'Failed to upload files' });
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/vet-visits
   * Submit a vet visit (foster-accessible)
   */
  app.post('/api/vet-visits', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { vetVisits } = await import('@shared/schema');

      const createSchema = z.object({
        animalId: z.string().uuid(),
        visitDate: z.string(),
        clinicName: z.string().optional(),
        reason: z.string().min(1, 'Please describe the reason for the vet visit'),
        documentUrls: z.array(z.string()).default([]),
      });

      const data = createSchema.parse(req.body);

      const [visit] = await db
        .insert(vetVisits)
        .values({
          tenantId: req.tenant!.id,
          animalId: data.animalId,
          submittedBy: req.user!.id,
          visitDate: new Date(data.visitDate),
          clinicName: data.clinicName || null,
          reason: data.reason,
          documentUrls: data.documentUrls,
          status: 'pending',
        })
        .returning();

      res.json({ vetVisit: visit });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/vet-visits
   * Get all vet visits for the tenant (staff/admin)
   * Optionally filter by ?status=pending or ?animalId=xxx
   */
  app.get('/api/vet-visits', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { vetVisits } = await import('@shared/schema');
      const statusFilter = req.query.status as string | undefined;
      const animalIdFilter = req.query.animalId as string | undefined;
      const locationFilter = req.query.location as string | undefined;

      const conditions = [eq(vetVisits.tenantId, req.tenant!.id)];
      if (statusFilter) {
        conditions.push(eq(vetVisits.status, statusFilter));
      }
      if (animalIdFilter) {
        conditions.push(eq(vetVisits.animalId, animalIdFilter));
      }
      if (locationFilter === 'shelter') {
        conditions.push(or(ne(animals.locationType, 'foster'), isNull(animals.locationType))!);
      } else if (locationFilter === 'foster') {
        conditions.push(eq(animals.locationType, 'foster'));
      }

      const visits = await db
        .select({
          id: vetVisits.id,
          animalId: vetVisits.animalId,
          submittedBy: vetVisits.submittedBy,
          visitDate: vetVisits.visitDate,
          clinicName: vetVisits.clinicName,
          reason: vetVisits.reason,
          documentUrls: vetVisits.documentUrls,
          status: vetVisits.status,
          processedBy: vetVisits.processedBy,
          processedAt: vetVisits.processedAt,
          processedNotes: vetVisits.processedNotes,
          createdAt: vetVisits.createdAt,
          animalName: animals.name,
          animalSpecies: animals.species,
          animalBreed: animals.breed,
          animalPhotoUrls: animals.photoUrls,
          animalAnimalId: animals.animalId,
        })
        .from(vetVisits)
        .leftJoin(animals, eq(vetVisits.animalId, animals.id))
        .where(and(...conditions))
        .orderBy(desc(vetVisits.createdAt));

      const submitterIds = [...new Set(visits.map(v => v.submittedBy))];
      let submitterMap: Record<string, string> = {};
      if (submitterIds.length > 0) {
        const submitters = await db
          .select({ id: users.id, fullName: users.fullName })
          .from(users)
          .where(inArray(users.id, submitterIds));
        submitterMap = Object.fromEntries(submitters.map(u => [u.id, u.fullName]));
      }

      const enriched = visits.map(v => ({
        ...v,
        submittedByName: submitterMap[v.submittedBy] || 'Unknown',
      }));

      res.json({ vetVisits: enriched });
    } catch (error) {
      next(error);
    }
  });

