  // ===== PREVENTATIVE CARE ENDPOINTS =====

  /**
   * GET /api/medical/preventative-care/types
   * Get preventative care types (filtered by species)
   */
  app.get('/api/medical/preventative-care/types', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareTypes } = await import('@shared/schema');
      const { species } = req.query;

      let whereConditions = [
        eq(preventativeCareTypes.isActive, true),
        or(
          isNull(preventativeCareTypes.tenantId),
          eq(preventativeCareTypes.tenantId, req.tenant!.id)
        )
      ];

      // Filter by species if provided
      if (species === 'Dog' || species === 'Cat') {
        whereConditions.push(
          or(
            eq(preventativeCareTypes.targetSpecies, species),
            eq(preventativeCareTypes.targetSpecies, 'Both')
          )
        );
      }

      const types = await db
        .select()
        .from(preventativeCareTypes)
        .where(and(...whereConditions))
        .orderBy(asc(preventativeCareTypes.sortOrder), asc(preventativeCareTypes.name));

      // Deduplicate: tenant overrides take precedence over platform defaults
      const tenantOverrideKeys = new Set(
        types
          .filter((t: any) => t.tenantId === req.tenant!.id)
          .map((t: any) => `${t.name}::${t.category}`)
      );
      const deduped = types.filter((t: any) => {
        if (t.tenantId) return true;
        return !tenantOverrideKeys.has(`${t.name}::${t.category}`);
      });

      res.json({ types: deduped });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/medical/preventative-care/types/intervals
   * Batch-update default and puppy interval days for care types.
   * If a type is a platform default (tenantId is null), clone it as a tenant-specific override.
   */
  app.patch('/api/medical/preventative-care/types/intervals', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const userRoles = req.user?.roles || [];
      if (!userRoles.includes("admin") && !userRoles.includes("owner")) {
        return res.status(403).json({ message: "Only admins and owners can update medical protocols" });
      }

      const { preventativeCareTypes } = await import('@shared/schema');
      const { z } = await import('zod');

      const updateItemSchema = z.object({
        id: z.string().uuid(),
        defaultIntervalDays: z.number().int().min(1).nullable(),
        puppyIntervalDays: z.number().int().min(1).nullable(),
      });
      const bodySchema = z.object({
        updates: z.array(updateItemSchema).min(1),
      });

      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: 'Invalid request', errors: parsed.error.flatten().fieldErrors });
      }

      let updatedCount = 0;
      for (const update of parsed.data.updates) {
        const [existing] = await db
          .select()
          .from(preventativeCareTypes)
          .where(eq(preventativeCareTypes.id, update.id));

        if (!existing) continue;

        if (existing.tenantId && existing.tenantId !== req.tenant!.id) {
          continue;
        }

        if (!existing.tenantId) {
          const [tenantOverride] = await db
            .select()
            .from(preventativeCareTypes)
            .where(and(
              eq(preventativeCareTypes.tenantId, req.tenant!.id),
              eq(preventativeCareTypes.name, existing.name),
              eq(preventativeCareTypes.category, existing.category)
            ));

          if (tenantOverride) {
            await db
              .update(preventativeCareTypes)
              .set({
                defaultIntervalDays: update.defaultIntervalDays,
                puppyIntervalDays: update.puppyIntervalDays,
              })
              .where(eq(preventativeCareTypes.id, tenantOverride.id));
          } else {
            await db
              .insert(preventativeCareTypes)
              .values({
                tenantId: req.tenant!.id,
                name: existing.name,
                category: existing.category,
                targetSpecies: existing.targetSpecies,
                isCore: existing.isCore,
                defaultIntervalDays: update.defaultIntervalDays,
                puppyIntervalDays: update.puppyIntervalDays,
                coversHeartworm: existing.coversHeartworm,
                coversFleaTick: existing.coversFleaTick,
                description: existing.description,
                sortOrder: existing.sortOrder,
                isActive: existing.isActive,
                manufacturer: existing.manufacturer,
              });
          }
          updatedCount++;
        } else {
          await db
            .update(preventativeCareTypes)
            .set({
              defaultIntervalDays: update.defaultIntervalDays,
              puppyIntervalDays: update.puppyIntervalDays,
            })
            .where(eq(preventativeCareTypes.id, update.id));
          updatedCount++;
        }
      }

      res.json({ message: `Updated ${updatedCount} protocol(s)`, updatedCount });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/medical/preventative-care/types
   * Create a new tenant-specific preventative care product.
   */
  app.post('/api/medical/preventative-care/types', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const userRoles = req.user?.roles || [];
      if (!userRoles.includes("admin") && !userRoles.includes("owner")) {
        return res.status(403).json({ message: "Only admins and owners can add medical products" });
      }

      const { preventativeCareTypes } = await import('@shared/schema');
      const { z } = await import('zod');

      const bodySchema = z.object({
        name: z.string().min(1).max(200),
        targetSpecies: z.enum(["Dog", "Cat", "Both"]).default("Both"),
        defaultIntervalDays: z.number().int().min(1),
        puppyIntervalDays: z.number().int().min(1).nullable().default(null),
        coversHeartworm: z.boolean().default(false),
        coversFleaTick: z.boolean().default(false),
        manufacturer: z.string().max(200).nullable().default(null),
        description: z.string().max(1000).nullable().default(null),
      });

      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid request", errors: parsed.error.flatten().fieldErrors });
      }

      const data = parsed.data;
      const trimmedName = data.name.trim();
      const { targetSpecies, defaultIntervalDays, puppyIntervalDays, coversHeartworm, coversFleaTick, manufacturer, description } = data;

      const existing = await db
        .select()
        .from(preventativeCareTypes)
        .where(and(
          sql`LOWER(${preventativeCareTypes.name}) = LOWER(${trimmedName})`,
          eq(preventativeCareTypes.category, "parasite_prevention"),
          or(
            isNull(preventativeCareTypes.tenantId),
            eq(preventativeCareTypes.tenantId, req.tenant!.id)
          )
        ));

      if (existing.length > 0) {
        return res.status(409).json({ message: "A product with this name already exists" });
      }

      const maxSort = await db
        .select({ max: sql`COALESCE(MAX(sort_order), 0)` })
        .from(preventativeCareTypes)
        .where(or(
          isNull(preventativeCareTypes.tenantId),
          eq(preventativeCareTypes.tenantId, req.tenant!.id)
        ));
      const nextSort = (Number(maxSort[0]?.max) || 0) + 10;

      const [created] = await db
        .insert(preventativeCareTypes)
        .values({
          tenantId: req.tenant!.id,
          name: trimmedName,
          category: "parasite_prevention",
          targetSpecies,
          isCore: false,
          defaultIntervalDays,
          puppyIntervalDays,
          coversHeartworm,
          coversFleaTick,
          manufacturer,
          description,
          sortOrder: nextSort,
          isActive: true,
        })
        .returning();

      res.status(201).json({ type: created });
    } catch (error) {
      next(error);
    }
  });

  /**
   * DELETE /api/medical/preventative-care/types/:id
   * Delete a tenant-specific preventative care product. Cannot delete platform defaults.
   */
  app.delete('/api/medical/preventative-care/types/:id', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const userRoles = req.user?.roles || [];
      if (!userRoles.includes("admin") && !userRoles.includes("owner")) {
        return res.status(403).json({ message: "Only admins and owners can delete medical products" });
      }

      const { preventativeCareTypes } = await import('@shared/schema');

      const [existing] = await db
        .select()
        .from(preventativeCareTypes)
        .where(eq(preventativeCareTypes.id, req.params.id));

      if (!existing) {
        return res.status(404).json({ message: "Product not found" });
      }

      if (!existing.tenantId) {
        return res.status(403).json({ message: "Cannot delete platform default products" });
      }

      if (existing.category !== "parasite_prevention") {
        return res.status(400).json({ message: "Only parasite prevention products can be managed here" });
      }

      if (existing.tenantId !== req.tenant!.id) {
        return res.status(403).json({ message: "Cannot delete products from another organization" });
      }

      await db
        .delete(preventativeCareTypes)
        .where(eq(preventativeCareTypes.id, req.params.id));

      res.json({ message: "Product deleted" });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/medical/preventative-care/coming-due
   * Get preventative care coming due (overdue, due today, coming due in 7 days)
   */
  app.get('/api/medical/preventative-care/coming-due', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords, vaccineRecords: vaccineRecordsTable, animals, TERMINAL_STATUSES: TERMINAL_STATUSES_PC } = await import('@shared/schema');
      const locationFilter = req.query.location as string | undefined;
      const locationCondition = locationFilter === 'shelter' ? or(ne(animals.locationType, 'foster'), isNull(animals.locationType)) : locationFilter === 'foster' ? eq(animals.locationType, 'foster') : undefined;

      const now = new Date();
      const today = new Date(now);
      today.setHours(0, 0, 0, 0);
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);
      const sevenDaysOut = new Date(today);
      sevenDaysOut.setDate(sevenDaysOut.getDate() + 7);

      type ComingDueItem = {
        record: {
          id: string;
          tenantId: string | null;
          animalId: string;
          careTypeId: string | null;
          careName: string | null;
          careCategory: string | null;
          dateAdministered: Date | string | null;
          nextDueDate: Date | string | null;
          notes: string | null;
          createdBy: string | null;
          createdAt: Date | null;
          sourceTable?: 'preventative_care_records' | 'vaccine_records';
        };
        animal: {
          id: string;
          name: string | null;
          species: string | null;
          breed: string | null;
          photoUrls: string[] | null;
          status: string | null;
          locationName: string | null;
        };
      };

      const [preventativeRows, vaccineRows] = await Promise.all([
        db
          .select({
            record: {
              id: preventativeCareRecords.id,
              tenantId: preventativeCareRecords.tenantId,
              animalId: preventativeCareRecords.animalId,
              careTypeId: preventativeCareRecords.careTypeId,
              careName: preventativeCareRecords.careName,
              careCategory: preventativeCareRecords.careCategory,
              dateAdministered: preventativeCareRecords.dateAdministered,
              nextDueDate: preventativeCareRecords.nextDueDate,
              notes: preventativeCareRecords.notes,
              createdBy: preventativeCareRecords.createdBy,
              createdAt: preventativeCareRecords.createdAt,
            },
            animal: {
              id: animals.id,
              name: animals.name,
              species: animals.species,
              breed: animals.breed,
              photoUrls: animals.photoUrls,
              status: animals.status,
              locationName: animals.locationName,
            }
          })
          .from(preventativeCareRecords)
          .innerJoin(animals, eq(preventativeCareRecords.animalId, animals.id))
          .where(and(
            eq(preventativeCareRecords.tenantId, req.tenant!.id),
            isNotNull(preventativeCareRecords.nextDueDate),
            lte(preventativeCareRecords.nextDueDate, sevenDaysOut),
            notInArray(animals.status, TERMINAL_STATUSES_PC),
            ...(locationCondition ? [locationCondition] : [])
          ))
          .orderBy(asc(preventativeCareRecords.nextDueDate)),

        db
          .select({
            id: vaccineRecordsTable.id,
            tenantId: vaccineRecordsTable.tenantId,
            animalId: vaccineRecordsTable.animalId,
            itemName: vaccineRecordsTable.itemName,
            dateDue: vaccineRecordsTable.dateDue,
            createdAt: vaccineRecordsTable.createdAt,
            animalId2: animals.id,
            animalName: animals.name,
            animalSpecies: animals.species,
            animalBreed: animals.breed,
            animalPhotoUrls: animals.photoUrls,
            animalStatus: animals.status,
            animalLocation: animals.locationName,
          })
          .from(vaccineRecordsTable)
          .innerJoin(animals, eq(vaccineRecordsTable.animalId, animals.id))
          .where(and(
            eq(vaccineRecordsTable.tenantId, req.tenant!.id),
            isNotNull(vaccineRecordsTable.dateDue),
            lte(vaccineRecordsTable.dateDue, sevenDaysOut),
            notInArray(animals.status, TERMINAL_STATUSES_PC),
            ...(locationCondition ? [locationCondition] : [])
          )),
      ]);

      const vaccineMapped: ComingDueItem[] = vaccineRows.map(v => ({
        record: {
          id: v.id,
          tenantId: v.tenantId,
          animalId: v.animalId,
          careTypeId: null,
          careName: v.itemName,
          careCategory: 'vaccine',
          dateAdministered: null,
          nextDueDate: v.dateDue,
          notes: null,
          createdBy: null,
          createdAt: v.createdAt,
          sourceTable: 'vaccine_records' as const,
        },
        animal: {
          id: v.animalId2,
          name: v.animalName,
          species: v.animalSpecies,
          breed: v.animalBreed,
          photoUrls: v.animalPhotoUrls,
          status: v.animalStatus,
          locationName: v.animalLocation,
        },
      }));

      const preventativeMapped: ComingDueItem[] = preventativeRows.map(r => ({
        record: { ...r.record, sourceTable: 'preventative_care_records' as const },
        animal: r.animal,
      }));

      const allRecords = [...preventativeMapped, ...vaccineMapped].sort((a, b) => {
        const aDate = a.record.nextDueDate ? new Date(a.record.nextDueDate as string | Date).getTime() : 0;
        const bDate = b.record.nextDueDate ? new Date(b.record.nextDueDate as string | Date).getTime() : 0;
        return aDate - bDate;
      });

      const overdue: ComingDueItem[] = [];
      const dueToday: ComingDueItem[] = [];
      const comingSoon: ComingDueItem[] = [];

      for (const item of allRecords) {
        const dueDate = new Date(item.record.nextDueDate as string | Date);
        dueDate.setHours(0, 0, 0, 0);

        if (dueDate < today) {
          overdue.push(item);
        } else if (dueDate >= today && dueDate < tomorrow) {
          dueToday.push(item);
        } else {
          comingSoon.push(item);
        }
      }

      res.json({ overdue, dueToday, comingSoon });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/medical/preventative-care/records
   * Add a new preventative care record
   */
  app.post('/api/medical/preventative-care/records', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords, preventativeCareTypes, insertPreventativeCareRecordSchema, animals } = await import('@shared/schema');

      const createFollowUp = req.body.createFollowUp === true;

      // Make careName, careCategory, and tenantId optional in parse — server derives/overrides them
      const { z } = await import('zod');
      const tolerantSchema = insertPreventativeCareRecordSchema.extend({
        careName: z.string().optional(),
        careCategory: z.string().optional(),
        tenantId: z.string().uuid().optional(),
      });
      const data = tolerantSchema.parse(req.body);

      // Get care type info for interval calculation and coverage flags
      let intervalDays: number | null = null;
      let careTypeInfo: { coversHeartworm: boolean; coversFleaTick: boolean } | null = null;
      let resolvedCareName = data.careName || 'Preventative Care';
      let resolvedCareCategory = (data as any).careCategory || 'other';

      if (data.careTypeId) {
        const [careType] = await db
          .select()
          .from(preventativeCareTypes)
          .where(eq(preventativeCareTypes.id, data.careTypeId))
          .limit(1);
        if (careType) {
          // Age-aware interval: use puppyIntervalDays if animal is under 6 months
          let usePuppyInterval = false;
          if (careType.puppyIntervalDays != null && data.animalId) {
            const [animalForAge] = await db.select({ dateOfBirth: animals.dateOfBirth }).from(animals).where(eq(animals.id, data.animalId)).limit(1);
            if (animalForAge?.dateOfBirth) {
              const ageMs = Date.now() - new Date(animalForAge.dateOfBirth).getTime();
              const sixMonthsMs = 6 * 30.44 * 24 * 60 * 60 * 1000;
              usePuppyInterval = ageMs < sixMonthsMs;
            }
          }
          intervalDays = usePuppyInterval ? careType.puppyIntervalDays : careType.defaultIntervalDays;
          careTypeInfo = { coversHeartworm: careType.coversHeartworm, coversFleaTick: careType.coversFleaTick };
          if (!data.careName) {
            resolvedCareName = careType.name;
          }
          if (!(data as any).careCategory) {
            resolvedCareCategory = careType.category;
          }
        }
      }

      // Calculate next due date if interval exists
      let nextDueDate: Date | null = null;
      if (intervalDays && data.dateAdministered) {
        nextDueDate = new Date(data.dateAdministered);
        nextDueDate.setDate(nextDueDate.getDate() + intervalDays);
      }

      const effectiveNextDueDate = data.nextDueDate || nextDueDate;

      // Auto-set status to pending for future-dated orders
      const prevTodayEnd = new Date();
      prevTodayEnd.setHours(23, 59, 59, 999);
      const isPrevFutureDate = new Date(data.dateAdministered) > prevTodayEnd;

      const [record] = await db
        .insert(preventativeCareRecords)
        .values({
          ...data,
          careName: resolvedCareName,
          careCategory: resolvedCareCategory as any,
          tenantId: req.tenant!.id,
          nextDueDate: effectiveNextDueDate,
          createdBy: req.user!.id,
          status: isPrevFutureDate ? 'pending' : (data.status || 'given'),
        })
        .returning();

      // Update animal's medicalDueDates cache if the care type covers heartworm or flea/tick
      if (careTypeInfo && effectiveNextDueDate && data.animalId && (careTypeInfo.coversHeartworm || careTypeInfo.coversFleaTick)) {
        try {
          const [animal] = await db
            .select()
            .from(animals)
            .where(eq(animals.id, data.animalId))
            .limit(1);

          const currentDueDates = (animal?.medicalDueDates as any) || {};
          const dueDateStr = effectiveNextDueDate instanceof Date
            ? effectiveNextDueDate.toISOString()
            : new Date(effectiveNextDueDate as any).toISOString();

          const updatedDueDates = { ...currentDueDates };

          if (careTypeInfo.coversHeartworm) {
            if (!updatedDueDates.heartwormDueDate || new Date(dueDateStr) > new Date(updatedDueDates.heartwormDueDate)) {
              updatedDueDates.heartwormDueDate = dueDateStr;
            }
          }
          if (careTypeInfo.coversFleaTick) {
            if (!updatedDueDates.fleaTickDueDate || new Date(dueDateStr) > new Date(updatedDueDates.fleaTickDueDate)) {
              updatedDueDates.fleaTickDueDate = dueDateStr;
            }
          }

          if (updatedDueDates && typeof updatedDueDates === 'object' && Object.keys(updatedDueDates).length > 0) {
            await db
              .update(animals)
              .set({ medicalDueDates: updatedDueDates })
              .where(eq(animals.id, data.animalId));
          }
        } catch (cacheError) {
          console.error('[PreventativeCare] Failed to update medicalDueDates cache:', cacheError);
        }
      }


      // Create a follow-up pending record for the next due date
      if (createFollowUp && effectiveNextDueDate && data.animalId && data.careTypeId) {
        try {
          const followUpDate = effectiveNextDueDate instanceof Date
            ? effectiveNextDueDate.toISOString().split("T")[0]
            : new Date(effectiveNextDueDate).toISOString().split("T")[0];

          // Calculate the next interval due date for the follow-up record itself
          let followUpNextDue: Date | null = null;
          if (intervalDays) {
            followUpNextDue = new Date(followUpDate);
            followUpNextDue.setDate(followUpNextDue.getDate() + intervalDays);
          }

          await db
            .insert(preventativeCareRecords)
            .values({
              animalId: data.animalId,
              tenantId: req.tenant!.id,
              careTypeId: data.careTypeId,
              dateAdministered: followUpDate,
              nextDueDate: followUpNextDue,
              status: "pending",
              createdBy: req.user!.id,
              manufacturer: data.manufacturer || null,
              notes: "Auto-scheduled follow-up",
            });
        } catch (followUpError) {
          console.error("[PreventativeCare] Failed to create follow-up record:", followUpError);
        }
      }

      res.status(201).json({ record });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:animalId/preventative-care/batch-create-core
   * Auto-create preventative care records for all core items based on animal species
   * Used at intake or when initializing preventative care tracking
   */
  app.post('/api/animals/:animalId/preventative-care/batch-create-core', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords, preventativeCareTypes, animals } = await import('@shared/schema');
      const { animalId } = req.params;
      const { dateAdministered } = req.body;
      const effectiveDate = dateAdministered ? new Date(dateAdministered) : new Date();

      // Get the animal to determine species
      const [animal] = await db
        .select({ species: animals.species })
        .from(animals)
        .where(and(
          eq(animals.id, animalId),
          eq(animals.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      // Get core preventative care types for this species
      const coreTypes = await db
        .select()
        .from(preventativeCareTypes)
        .where(and(
          eq(preventativeCareTypes.isCore, true),
          or(
            eq(preventativeCareTypes.targetSpecies, animal.species || 'Dog'),
            eq(preventativeCareTypes.targetSpecies, 'Both')
          )
        ));

      // Check which core types already have records for this animal
      const existingRecords = await db
        .select({ careTypeId: preventativeCareRecords.careTypeId })
        .from(preventativeCareRecords)
        .where(and(
          eq(preventativeCareRecords.animalId, animalId),
          eq(preventativeCareRecords.tenantId, req.tenant!.id)
        ));

      const existingTypeIds = new Set(existingRecords.map(r => r.careTypeId));

      // Filter to only create records for types that don't already exist
      const typesToCreate = coreTypes.filter(t => !existingTypeIds.has(t.id));

      if (typesToCreate.length === 0) {
        return res.json({ 
          message: 'All core preventative care items already recorded',
          created: 0,
          records: []
        });
      }

      // Create records for each core type
      const recordsToInsert = typesToCreate.map(type => {
        let nextDueDate: Date | null = null;
        if (type.defaultIntervalDays) {
          nextDueDate = new Date(effectiveDate);
          nextDueDate.setDate(nextDueDate.getDate() + type.defaultIntervalDays);
        }

        return {
          tenantId: req.tenant!.id,
          animalId,
          careTypeId: type.id,
          dateAdministered: effectiveDate,
          nextDueDate,
          notes: 'Auto-created at intake',
          createdBy: req.user!.id,
        };
      });

      const createdRecords = await db
        .insert(preventativeCareRecords)
        .values(recordsToInsert)
        .returning();

      // Update animal's medicalDueDates cache based on coverage flags
      try {
        const dueDates: Record<string, string> = {};
        for (let i = 0; i < typesToCreate.length; i++) {
          const type = typesToCreate[i];
          const record = createdRecords[i];
          if (record?.nextDueDate) {
            const dueStr = new Date(record.nextDueDate).toISOString();
            if (type.coversHeartworm && (!dueDates.heartwormDueDate || new Date(dueStr) > new Date(dueDates.heartwormDueDate))) {
              dueDates.heartwormDueDate = dueStr;
            }
            if (type.coversFleaTick && (!dueDates.fleaTickDueDate || new Date(dueStr) > new Date(dueDates.fleaTickDueDate))) {
              dueDates.fleaTickDueDate = dueStr;
            }
          }
        }
        if (Object.keys(dueDates).length > 0) {
          const [existingAnimal] = await db
            .select()
            .from(animals)
            .where(eq(animals.id, animalId))
            .limit(1);
          const merged = { ...((existingAnimal?.medicalDueDates as any) || {}), ...dueDates };
          if (merged && typeof merged === 'object' && Object.keys(merged).length > 0) {
            await db.update(animals).set({ medicalDueDates: merged }).where(eq(animals.id, animalId));
          }
        }
      } catch (cacheError) {
        console.error('[PreventativeCare] Failed to update medicalDueDates cache (batch):', cacheError);
      }

      res.status(201).json({
        message: `Created ${createdRecords.length} core preventative care records`,
        created: createdRecords.length,
        records: createdRecords,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:animalId/preventative-care/apply-protocol
   * Apply a medical protocol (predefined set of preventative care items) to an animal
   * Protocols: adult_dog, puppy, adult_cat, kitten, intake_dog, intake_cat
   */
  app.post('/api/animals/:animalId/preventative-care/apply-protocol', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords, preventativeCareTypes, animals } = await import('@shared/schema');
      const { animalId } = req.params;
      const { protocolName, dateAdministered, markInitialAsGiven = true } = req.body;
      const effectiveDate = dateAdministered ? new Date(dateAdministered) : new Date();

      if (!protocolName) {
        return res.status(400).json({ error: 'Protocol name is required' });
      }

      // Get the animal to determine species
      const [animal] = await db
        .select({ species: animals.species, name: animals.name })
        .from(animals)
        .where(and(
          eq(animals.id, animalId),
          eq(animals.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      const protocolMappings: Record<string, { items: { name: string, dayOffset: number }[], description: string }> = {
        'adult_dog': {
          items: [
            { name: 'Rabies (1-Year)', dayOffset: 0 },
            { name: 'DHPP (DA2PP)', dayOffset: 0 },
            { name: 'Bordetella', dayOffset: 0 },
            { name: 'Heartworm Prevention', dayOffset: 0 },
            { name: 'Flea & Tick Prevention', dayOffset: 0 },
          ],
          description: 'Adult Dog Standard'
        },
        'puppy': {
          items: [
            { name: 'Dewormer (Pyrantel)', dayOffset: 0 },
            { name: 'DHPP (DA2PP)', dayOffset: 0 },
            { name: 'Flea & Tick Prevention', dayOffset: 0 },
            { name: 'Heartworm Prevention', dayOffset: 30 },
          ],
          description: 'Puppy Protocol'
        },
        'adult_cat': {
          items: [
            { name: 'Rabies (1-Year)', dayOffset: 0 },
            { name: 'FVRCP', dayOffset: 0 },
            { name: 'Heartworm Prevention', dayOffset: 0 },
            { name: 'Flea & Tick Prevention', dayOffset: 0 },
          ],
          description: 'Adult Cat Standard'
        },
        'kitten': {
          items: [
            { name: 'Dewormer (Pyrantel)', dayOffset: 0 },
            { name: 'FVRCP', dayOffset: 0 },
            { name: 'Flea & Tick Prevention', dayOffset: 0 },
            { name: 'Heartworm Prevention', dayOffset: 30 },
          ],
          description: 'Kitten Protocol'
        },
        'intake_dog': {
          items: [
            { name: 'Dewormer (Pyrantel)', dayOffset: 0 },
            { name: 'Flea & Tick Prevention', dayOffset: 0 },
            { name: 'Heartworm Test (Antigen)', dayOffset: 0 },
            { name: 'Microchip Implant', dayOffset: 0 },
          ],
          description: 'Intake Default (Dog)'
        },
        'intake_cat': {
          items: [
            { name: 'Dewormer (Pyrantel)', dayOffset: 0 },
            { name: 'Flea & Tick Prevention', dayOffset: 0 },
            { name: 'FeLV/FIV Combo Test', dayOffset: 0 },
            { name: 'Microchip Implant', dayOffset: 0 },
          ],
          description: 'Intake Default (Cat)'
        }
      };

      const protocol = protocolMappings[protocolName];
      if (!protocol) {
        return res.status(400).json({ 
          error: 'Invalid protocol name',
          validProtocols: Object.keys(protocolMappings)
        });
      }

      const careTypeNames = protocol.items.map(i => i.name);

      // Get the care types matching the protocol's care type names
      // Filter by species compatibility
      const allTypes = await db
        .select({
          id: preventativeCareTypes.id,
          name: preventativeCareTypes.name,
          category: preventativeCareTypes.category,
          targetSpecies: preventativeCareTypes.targetSpecies,
          defaultIntervalDays: preventativeCareTypes.defaultIntervalDays,
          coversHeartworm: preventativeCareTypes.coversHeartworm,
          coversFleaTick: preventativeCareTypes.coversFleaTick,
        })
        .from(preventativeCareTypes)
        .where(and(
          eq(preventativeCareTypes.isActive, true),
          inArray(preventativeCareTypes.name, careTypeNames),
          or(
            eq(preventativeCareTypes.targetSpecies, animal.species || 'Dog'),
            eq(preventativeCareTypes.targetSpecies, 'Both')
          )
        ));

      if (allTypes.length === 0) {
        return res.status(400).json({ 
          error: 'No matching care types found for this protocol and species',
          protocol: protocol.description,
          species: animal.species
        });
      }

      // Check which types already have records for this animal
      const existingRecords = await db
        .select({ careTypeId: preventativeCareRecords.careTypeId })
        .from(preventativeCareRecords)
        .where(and(
          eq(preventativeCareRecords.animalId, animalId),
          eq(preventativeCareRecords.tenantId, req.tenant!.id)
        ));

      const existingTypeIds = new Set(existingRecords.map(r => r.careTypeId));

      // Filter to only create records for types that don't already exist
      const typesToCreate = allTypes.filter(t => !existingTypeIds.has(t.id));

      if (typesToCreate.length === 0) {
        return res.json({ 
          message: `All items from ${protocol.description} already recorded for ${animal.name}`,
          created: 0,
          givenCount: 0,
          scheduledCount: 0,
          skipped: allTypes.length,
          records: []
        });
      }

      // Build a lookup map from protocol items for dayOffset by name
      const dayOffsetMap = new Map(protocol.items.map(i => [i.name, i.dayOffset]));

      // Create records for each type with smart scheduling
      const recordsToInsert = typesToCreate.map(type => {
        const dayOffset = dayOffsetMap.get(type.name) ?? 0;
        let status: "given" | "pending";
        let nextDueDate: Date | null = null;

        if (markInitialAsGiven && dayOffset === 0) {
          status = 'given';
          if (type.defaultIntervalDays) {
            nextDueDate = new Date(effectiveDate);
            nextDueDate.setDate(nextDueDate.getDate() + type.defaultIntervalDays);
          }
        } else if (markInitialAsGiven && dayOffset > 0) {
          status = 'pending';
          nextDueDate = new Date(effectiveDate);
          nextDueDate.setDate(nextDueDate.getDate() + dayOffset);
        } else {
          status = 'pending';
          if (dayOffset > 0) {
            nextDueDate = new Date(effectiveDate);
            nextDueDate.setDate(nextDueDate.getDate() + dayOffset);
          } else if (type.defaultIntervalDays) {
            nextDueDate = new Date(effectiveDate);
            nextDueDate.setDate(nextDueDate.getDate() + type.defaultIntervalDays);
          }
        }

        return {
          tenantId: req.tenant!.id,
          animalId,
          careTypeId: type.id,
          careName: type.name,
          careCategory: type.category as "vaccine" | "parasite_prevention" | "test" | "other",
          status,
          dateAdministered: effectiveDate,
          nextDueDate,
          notes: `Applied via ${protocol.description} protocol`,
          createdBy: req.user!.id,
        };
      });

      const createdRecords = await db
        .insert(preventativeCareRecords)
        .values(recordsToInsert)
        .returning();

      // Update animal's medicalDueDates cache based on coverage flags
      try {
        const protocolDueDates: Record<string, string> = {};
        for (let i = 0; i < typesToCreate.length; i++) {
          const type = typesToCreate[i];
          const record = createdRecords[i];
          if (record?.nextDueDate) {
            const dueStr = new Date(record.nextDueDate).toISOString();
            if (type.coversHeartworm && (!protocolDueDates.heartwormDueDate || new Date(dueStr) > new Date(protocolDueDates.heartwormDueDate))) {
              protocolDueDates.heartwormDueDate = dueStr;
            }
            if (type.coversFleaTick && (!protocolDueDates.fleaTickDueDate || new Date(dueStr) > new Date(protocolDueDates.fleaTickDueDate))) {
              protocolDueDates.fleaTickDueDate = dueStr;
            }
          }
        }
        if (Object.keys(protocolDueDates).length > 0) {
          const [existingAnimal] = await db
            .select()
            .from(animals)
            .where(eq(animals.id, animalId))
            .limit(1);
          const merged = { ...((existingAnimal?.medicalDueDates as any) || {}), ...protocolDueDates };
          if (merged && typeof merged === 'object' && Object.keys(merged).length > 0) {
            await db.update(animals).set({ medicalDueDates: merged }).where(eq(animals.id, animalId));
          }
        }
      } catch (cacheError) {
        console.error('[PreventativeCare] Failed to update medicalDueDates cache (protocol):', cacheError);
      }

      const givenCount = recordsToInsert.filter(r => r.status === 'given').length;
      const scheduledCount = recordsToInsert.filter(r => r.status === 'pending').length;

      const messageParts: string[] = [];
      if (givenCount > 0) messageParts.push(`${givenCount} dose${givenCount !== 1 ? 's' : ''} given now`);
      if (scheduledCount > 0) messageParts.push(`${scheduledCount} dose${scheduledCount !== 1 ? 's' : ''} scheduled for future`);

      res.status(201).json({
        message: `Applied ${protocol.description}: ${messageParts.join(', ')}.`,
        created: createdRecords.length,
        givenCount,
        scheduledCount,
        skipped: allTypes.length - typesToCreate.length,
        protocol: protocol.description,
        records: createdRecords,
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/animals/:animalId/preventative-care/apply-puppy-protocol
   * Apply age-aware puppy protocol with DHPP series catch-up and 16-week completion rule
   */
  app.post('/api/animals/:animalId/preventative-care/apply-puppy-protocol', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { animals } = await import('@shared/schema');
      const { applyPuppyProtocol } = await import('./services/puppy-protocol');
      const { animalId } = req.params;

      const [animal] = await db
        .select({ species: animals.species, name: animals.name, dateOfBirth: animals.dateOfBirth })
        .from(animals)
        .where(and(
          eq(animals.id, animalId),
          eq(animals.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!animal) {
        return res.status(404).json({ error: 'Animal not found' });
      }

      if (animal.species !== 'Dog') {
        return res.status(400).json({ error: 'Puppy protocol is only available for dogs' });
      }

      if (!animal.dateOfBirth) {
        return res.status(400).json({ error: 'Date of birth is required for puppy protocol. Please set the animal\'s DOB first.' });
      }

      const result = await applyPuppyProtocol(animalId, req.tenant!.id, req.user!.id, new Date(animal.dateOfBirth));

      res.status(201).json({
        message: `Puppy Protocol applied for ${animal.name}: ${result.scheduled} scheduled, ${result.catchUp} catch-up, ${result.skipped} skipped.`,
        ...result,
      });
    } catch (error) {
      next(error);
    }
  });

    /**
   * POST /api/preventative-care/backfill-all
   * Bulk backfill: Scan all active animals and create missing core preventative care records
   * This is the "Generate Missing Tasks" scheduler engine
   */
  app.post('/api/preventative-care/backfill-all', requireTenant, requireAuth, requireRole('admin', 'staff'), async (req, res, next) => {
    try {
      const { preventativeCareRecords, preventativeCareTypes, animals } = await import('@shared/schema');
      const { z } = await import('zod');
      
      // Validate request body
      const bodySchema = z.object({
        dateAdministered: z.string().datetime().optional(),
      }).optional();
      
      const validatedBody = bodySchema.parse(req.body || {});
      const effectiveDate = validatedBody?.dateAdministered ? new Date(validatedBody.dateAdministered) : new Date();

      // Get all active animals for this tenant (status = available, hold, medical_hold, foster, pending_adoption, trial)
      const activeStatuses = ['available', 'hold', 'medical_hold', 'foster', 'pending_adoption', 'trial'];
      const activeAnimals = await db
        .select({ id: animals.id, name: animals.name, species: animals.species })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          inArray(animals.status, activeStatuses)
        ));

      if (activeAnimals.length === 0) {
        return res.json({
          message: 'No active animals found',
          summary: { animalsProcessed: 0, totalRecordsCreated: 0, byAnimal: [] }
        });
      }

      // Get all core preventative care types
      const coreTypes = await db
        .select({
          id: preventativeCareTypes.id,
          name: preventativeCareTypes.name,
          category: preventativeCareTypes.category,
          targetSpecies: preventativeCareTypes.targetSpecies,
          defaultIntervalDays: preventativeCareTypes.defaultIntervalDays,
        })
        .from(preventativeCareTypes)
        .where(eq(preventativeCareTypes.isCore, true));

      if (coreTypes.length === 0) {
        return res.json({
          message: 'No core preventative care types configured',
          summary: { animalsProcessed: 0, totalRecordsCreated: 0, byAnimal: [] }
        });
      }

      // Get all existing preventative care records for these animals
      const animalIds = activeAnimals.map(a => a.id);
      const existingRecords = await db
        .select({ animalId: preventativeCareRecords.animalId, careTypeId: preventativeCareRecords.careTypeId })
        .from(preventativeCareRecords)
        .where(and(
          eq(preventativeCareRecords.tenantId, req.tenant!.id),
          inArray(preventativeCareRecords.animalId, animalIds)
        ));

      // Build a map of existing records: animalId -> Set of careTypeIds
      const existingMap = new Map<string, Set<string>>();
      for (const record of existingRecords) {
        if (!existingMap.has(record.animalId)) {
          existingMap.set(record.animalId, new Set());
        }
        if (record.careTypeId) {
          existingMap.get(record.animalId)!.add(record.careTypeId);
        }
      }

      // Process each animal and determine which core types are missing
      const allRecordsToInsert: any[] = [];
      const summary: { animalId: string; animalName: string; created: number; types: string[] }[] = [];

      for (const animal of activeAnimals) {
        const existingTypeIds = existingMap.get(animal.id) || new Set();
        // Normalize species to title case for comparison (e.g., "dog" -> "Dog", "CAT" -> "Cat")
        const rawSpecies = animal.species || 'Dog';
        const species = rawSpecies.charAt(0).toUpperCase() + rawSpecies.slice(1).toLowerCase();

        // Filter core types applicable to this animal's species (case-insensitive comparison)
        const applicableTypes = coreTypes.filter(t => 
          t.targetSpecies === 'Both' || t.targetSpecies.toLowerCase() === species.toLowerCase()
        );

        // Find missing types
        const missingTypes = applicableTypes.filter(t => !existingTypeIds.has(t.id));

        if (missingTypes.length > 0) {
          const typeNames: string[] = [];
          for (const type of missingTypes) {
            let nextDueDate: Date | null = null;
            if (type.defaultIntervalDays) {
              nextDueDate = new Date(effectiveDate);
              nextDueDate.setDate(nextDueDate.getDate() + type.defaultIntervalDays);
            }

            allRecordsToInsert.push({
              tenantId: req.tenant!.id,
              animalId: animal.id,
              careTypeId: type.id,
              careName: type.name,
              careCategory: type.category,
              dateAdministered: effectiveDate,
              nextDueDate,
              notes: 'Auto-created via backfill',
              createdBy: req.user!.id,
            });
            typeNames.push(type.name);
          }

          summary.push({
            animalId: animal.id,
            animalName: animal.name,
            created: missingTypes.length,
            types: typeNames
          });
        }
      }

      // Bulk insert all records
      let createdCount = 0;
      if (allRecordsToInsert.length > 0) {
        await db.insert(preventativeCareRecords).values(allRecordsToInsert);
        createdCount = allRecordsToInsert.length;
      }

      res.status(201).json({
        message: `Backfill complete: Created ${createdCount} preventative care records for ${summary.length} animals`,
        summary: {
          animalsProcessed: activeAnimals.length,
          animalsWithNewRecords: summary.length,
          totalRecordsCreated: createdCount,
          byAnimal: summary
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/animals/:animalId/preventative-care
   * Get preventative care records for an animal
   */
  app.get('/api/animals/:animalId/preventative-care', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords } = await import('@shared/schema');

      const records = await db
        .select()
        .from(preventativeCareRecords)
        .where(and(
          eq(preventativeCareRecords.animalId, req.params.animalId),
          eq(preventativeCareRecords.tenantId, req.tenant!.id)
        ))
        .orderBy(desc(preventativeCareRecords.dateAdministered));

      const completedByIds = [...new Set(records.map(r => r.completedByUserId).filter(Boolean))] as string[];
      let completedByNameMap: Record<string, string> = {};
      if (completedByIds.length > 0) {
        const completedByUsers = await db
          .select({ id: users.id, fullName: users.fullName })
          .from(users)
          .where(inArray(users.id, completedByIds));
        completedByNameMap = Object.fromEntries(completedByUsers.map(u => [u.id, u.fullName]));
      }

      const pcEditorIds = [...new Set(records.map(r => r.lastEditedBy).filter(Boolean))] as string[];
      let pcEditorMap: Record<string, string> = {};
      if (pcEditorIds.length > 0) {
        const eu = await db.select({ id: users.id, fullName: users.fullName }).from(users).where(inArray(users.id, pcEditorIds));
        pcEditorMap = Object.fromEntries(eu.map(u => [u.id, u.fullName]));
      }

      const enrichedRecords = records.map(r => ({
        ...r,
        completedByName: r.completedByUserId ? (completedByNameMap[r.completedByUserId] || null) : null,
        lastEditedByName: r.lastEditedBy ? (pcEditorMap[r.lastEditedBy] || null) : null,
      }));

      res.json({ records: enrichedRecords });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/medical/preventative-care/records/:recordId
   * Update a preventative care record
   */
  app.patch('/api/medical/preventative-care/records/:recordId', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { preventativeCareRecords, preventativeCareTypes } = await import('@shared/schema');
      const { recordId } = req.params;

      // Verify record exists and belongs to tenant
      const [existingRecord] = await db
        .select()
        .from(preventativeCareRecords)
        .where(and(
          eq(preventativeCareRecords.id, recordId),
          eq(preventativeCareRecords.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!existingRecord) {
        return res.status(404).json({ error: 'Record not found' });
      }

      const { careTypeId, dateAdministered, administeredBy, notes, lotNumber, manufacturer, administrationRoute } = req.body;

      // Recalculate next due date if date or care type changed
      let nextDueDate: Date | null = existingRecord.nextDueDate;
      const effectiveCareTypeId = careTypeId || existingRecord.careTypeId;
      const effectiveDate = dateAdministered || existingRecord.dateAdministered;

      if (careTypeId || dateAdministered) {
        const [careType] = await db
          .select()
          .from(preventativeCareTypes)
          .where(eq(preventativeCareTypes.id, effectiveCareTypeId))
          .limit(1);

        if (careType?.defaultIntervalDays) {
          nextDueDate = new Date(effectiveDate);
          nextDueDate.setDate(nextDueDate.getDate() + careType.defaultIntervalDays);
        }
      }

      const [updatedRecord] = await db
        .update(preventativeCareRecords)
        .set({
          ...(careTypeId && { careTypeId }),
          ...(dateAdministered && { dateAdministered: new Date(dateAdministered) }),
          ...(administeredBy !== undefined && { administeredBy }),
          ...(notes !== undefined && { notes }),
          ...(lotNumber !== undefined && { lotNumber }),
          ...(manufacturer !== undefined && { manufacturer }),
          ...(administrationRoute !== undefined && { administrationRoute }),
          nextDueDate,
          updatedAt: new Date(),
          lastEditedAt: new Date(),
          lastEditedBy: req.user!.id,
        })
        .where(eq(preventativeCareRecords.id, recordId))
        .returning();

      res.json({ record: updatedRecord });
    } catch (error) {
      next(error);
    }
  });

