  /**
   * POST /api/compliance-confirmations/:confirmationId/review
   * Staff approves or rejects an adopter compliance confirmation
   */
  app.post('/api/compliance-confirmations/:confirmationId/review', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { adopterComplianceConfirmations, preventativeCareRecords, preventativeCareTypes } = await import('@shared/schema');
      const { confirmationId } = req.params;
      const { action, reviewNotes } = req.body;

      if (!action || !['approve', 'reject'].includes(action)) {
        return res.status(400).json({ error: 'Action must be "approve" or "reject"' });
      }

      const [confirmation] = await db
        .select()
        .from(adopterComplianceConfirmations)
        .where(and(
          eq(adopterComplianceConfirmations.id, confirmationId),
          eq(adopterComplianceConfirmations.tenantId, req.tenant!.id),
          eq(adopterComplianceConfirmations.status, 'pending_review')
        ))
        .limit(1);

      if (!confirmation) {
        return res.status(404).json({ error: 'Confirmation not found or already reviewed' });
      }

      const newStatus = action === 'approve' ? 'approved' : 'rejected';

      const [updated] = await db
        .update(adopterComplianceConfirmations)
        .set({
          status: newStatus,
          reviewedBy: req.user!.id,
          reviewedAt: new Date(),
          reviewNotes: reviewNotes || null,
        })
        .where(eq(adopterComplianceConfirmations.id, confirmationId))
        .returning();

      if (action === 'approve' && confirmation.preventativeCareRecordId) {
        const [careRecord] = await db
          .select({
            id: preventativeCareRecords.id,
            careTypeId: preventativeCareRecords.careTypeId,
          })
          .from(preventativeCareRecords)
          .where(eq(preventativeCareRecords.id, confirmation.preventativeCareRecordId))
          .limit(1);

        if (careRecord) {
          let newNextDueDate: Date | null = null;

          if (careRecord.careTypeId) {
            const [careType] = await db
              .select({ defaultIntervalDays: preventativeCareTypes.defaultIntervalDays })
              .from(preventativeCareTypes)
              .where(eq(preventativeCareTypes.id, careRecord.careTypeId))
              .limit(1);

            if (careType?.defaultIntervalDays) {
              newNextDueDate = new Date(confirmation.dateAdministered);
              newNextDueDate.setDate(newNextDueDate.getDate() + careType.defaultIntervalDays);
            }
          }

          await db
            .update(preventativeCareRecords)
            .set({
              dateAdministered: confirmation.dateAdministered,
              nextDueDate: newNextDueDate,
              clinicName: confirmation.clinicName || undefined,
              notes: confirmation.notes ? `Adopter confirmed: ${confirmation.notes}` : undefined,
              updatedAt: new Date(),
            })
            .where(eq(preventativeCareRecords.id, confirmation.preventativeCareRecordId));
        }
      }

      res.json(updated);
    } catch (error) {
      next(error);
    }
  });

