  /**
   * GET /api/animals/:animalId/medical/history
   * Get chronological medical history for an animal
   */
  app.get('/api/animals/:animalId/medical/history', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalExams, vaccineRecords, diagnosticTests, procedureLogs, medicalPrescriptions, medicalDoses, users } = await import('@shared/schema');
      
      // Check permissions
      const permissions = await checkMedicalRecordPermissions(
        req.user!.id,
        req.params.animalId,
        req.tenant!.id,
        req.user!.roles
      );

      if (!permissions.canView) {
        return res.status(403).json({ 
          error: 'Access denied',
          message: 'You do not have permission to view medical records for this animal'
        });
      }
      
      // Get all medical records for this animal - explicit field selection for dynamic import
      const [exams, vaccines, diagnostics, procedures, prescriptions, doses] = await Promise.all([
        db.select({
          id: medicalExams.id,
          animalId: medicalExams.animalId,
          examDate: medicalExams.examDate,
          examType: medicalExams.examType,
          performedBy: medicalExams.performedBy,
          subjective: medicalExams.subjective,
          objective: medicalExams.objective,
          assessment: medicalExams.assessment,
          plan: medicalExams.plan,
          structuredFields: medicalExams.structuredFields,
          createdAt: medicalExams.createdAt,
          lastEditedAt: medicalExams.lastEditedAt,
          lastEditedBy: medicalExams.lastEditedBy,
        }).from(medicalExams).where(and(
          eq(medicalExams.animalId, req.params.animalId),
          eq(medicalExams.tenantId, req.tenant!.id)
        )),
        db.select({
          id: vaccineRecords.id,
          animalId: vaccineRecords.animalId,
          itemName: vaccineRecords.itemName,
          dateGiven: vaccineRecords.dateGiven,
          dateDue: vaccineRecords.dateDue,
          lotNumber: vaccineRecords.lotNumber,
          manufacturer: vaccineRecords.manufacturer,
          administeredBy: vaccineRecords.administeredBy,
          clinicName: vaccineRecords.clinicName,
          createdAt: vaccineRecords.createdAt,
          lastEditedAt: vaccineRecords.lastEditedAt,
          lastEditedBy: vaccineRecords.lastEditedBy,
        }).from(vaccineRecords).where(and(
          eq(vaccineRecords.animalId, req.params.animalId),
          eq(vaccineRecords.tenantId, req.tenant!.id)
        )),
        db.select({
          id: diagnosticTests.id,
          animalId: diagnosticTests.animalId,
          testName: diagnosticTests.testName,
          testDate: diagnosticTests.testDate,
          result: diagnosticTests.result,
          notes: diagnosticTests.notes,
          createdAt: diagnosticTests.createdAt,
          lastEditedAt: diagnosticTests.lastEditedAt,
          lastEditedBy: diagnosticTests.lastEditedBy,
        }).from(diagnosticTests).where(and(
          eq(diagnosticTests.animalId, req.params.animalId),
          eq(diagnosticTests.tenantId, req.tenant!.id)
        )),
        db.select({
          id: procedureLogs.id,
          animalId: procedureLogs.animalId,
          procedureName: procedureLogs.procedureName,
          procedureDate: procedureLogs.procedureDate,
          veterinarian: procedureLogs.veterinarian,
          notes: procedureLogs.notes,
          createdAt: procedureLogs.createdAt,
          lastEditedAt: procedureLogs.lastEditedAt,
          lastEditedBy: procedureLogs.lastEditedBy,
        }).from(procedureLogs).where(and(
          eq(procedureLogs.animalId, req.params.animalId),
          eq(procedureLogs.tenantId, req.tenant!.id)
        )),
        db.select({
          id: medicalPrescriptions.id,
          animalId: medicalPrescriptions.animalId,
          medicationName: medicalPrescriptions.medicationName,
          dosage: medicalPrescriptions.dosage,
          frequency: medicalPrescriptions.frequency,
          startDate: medicalPrescriptions.startDate,
          endDate: medicalPrescriptions.endDate,
          notes: medicalPrescriptions.notes,
          createdAt: medicalPrescriptions.createdAt,
          lastEditedAt: medicalPrescriptions.lastEditedAt,
          lastEditedBy: medicalPrescriptions.lastEditedBy,
        }).from(medicalPrescriptions).where(and(
          eq(medicalPrescriptions.animalId, req.params.animalId),
          eq(medicalPrescriptions.tenantId, req.tenant!.id)
        )),
        db.select({
          doseId: medicalDoses.id,
          prescriptionId: medicalDoses.prescriptionId,
          status: medicalDoses.status,
          givenAt: medicalDoses.givenAt,
          dueDate: medicalDoses.dueDate,
          notes: medicalDoses.notes,
          administeredBy: medicalDoses.administeredBy,
          medicationName: medicalPrescriptions.medicationName,
          dosage: medicalPrescriptions.dosage,
          animalId: medicalPrescriptions.animalId,
        })
          .from(medicalDoses)
          .innerJoin(medicalPrescriptions, eq(medicalDoses.prescriptionId, medicalPrescriptions.id))
          .where(and(
            eq(medicalPrescriptions.animalId, req.params.animalId),
            eq(medicalDoses.tenantId, req.tenant!.id),
            inArray(medicalDoses.status, ['given', 'skipped', 'unable'])
          )),
      ]);

      const doseAdminIds = [...new Set(doses.map(d => d.administeredBy).filter(Boolean))] as string[];
      let doseUserNameMap: Record<string, string> = {};
      if (doseAdminIds.length > 0) {
        const adminUsers = await db
          .select({ id: users.id, name: users.fullName })
          .from(users)
          .where(inArray(users.id, doseAdminIds));
        doseUserNameMap = Object.fromEntries(adminUsers.map(u => [u.id, u.name]));
      }
      const enrichedDoses = doses.map(d => ({
        ...d,
        administeredByName: d.administeredBy ? (doseUserNameMap[d.administeredBy] || null) : null,
      }));

      // Resolve editor names for audit trail
      const allEditedByIds = [...new Set([
        ...exams.map(e => e.lastEditedBy),
        ...vaccines.map(v => v.lastEditedBy),
        ...diagnostics.map(d => d.lastEditedBy),
        ...procedures.map(p => p.lastEditedBy),
        ...prescriptions.map(p => p.lastEditedBy),
      ].filter(Boolean))] as string[];
      let editorNameMap: Record<string, string> = {};
      if (allEditedByIds.length > 0) {
        const editorUsers = await db
          .select({ id: users.id, name: users.fullName })
          .from(users)
          .where(inArray(users.id, allEditedByIds));
        editorNameMap = Object.fromEntries(editorUsers.map(u => [u.id, u.name]));
      }

      const enrichRecord = (rec: any) => ({
        ...rec,
        lastEditedByName: rec.lastEditedBy ? (editorNameMap[rec.lastEditedBy] || null) : null,
      });

      // Combine and sort by date
      const history = [
        ...exams.map(e => ({ type: 'exam' as const, date: e.examDate, data: enrichRecord(e) })),
        ...vaccines.map(v => ({ type: 'vaccine' as const, date: v.dateGiven, data: enrichRecord(v) })),
        ...diagnostics.map(d => ({ type: 'diagnostic' as const, date: d.testDate, data: enrichRecord(d) })),
        ...procedures.map(p => ({ type: 'procedure' as const, date: p.procedureDate, data: enrichRecord(p) })),
        ...prescriptions.map(p => ({ type: 'prescription' as const, date: p.startDate, data: enrichRecord(p) })),
        ...enrichedDoses.filter(d => d.givenAt || d.dueDate).map(d => ({ type: 'dose' as const, date: (d.givenAt || d.dueDate)!, data: d })),
      ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      res.json({ history });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/animals/:animalId/medical-summary
   * Get medical summary for fosters (prescriptions and vaccines)
   * Requires foster role and animal must be assigned to the requesting foster
   */
  app.get('/api/animals/:animalId/medical-summary', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { medicalPrescriptions, vaccineRecords, fosterAnimals } = await import('@shared/schema');
      
      const isStaff = ['admin', 'staff', 'manager', 'vet'].includes(req.user!.activeRole ?? '');

      if (!isStaff) {
        // Foster users: verify the animal is actively assigned to them
        const fosterAnimal = await db
          .select({ id: fosterAnimals.id })
          .from(fosterAnimals)
          .where(and(
            eq(fosterAnimals.animalId, req.params.animalId),
            eq(fosterAnimals.fosterId, req.user!.id),
            eq(fosterAnimals.tenantId, req.tenant!.id),
            eq(fosterAnimals.status, 'active')
          ))
          .limit(1);

        if (fosterAnimal.length === 0) {
          return res.status(403).json({ 
            error: 'Access denied',
            message: 'You can only view medical information for animals assigned to you'
          });
        }
      }
      
      // Get prescriptions and vaccines for this animal - explicit field selection for dynamic import
      const [prescriptions, vaccines] = await Promise.all([
        db.select({
          id: medicalPrescriptions.id,
          medicationName: medicalPrescriptions.medicationName,
          dosage: medicalPrescriptions.dosage,
          route: medicalPrescriptions.route,
          frequency: medicalPrescriptions.frequency,
          startDate: medicalPrescriptions.startDate,
          endDate: medicalPrescriptions.endDate,
          notes: medicalPrescriptions.notes,
          isControlledSubstance: medicalPrescriptions.isControlledSubstance,
          createdBy: medicalPrescriptions.createdBy,
        }).from(medicalPrescriptions).where(and(
          eq(medicalPrescriptions.animalId, req.params.animalId),
          eq(medicalPrescriptions.tenantId, req.tenant!.id)
        )).orderBy(desc(medicalPrescriptions.startDate)),
        db.select({
          id: vaccineRecords.id,
          itemName: vaccineRecords.itemName,
          dateGiven: vaccineRecords.dateGiven,
          dateDue: vaccineRecords.dateDue,
          administeredBy: vaccineRecords.administeredBy,
        }).from(vaccineRecords).where(and(
          eq(vaccineRecords.animalId, req.params.animalId),
          eq(vaccineRecords.tenantId, req.tenant!.id)
        )).orderBy(desc(vaccineRecords.dateGiven)),
      ]);

      res.json({ prescriptions, vaccines });
    } catch (error) {
      next(error);
    }
  });

