  /**
   * GET /api/calendars/export/ical
   * Export calendars as iCal (.ics) file
   */
  app.get('/api/calendars/export/ical', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { calendars: calendarsSchema, calendarEvents } = await import('@shared/schema');
      
      // Get all events for the tenant
      const events = await db
        .select()
        .from(calendarEvents)
        .where(eq(calendarEvents.tenantId, req.tenant!.id))
        .orderBy(calendarEvents.startTime);

      // Generate iCal format
      const ical = [
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//Animal Rescue Calendar//EN',
        `CALSCALE:GREGORIAN`,
        `X-WR-CALNAME:${req.tenant!.name}`,
        `X-WR-TIMEZONE:UTC`,
        ...events.flatMap(event => [
          'BEGIN:VEVENT',
          `UID:${event.id}@rescueportal.com`,
          `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').split('.')[0]}Z`,
          `DTSTART:${new Date(event.startTime).toISOString().replace(/[-:]/g, '').split('.')[0]}Z`,
          `DTEND:${new Date(event.endTime).toISOString().replace(/[-:]/g, '').split('.')[0]}Z`,
          `SUMMARY:${event.title}`,
          ...(event.description ? [`DESCRIPTION:${event.description.replace(/\n/g, '\\n')}`] : []),
          ...(event.location ? [`LOCATION:${event.location}`] : []),
          'END:VEVENT'
        ]),
        'END:VCALENDAR'
      ].join('\r\n');

      res.setHeader('Content-Type', 'text/calendar; charset=utf-8');
      res.setHeader('Content-Disposition', `attachment; filename="${req.tenant!.subdomain}-calendar.ics"`);
      res.send(ical);
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/calendars/share-image
   * Generate a shareable PNG image of the current month's calendar
   * Query params: month (ISO date string, defaults to current month)
   */
  app.get('/api/calendars/share-image', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { calendars: calendarsSchema, calendarEvents } = await import('@shared/schema');
      const { generateCalendarShareImage } = await import('./services/calendar-share-image');

      const monthParam = req.query.month as string | undefined;
      const month = monthParam ? new Date(monthParam) : new Date();
      const calendarIdParam = req.query.calendarId as string | undefined;

      let tenantCalendars;
      if (calendarIdParam) {
        tenantCalendars = await db
          .select()
          .from(calendarsSchema)
          .where(and(eq(calendarsSchema.tenantId, req.tenant!.id), eq(calendarsSchema.id, calendarIdParam)));
      } else {
        tenantCalendars = await db
          .select()
          .from(calendarsSchema)
          .where(eq(calendarsSchema.tenantId, req.tenant!.id));
      }

      if (tenantCalendars.length === 0) {
        return res.status(404).json({ error: 'No calendars found' });
      }

      const calendarIds = tenantCalendars.map(c => c.id);

      let events;
      if (calendarIds.length === 1) {
        events = await db
          .select()
          .from(calendarEvents)
          .where(and(eq(calendarEvents.tenantId, req.tenant!.id), eq(calendarEvents.calendarId, calendarIds[0])))
          .orderBy(calendarEvents.startTime);
      } else {
        events = await db
          .select()
          .from(calendarEvents)
          .where(and(eq(calendarEvents.tenantId, req.tenant!.id), inArray(calendarEvents.calendarId, calendarIds)))
          .orderBy(calendarEvents.startTime);
      }

      const host = req.get('host') || '';
      const baseUrl = `${req.protocol}://${host}`;
      const hasCustomDomain = (req.tenant as any).customDomain && host.includes((req.tenant as any).customDomain);
      const tenantPath = hasCustomDomain ? '' : (req.tenant!.subdomain ? `/${req.tenant!.subdomain}` : '');
      const calendarPageUrl = `${baseUrl}${tenantPath}/dashboard/calendar`;

      const imageBuffer = await generateCalendarShareImage({
        tenantName: req.tenant!.name,
        tenantLogo: req.tenant!.logoUrl,
        calendars: tenantCalendars.map(c => ({ id: c.id, name: c.name, color: c.color || '#6366f1', type: c.type, minVolunteersRequired: c.minVolunteersRequired })),
        events: events.map(e => ({
          id: e.id,
          title: e.title,
          startTime: e.startTime,
          endTime: e.endTime,
          location: e.location,
          description: e.description,
          calendarId: e.calendarId,
        })),
        month,
        calendarPageUrl,
      });

      const { ObjectStorageService } = await import('./objectStorage');
      const objectStorage = new ObjectStorageService();

      const calendarNames = tenantCalendars.map(c => c.name).join('-');
      const monthLabel = month.toISOString().slice(0, 7);
      const slugName = calendarNames.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
      const timestamp = Date.now();
      const shareFilename = slugName + '-' + monthLabel + '-' + timestamp + '.png';

      const { objectPath } = await objectStorage.uploadTenantFile(
        req.tenant!.id,
        'calendar-shares',
        imageBuffer,
        'image/png',
        shareFilename
      );

      const imageUrl = `${baseUrl}${tenantPath}${objectPath}`;

      res.json({
        imageUrl,
        objectPath,
        calendarPageUrl,
        month: month.toISOString(),
      });
    } catch (error) {
      console.error('Error generating calendar share image:', error);
      next(error);
    }
  });

