  /**
   * GET /api/campaign-contributions-summary
   * Get contribution summaries (total raised + count) for all campaigns in bulk
   */
  app.get('/api/campaign-contributions-summary', requireTenant, async (req, res, next) => {
    try {
      const { campaignContributions } = await import('@shared/schema');
      const { sql: sqlTag } = await import('drizzle-orm');

      const summaries = await db
        .select({
          donationLinkId: campaignContributions.donationLinkId,
          totalRaised: sqlTag<number>`COALESCE(SUM(${campaignContributions.amount}), 0)::int`,
          contributorCount: sqlTag<number>`COUNT(*)::int`,
        })
        .from(campaignContributions)
        .where(eq(campaignContributions.tenantId, req.tenant!.id))
        .groupBy(campaignContributions.donationLinkId);

      const summaryMap: Record<string, { totalRaised: number; contributorCount: number }> = {};
      for (const s of summaries) {
        summaryMap[s.donationLinkId] = { totalRaised: s.totalRaised, contributorCount: s.contributorCount };
      }

      res.json({ summaries: summaryMap });
    } catch (error) {
      next(error);
    }
  });

