  /**
   * GET /api/public-emergency-campaigns
   * Public endpoint returning active emergency fund campaigns for the donate page (no auth required)
   */
  app.get('/api/public-emergency-campaigns', requireTenant, async (req, res, next) => {
    try {
      const { donationLinks, campaignContributions } = await import('@shared/schema');
      const { sql: sqlTag } = await import('drizzle-orm');

      const campaigns = await db
        .select({
          id: donationLinks.id,
          title: donationLinks.title,
          description: donationLinks.description,
          imageUrl: donationLinks.imageUrl,
          goalAmount: donationLinks.goalAmount,
          stripePaymentLinkUrl: donationLinks.stripePaymentLinkUrl,
          createdAt: donationLinks.createdAt,
        })
        .from(donationLinks)
        .where(
          and(
            eq(donationLinks.tenantId, req.tenant!.id),
            eq(donationLinks.campaignType, 'emergency_fund'),
            eq(donationLinks.isActive, true)
          )
        )
        .orderBy(desc(donationLinks.createdAt));

      const summaries = await db
        .select({
          donationLinkId: campaignContributions.donationLinkId,
          totalRaised: sqlTag<number>`COALESCE(SUM(${campaignContributions.amount}), 0)::int`,
          contributorCount: sqlTag<number>`COUNT(*)::int`,
        })
        .from(campaignContributions)
        .where(eq(campaignContributions.tenantId, req.tenant!.id))
        .groupBy(campaignContributions.donationLinkId);

      const summaryMap: Record<string, { totalRaised: number; contributorCount: number }> = {};
      for (const s of summaries) {
        summaryMap[s.donationLinkId] = { totalRaised: s.totalRaised, contributorCount: s.contributorCount };
      }

      res.json({ campaigns, summaries: summaryMap });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/emergency-fund-checkout
   * Create a Stripe Checkout Session for an emergency fund campaign with a dynamic donation amount
   */
  app.post('/api/emergency-fund-checkout', requireTenant, async (req, res, next) => {
    try {
      const { donationLinks } = await import('@shared/schema');
      const Stripe = (await import('stripe')).default;

      const checkoutSchema = z.object({
        campaignId: z.string().min(1),
        amount: z.number().int().min(100, "Minimum donation is $1.00"),
      });

      const { campaignId, amount } = checkoutSchema.parse(req.body);

      const [campaign] = await db
        .select({
          id: donationLinks.id,
          title: donationLinks.title,
          description: donationLinks.description,
          imageUrl: donationLinks.imageUrl,
          stripeProductId: donationLinks.stripeProductId,
          tenantId: donationLinks.tenantId,
          isActive: donationLinks.isActive,
          campaignType: donationLinks.campaignType,
        })
        .from(donationLinks)
        .where(
          and(
            eq(donationLinks.id, campaignId),
            eq(donationLinks.tenantId, req.tenant!.id),
            eq(donationLinks.campaignType, 'emergency_fund'),
            eq(donationLinks.isActive, true)
          )
        )
        .limit(1);

      if (!campaign) {
        return res.status(404).json({ error: 'Campaign not found or inactive' });
      }

      const [tenant] = await db
        .select({
          stripeConnectedAccountId: tenants.stripeConnectedAccountId,
          subscriptionTier: tenants.subscriptionTier,
          platformFeePercent: tenants.platformFeePercent,
        })
        .from(tenants)
        .where(eq(tenants.id, req.tenant!.id))
        .limit(1);

      if (!tenant?.stripeConnectedAccountId) {
        return res.status(400).json({ error: 'Stripe Connect account not configured.' });
      }

      const stripeSecretKey = process.env.PLATFORM_STRIPE_SECRET_KEY;
      if (!stripeSecretKey) {
        return res.status(500).json({ error: 'Stripe configuration missing' });
      }

      const stripe = new Stripe(stripeSecretKey, { apiVersion: '2024-12-18.acacia' });

      const { calculatePlatformFee } = await import('./config/platform');
      const platformFeeAmount = calculatePlatformFee(
        amount,
        tenant.subscriptionTier || 'free',
        tenant.platformFeePercent
      );

      const host = req.get('host');
      const protocol = req.headers['x-forwarded-proto'] || 'https';

      const lineItemData: any = {
        price_data: {
          currency: 'usd',
          unit_amount: amount,
          product_data: {
            name: campaign.title,
            description: (campaign.description || `Emergency fund donation for ${campaign.title}`).slice(0, 500),
          },
        },
        quantity: 1,
      };

      if (campaign.imageUrl) {
        const fullImageUrl = campaign.imageUrl!.startsWith("http") ? campaign.imageUrl! : `${protocol}://${host}${campaign.imageUrl!.startsWith("/") ? "" : "/"}${campaign.imageUrl!}`; lineItemData.price_data.product_data.images = [fullImageUrl];
      }

      // ACH eligibility for emergency-fund gift (same $250 one-time threshold).
      const { isAchEligible } = await import('@shared/ach-eligibility');
      const { connectAccountSupportsAch } = await import('./lib/stripe-service');
      let offerEmergencyAch = isAchEligible({
        amountCents: amount,
        isRecurring: false,
        surface: 'emergency_fund',
      });
      if (offerEmergencyAch && tenant.stripeConnectedAccountId) {
        offerEmergencyAch = await connectAccountSupportsAch(stripe, tenant.stripeConnectedAccountId);
      }

      const sessionParams: any = {
        mode: 'payment',
        submit_type: 'donate',
        line_items: [lineItemData],
        success_url: `${protocol}://${host}/thank-you?session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: `${protocol}://${host}/donate`,
        custom_text: {
          submit: {
            message: (campaign.description || `Thank you for supporting ${campaign.title}!`).slice(0, 1200),
          },
        },
        metadata: {
          campaignId: campaign.id,
          tenantId: req.tenant!.id,
          type: 'emergency_fund',
          achSurface: 'emergency_fund',
          achOffered: offerEmergencyAch ? 'true' : 'false',
        },
        payment_method_types: offerEmergencyAch ? ['card', 'us_bank_account'] : ['card'],
        ...(offerEmergencyAch ? {
          payment_method_options: {
            us_bank_account: {
              financial_connections: { permissions: ['payment_method', 'balances'] },
              verification_method: 'instant',
            },
          },
        } : {}),
        payment_intent_data: { statement_descriptor_suffix: toStripeStatementDescriptor(tenant.name) },
      };

      if (platformFeeAmount > 0) {
        sessionParams.payment_intent_data.application_fee_amount = platformFeeAmount;
        console.log(`[EMERGENCY-FUND] Platform fee: ${platformFeeAmount} cents on ${amount} cent donation`);
      }

      const session = await stripe.checkout.sessions.create(sessionParams, {
        stripeAccount: tenant.stripeConnectedAccountId,
      });

      res.json({ url: session.url });
    } catch (error) {
      next(error);
    }
  });





  /**
   * GET /api/campaign-updates/:donationLinkId
   * Get all updates for a campaign (public-facing, no auth required)
   */
  app.get('/api/campaign-updates/:donationLinkId', requireTenant, async (req, res, next) => {
    try {
      const { campaignUpdates, donationLinks } = await import('@shared/schema');
      const { donationLinkId } = req.params;

      const [campaign] = await db
        .select({ id: donationLinks.id })
        .from(donationLinks)
        .where(and(
          eq(donationLinks.id, donationLinkId),
          eq(donationLinks.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!campaign) {
        return res.status(404).json({ error: 'Campaign not found' });
      }

      const updates = await db
        .select()
        .from(campaignUpdates)
        .where(and(
          eq(campaignUpdates.donationLinkId, donationLinkId),
          eq(campaignUpdates.tenantId, req.tenant!.id)
        ))
        .orderBy(desc(campaignUpdates.createdAt));

      res.json({ updates });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/campaign-updates
   * Create a new campaign update (staff only)
   */
  app.post('/api/campaign-updates', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff'), async (req, res, next) => {
    try {
      const { campaignUpdates, donationLinks } = await import('@shared/schema');

      const updateSchema = z.object({
        donationLinkId: z.string().uuid(),
        title: z.string().min(1).max(200),
        content: z.string().min(1).max(5000),
        photoUrls: z.array(z.string()).optional().default([]),
      });

      const data = updateSchema.parse(req.body);

      const [campaign] = await db
        .select({ id: donationLinks.id })
        .from(donationLinks)
        .where(and(
          eq(donationLinks.id, data.donationLinkId),
          eq(donationLinks.tenantId, req.tenant!.id),
          eq(donationLinks.campaignType, 'emergency_fund')
        ))
        .limit(1);

      if (!campaign) {
        return res.status(404).json({ error: 'Emergency fund campaign not found' });
      }

      const [update] = await db
        .insert(campaignUpdates)
        .values({
          tenantId: req.tenant!.id,
          donationLinkId: data.donationLinkId,
          title: data.title,
          content: data.content,
          photoUrls: data.photoUrls,
        })
        .returning();

      res.status(201).json({ update });
    } catch (error) {
      next(error);
    }
  });

