  /**
   * GET /api/person-documents/:personType/:personId
   * Fetch all documents and related applications/agreements for a person
   */
  app.get('/api/person-documents/:personType/:personId', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { personDocuments, contacts, applications: applicationsTable, fosterApplications: fosterAppsTable, volunteerApplications: volunteerAppsTable, adoptionContracts: adoptionContractsTable, adoptionCheckoutSessions: adoptionSessionsTable, placementAgreementSessions: placementSessionsTable, fosterAgreementSessions: fosterSessionsTable, surrenderAgreementSessions: surrenderSessionsTable, volunteerAgreementSessions: volunteerSessionsTable, animals: animalsTable } = await import('@shared/schema');

      const tenantId = req.tenant!.id;
      const { personType, personId } = req.params;

      const docs = await db
        .select()
        .from(personDocuments)
        .where(
          and(
            eq(personDocuments.tenantId, tenantId),
            eq(personDocuments.personType, personType),
            eq(personDocuments.personId, personId)
          )
        )
        .orderBy(desc(personDocuments.createdAt));

      let contactEmail: string | null = null;
      if (personType === 'contact') {
        const [contact] = await db
          .select({ email: contacts.email })
          .from(contacts)
          .where(and(eq(contacts.id, personId), eq(contacts.tenantId, tenantId)))
          .limit(1);
        contactEmail = contact?.email?.toLowerCase()?.trim() || null;
      }

      const relatedApplications: Array<{
        id: string;
        type: string;
        title: string;
        applicantName: string;
        applicantEmail: string;
        status: string;
        createdAt: string;
      }> = [];

      if (contactEmail) {
        const adoptionApps = await db
          .select({
            id: applicationsTable.id,
            applicantName: applicationsTable.applicantName,
            applicantEmail: applicationsTable.applicantEmail,
            status: applicationsTable.stage,
            animalId: applicationsTable.animalId,
            createdAt: applicationsTable.createdAt,
          })
          .from(applicationsTable)
          .where(
            and(
              eq(applicationsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${applicationsTable.applicantEmail})) = ${contactEmail}`
            )
          )
          .orderBy(desc(applicationsTable.createdAt));

        for (const app of adoptionApps) {
          const [animal] = await db
            .select({ name: animalsTable.name })
            .from(animalsTable)
            .where(eq(animalsTable.id, app.animalId))
            .limit(1);
          relatedApplications.push({
            id: app.id,
            type: 'adoption_application',
            title: `Adoption Application - ${animal?.name || 'Unknown'}`,
            applicantName: app.applicantName,
            applicantEmail: app.applicantEmail,
            status: app.status,
            createdAt: app.createdAt.toISOString(),
          });
        }

        const fosterApps = await db
          .select({
            id: fosterAppsTable.id,
            applicantName: fosterAppsTable.applicantName,
            applicantEmail: fosterAppsTable.applicantEmail,
            status: fosterAppsTable.status,
            createdAt: fosterAppsTable.createdAt,
          })
          .from(fosterAppsTable)
          .where(
            and(
              eq(fosterAppsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${fosterAppsTable.applicantEmail})) = ${contactEmail}`
            )
          )
          .orderBy(desc(fosterAppsTable.createdAt));

        for (const app of fosterApps) {
          relatedApplications.push({
            id: app.id,
            type: 'foster_application',
            title: `Foster Application`,
            applicantName: app.applicantName,
            applicantEmail: app.applicantEmail,
            status: app.status,
            createdAt: app.createdAt.toISOString(),
          });
        }

        const volunteerApps = await db
          .select({
            id: volunteerAppsTable.id,
            applicantName: volunteerAppsTable.applicantName,
            applicantEmail: volunteerAppsTable.applicantEmail,
            status: volunteerAppsTable.status,
            createdAt: volunteerAppsTable.createdAt,
          })
          .from(volunteerAppsTable)
          .where(
            and(
              eq(volunteerAppsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${volunteerAppsTable.applicantEmail})) = ${contactEmail}`
            )
          )
          .orderBy(desc(volunteerAppsTable.createdAt));

        for (const app of volunteerApps) {
          relatedApplications.push({
            id: app.id,
            type: 'volunteer_application',
            title: `Volunteer Application`,
            applicantName: app.applicantName,
            applicantEmail: app.applicantEmail,
            status: app.status,
            createdAt: app.createdAt.toISOString(),
          });
        }
      }

      const allDocuments = docs.map(d => ({
        id: d.id,
        title: d.title,
        description: d.description,
        documentType: d.documentType,
        documentSubtype: d.documentSubtype,
        objectPath: d.objectPath,
        fileName: d.fileName,
        fileSize: d.fileSize,
        createdAt: d.createdAt.toISOString(),
      }));

      if (contactEmail) {
        const existingDocSourceIds = new Set(docs.filter(d => d.sourceId).map(d => d.sourceId));

        const adoptionAgreements = await db
          .select({
            contractId: adoptionContractsTable.id,
            signerName: adoptionContractsTable.signerName,
            signerEmail: adoptionContractsTable.signerEmail,
            signedAt: adoptionContractsTable.signedAt,
            contractPdfUrl: adoptionContractsTable.contractPdfUrl,
            sessionId: adoptionContractsTable.sessionId,
            animalId: adoptionSessionsTable.animalId,
          })
          .from(adoptionContractsTable)
          .innerJoin(adoptionSessionsTable, eq(adoptionContractsTable.sessionId, adoptionSessionsTable.id))
          .where(
            and(
              eq(adoptionSessionsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${adoptionContractsTable.signerEmail})) = ${contactEmail}`,
              isNotNull(adoptionContractsTable.signedAt)
            )
          )
          .orderBy(desc(adoptionContractsTable.signedAt));

        for (const ag of adoptionAgreements) {
          if (existingDocSourceIds.has(ag.sessionId)) continue;
          const [animal] = await db
            .select({ name: animalsTable.name })
            .from(animalsTable)
            .where(eq(animalsTable.id, ag.animalId))
            .limit(1);
          allDocuments.push({
            id: `ac-${ag.contractId}`,
            title: `Adoption Contract - ${animal?.name || 'Unknown'}`,
            description: `Signed by ${ag.signerName} on ${ag.signedAt?.toLocaleDateString() || 'unknown date'}`,
            documentType: 'agreement',
            documentSubtype: 'adoption_contract',
            objectPath: ag.contractPdfUrl,
            fileName: `adoption-contract-${(animal?.name || 'unknown').replace(/\s+/g, '-').toLowerCase()}.pdf`,
            fileSize: null,
            createdAt: ag.signedAt?.toISOString() || new Date().toISOString(),
          });
        }

        const placementAgreements = await db
          .select({
            id: placementSessionsTable.id,
            fosterName: placementSessionsTable.fosterName,
            fosterEmail: placementSessionsTable.fosterEmail,
            signedAt: placementSessionsTable.signedAt,
            contractPdfUrl: placementSessionsTable.contractPdfUrl,
            animalName: placementSessionsTable.animalName,
          })
          .from(placementSessionsTable)
          .where(
            and(
              eq(placementSessionsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${placementSessionsTable.fosterEmail})) = ${contactEmail}`,
              isNotNull(placementSessionsTable.signedAt)
            )
          )
          .orderBy(desc(placementSessionsTable.signedAt));

        for (const ag of placementAgreements) {
          if (existingDocSourceIds.has(ag.id)) continue;
          allDocuments.push({
            id: `pa-${ag.id}`,
            title: `Placement Agreement - ${ag.animalName || 'Unknown'}`,
            description: `Signed by ${ag.fosterName} on ${ag.signedAt?.toLocaleDateString() || 'unknown date'}`,
            documentType: 'agreement',
            documentSubtype: 'placement_agreement',
            objectPath: ag.contractPdfUrl,
            fileName: `placement-agreement-${(ag.animalName || 'unknown').replace(/\s+/g, '-').toLowerCase()}.pdf`,
            fileSize: null,
            createdAt: ag.signedAt?.toISOString() || new Date().toISOString(),
          });
        }

        const fosterAgreements = await db
          .select({
            id: fosterSessionsTable.id,
            fosterName: fosterSessionsTable.fosterName,
            fosterEmail: fosterSessionsTable.fosterEmail,
            signedAt: fosterSessionsTable.signedAt,
            contractPdfUrl: fosterSessionsTable.contractPdfUrl,
            animalName: fosterSessionsTable.animalName,
          })
          .from(fosterSessionsTable)
          .where(
            and(
              eq(fosterSessionsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${fosterSessionsTable.fosterEmail})) = ${contactEmail}`,
              isNotNull(fosterSessionsTable.signedAt)
            )
          )
          .orderBy(desc(fosterSessionsTable.signedAt));

        for (const ag of fosterAgreements) {
          if (existingDocSourceIds.has(ag.id)) continue;
          allDocuments.push({
            id: `fa-${ag.id}`,
            title: `Foster Agreement - ${ag.animalName || 'Unknown'}`,
            description: `Signed by ${ag.fosterName} on ${ag.signedAt?.toLocaleDateString() || 'unknown date'}`,
            documentType: 'agreement',
            documentSubtype: 'foster_agreement',
            objectPath: ag.contractPdfUrl,
            fileName: `foster-agreement-${(ag.animalName || 'unknown').replace(/\s+/g, '-').toLowerCase()}.pdf`,
            fileSize: null,
            createdAt: ag.signedAt?.toISOString() || new Date().toISOString(),
          });
        }

        const surrenderAgreements = await db
          .select({
            id: surrenderSessionsTable.id,
            ownerName: surrenderSessionsTable.ownerName,
            ownerEmail: surrenderSessionsTable.ownerEmail,
            signedAt: surrenderSessionsTable.signedAt,
            contractPdfUrl: surrenderSessionsTable.contractPdfUrl,
          })
          .from(surrenderSessionsTable)
          .where(
            and(
              eq(surrenderSessionsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${surrenderSessionsTable.ownerEmail})) = ${contactEmail}`,
              isNotNull(surrenderSessionsTable.signedAt)
            )
          )
          .orderBy(desc(surrenderSessionsTable.signedAt));

        for (const ag of surrenderAgreements) {
          if (existingDocSourceIds.has(ag.id)) continue;
          allDocuments.push({
            id: `sa-${ag.id}`,
            title: `Surrender Agreement`,
            description: `Signed by ${ag.ownerName} on ${ag.signedAt?.toLocaleDateString() || 'unknown date'}`,
            documentType: 'agreement',
            documentSubtype: 'surrender_agreement',
            objectPath: ag.contractPdfUrl,
            fileName: `surrender-agreement.pdf`,
            fileSize: null,
            createdAt: ag.signedAt?.toISOString() || new Date().toISOString(),
          });
        }

        const volunteerWaivers = await db
          .select({
            id: volunteerSessionsTable.id,
            volunteerName: volunteerSessionsTable.volunteerName,
            volunteerEmail: volunteerSessionsTable.volunteerEmail,
            signedAt: volunteerSessionsTable.signedAt,
            contractPdfUrl: volunteerSessionsTable.contractPdfUrl,
          })
          .from(volunteerSessionsTable)
          .where(
            and(
              eq(volunteerSessionsTable.tenantId, tenantId),
              sql`LOWER(TRIM(${volunteerSessionsTable.volunteerEmail})) = ${contactEmail}`,
              isNotNull(volunteerSessionsTable.signedAt)
            )
          )
          .orderBy(desc(volunteerSessionsTable.signedAt));

        for (const ag of volunteerWaivers) {
          if (existingDocSourceIds.has(ag.id)) continue;
          allDocuments.push({
            id: `vw-${ag.id}`,
            title: `Volunteer Hold Harmless Waiver`,
            description: `Signed by ${ag.volunteerName} on ${ag.signedAt?.toLocaleDateString() || 'unknown date'}`,
            documentType: 'agreement',
            documentSubtype: 'volunteer_hold_harmless',
            objectPath: ag.contractPdfUrl,
            fileName: `volunteer-waiver.pdf`,
            fileSize: null,
            createdAt: ag.signedAt?.toISOString() || new Date().toISOString(),
          });
        }
      }

      res.json({
        documents: allDocuments,
        relatedApplications,
      });
    } catch (error) {
      next(error);
    }
  });

