  /**
   * GET /api/person-documents/:id/signed-url
   * Get a signed URL for viewing/downloading a person document
   */
  app.get('/api/person-documents/:id/signed-url', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { personDocuments } = await import('@shared/schema');
      const { signObjectURL } = await import('./objectStorage');
      const tenantId = req.tenant!.id;
      const disposition = (req.query.disposition as string) || 'inline';

      let objectPath: string | null = null;

      const docId = req.params.id;
      const isVirtualDoc = /^(ac|pa|fa|sa|vw)-/.test(docId);

      if (isVirtualDoc) {
        objectPath = req.query.objectPath as string || null;
      } else {
        const [doc] = await db
          .select()
          .from(personDocuments)
          .where(
            and(
              eq(personDocuments.id, docId),
              eq(personDocuments.tenantId, tenantId)
            )
          )
          .limit(1);

        if (!doc) {
          return res.status(404).json({ error: 'Document not found' });
        }
        objectPath = doc.objectPath;
      }

      if (!objectPath) {
        return res.status(400).json({ error: 'Document has no file attached' });
      }

      if (objectPath.startsWith('http://') || objectPath.startsWith('https://')) {
        return res.json({ signedUrl: objectPath });
      }

      const privateObjectDir = process.env.PRIVATE_OBJECT_DIR;
      if (!privateObjectDir) {
        return res.status(500).json({ error: 'Object storage not configured' });
      }

      const pathAfterObjects = objectPath.replace(/^\/objects\//, '');
      const fullPath = `${privateObjectDir}/${pathAfterObjects}`;
      const pathParts = fullPath.split('/');
      const bucketName = pathParts[1];
      const objectName = pathParts.slice(2).join('/');

      const signedUrl = await signObjectURL({
        bucketName,
        objectName,
        method: 'GET',
        ttlSec: 900,
      });

      res.json({ signedUrl });
    } catch (error) {
      next(error);
    }
  });

