  /**
   * GET /api/order-sets
   * List order sets for current tenant with their items populated
   */
  app.get('/api/order-sets', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const { orderSets, orderSetItems, medicalCatalog } = await import('@shared/schema');
      const tenantId = req.tenant!.id;

      const sets = await db
        .select()
        .from(orderSets)
        .where(and(eq(orderSets.tenantId, tenantId), eq(orderSets.isActive, true)))
        .orderBy(orderSets.setName);

      const result = await Promise.all(sets.map(async (set) => {
        const items = await db
          .select({
            id: orderSetItems.id,
            sortOrder: orderSetItems.sortOrder,
            offsetDays: orderSetItems.offsetDays,
            catalogItem: {
              id: medicalCatalog.id,
              name: medicalCatalog.name,
              category: medicalCatalog.category,
              defaultDose: medicalCatalog.defaultDose,
              defaultFrequency: medicalCatalog.defaultFrequency,
            },
          })
          .from(orderSetItems)
          .innerJoin(medicalCatalog, eq(orderSetItems.catalogItemId, medicalCatalog.id))
          .where(eq(orderSetItems.orderSetId, set.id))
          .orderBy(orderSetItems.sortOrder);

        return { ...set, items };
      }));

      res.json(result);
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/order-sets
   * Create an order set with items
   */
  app.post('/api/order-sets', requireTenant, requireAuth, requireRole('admin', 'owner', 'staff'), async (req, res, next) => {
    try {
      const { orderSets, orderSetItems } = await import('@shared/schema');
      const tenantId = req.tenant!.id;
      const { setName, description, catalogItemIds, items: itemsWithOffset } = req.body;

      const hasItems = Array.isArray(itemsWithOffset) && itemsWithOffset.length > 0;
      const hasLegacy = Array.isArray(catalogItemIds) && catalogItemIds.length > 0;

      if (!setName || (!hasItems && !hasLegacy)) {
        return res.status(400).json({ error: 'setName and items (or catalogItemIds) are required' });
      }

      const [createdSet] = await db
        .insert(orderSets)
        .values({ tenantId, setName, description: description || null })
        .returning();

      const itemRows = hasItems
        ? itemsWithOffset.map((item: { catalogItemId: string; offsetDays?: number }, idx: number) => ({
            orderSetId: createdSet.id,
            catalogItemId: item.catalogItemId,
            sortOrder: idx,
            offsetDays: item.offsetDays ?? 0,
          }))
        : catalogItemIds.map((catId: string, idx: number) => ({
            orderSetId: createdSet.id,
            catalogItemId: catId,
            sortOrder: idx,
            offsetDays: 0,
          }));

      await db.insert(orderSetItems).values(itemRows);

      res.status(201).json(createdSet);
    } catch (error) {
      next(error);
    }
  });

  // ===== FUNDRAISER EVENTS =====

  /**
   * POST /api/fundraiser-events/images/upload
   * Admin: upload a hero image for a fundraiser event
   */
  app.post('/api/fundraiser-events/images/upload', requireTenant, requireAuth, requireRoleOrPageAccess('fundraiser-events', 'admin', 'owner'), async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { TenantFileStorage } = await import('./lib/tenantFileStorage');
      const imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'heic', 'heif', 'bmp', 'avif'];
      const upload = multer({
        storage: multer.memoryStorage(),
        limits: { fileSize: 10 * 1024 * 1024 },
        fileFilter: (_req, file, cb) => {
          if (file.mimetype.startsWith('image/')) { cb(null, true); return; }
          const ext = file.originalname.toLowerCase().split('.').pop();
          if (ext && imageExtensions.includes(ext)) { cb(null, true); } else { cb(new Error('Only image files are allowed')); }
        },
      }).single('file');

      upload(req, res, async (err) => {
        if (err) return res.status(400).json({ error: err.message });
        const file = req.file;
        if (!file) return res.status(400).json({ error: 'No file uploaded' });
        try {
          const tenantId = req.tenant!.id;
          const userId = req.session.userId!;
          let fileBuffer = file.buffer;
          let contentType = file.mimetype;
          const ext = file.originalname.toLowerCase().split('.').pop();
          if (ext === 'heic' || ext === 'heif' || file.mimetype === 'image/heic' || file.mimetype === 'image/heif') {
            try {
              const heicConvert = (await import('heic-convert')).default;
              const converted = await heicConvert({ buffer: file.buffer, format: 'JPEG', quality: 0.9 });
              fileBuffer = Buffer.from(converted);
              contentType = 'image/jpeg';
            } catch { /* keep original */ }
          }
          const storage = await TenantFileStorage.forTenant(tenantId);
          const result = await storage.uploadFile({
            tenantId, userId,
            category: 'fundraiser-images',
            visibility: 'public',
            fileName: file.originalname,
            mimeType: contentType,
            content: fileBuffer,
          });
          if (!result.success) return res.status(500).json({ error: result.error || 'Upload failed' });
          res.json({ imageUrl: result.fileUrl });
        } catch (e: any) {
          console.error('[FUNDRAISER-UPLOAD]', e);
          res.status(500).json({ error: 'Upload failed' });
        }
      });
    } catch (error) { next(error); }
  });

