  /**
   * POST /api/peer-campaigns
   * Public: Create a new P2P fundraiser campaign
   */
  app.post('/api/peer-campaigns', requireTenant, async (req, res, next) => {
    try {
      const { peerCampaigns } = await import('@shared/schema');

      const createSchema = z.object({
        creatorName: z.string().min(1).max(200),
        creatorEmail: z.string().email(),
        campaignTitle: z.string().min(1).max(200),
        campaignStory: z.string().max(5000).optional(),
        goalAmount: z.number().int().min(100),
        goalType: z.enum(['currency', 'units']).default('currency'),
        goalUnitLabel: z.string().max(50).optional(),
        goalTarget: z.number().int().min(1).optional(),
        animalName: z.string().max(100).optional(),
        coverImageUrl: z.string().max(500).optional(),
        endsAt: z.string().optional(),
        primaryColor: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
        accentColor: z.string().regex(/^#[0-9a-fA-F]{6}$/).optional(),
      });

      const data = createSchema.parse(req.body);

      // If an animal name is provided, prepend it to the story for context
      let finalStory = data.campaignStory || null;
      if (data.animalName && data.animalName.trim()) {
        const animalPrefix = `This campaign is for ${data.animalName.trim()}.`;
        finalStory = finalStory ? `${animalPrefix}\n\n${finalStory}` : animalPrefix;
      }

      let slug = data.campaignTitle
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .substring(0, 60);

      const [existing] = await db
        .select({ id: peerCampaigns.id })
        .from(peerCampaigns)
        .where(and(eq(peerCampaigns.tenantId, req.tenant!.id), eq(peerCampaigns.slug, slug)))
        .limit(1);

      if (existing) {
        slug = slug + '-' + Date.now().toString(36);
      }

      const [campaign] = await db.insert(peerCampaigns).values({
        tenantId: req.tenant!.id,
        creatorName: data.creatorName,
        creatorEmail: data.creatorEmail,
        campaignTitle: data.campaignTitle,
        campaignStory: finalStory,
        goalAmount: data.goalAmount,
        goalType: data.goalType,
        goalUnitLabel: data.goalUnitLabel || null,
        goalTarget: data.goalTarget || null,
        slug,
        coverImageUrl: data.coverImageUrl || null,
        endsAt: data.endsAt ? new Date(data.endsAt) : null,
        primaryColor: data.primaryColor || null,
        accentColor: data.accentColor || null,
      }).returning();

      res.json({ campaign });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/peer-campaigns/public-media/upload
   * Public: Upload a cover image for a campaign (no auth required)
   */
  app.post('/api/peer-campaigns/public-media/upload', requireTenant, async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { TenantFileStorage } = await import('./lib/tenantFileStorage');

      const imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'heif'];

      const upload = multer({
        storage: multer.memoryStorage(),
        limits: { fileSize: 10 * 1024 * 1024 },
        fileFilter: (_req: any, file: any, cb: any) => {
          const ext = file.originalname.toLowerCase().split('.').pop();
          if (file.mimetype.startsWith('image/') || (ext && imageExtensions.includes(ext))) {
            cb(null, true);
          } else {
            cb(new Error('Only image files are allowed'));
          }
        },
      }).array('files', 1);

      upload(req, res, async (err: any) => {
        if (err) return res.status(400).json({ error: err.message });

        const files = req.files as Express.Multer.File[];
        if (!files || files.length === 0) return res.status(400).json({ error: 'No files uploaded' });

        try {
          const tenantId = req.tenant!.id;
          const storage = await TenantFileStorage.forTenant(tenantId);
          const uploadedPaths: string[] = [];

          for (const file of files) {
            const ext = file.originalname.split('.').pop() || 'jpg';
            const fileName = `campaign-cover-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
            const filePath = `campaigns/${fileName}`;
            const objectPath = await storage.uploadFile(filePath, file.buffer, file.mimetype);
            uploadedPaths.push(objectPath);
          }

          res.json({ uploadedPaths });
        } catch (uploadError) {
          next(uploadError);
        }
      });
    } catch (error) {
      next(error);
    }
  });

  
