  /**
   * GET /api/peer-campaigns/:slug
   * Public: Get a campaign by slug for the landing page
   */
  app.get('/api/peer-campaigns/:slug', requireTenant, async (req, res, next) => {
    try {
      const { peerCampaigns, peerCampaignDonations } = await import('@shared/schema');

      const [campaign] = await db
        .select()
        .from(peerCampaigns)
        .where(and(
          eq(peerCampaigns.tenantId, req.tenant!.id),
          eq(peerCampaigns.slug, req.params.slug),
          eq(peerCampaigns.isActive, true)
        ))
        .limit(1);

      if (!campaign) return res.status(404).json({ error: 'Campaign not found' });

      const donations = await db
        .select({
          donorName: peerCampaignDonations.donorName,
          amount: peerCampaignDonations.amount,
          message: peerCampaignDonations.message,
          isAnonymous: peerCampaignDonations.isAnonymous,
          pledgeType: peerCampaignDonations.pledgeType,
          pledgePerUnit: peerCampaignDonations.pledgePerUnit,
          createdAt: peerCampaignDonations.createdAt,
        })
        .from(peerCampaignDonations)
        .where(and(
          eq(peerCampaignDonations.peerCampaignId, campaign.id),
          sql`(${peerCampaignDonations.paymentStatus} = 'paid' OR ${peerCampaignDonations.pledgeType} = 'per_unit')`
        ))
        .orderBy(desc(peerCampaignDonations.createdAt))
        .limit(50);

      const { peerCampaignUpdates } = await import('@shared/schema');
      const updates = await db
        .select()
        .from(peerCampaignUpdates)
        .where(eq(peerCampaignUpdates.peerCampaignId, campaign.id))
        .orderBy(desc(peerCampaignUpdates.createdAt))
        .limit(50);

      let animal = null;
      if (campaign.animalId) {
        const { animals } = await import('@shared/schema');
        const [a] = await db.select({ id: animals.id, name: animals.name, species: animals.species, breed: animals.breed, photoUrls: animals.photoUrls }).from(animals).where(eq(animals.id, campaign.animalId)).limit(1);
        animal = a || null;
      }

      const { campaignParticipants } = await import('@shared/schema');
      const participantsRaw = await db
        .select()
        .from(campaignParticipants)
        .where(and(
          eq(campaignParticipants.peerCampaignId, campaign.id),
          eq(campaignParticipants.tenantId, req.tenant!.id),
          eq(campaignParticipants.isActive, true)
        ))
        .orderBy(desc(campaignParticipants.currentUnits));

      let participants: any[] = [];
      if (participantsRaw.length > 0) {
        const pledgeTotals = await db
          .select({
            participantId: peerCampaignDonations.participantId,
            totalAmount: sql<number>`COALESCE(SUM(${peerCampaignDonations.amount}), 0)`,
            donationCount: sql<number>`COUNT(*)`,
          })
          .from(peerCampaignDonations)
          .where(and(
            eq(peerCampaignDonations.peerCampaignId, campaign.id),
            isNotNull(peerCampaignDonations.participantId),
            sql`(${peerCampaignDonations.paymentStatus} = 'paid' OR ${peerCampaignDonations.pledgeType} = 'per_unit')`
          ))
          .groupBy(peerCampaignDonations.participantId);

        const totalsMap = new Map(pledgeTotals.map(t => [t.participantId, { totalAmount: Number(t.totalAmount), donationCount: Number(t.donationCount) }]));
        participants = participantsRaw.map(p => ({
          ...p,
          totalRaised: totalsMap.get(p.id)?.totalAmount || 0,
          donationCount: totalsMap.get(p.id)?.donationCount || 0,
        }));
      }

      res.json({ campaign, donations, updates, animal, participants });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/peer-campaigns/:slug/checkout
   * Public: Create a Stripe checkout session for donating to a P2P campaign
   */
  app.post('/api/peer-campaigns/:slug/checkout', requireTenant, async (req, res, next) => {
    try {
      const { peerCampaigns, peerCampaignDonations, campaignParticipants } = await import('@shared/schema');
      const { stripeService } = await import('./lib/stripe-service');
      const { calculatePlatformFee, calculateDonorCoversFees } = await import('./config/platform');

      const checkoutSchema = z.object({
        amount: z.number().int().min(100),
        donorName: z.string().min(1),
        donorEmail: z.string().email().optional(),
        message: z.string().max(500).optional(),
        isAnonymous: z.boolean().default(false),
        donorCoversFees: z.boolean().default(false),
        participantId: z.string().uuid().optional(),
      });

      const data = checkoutSchema.parse(req.body);

      const [campaign] = await db
        .select()
        .from(peerCampaigns)
        .where(and(
          eq(peerCampaigns.tenantId, req.tenant!.id),
          eq(peerCampaigns.slug, req.params.slug),
          eq(peerCampaigns.isActive, true)
        ))
        .limit(1);

      if (!campaign) return res.status(404).json({ error: 'Campaign not found' });

      if (campaign.status === 'completed' || campaign.status === 'cancelled') {
        return res.status(400).json({ error: 'This campaign is no longer accepting donations' });
      }
      if (campaign.endsAt && new Date(campaign.endsAt) < new Date()) {
        return res.status(400).json({ error: 'This campaign has ended' });
      }

      if (data.participantId) {
        const [validParticipant] = await db
          .select({ id: campaignParticipants.id })
          .from(campaignParticipants)
          .where(and(
            eq(campaignParticipants.id, data.participantId),
            eq(campaignParticipants.peerCampaignId, campaign.id),
            eq(campaignParticipants.tenantId, req.tenant!.id),
            eq(campaignParticipants.isActive, true)
          ))
          .limit(1);
        if (!validParticipant) {
          return res.status(400).json({ error: 'Invalid participant' });
        }
      }

      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, req.tenant!.id))
        .limit(1);

      if (!tenant || !tenant.stripeEnabled) {
        return res.status(400).json({ error: 'Stripe is not configured for this rescue' });
      }

      let chargeAmount = data.amount;
      let feesCovered = 0;
      if (data.donorCoversFees) {
        const feeCalc = calculateDonorCoversFees(data.amount, tenant.subscriptionTier || 'free', tenant.platformFeePercent);
        chargeAmount = feeCalc.totalAmount;
        feesCovered = feeCalc.feesCovered;
      }

      const platformFeeAmount = calculatePlatformFee(chargeAmount, tenant.subscriptionTier || 'free', tenant.platformFeePercent);

      const [donation] = await db.insert(peerCampaignDonations).values({
        tenantId: req.tenant!.id,
        peerCampaignId: campaign.id,
        donorName: data.donorName,
        donorEmail: data.donorEmail || null,
        amount: data.amount,
        message: data.message || null,
        isAnonymous: data.isAnonymous,
        paymentStatus: 'pending',
        participantId: data.participantId || null,
      }).returning();

      const host = req.get('host') || '';
      const baseUrl = `${req.protocol}://${host}`;
      const hasCustomDomain = (tenant as any).customDomain && host.includes((tenant as any).customDomain);
      const tenantPath = hasCustomDomain ? '' : (tenant.subdomain ? `/${tenant.subdomain}` : '');

      const session = await stripeService.createCheckoutSession(tenant, {
        amount: chargeAmount,
        currency: 'usd',
        customerEmail: data.donorEmail,
        isRecurring: false,
        // 'p2p' surface: ACH offered on one-time gifts >= $250. Lower amounts
        // stay card-only so small impulse pledges still confirm instantly on
        // the public campaign page.
        surface: 'p2p',
        successUrl: `${baseUrl}${tenantPath}/campaign/${campaign.slug}?donation=success`,
        cancelUrl: `${baseUrl}${tenantPath}/campaign/${campaign.slug}`,
        platformFeeAmount: platformFeeAmount,
        connectedAccountId: tenant.stripeConnectedAccountId || undefined,
        metadata: {
          peerCampaignId: campaign.id,
          peerCampaignSlug: campaign.slug,
          peerDonationId: donation.id,
          donorName: data.donorName,
          isAnonymous: data.isAnonymous.toString(),
          baseAmount: data.amount.toString(),
          chargeAmount: chargeAmount.toString(),
          donorCoveredFees: data.donorCoversFees.toString(),
          feesCovered: feesCovered.toString(),
          platformFeeAmount: platformFeeAmount.toString(),
        },
      });

      if (!session) {
        return res.status(500).json({ error: 'Failed to create checkout session' });
      }

      await db.update(peerCampaignDonations)
        .set({ stripeSessionId: session.id })
        .where(eq(peerCampaignDonations.id, donation.id));

      res.json({ sessionId: session.id, url: session.url });
    } catch (error) {
      next(error);
    }
  });

  /**
   * GET /api/peer-campaigns
   * Admin: List all P2P campaigns for the tenant
   */
  app.get('/api/peer-campaigns', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff', 'manager'), async (req, res, next) => {
    try {
      const { peerCampaigns, peerCampaignDonations } = await import('@shared/schema');

      const campaigns = await db
        .select()
        .from(peerCampaigns)
        .where(eq(peerCampaigns.tenantId, req.tenant!.id))
        .orderBy(desc(peerCampaigns.createdAt));

      const campaignIds = campaigns.map(c => c.id);
      let donationCounts: Record<string, { count: number; total: number }> = {};

      if (campaignIds.length > 0) {
        const stats = await db
          .select({
            campaignId: peerCampaignDonations.peerCampaignId,
            count: sql<number>`COUNT(*)`,
            total: sql<number>`COALESCE(SUM(${peerCampaignDonations.amount}), 0)`,
          })
          .from(peerCampaignDonations)
          .where(and(
            eq(peerCampaignDonations.paymentStatus, 'paid'),
            inArray(peerCampaignDonations.peerCampaignId, campaignIds)
          ))
          .groupBy(peerCampaignDonations.peerCampaignId);

        stats.forEach(s => {
          donationCounts[s.campaignId] = { count: Number(s.count), total: Number(s.total) };
        });
      }

      let intakeSubmittedIds = new Set<string>();
      if (campaignIds.length > 0) {
        const intakeRows = await db
          .select({ campaignId: campaignIntakeTokens.createdCampaignId })
          .from(campaignIntakeTokens)
          .where(and(
            eq(campaignIntakeTokens.tenantId, req.tenant!.id),
            isNotNull(campaignIntakeTokens.createdCampaignId)
          ));
        intakeRows.forEach(r => { if (r.campaignId) intakeSubmittedIds.add(r.campaignId); });
      }

      const enriched = campaigns.map(c => ({
        ...c,
        donationCount: donationCounts[c.id]?.count || 0,
        donationTotal: donationCounts[c.id]?.total || 0,
        isPartnerSubmitted: intakeSubmittedIds.has(c.id),
      }));

      res.json({ campaigns: enriched });
    } catch (error) {
      next(error);
    }
  });

