  /**
   * POST /api/peer-campaigns/media/upload
   * Staff: Upload media (images/videos) for campaign updates
   */
  app.post('/api/peer-campaigns/media/upload', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff', 'manager'), async (req, res, next) => {
    try {
      const multer = (await import('multer')).default;
      const { TenantFileStorage } = await import('./lib/tenantFileStorage');

      const allowedExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'heic', 'heif', 'mp4', 'mov', 'webm', 'ogg', 'm4v'];

      const upload = multer({
        storage: multer.memoryStorage(),
        limits: { fileSize: 100 * 1024 * 1024 },
        fileFilter: (_req: any, file: any, cb: any) => {
          const ext = file.originalname.toLowerCase().split('.').pop();
          if (file.mimetype.startsWith('image/') || file.mimetype.startsWith('video/') || (ext && allowedExtensions.includes(ext))) {
            cb(null, true);
          } else {
            cb(new Error('Only image and video files are allowed'));
          }
        },
      }).array('files', 5);

      upload(req, res, async (err: any) => {
        if (err) return res.status(400).json({ error: err.message });

        const files = req.files as Express.Multer.File[];
        if (!files || files.length === 0) return res.status(400).json({ error: 'No files uploaded' });

        try {
          const tenantId = req.tenant!.id;
          const storage = await TenantFileStorage.forTenant(tenantId);
          const uploadedPaths: string[] = [];

          for (const file of files) {
            const ext = file.originalname.split('.').pop() || 'bin';
            const fileName = `campaign-media-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
            const filePath = `campaigns/${fileName}`;
            const objectPath = await storage.uploadFile(filePath, file.buffer, file.mimetype);
            uploadedPaths.push(objectPath);
          }

          res.json({ uploadedPaths });
        } catch (uploadError) {
          next(uploadError);
        }
      });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/peer-campaigns/:id/progress
   * Staff: Update campaign progress (for unit-based campaigns)
   */
  app.patch('/api/peer-campaigns/:id/progress', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff', 'manager'), async (req, res, next) => {
    try {
      const { peerCampaigns } = await import('@shared/schema');

      const progressSchema = z.object({
        currentProgress: z.number().int().min(0),
      });

      const data = progressSchema.parse(req.body);

      const [campaign] = await db
        .update(peerCampaigns)
        .set({ currentProgress: data.currentProgress })
        .where(and(
          eq(peerCampaigns.id, req.params.id),
          eq(peerCampaigns.tenantId, req.tenant!.id)
        ))
        .returning();

      if (!campaign) return res.status(404).json({ error: 'Campaign not found' });

      res.json({ campaign });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/peer-campaigns/:slug/pledge
   * Public: Create a pledge-per-unit donation (saved as pending)
   */
  app.post('/api/peer-campaigns/:slug/pledge', requireTenant, async (req, res, next) => {
    try {
      const { peerCampaigns, peerCampaignDonations, campaignParticipants } = await import('@shared/schema');

      const pledgeSchema = z.object({
        donorName: z.string().min(1).max(200),
        donorEmail: z.string().email().optional(),
        pledgePerUnit: z.number().int().min(1),
        message: z.string().max(500).optional(),
        isAnonymous: z.boolean().default(false),
        participantId: z.string().uuid().optional(),
      });

      const data = pledgeSchema.parse(req.body);

      const [campaign] = await db
        .select()
        .from(peerCampaigns)
        .where(and(
          eq(peerCampaigns.tenantId, req.tenant!.id),
          eq(peerCampaigns.slug, req.params.slug),
          eq(peerCampaigns.isActive, true)
        ))
        .limit(1);

      if (!campaign) return res.status(404).json({ error: 'Campaign not found' });

      if (campaign.goalType !== 'units') {
        return res.status(400).json({ error: 'Pledges are only available for unit-based campaigns' });
      }
      if (campaign.status === 'completed' || campaign.status === 'cancelled') {
        return res.status(400).json({ error: 'This campaign is no longer accepting pledges' });
      }
      if (campaign.endsAt && new Date(campaign.endsAt) < new Date()) {
        return res.status(400).json({ error: 'This campaign has ended' });
      }

      if (data.participantId) {
        const [validParticipant] = await db
          .select({ id: campaignParticipants.id })
          .from(campaignParticipants)
          .where(and(
            eq(campaignParticipants.id, data.participantId),
            eq(campaignParticipants.peerCampaignId, campaign.id),
            eq(campaignParticipants.tenantId, req.tenant!.id),
            eq(campaignParticipants.isActive, true)
          ))
          .limit(1);
        if (!validParticipant) {
          return res.status(400).json({ error: 'Invalid participant' });
        }
      }

      const maxAmount = data.pledgePerUnit * (campaign.goalTarget || 0);

      const [donation] = await db.insert(peerCampaignDonations).values({
        tenantId: req.tenant!.id,
        peerCampaignId: campaign.id,
        donorName: data.donorName,
        donorEmail: data.donorEmail || null,
        amount: maxAmount,
        message: data.message || null,
        isAnonymous: data.isAnonymous,
        paymentStatus: 'pending',
        pledgeType: 'per_unit',
        pledgePerUnit: data.pledgePerUnit,
        participantId: data.participantId || null,
      }).returning();

      res.json({ pledge: donation });
    } catch (error) {
      next(error);
    }
  });

  // ============================================================================
  // Campaign Participants Routes (Team-Based Fundraising)
  // ============================================================================

  /**
   * GET /api/peer-campaigns/:id/participants
   * Public: Get all participants for a campaign with aggregated pledge totals
   */
  app.get('/api/peer-campaigns/:id/participants', requireTenant, async (req, res, next) => {
    try {
      const { campaignParticipants, peerCampaignDonations } = await import('@shared/schema');

      const participants = await db
        .select()
        .from(campaignParticipants)
        .where(and(
          eq(campaignParticipants.tenantId, req.tenant!.id),
          eq(campaignParticipants.peerCampaignId, req.params.id),
          eq(campaignParticipants.isActive, true)
        ))
        .orderBy(desc(campaignParticipants.currentUnits));

      const pledgeTotals = await db
        .select({
          participantId: peerCampaignDonations.participantId,
          totalAmount: sql<number>`COALESCE(SUM(${peerCampaignDonations.amount}), 0)`,
          donationCount: sql<number>`COUNT(*)`,
        })
        .from(peerCampaignDonations)
        .where(and(
          eq(peerCampaignDonations.peerCampaignId, req.params.id),
          isNotNull(peerCampaignDonations.participantId),
          sql`(${peerCampaignDonations.paymentStatus} = 'paid' OR ${peerCampaignDonations.pledgeType} = 'per_unit')`
        ))
        .groupBy(peerCampaignDonations.participantId);

      const totalsMap = new Map(pledgeTotals.map(t => [t.participantId, { totalAmount: Number(t.totalAmount), donationCount: Number(t.donationCount) }]));

      const enriched = participants.map(p => ({
        ...p,
        totalRaised: totalsMap.get(p.id)?.totalAmount || 0,
        donationCount: totalsMap.get(p.id)?.donationCount || 0,
      }));

      res.json({ participants: enriched });
    } catch (error) {
      next(error);
    }
  });

  /**
   * POST /api/peer-campaigns/:id/participants
   * Staff/Admin: Create participant(s) — supports single or bulk array
   */
  app.post('/api/peer-campaigns/:id/participants', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff', 'manager'), async (req, res, next) => {
    try {
      const { campaignParticipants, peerCampaigns } = await import('@shared/schema');

      const [campaign] = await db
        .select()
        .from(peerCampaigns)
        .where(and(
          eq(peerCampaigns.id, req.params.id),
          eq(peerCampaigns.tenantId, req.tenant!.id)
        ))
        .limit(1);

      if (!campaign) return res.status(404).json({ error: 'Campaign not found' });

      const avatarTypes = ['dog1', 'cat1', 'bone', 'paw', 'bird1', 'fish1', 'rabbit1', 'turtle1', 'star', 'heart'];

      const participantSchema = z.object({
        displayName: z.string().min(1).max(100),
        avatarType: z.enum(avatarTypes as [string, ...string[]]).optional(),
      });

      const body = req.body;
      const items = Array.isArray(body) ? body : [body];

      const validated = items.map(item => participantSchema.parse(item));

      const created = await db.insert(campaignParticipants).values(
        validated.map(v => ({
          tenantId: req.tenant!.id,
          peerCampaignId: campaign.id,
          displayName: v.displayName,
          avatarType: (v.avatarType || avatarTypes[Math.floor(Math.random() * avatarTypes.length)]) as "dog1" | "cat1" | "bone" | "paw" | "bird1" | "fish1" | "rabbit1" | "turtle1" | "star" | "heart",
        }))
      ).returning();

      res.json({ participants: created });
    } catch (error) {
      next(error);
    }
  });

  /**
   * PATCH /api/peer-campaigns/:id/participants/:pid
   * Staff/Admin: Update a participant
   */
  app.patch('/api/peer-campaigns/:id/participants/:pid', requireTenant, requireAuth, requireRole('admin', 'owner', 'board_member', 'staff', 'manager'), async (req, res, next) => {
    try {
      const { campaignParticipants } = await import('@shared/schema');

      const avatarTypes = ['dog1', 'cat1', 'bone', 'paw', 'bird1', 'fish1', 'rabbit1', 'turtle1', 'star', 'heart'];

      const updateSchema = z.object({
        displayName: z.string().min(1).max(100).optional(),
        avatarType: z.enum(avatarTypes as [string, ...string[]]).optional(),
        currentUnits: z.number().int().min(0).optional(),
        isActive: z.boolean().optional(),
      });

      const data = updateSchema.parse(req.body);

      const updateFields: Record<string, unknown> = {};
      if (data.displayName !== undefined) updateFields.displayName = data.displayName;
      if (data.avatarType !== undefined) updateFields.avatarType = data.avatarType as "dog1" | "cat1" | "bone" | "paw" | "bird1" | "fish1" | "rabbit1" | "turtle1" | "star" | "heart";
      if (data.currentUnits !== undefined) updateFields.currentUnits = data.currentUnits;
      if (data.isActive !== undefined) updateFields.isActive = data.isActive;

      const [updated] = await db
        .update(campaignParticipants)
        .set(updateFields)
        .where(and(
          eq(campaignParticipants.id, req.params.pid),
          eq(campaignParticipants.peerCampaignId, req.params.id),
          eq(campaignParticipants.tenantId, req.tenant!.id)
        ))
        .returning();

      if (!updated) return res.status(404).json({ error: 'Participant not found' });

      res.json({ participant: updated });
    } catch (error) {
      next(error);
    }
  });

