  /**
   * GET /api/tnr-records
   * List TNR animals for this tenant, optionally filtered by ?month=YYYY-MM
   */
  app.get('/api/tnr-records', requireTenant, requireAuth, async (req, res, next) => {
    try {
      const monthParam = req.query.month as string | undefined;
      let conditions: any[] = [eq(animals.tenantId, req.tenant!.id), eq(animals.recordType, 'tnr')];
      if (monthParam && /^\d{4}-\d{2}$/.test(monthParam)) {
        const [y, m] = monthParam.split('-').map(Number);
        const monthStart = new Date(y, m - 1, 1, 0, 0, 0, 0);
        const monthEnd = new Date(y, m, 0, 23, 59, 59, 999);
        conditions.push(gte(animals.intakeDate, monthStart), lte(animals.intakeDate, monthEnd));
      }
      const records = await db
        .select({
          id: animals.id,
          name: animals.name,
          species: animals.species,
          sex: animals.sex,
          breed: animals.breed,
          colors: animals.colors,
          status: animals.status,
          intakeDate: animals.intakeDate,
          photoUrls: animals.photoUrls,
          recordType: animals.recordType,
          colonyLocation: animals.colonyLocation,
          earTipped: animals.earTipped,
          caretakerName: animals.caretakerName,
          caretakerPhone: animals.caretakerPhone,
          invoiceNumber: animals.invoiceNumber,
          surgeryLocation: animals.surgeryLocation,
          partnership: animals.partnership,
          releaseLocation: animals.releaseLocation,
          trapNumber: animals.trapNumber,
          tnrNotes: animals.tnrNotes,
          colonyName: animals.colonyName,
          trapperName: animals.trapperName,
          dateAltered: animals.dateAltered,
          rabiesTagNumber: animals.rabiesTagNumber,
          fvrcpVaxGiven: animals.fvrcpVaxGiven,
          fivFelvResult: animals.fivFelvResult,
          tnrOutcomeType: animals.tnrOutcomeType,
          tnrOutcomeDate: animals.tnrOutcomeDate,
          latitude: animals.latitude,
          longitude: animals.longitude,
          neuterStatus: animals.neuterStatus,
          localShelterId: animals.localShelterId,
          createdAt: animals.createdAt,
        })
        .from(animals)
        .where(and(...conditions))
        .orderBy(animals.intakeDate);
      res.json({ records });
    } catch (error) { next(error); }
  });

  /**
   * POST /api/tnr-records/geocode-backfill
   * Geocode all TNR records with colonyLocation but missing lat/lng
   */
  app.post('/api/tnr-records/geocode-backfill', requireTenant, requireAuth, requireRole('admin', 'owner'), async (req, res, next) => {
    try {
      const { geocodeAddress } = await import('./lib/geocoding');
      const ungeocodedRecords = await db
        .select({ id: animals.id, colonyLocation: animals.colonyLocation })
        .from(animals)
        .where(and(
          eq(animals.tenantId, req.tenant!.id),
          eq(animals.recordType, 'tnr'),
          isNotNull(animals.colonyLocation),
          or(isNull(animals.latitude), isNull(animals.longitude)),
        ));

      const geocodeCache: Record<string, { latitude: number; longitude: number } | null> = {};
      let updated = 0;

      for (const record of ungeocodedRecords) {
        if (!record.colonyLocation) continue;
        const key = record.colonyLocation.trim().toLowerCase();
        let coords = geocodeCache[key];
        if (coords === undefined) {
          coords = await geocodeAddress(record.colonyLocation);
          geocodeCache[key] = coords;
        }
        if (coords) {
          await db.update(animals)
            .set({ latitude: coords.latitude, longitude: coords.longitude })
            .where(eq(animals.id, record.id));
          updated++;
        }
      }

      res.json({ total: ungeocodedRecords.length, updated });
    } catch (error) { next(error); }
  });

